INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39337, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "林業", "is_correct": true, "explanation": "この地方で盛んな産業の名前として、森林を管理して木材を生産する仕事を表し、文に合う。"}, {"text": "丸太", "is_correct": false, "explanation": "丸太は切り出した木の幹で、産業の名前ではないので「盛んで」に合わない。"}, {"text": "樹木", "is_correct": false, "explanation": "樹木は木そのものを指し、産業を表さないので文に合わない。"}, {"text": "苗木", "is_correct": false, "explanation": "苗木は植えるための若い木で、産業を表す語ではない。"}], "explanations": {"林業": "この地方で盛んな産業の名前として、森林を管理して木材を生産する仕事を表し、文に合う。", "丸太": "丸太は切り出した木の幹で、産業の名前ではないので「盛んで」に合わない。", "樹木": "樹木は木そのものを指し、産業を表さないので文に合わない。", "苗木": "苗木は植えるための若い木で、産業を表す語ではない。"}, "sentence_index": 0, "correct_answer": "林業"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "林業は、木材を使って家具や器を作る技術です。", "explanation": "ここは〈木工〉の意味。木材で家具や器を作る技術で、森林を管理して木材を生産する林業とは別なので合わない。"}, {"text": "林業は、木材のパルプから紙を作る産業です。", "explanation": "ここは〈製紙業〉の意味。パルプから紙を作る産業で、森林の管理と木材の生産を指す林業とは違うので合わない。"}, {"text": "林業の会社は、ビルの基礎工事を請け負っています。", "explanation": "ここは〈建設業〉の意味。ビルの土木・建築工事を指す仕事で、森を管理して木材を生産する林業とは違うので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4c8d929-a1f4-47d6-b121-5e9a43eae7b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39337, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "林業", "is_correct": true, "explanation": "政府が支える対象として、森林管理と木材生産の産業を表す語が入り、文に合う。"}, {"text": "工具", "is_correct": false, "explanation": "工具は作業に使う道具で、「支える」対象の産業や仕事ではないので文に合わない。"}, {"text": "林道", "is_correct": false, "explanation": "林道は山の中の道で、「支える」の対象にはならない。"}, {"text": "樹脂", "is_correct": false, "explanation": "樹脂は樹木などから得られる物質で、支える対象の産業ではない。"}], "explanations": {"林業": "政府が支える対象として、森林管理と木材生産の産業を表す語が入り、文に合う。", "工具": "工具は作業に使う道具で、「支える」対象の産業や仕事ではないので文に合わない。", "林道": "林道は山の中の道で、「支える」の対象にはならない。", "樹脂": "樹脂は樹木などから得られる物質で、支える対象の産業ではない。"}, "sentence_index": 6, "correct_answer": "林業"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "林業の船が夜明けに港を出て、魚を捕りに行きます。", "explanation": "ここは〈漁業〉の意味。魚を捕る産業で、森林を管理して木材を生産する林業とは違うので合わない。"}, {"text": "林業は、山から石炭や鉄鉱石を掘り出して、町の工場に運びます。", "explanation": "ここは〈鉱業〉の意味。山の鉱物を掘る産業で、木材を生産する林業とは別なので合わない。"}, {"text": "林業の職人が、公園の池や石を組んで、庭園の景色を整えます。", "explanation": "ここは〈造園〉の意味。庭や公園を設計・整備する仕事で、森林の管理と木材生産の林業には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4c8d929-a1f4-47d6-b121-5e9a43eae7b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39337, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "父は林業で従事していて、毎日山に入ります。", "corrected_sentence": "父は林業に従事していて、毎日山に入ります。", "error_description": "「従事する」は「〜に従事する」で「に」を取る。ここの「で」が誤りで、「に」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4c8d929-a1f4-47d6-b121-5e9a43eae7b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39337, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "国内の林業に衰えたら、森の手入れが途絶えます。", "corrected_sentence": "国内の林業が衰えたら、森の手入れが途絶えます。", "error_description": "「衰える」は主語を「が」で示す。対象語の後の「に」が誤りで、「が」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4c8d929-a1f4-47d6-b121-5e9a43eae7b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39338, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "正解。「口伝えで受け継がれている」の「で」は手段を表す。"}, {"text": "を", "is_correct": false, "explanation": "目的語を示す「を」は、手段の「口伝え」には使えない。"}, {"text": "に", "is_correct": false, "explanation": "帰着・相手の「に」は、手段を表す口伝えには合わない。"}, {"text": "と", "is_correct": false, "explanation": "共同・引用の「と」は、「口伝えと受け継がれている」と文が成り立たない。"}], "correct_answer": "で", "explanations": {"で": "正解。「口伝えで受け継がれている」の「で」は手段を表す。", "を": "目的語を示す「を」は、手段の「口伝え」には使えない。", "に": "帰着・相手の「に」は、手段を表す口伝えには合わない。", "と": "共同・引用の「と」は、「口伝えと受け継がれている」と文が成り立たない。"}, "error_tags": {"を": "対象格", "に": "帰着・相手", "と": "共同・引用"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'acd1f4a8-eb16-4a36-ad41-5791be3ae06d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39338, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "正解。「口伝えで子どもたちに残している」の「で」は手段を表す。"}, {"text": "が", "is_correct": false, "explanation": "主格の「が」にすると、「口伝えが残している」となり主語として成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "連体の「の」は名詞をつなぐだけで、「口伝えの残している」は文が成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "共同・引用の「と」は、「口伝えと残している」では手段の意味が出ない。"}], "correct_answer": "で", "explanations": {"で": "正解。「口伝えで子どもたちに残している」の「で」は手段を表す。", "が": "主格の「が」にすると、「口伝えが残している」となり主語として成り立たない。", "の": "連体の「の」は名詞をつなぐだけで、「口伝えの残している」は文が成り立たない。", "と": "共同・引用の「と」は、「口伝えと残している」では手段の意味が出ない。"}, "error_tags": {"が": "主格", "の": "連体", "と": "共同・引用"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'acd1f4a8-eb16-4a36-ad41-5791be3ae06d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39338, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "話すことや聞くことで、次の人に伝えること。", "primary_collocate": null, "pronunciation": "くちづたえ", "ipa": "kɯtɕidzɯtae", "syllable_count": 5, "sentences": [{"text": "この村の昔話は、祖父母から親へ、親から子へと口伝えで伝わってきた。", "target_word": "口伝え", "complexity_tier": "T3", "furigana": "この村[むら]の昔話[むかしばなし]は、祖父母[そふぼ]から親[おや]へ、親[おや]から子[こ]へと口伝[くちづた]えで伝[つた]わってきた。", "sentence_source": "generated"}, {"text": "祭りの踊り方は本に書かれておらず、口伝えで受け継がれている。", "target_word": "口伝え", "complexity_tier": "T3", "furigana": "祭[まつ]りの踊[おど]り方[かた]は本[ほん]に書[か]かれておらず、口伝[くちづた]えで受[う]け継[つ]がれている。", "sentence_source": "generated"}, {"text": "昔の職人の技は、口伝えで弟子に教えられた。", "target_word": "口伝え", "complexity_tier": "T3", "furigana": "昔[むかし]の職人[しょくにん]の技[わざ]は、口伝[くちづた]えで弟子[でし]に教[おし]えられた。", "sentence_source": "generated"}, {"text": "おばあちゃんの料理のコツは口伝えなので、レシピがない。", "target_word": "口伝え", "complexity_tier": "T3", "furigana": "おばあちゃんの料理[りょうり]のコツは口伝[くちづた]えなので、レシピがない。", "sentence_source": "generated"}, {"text": "文字がなかった時代、歴史は口伝えで次の世代に残された。", "target_word": "口伝え", "complexity_tier": "T3", "furigana": "文字[もじ]がなかった時代[じだい]、歴史[れきし]は口伝[くちづた]えで次[つぎ]の世代[せだい]に残[のこ]された。", "sentence_source": "generated"}, {"text": "この民謡は口伝えだったため、地方によって歌詞が少しちがう。", "target_word": "口伝え", "complexity_tier": "T3", "furigana": "この民謡[みんよう]は口伝[くちづた]えだったため、地方[ちほう]によって歌詞[かし]が少[すこ]しちがう。", "sentence_source": "generated"}, {"text": "その作り方は、口伝えでしか知られていない。", "target_word": "口伝え", "complexity_tier": "T3", "furigana": "その作[つく]り方[かた]は、口伝[くちづた]えでしか知[し]られていない。", "sentence_source": "generated"}, {"text": "先祖が経験した大きな地震の話を、口伝えで子どもたちに残している。", "target_word": "口伝え", "complexity_tier": "T3", "furigana": "先祖[せんぞ]が経験[けいけん]した大[おお]きな地震[じしん]の話[はなし]を、口伝[くちづた]えで子[こ]どもたちに残[のこ]している。", "sentence_source": "generated"}, {"text": "この薬草の使い方は、長いあいだ口伝えでしか知られていなかった。", "target_word": "口伝え", "complexity_tier": "T3", "furigana": "この薬草[やくそう]の使[つか]い方[かた]は、長[なが]いあいだ口伝[くちづた]えでしか知[し]られていなかった。", "sentence_source": "generated"}, {"text": "祖父は、村の祭りの由来を孫に口伝えで教えてくれた。", "target_word": "口伝え", "complexity_tier": "T3", "furigana": "祖父[そふ]は、村[むら]の祭[まつ]りの由来[ゆらい]を孫[まご]に口伝[くちづた]えで教[おし]えてくれた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "口伝え", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "話して聞かせることで知識や話を次の人・次の世代へ伝えること(口承)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b5f4a63-69ff-4d35-93ef-31c84933d968') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39338, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "口伝え", "is_correct": true, "explanation": "正解。「口伝えで伝わってきた」は、言葉で世代から世代へ受け継がれたという意味で文が成り立つ。"}, {"text": "口論", "is_correct": false, "explanation": "言い争いの意味で、「口論で伝わってきた」は意味が通らない。"}, {"text": "夕立", "is_correct": false, "explanation": "急な雨の意味で、伝わる手段にならないので空欄に入らない。"}, {"text": "草履", "is_correct": false, "explanation": "履物の名前で、伝わる手段にはならないので文が成り立たない。"}], "explanations": {"口伝え": "正解。「口伝えで伝わってきた」は、言葉で世代から世代へ受け継がれたという意味で文が成り立つ。", "口論": "言い争いの意味で、「口論で伝わってきた」は意味が通らない。", "夕立": "急な雨の意味で、伝わる手段にならないので空欄に入らない。", "草履": "履物の名前で、伝わる手段にはならないので文が成り立たない。"}, "sentence_index": 0, "correct_answer": "口伝え"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "祭りの神輿を、口伝えで次の町へ運んだ。", "explanation": "ここは〈運搬〉の意味。物を運ぶのは体や車で行うことで、言葉で伝える口伝えでは運べないので合わない。"}, {"text": "祭りの踊り方は古い巻物に口伝えで残されている。", "explanation": "ここは〈記録〉の意味。巻物に書き残した内容は口伝えとは言わないので、この文では合わない。"}, {"text": "先生の口伝えを掲示板に貼った。", "explanation": "ここは〈伝言〉の意味。伝言は紙に書いて貼れるが、口伝えは言葉で伝える行為で、貼れるものではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'acd1f4a8-eb16-4a36-ad41-5791be3ae06d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39338, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "口伝え", "is_correct": true, "explanation": "正解。「口伝えでしか知られていない」の手段を表すので、空欄に入る。"}, {"text": "雑巾", "is_correct": false, "explanation": "掃除用の布で、「雑巾でしか知られていない」は作り方の伝わり方として成り立たない。"}, {"text": "指輪", "is_correct": false, "explanation": "装身具で、「指輪でしか知られていない」は作り方の伝わり方として成り立たない。"}, {"text": "下駄", "is_correct": false, "explanation": "履物で、「下駄でしか知られていない」は作り方の伝わり方として成り立たない。"}], "explanations": {"口伝え": "正解。「口伝えでしか知られていない」の手段を表すので、空欄に入る。", "雑巾": "掃除用の布で、「雑巾でしか知られていない」は作り方の伝わり方として成り立たない。", "指輪": "装身具で、「指輪でしか知られていない」は作り方の伝わり方として成り立たない。", "下駄": "履物で、「下駄でしか知られていない」は作り方の伝わり方として成り立たない。"}, "sentence_index": 6, "correct_answer": "口伝え"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "祖父は、祭りの踊りを口伝えで孫に見せた。", "explanation": "ここは〈実演〉の意味。見せるのは目で見て伝えることで、口伝えは言葉で伝えるので合わない。"}, {"text": "祖父は、昔の話を口伝えで録って孫に残した。", "explanation": "ここは〈録音〉の意味。録るのは機械による記録で、口伝えでは録れないので合わない。"}, {"text": "母は、料理の味を口伝えで確かめた。", "explanation": "ここは〈味見〉の意味。味は舌で確かめるもので、口伝えでは確かめられないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'acd1f4a8-eb16-4a36-ad41-5791be3ae06d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39338, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この作り方は、口伝えを若い世代に受け継がれてきた。", "corrected_sentence": "この作り方は、口伝えで若い世代に受け継がれてきた。", "error_description": "正しくは「口伝えで」（手段の「で」）。「を」は目的語を示すので、手段の口伝えには使えない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'acd1f4a8-eb16-4a36-ad41-5791be3ae06d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39338, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この歌は、母から娘へ口伝えで伝えられてきない。", "corrected_sentence": "この歌は、母から娘へ口伝えで伝えられてきた。", "error_description": "正しくは「伝えられてきた」。「伝えられてきない」は「～てくる」の活用が成立せず、誤った形。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'acd1f4a8-eb16-4a36-ad41-5791be3ae06d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39339, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "正解。「口伝えで回した」の「で」は手段を表す。"}, {"text": "が", "is_correct": false, "explanation": "主格の「が」にすると「口伝えが回した」となり、主語として成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "連体の「の」では「口伝えの回した」となり、文が成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "共同・引用の「と」では「口伝えと回した」となり、手段の意味が出ない。"}], "correct_answer": "で", "explanations": {"で": "正解。「口伝えで回した」の「で」は手段を表す。", "が": "主格の「が」にすると「口伝えが回した」となり、主語として成り立たない。", "の": "連体の「の」では「口伝えの回した」となり、文が成り立たない。", "と": "共同・引用の「と」では「口伝えと回した」となり、手段の意味が出ない。"}, "error_tags": {"が": "主格", "の": "連体", "と": "共同・引用"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'acd1f4a8-eb16-4a36-ad41-5791be3ae06d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39339, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "正解。「口伝えで伝わった」の「で」は手段を表す。"}, {"text": "を", "is_correct": false, "explanation": "目的語の「を」では「口伝えを伝わった」となり、自動詞「伝わる」と合わない。"}, {"text": "に", "is_correct": false, "explanation": "帰着の「に」では「口伝えに伝わった」となり、手段の意味が出ない。"}, {"text": "と", "is_correct": false, "explanation": "共同・引用の「と」では「口伝えと伝わった」となり、文が成り立たない。"}], "correct_answer": "で", "explanations": {"で": "正解。「口伝えで伝わった」の「で」は手段を表す。", "を": "目的語の「を」では「口伝えを伝わった」となり、自動詞「伝わる」と合わない。", "に": "帰着の「に」では「口伝えに伝わった」となり、手段の意味が出ない。", "と": "共同・引用の「と」では「口伝えと伝わった」となり、文が成り立たない。"}, "error_tags": {"を": "対象格", "に": "帰着・相手", "と": "共同・引用"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'acd1f4a8-eb16-4a36-ad41-5791be3ae06d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39339, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "言葉で伝えること。口頭で伝達すること。", "primary_collocate": null, "pronunciation": "くちづたえ", "ipa": "kɯtɕidzɯtae", "syllable_count": 5, "sentences": [{"text": "大事な用事なので、メールではなく口伝えで知らせてください。", "target_word": "口伝え", "complexity_tier": "T3", "furigana": "大事[だいじ]な用事[ようじ]なので、メールではなく口伝[くちづた]えで知[し]らせてください。", "sentence_source": "generated"}, {"text": "先生の伝言を、クラスの友達に口伝えで回した。", "target_word": "口伝え", "complexity_tier": "T3", "furigana": "先生[せんせい]の伝言[でんごん]を、クラスの友達[ともだち]に口伝[くちづた]えで回[まわ]した。", "sentence_source": "generated"}, {"text": "電話がつながらなかったので、隣の人に口伝えで頼んだ。", "target_word": "口伝え", "complexity_tier": "T3", "furigana": "電話[でんわ]がつながらなかったので、隣[となり]の人[ひと]に口伝[くちづた]えで頼[たの]んだ。", "sentence_source": "generated"}, {"text": "口伝えだと間違いやすいから、集合場所はメモにも書いておこう。", "target_word": "口伝え", "complexity_tier": "T3", "furigana": "口伝[くちづた]えだと間違[まちが]いやすいから、集合[しゅうごう]場所[ばしょ]はメモにも書[か]いておこう。", "sentence_source": "generated"}, {"text": "会議の変更は、課長が口伝えで全員に伝えた。", "target_word": "口伝え", "complexity_tier": "T3", "furigana": "会議[かいぎ]の変更[へんこう]は、課長[かちょう]が口伝[くちづた]えで全員[ぜんいん]に伝[つた]えた。", "sentence_source": "generated"}, {"text": "口伝えで聞いた話なので、本当かどうか分からない。", "target_word": "口伝え", "complexity_tier": "T3", "furigana": "口伝[くちづた]えで聞[き]いた話[はなし]なので、本当[ほんとう]かどうか分[わ]からない。", "sentence_source": "generated"}, {"text": "彼は手紙を書かず、友人を通して口伝えで返事をした。", "target_word": "口伝え", "complexity_tier": "T3", "furigana": "彼[かれ]は手紙[てがみ]を書[か]かず、友人[ゆうじん]を通[とお]して口伝[くちづた]えで返事[へんじ]をした。", "sentence_source": "generated"}, {"text": "工事の日程は口伝えで伝わったため、知らない人もいた。", "target_word": "口伝え", "complexity_tier": "T3", "furigana": "工事[こうじ]の日程[にってい]は口伝[くちづた]えで伝[つた]わったため、知[し]らない人[ひと]もいた。", "sentence_source": "generated"}, {"text": "兄は私の話を口伝えで母に知らせたらしい。", "target_word": "口伝え", "complexity_tier": "T3", "furigana": "兄[あに]は私[わたし]の話[はなし]を口伝[くちづた]えで母[はは]に知[し]らせたらしい。", "sentence_source": "generated"}, {"text": "急ぎの連絡は、口伝えより文書のほうが確実だ。", "target_word": "口伝え", "complexity_tier": "T3", "furigana": "急[いそ]ぎの連絡[れんらく]は、口伝[くちづた]えより文書[ぶんしょ]のほうが確実[かくじつ]だ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "口伝え", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "文書ではなく言葉で用件や連絡を人に伝えること(口頭伝達)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b5f4a63-69ff-4d35-93ef-31c84933d968') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39339, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "口伝え", "is_correct": true, "explanation": "正解。言葉で知らせる手段を表し、「メールではなく口伝えで」と対比が成り立つ。"}, {"text": "石鹸", "is_correct": false, "explanation": "洗浄用品で、連絡の手段にはならないので「石鹸で知らせて」は成り立たない。"}, {"text": "砂糖", "is_correct": false, "explanation": "調味料で、知らせる手段にはならないので文が成り立たない。"}, {"text": "雑草", "is_correct": false, "explanation": "植物の名前で、連絡の手段にはならないので文が成り立たない。"}], "explanations": {"口伝え": "正解。言葉で知らせる手段を表し、「メールではなく口伝えで」と対比が成り立つ。", "石鹸": "洗浄用品で、連絡の手段にはならないので「石鹸で知らせて」は成り立たない。", "砂糖": "調味料で、知らせる手段にはならないので文が成り立たない。", "雑草": "植物の名前で、連絡の手段にはならないので文が成り立たない。"}, "sentence_index": 0, "correct_answer": "口伝え"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "犯人の足跡を、口伝えで追った。", "explanation": "ここは〈追跡〉の意味。足跡をたどるのは目で追うことで、言葉で伝える口伝えとは合わない。"}, {"text": "学校の文集は、口伝えで出版された。", "explanation": "ここは〈印刷〉の意味。文集の出版は印刷物で行うもので、口伝えでは出版されないので合わない。"}, {"text": "試験の結果は、口伝えで見た。", "explanation": "ここは〈掲示板〉の意味。結果を見るのは目で確かめることで、言葉で伝える口伝えとは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'acd1f4a8-eb16-4a36-ad41-5791be3ae06d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39339, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "口伝え", "is_correct": true, "explanation": "正解。友人を通して言葉で返事をしたという手段を表す。"}, {"text": "雨具", "is_correct": false, "explanation": "雨の日に使う道具で、返事の手段にはならないので文が成り立たない。"}, {"text": "洗剤", "is_correct": false, "explanation": "洗浄用品で、返事の手段にはならないので文が成り立たない。"}, {"text": "足跡", "is_correct": false, "explanation": "地面に残る跡で、返事の手段にはならないので文が成り立たない。"}], "explanations": {"口伝え": "正解。友人を通して言葉で返事をしたという手段を表す。", "雨具": "雨の日に使う道具で、返事の手段にはならないので文が成り立たない。", "洗剤": "洗浄用品で、返事の手段にはならないので文が成り立たない。", "足跡": "地面に残る跡で、返事の手段にはならないので文が成り立たない。"}, "sentence_index": 6, "correct_answer": "口伝え"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "引っ越しの荷物は、口伝えで運んだ。", "explanation": "ここは〈トラック〉の意味。荷物は車などで運ぶもので、言葉で伝える口伝えでは運べないので合わない。"}, {"text": "答案は、口伝えで採点した。", "explanation": "ここは〈赤ペン〉の意味。採点は印を付ける作業で、口伝えでは採点できないので合わない。"}, {"text": "ビルの高さは、口伝えで測った。", "explanation": "ここは〈巻き尺〉の意味。長さは道具で測るもので、口伝えでは測れないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'acd1f4a8-eb16-4a36-ad41-5791be3ae06d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39339, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "休校の知らせは口伝えを班長に伝えた。", "corrected_sentence": "休校の知らせは口伝えで班長に伝えた。", "error_description": "正しくは「口伝えで」（手段の「で」）。「口伝えを」は目的語になり、手段の意味が消える。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'acd1f4a8-eb16-4a36-ad41-5791be3ae06d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39339, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "連絡は口伝えで班長に伝えらた。", "corrected_sentence": "連絡は口伝えで班長に伝えられた。", "error_description": "正しくは「伝えられた」（受け身の過去形）。「伝えらた」は「れ」が抜けた活用の誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'acd1f4a8-eb16-4a36-ad41-5791be3ae06d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39340, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "切断", "is_correct": true, "explanation": "接続の対義語。つなぐことと断つことは反対の関係にある。"}, {"text": "点検", "is_correct": false, "explanation": "機器の状態を調べる語で、接続の対義語ではない。"}, {"text": "保存", "is_correct": false, "explanation": "データを残す語で、接続と反対の関係にない。"}, {"text": "開始", "is_correct": false, "explanation": "始めることで、つなぐこととは反対の関係にない。"}], "correct_answer": "切断", "explanations": {"切断": "接続の対義語。つなぐことと断つことは反対の関係にある。", "点検": "機器の状態を調べる語で、接続の対義語ではない。", "保存": "データを残す語で、接続と反対の関係にない。", "開始": "始めることで、つなぐこととは反対の関係にない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5593d2b7-80a9-4995-a7a4-efc478deacdf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39340, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "切断", "is_correct": true, "explanation": "接続の対義語。つなぐことと断つことは反対の関係にある。"}, {"text": "整備", "is_correct": false, "explanation": "機器を整える語で、接続の対義語ではない。"}, {"text": "開発", "is_correct": false, "explanation": "新しく作る語で、接続の対義語ではない。"}, {"text": "調査", "is_correct": false, "explanation": "調べる語で、接続の対義語ではない。"}], "correct_answer": "切断", "explanations": {"切断": "接続の対義語。つなぐことと断つことは反対の関係にある。", "整備": "機器を整える語で、接続の対義語ではない。", "開発": "新しく作る語で、接続の対義語ではない。", "調査": "調べる語で、接続の対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5593d2b7-80a9-4995-a7a4-efc478deacdf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39340, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "あるものとあるものをつなぐこと。", "primary_collocate": null, "pronunciation": "せつぞく", "ipa": "setsɯzokɯ", "syllable_count": 4, "sentences": [{"text": "このパソコンはインターネットに接続されていない。", "target_word": "接続されて", "complexity_tier": "T3", "furigana": "このパソコンはインターネットに接続[せつぞく]されていない。", "sentence_source": "generated"}, {"text": "電波が弱くて、接続が何度も切れてしまう。", "target_word": "接続", "complexity_tier": "T3", "furigana": "電波[でんぱ]が弱[よわ]くて、接続[せつぞく]が何度[なんど]も切[き]れてしまう。", "sentence_source": "generated"}, {"text": "プリンターをパソコンに接続して、写真を印刷した。", "target_word": "接続して", "complexity_tier": "T3", "furigana": "プリンターをパソコンに接続[せつぞく]して、写真[しゃしん]を印刷[いんさつ]した。", "sentence_source": "generated"}, {"text": "駅の構内では、無料のWi-Fiに接続できる。", "target_word": "接続できる", "complexity_tier": "T3", "furigana": "駅[えき]の構内[こうない]では、無料[むりょう]のWi-Fiに接続[せつぞく]できる。", "sentence_source": "generated"}, {"text": "ケーブルの接続を確かめてから、電源を入れた。", "target_word": "接続", "complexity_tier": "T3", "furigana": "ケーブルの接続[せつぞく]を確[たし]かめてから、電源[でんげん]を入[い]れた。", "sentence_source": "generated"}, {"text": "二つのパイプを接続するには、専用の部品が必要だ。", "target_word": "接続する", "complexity_tier": "T3", "furigana": "二[ふた]つのパイプを接続[せつぞく]するには、専用[せんよう]の部品[ぶひん]が必要[ひつよう]だ。", "sentence_source": "generated"}, {"text": "工事が終わり、新しい道路が高速道路に接続した。", "target_word": "接続した", "complexity_tier": "T3", "furigana": "工事[こうじ]が終[お]わり、新[あたら]しい道路[どうろ]が高速[こうそく]道路[どうろ]に接続[せつぞく]した。", "sentence_source": "generated"}, {"text": "古いテレビは、新しい機械と接続できなかった。", "target_word": "接続できなかった", "complexity_tier": "T3", "furigana": "古[ふる]いテレビは、新[あたら]しい機械[きかい]と接続[せつぞく]できなかった。", "sentence_source": "generated"}, {"text": "接続が不安定なので、会議の音声が途切れた。", "target_word": "接続", "complexity_tier": "T3", "furigana": "接続[せつぞく]が不安定[ふあんてい]なので、会議[かいぎ]の音声[おんせい]が途切[とぎ]れた。", "sentence_source": "generated"}, {"text": "この線をアンプに接続すると、音が大きくなる。", "target_word": "接続する", "complexity_tier": "T3", "furigana": "この線[せん]をアンプに接続[せつぞく]すると、音[おと]が大[おお]きくなる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "接続", "label": "名詞形"}, {"form": "接続する", "label": "辞書形"}, {"form": "接続しない", "label": "否定形"}, {"form": "接続して", "label": "て形"}, {"form": "接続した", "label": "過去形"}, {"form": "接続される", "label": "受身形"}, {"form": "接続できる", "label": "可能形"}], "register": "neutral", "sense_fingerprint": "機器・回線・管・道路など二つのものをつなぐこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42eca1a3-84c0-4f6d-85ec-ac958200009e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39340, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "接続されて", "is_correct": true, "explanation": "「インターネットに接続されていない」となり、受身の「ていない」で成立する。"}, {"text": "接続しない", "is_correct": false, "explanation": "「インターネットに接続しないいない」となり成立しない。"}, {"text": "接続させ", "is_correct": false, "explanation": "使役の途中で切れ、「いない」と続かない。"}, {"text": "接続でき", "is_correct": false, "explanation": "可能形で「いない」と続かず不自然。"}], "explanations": {"接続されて": "「インターネットに接続されていない」となり、受身の「ていない」で成立する。", "接続しない": "「インターネットに接続しないいない」となり成立しない。", "接続させ": "使役の途中で切れ、「いない」と続かない。", "接続でき": "可能形で「いない」と続かず不自然。"}, "sentence_index": 0, "correct_answer": "接続されて"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "取引先を、高級な店で接続した。", "explanation": "ここは〈接待〉（客をもてなす）の意味。〈接続〉は物や回線をつなぐことで、客をもてなす場面には使わない。"}, {"text": "子どもに、新しいワクチンを接続した。", "explanation": "ここは〈接種〉（ワクチンを体に入れる）の意味。〈接続〉は物どうしをつなぐことで、体への注射には使わない。"}, {"text": "台風が島に接続した。", "explanation": "ここは〈接近〉（近づく）の意味。〈接続〉はものを結ぶことで、台風の接近には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5593d2b7-80a9-4995-a7a4-efc478deacdf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39340, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "接続した", "is_correct": true, "explanation": "「高速道路に接続した」の過去形で、文が完結する。"}, {"text": "接続して", "is_correct": false, "explanation": "て形で文が途中で止まり、文末にならない。"}, {"text": "接続させ", "is_correct": false, "explanation": "使役で切れ、文として成立しない。"}, {"text": "接続しよう", "is_correct": false, "explanation": "意志形で、道路が意志を持つ文になり不自然。"}], "explanations": {"接続した": "「高速道路に接続した」の過去形で、文が完結する。", "接続して": "て形で文が途中で止まり、文末にならない。", "接続させ": "使役で切れ、文として成立しない。", "接続しよう": "意志形で、道路が意志を持つ文になり不自然。"}, "sentence_index": 6, "correct_answer": "接続した"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "両チームの試合は最後まで接続した。", "explanation": "ここは〈接戦〉（勝敗がわからないほど競り合う）の意味。〈接続〉はつなぐことで、競り合いには使わない。"}, {"text": "車がガードレールに接続した。", "explanation": "ここは〈接触〉（ぶつかって触れる）の意味。〈接続〉は線や機器をつなぐことで、ぶつかる場面には使わない。"}, {"text": "雨が朝からずっと接続している。", "explanation": "ここは〈継続〉（続く）の意味。〈接続〉は物どうしをつなぐことで、雨が続くことには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5593d2b7-80a9-4995-a7a4-efc478deacdf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39340, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "工事のあと、この地域の回線は本線に接続さされた。", "corrected_sentence": "工事のあと、この地域の回線は本線に接続された。", "error_description": "正しくは「接続された」（接続＋受身「された」）。「さされ」は使役と受身の混同による誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5593d2b7-80a9-4995-a7a4-efc478deacdf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39340, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "このケーブルを、スピーカーの端子に接続しくください。", "corrected_sentence": "このケーブルを、スピーカーの端子に接続してください。", "error_description": "正しくは「接続してください」。「接続しくください」は「する」の連用形「して」の誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5593d2b7-80a9-4995-a7a4-efc478deacdf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
