INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39341, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "切断", "is_correct": true, "explanation": "接続の対義語。つなぐことと断つことは反対の関係にある。"}, {"text": "整備", "is_correct": false, "explanation": "機器を整える語で、接続の対義語ではない。"}, {"text": "開発", "is_correct": false, "explanation": "新しく作る語で、接続の対義語ではない。"}, {"text": "調査", "is_correct": false, "explanation": "調べる語で、接続の対義語ではない。"}], "correct_answer": "切断", "explanations": {"切断": "接続の対義語。つなぐことと断つことは反対の関係にある。", "整備": "機器を整える語で、接続の対義語ではない。", "開発": "新しく作る語で、接続の対義語ではない。", "調査": "調べる語で、接続の対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5593d2b7-80a9-4995-a7a4-efc478deacdf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39341, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "断絶している物事や関係を再び結びつけること。", "primary_collocate": null, "pronunciation": "せつぞく", "ipa": "setsɯzokɯ", "syllable_count": 4, "sentences": [{"text": "切れていた回線を接続し直すと、通信が復旧した。", "target_word": "接続し直す", "complexity_tier": "T3", "furigana": "切[き]れていた回線[かいせん]を接続[せつぞく]し直[なお]すと、通信[つうしん]が復旧[ふっきゅう]した。", "sentence_source": "generated"}, {"text": "外れていた配線を接続したら、部屋の電気がついた。", "target_word": "接続した", "complexity_tier": "T3", "furigana": "外[はず]れていた配線[はいせん]を接続[せつぞく]したら、部屋[へや]の電気[でんき]がついた。", "sentence_source": "generated"}, {"text": "外れたホースを接続すれば、また水が出るはずだ。", "target_word": "接続すれば", "complexity_tier": "T3", "furigana": "外[はず]れたホースを接続[せつぞく]すれば、また水[みず]が出[で]るはずだ。", "sentence_source": "generated"}, {"text": "通話が途中で切れたので、すぐにもう一度接続した。", "target_word": "接続した", "complexity_tier": "T3", "furigana": "通話[つうわ]が途中[とちゅう]で切[き]れたので、すぐにもう一度[いちど]接続[せつぞく]した。", "sentence_source": "generated"}, {"text": "洪水で切れた道路は、仮設の橋で接続された。", "target_word": "接続された", "complexity_tier": "T3", "furigana": "洪水[こうずい]で切[き]れた道路[どうろ]は、仮設[かせつ]の橋[はし]で接続[せつぞく]された。", "sentence_source": "generated"}, {"text": "断線した電話をもう一度接続してもらい、連絡がついた。", "target_word": "接続して", "complexity_tier": "T3", "furigana": "断線[だんせん]した電話[でんわ]をもう一度[いちど]接続[せつぞく]してもらい、連絡[れんらく]がついた。", "sentence_source": "generated"}, {"text": "切れたケーブルを接続しようとしたが、部品が足りなかった。", "target_word": "接続しよう", "complexity_tier": "T3", "furigana": "切[き]れたケーブルを接続[せつぞく]しようとしたが、部品[ぶひん]が足[た]りなかった。", "sentence_source": "generated"}, {"text": "地震で止まった水道は、新しい管を接続してようやく復旧した。", "target_word": "接続して", "complexity_tier": "T3", "furigana": "地震[じしん]で止[と]まった水道[すいどう]は、新[あたら]しい管[くだ]を接続[せつぞく]してようやく復旧[ふっきゅう]した。", "sentence_source": "generated"}, {"text": "台風で切れたネットの回線は、夜になってやっと接続された。", "target_word": "接続された", "complexity_tier": "T3", "furigana": "台風[たいふう]で切[き]れたネットの回線[かいせん]は、夜[よる]になってやっと接続[せつぞく]された。", "sentence_source": "generated"}, {"text": "断絶していた通信を接続するため、技術者は夜通し作業した。", "target_word": "接続する", "complexity_tier": "T3", "furigana": "断絶[だんぜつ]していた通信[つうしん]を接続[せつぞく]するため、技術者[ぎじゅつしゃ]は夜通[よどお]し作業[さぎょう]した。", "sentence_source": "generated"}], "morphological_forms": [{"form": "接続", "label": "名詞形"}, {"form": "接続する", "label": "辞書形"}, {"form": "接続しない", "label": "否定形"}, {"form": "接続して", "label": "て形"}, {"form": "接続した", "label": "過去形"}, {"form": "接続された", "label": "受身形"}, {"form": "接続すれば", "label": "仮定形"}], "register": "neutral", "sense_fingerprint": "切れたり途絶えたりしていた回線・配線・道などを再びつなぐこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42eca1a3-84c0-4f6d-85ec-ac958200009e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39341, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "接続し直す", "is_correct": true, "explanation": "「接続し直すと」の条件節で、回線を結び直すと復旧するという意味が成立する。"}, {"text": "接続し直さ", "is_correct": false, "explanation": "未然形で切れ、「接続し直さと」は成立しない。"}, {"text": "接続し直して", "is_correct": false, "explanation": "て形で「接続し直してと」と続かず不自然。"}, {"text": "接続し直せ", "is_correct": false, "explanation": "命令形で、条件の「と」と続かず成立しない。"}], "explanations": {"接続し直す": "「接続し直すと」の条件節で、回線を結び直すと復旧するという意味が成立する。", "接続し直さ": "未然形で切れ、「接続し直さと」は成立しない。", "接続し直して": "て形で「接続し直してと」と続かず不自然。", "接続し直せ": "命令形で、条件の「と」と続かず成立しない。"}, "sentence_index": 0, "correct_answer": "接続し直す"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "工事は雨のあと、翌日に接続した。", "explanation": "ここは〈再開〉（止まったものを再び始める）の意味。〈接続〉は回線や機器をつなぐ語で、工事の再開には使わない。"}, {"text": "両チームの試合は最後まで接続した。", "explanation": "ここは〈接戦〉（勝敗が決まらないほど競り合う）の意味。〈接続〉は断たれたものを結び直すことで、競り合いには使わない。"}, {"text": "倒産した会社は、新しい社長のもとで接続された。", "explanation": "ここは〈再建〉（立て直す）の意味。〈接続〉は断たれた物を結び直すことで、会社の立て直しには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5593d2b7-80a9-4995-a7a4-efc478deacdf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39341, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "接続しよう", "is_correct": true, "explanation": "「接続しようとしたが」で、接続しようとしたという意志が表せる。"}, {"text": "接続して", "is_correct": false, "explanation": "て形で「接続してとしたが」と続かず不自然。"}, {"text": "接続し", "is_correct": false, "explanation": "連用形で止まり、「とした」と続かない。"}, {"text": "接続させ", "is_correct": false, "explanation": "使役で「接続させとした」となり不自然。"}], "explanations": {"接続しよう": "「接続しようとしたが」で、接続しようとしたという意志が表せる。", "接続して": "て形で「接続してとしたが」と続かず不自然。", "接続し": "連用形で止まり、「とした」と続かない。", "接続させ": "使役で「接続させとした」となり不自然。"}, "sentence_index": 6, "correct_answer": "接続しよう"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "小さな子に、ワクチンを接続した。", "explanation": "ここは〈接種〉（ワクチンを体に入れる）の意味。〈接続〉は断たれたものを結び直すことで、体への注射には使わない。"}, {"text": "台風が島に接続している。", "explanation": "ここは〈接近〉（近づく）の意味。〈接続〉は断たれたものを結び直すことで、台風が近づく様子には使わない。"}, {"text": "店員は笑顔で客を接続した。", "explanation": "ここは〈接客〉（客の対応をする）の意味。〈接続〉は断たれたものを結び直すことで、客の対応には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5593d2b7-80a9-4995-a7a4-efc478deacdf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39341, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "切れていた電話線を接続し直しところ、ようやく通じた。", "corrected_sentence": "切れていた電話線を接続し直したところ、ようやく通じた。", "error_description": "正しくは「接続し直したところ」。「直し」の後の「た」が抜けている。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5593d2b7-80a9-4995-a7a4-efc478deacdf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39341, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "修理のあと、切れていた配線は再び接続しいる。", "corrected_sentence": "修理のあと、切れていた配線は再び接続している。", "error_description": "正しくは「接続している」（接続＋ている）。「接続しいる」は活用の誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5593d2b7-80a9-4995-a7a4-efc478deacdf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
