INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39342, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "間違いなく本当だと思える、信頼できる様子です。", "primary_collocate": null, "pronunciation": "たしか", "ipa": "taɕika", "syllable_count": 3, "sentences": [{"text": "確かな答えが出るまで、じっくり調べましょう。", "target_word": "確かな", "complexity_tier": "T3", "furigana": "確[たし]かな答[こた]えが出[で]るまで、じっくり調[しら]べましょう。", "sentence_source": "generated"}, {"text": "彼の言葉は確かで、嘘を言っているとは思えない。", "target_word": "確かで", "complexity_tier": "T3", "furigana": "彼[かれ]の言葉[ことば]は確[たし]かで、嘘[うそ]を言[い]っているとは思[おも]えない。", "sentence_source": "generated"}, {"text": "確かな目を持つ店主が、本物だけを選んで売っている。", "target_word": "確かな", "complexity_tier": "T3", "furigana": "確[たし]かな目[め]を持[も]つ店主[てんしゅ]が、本物[ほんもの]だけを選[えら]んで売[う]っている。", "sentence_source": "generated"}, {"text": "この地図は確かなので、迷う心配はありません。", "target_word": "確かな", "complexity_tier": "T3", "furigana": "この地図[ちず]は確[たし]かなので、迷[まよ]う心配[しんぱい]はありません。", "sentence_source": "generated"}, {"text": "彼の約束は確かだから、安心して待てる。", "target_word": "確かだ", "complexity_tier": "T3", "furigana": "彼[かれ]の約束[やくそく]は確[たし]かだから、安心[あんしん]して待[ま]てる。", "sentence_source": "generated"}, {"text": "確かな手応えがあったので、試験の結果に期待している。", "target_word": "確かな", "complexity_tier": "T3", "furigana": "確[たし]かな手応[てごた]えがあったので、試験[しけん]の結果[けっか]に期待[きたい]している。", "sentence_source": "generated"}, {"text": "事故の原因はまだ確かではなく、警察が調べている。", "target_word": "確か", "complexity_tier": "T3", "furigana": "事故[じこ]の原因[げんいん]はまだ確[たし]かではなく、警察[けいさつ]が調[しら]べている。", "sentence_source": "generated"}, {"text": "確かな数字を示さなければ、会議では認められない。", "target_word": "確かな", "complexity_tier": "T3", "furigana": "確[たし]かな数字[すうじ]を示[しめ]さなければ、会議[かいぎ]では認[みと]められない。", "sentence_source": "generated"}, {"text": "彼女の記憶は確かで、十年前の出来事もよく覚えている。", "target_word": "確かで", "complexity_tier": "T3", "furigana": "彼女[かのじょ]の記憶[きおく]は確[たし]かで、十年前[じゅうねんまえ]の出来事[できごと]もよく覚[おぼ]えている。", "sentence_source": "generated"}, {"text": "確かな知らせを聞いて、家族みんなが喜んだ。", "target_word": "確かな", "complexity_tier": "T3", "furigana": "確[たし]かな知[し]らせを聞[き]いて、家族[かぞく]みんなが喜[よろこ]んだ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "確か", "label": "語幹"}, {"form": "確かな", "label": "連体形"}, {"form": "確かだ", "label": "終止形"}, {"form": "確かで", "label": "連用形"}, {"form": "確かではない", "label": "否定形"}], "register": "neutral", "sense_fingerprint": "間違いなく本当だと思える、信頼できる様子(形状詞)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99762afa-59c1-4c2e-a5e4-2262b3d2a431') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39342, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "確かな", "is_correct": true, "explanation": "連体形。後ろの名詞「答え」を修飾する正しい形。"}, {"text": "確かだ", "is_correct": false, "explanation": "終止形なので、名詞「答え」の前には続かない。"}, {"text": "確かで", "is_correct": false, "explanation": "連用形で、名詞を直接修飾できない。"}, {"text": "確かなら", "is_correct": false, "explanation": "仮定形で条件を表すため、「答え」を修飾できない。"}], "explanations": {"確かな": "連体形。後ろの名詞「答え」を修飾する正しい形。", "確かだ": "終止形なので、名詞「答え」の前には続かない。", "確かで": "連用形で、名詞を直接修飾できない。", "確かなら": "仮定形で条件を表すため、「答え」を修飾できない。"}, "sentence_index": 0, "correct_answer": "確かな"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "確かな波が、岸に激しく打ち寄せた。", "explanation": "ここは〈荒い〉の意味。確かなは正しさや信頼を表すので、波の荒さは表せない。「荒い波」と言う。"}, {"text": "確かな森が、どこまでも広がっていた。", "explanation": "ここは〈豊かな〉の意味。確かなは間違いのなさを表すので、森の豊かさは表せない。"}, {"text": "確かなお湯で、体を温めた。", "explanation": "ここは〈熱い〉の意味。確かなは正しさや信頼を表すので、湯の熱さは表せない。「熱いお湯」と言う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74db7eed-5d9a-45a8-a0e9-e766affdf1f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39342, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "確か", "is_correct": true, "explanation": "語幹。「確かではなく」の形で、「確か」＋「では」が続く。"}, {"text": "確かな", "is_correct": false, "explanation": "連体形。「確かなではなく」となり、「ではなく」に続けられない。"}, {"text": "確実な", "is_correct": false, "explanation": "連体形。「確実なではなく」となり、文として成り立たない。"}, {"text": "確実で", "is_correct": false, "explanation": "連用形。「確実でではなく」となり、「ではなく」と続かない。"}], "explanations": {"確か": "語幹。「確かではなく」の形で、「確か」＋「では」が続く。", "確かな": "連体形。「確かなではなく」となり、「ではなく」に続けられない。", "確実な": "連体形。「確実なではなく」となり、文として成り立たない。", "確実で": "連用形。「確実でではなく」となり、「ではなく」と続かない。"}, "sentence_index": 6, "correct_answer": "確か"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "確かな色の服を選んだ。", "explanation": "ここは〈地味な〉の意味。確かなは間違いのなさを表すので、色味の控えめさは表せない。"}, {"text": "確かな風が、首筋を冷やした。", "explanation": "ここは〈冷たい〉の意味。確かなは正しさや信頼を表すので、風の冷たさは表せない。「冷たい風」と言う。"}, {"text": "確かな部屋で、ゆっくり休んだ。", "explanation": "ここは〈清潔な〉の意味。確かなは部屋の清潔さを表せず、この文の意味に合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74db7eed-5d9a-45a8-a0e9-e766affdf1f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39342, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼の証言は確かさ記録に基づいている。", "corrected_sentence": "彼の証言は確かな記録に基づいている。", "error_description": "名詞「記録」を修飾するには連体形「確かな」が必要。「確かさ」は名詞なので、「記録」の前に置くと文が成り立たない。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "確かで", "is_correct": true, "explanation": "連用形。「確かで、」と後ろの文へ続ける形。"}, {"text": "確かな", "is_correct": false, "explanation": "連体形。名詞の前に置く形で、「言葉は確かな、」と続けられない。"}, {"text": "確かだ", "is_correct": false, "explanation": "終止形。「言葉は確かだ」で文が切れるので、「、」で続く形ではない。"}, {"text": "確かさ", "is_correct": false, "explanation": "名詞形。「言葉は確かさ、」と続けられず、文が成り立たない。"}], "correct_form": "確かで", "base_form": "確か", "form_label": "連用形", "sentence_index": 1, "explanations": {"確かで": "連用形。「確かで、」と後ろの文へ続ける形。", "確かな": "連体形。名詞の前に置く形で、「言葉は確かな、」と続けられない。", "確かだ": "終止形。「言葉は確かだ」で文が切れるので、「、」で続く形ではない。", "確かさ": "名詞形。「言葉は確かさ、」と続けられず、文が成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74db7eed-5d9a-45a8-a0e9-e766affdf1f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39342, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "その説明には確かだ裏付けがある。", "corrected_sentence": "その説明には確かな裏付けがある。", "error_description": "名詞「裏付け」を修飾するには連体形「確かな」が必要。「確かだ」は終止形なので、名詞の前には置けない。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "確かな", "is_correct": true, "explanation": "連体形。後ろの名詞「数字」を修飾する正しい形。"}, {"text": "確か", "is_correct": false, "explanation": "語幹だけでは名詞「数字」を修飾できず、「確か数字」とは言えない。"}, {"text": "確かに", "is_correct": false, "explanation": "副詞の形で、名詞「数字」の前には置けない。「確かに数字」は成り立たない。"}, {"text": "確かでした", "is_correct": false, "explanation": "丁寧な過去の述語形で、名詞を修飾しない。「確かでした数字」は文として続かない。"}], "correct_form": "確かな", "base_form": "確か", "form_label": "連体形", "sentence_index": 7, "explanations": {"確かな": "連体形。後ろの名詞「数字」を修飾する正しい形。", "確か": "語幹だけでは名詞「数字」を修飾できず、「確か数字」とは言えない。", "確かに": "副詞の形で、名詞「数字」の前には置けない。「確かに数字」は成り立たない。", "確かでした": "丁寧な過去の述語形で、名詞を修飾しない。「確かでした数字」は文として続かない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74db7eed-5d9a-45a8-a0e9-e766affdf1f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
