INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39343, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "間違いなくそうだと信じられる様子。また、しっかりしていて動かない様。", "primary_collocate": null, "pronunciation": "たしか", "ipa": "taɕika", "syllable_count": 3, "sentences": [{"text": "親である私にできるのは、その勇気ある第一歩を、ただ静かに、そして確かな祈りを込めて見守ることだけだ。", "target_word": "確かな", "complexity_tier": "T4", "furigana": "親[おや]である私[わたし]にできるのは、その勇気[ゆうき]ある第一歩[だいいっぽ]を、ただ静[しず]かに、そして確[たし]かな祈[いの]りを込[こ]めて見守[みまも]ることだけだ。", "sentence_source": "mined"}, {"text": "この時計は確かな品質で、十年使っても狂わない。", "target_word": "確かな", "complexity_tier": "T3", "furigana": "この時計[とけい]は確[たし]かな品質[ひんしつ]で、十年[じゅうねん]使[つか]っても狂[くる]わない。", "sentence_source": "generated"}, {"text": "彼の説明には確かな証拠があるので、みんな納得した。", "target_word": "確かな", "complexity_tier": "T3", "furigana": "彼[かれ]の説明[せつめい]には確[たし]かな証拠[しょうこ]があるので、みんな納得[なっとく]した。", "sentence_source": "generated"}, {"text": "確かな情報が届くまで、発表は待つことにした。", "target_word": "確かな", "complexity_tier": "T3", "furigana": "確[たし]かな情報[じょうほう]が届[とど]くまで、発表[はっぴょう]は待[ま]つことにした。", "sentence_source": "generated"}, {"text": "彼女は確かな足取りで、階段を上っていった。", "target_word": "確かな", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は確[たし]かな足取[あしど]りで、階段[かいだん]を上[のぼ]っていった。", "sentence_source": "generated"}, {"text": "結果が確かなら、明日にも工事を始められます。", "target_word": "確かなら", "complexity_tier": "T3", "furigana": "結果[けっか]が確[たし]かなら、明日[あした]にも工事[こうじ]を始[はじ]められます。", "sentence_source": "generated"}, {"text": "彼は若いが、腕は確かだ。だから大事な仕事を任せている。", "target_word": "確か", "complexity_tier": "T3", "furigana": "彼[かれ]は若[わか]いが、腕[うで]は確[たし]かだ。だから大事[だいじ]な仕事[しごと]を任[まか]せている。", "sentence_source": "generated"}, {"text": "噂ではなく、確かな筋から聞いた話です。", "target_word": "確かな", "complexity_tier": "T3", "furigana": "噂[うわさ]ではなく、確[たし]かな筋[すじ]から聞[き]いた話[はなし]です。", "sentence_source": "generated"}, {"text": "長い練習のおかげで、彼のピアノは確かな技術に支えられている。", "target_word": "確かな", "complexity_tier": "T4", "furigana": "長[なが]い練習[れんしゅう]のおかげで、彼[かれ]のピアノは確[たし]かな技術[ぎじゅつ]に支[ささ]えられている。", "sentence_source": "generated"}, {"text": "薬の効果が確かだと分かって、医者は処方を続けた。", "target_word": "確かだ", "complexity_tier": "T3", "furigana": "薬[くすり]の効果[こうか]が確[たし]かだと分[わ]かって、医者[いしゃ]は処方[しょほう]を続[つづ]けた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "確か", "label": "語幹"}, {"form": "確かな", "label": "連体形"}, {"form": "確かだ", "label": "終止形"}, {"form": "確かで", "label": "連用形"}, {"form": "確かなら", "label": "仮定形"}], "register": "neutral", "sense_fingerprint": "間違いがなく信頼できる、またはしっかりして揺らがない様子(形状詞)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99762afa-59c1-4c2e-a5e4-2262b3d2a431') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39343, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "確かな", "is_correct": true, "explanation": "連体形。後ろの名詞「祈り」を修飾する正しい形。"}, {"text": "確かだ", "is_correct": false, "explanation": "終止形なので、名詞「祈り」の前に続けられない。"}, {"text": "確かで", "is_correct": false, "explanation": "連用形で、名詞を直接修飾できない。「確かで祈り」は成り立たない。"}, {"text": "確かなら", "is_correct": false, "explanation": "仮定形で「〜なら」という条件を表すため、名詞を修飾できない。"}], "explanations": {"確かな": "連体形。後ろの名詞「祈り」を修飾する正しい形。", "確かだ": "終止形なので、名詞「祈り」の前に続けられない。", "確かで": "連用形で、名詞を直接修飾できない。「確かで祈り」は成り立たない。", "確かなら": "仮定形で「〜なら」という条件を表すため、名詞を修飾できない。"}, "sentence_index": 0, "correct_answer": "確かな"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "確かな日差しが、部屋いっぱいに差し込んだ。", "explanation": "ここは〈強い〉の意味。確かなは正しさや信頼を表すので、日差しの強さは表せない。「強い日差し」と言う。"}, {"text": "確かな石を、一人で持ち上げた。", "explanation": "ここは〈重い〉の意味。確かなは正しさや信頼を表すので、石の重さは表せない。「重い石」と言う。"}, {"text": "確かな夕焼けが、空を真っ赤に染めていた。", "explanation": "ここは〈鮮やかな〉の意味。確かなは間違いのなさを表すので、色の鮮やかさには合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74db7eed-5d9a-45a8-a0e9-e766affdf1f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39343, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "確か", "is_correct": true, "explanation": "語幹。「腕は確かだ」の「確か」に「だ」が続く形。"}, {"text": "確かな", "is_correct": false, "explanation": "連体形。「腕は確かなだ」となり、「だ」の前には置けない。"}, {"text": "確実な", "is_correct": false, "explanation": "連体形。「腕は確実なだ」となり、文として成り立たない。"}, {"text": "確実で", "is_correct": false, "explanation": "連用形。「確実でだ」となり、「だ」に続けられない。"}], "explanations": {"確か": "語幹。「腕は確かだ」の「確か」に「だ」が続く形。", "確かな": "連体形。「腕は確かなだ」となり、「だ」の前には置けない。", "確実な": "連体形。「腕は確実なだ」となり、文として成り立たない。", "確実で": "連用形。「確実でだ」となり、「だ」に続けられない。"}, "sentence_index": 6, "correct_answer": "確か"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "確かな夜が、村を包んでいた。", "explanation": "ここは〈静かな〉の意味。確かなは正しさや信頼を表すので、夜の静けさは表せない。「静かな夜」と言う。"}, {"text": "確かな海が広がっていた。", "explanation": "ここは〈穏やかな〉の意味。確かなは間違いのなさを表すので、海の穏やかな様子には合わない。"}, {"text": "確かな部屋で、ゆっくり休んだ。", "explanation": "ここは〈清潔な〉の意味。確かなは部屋の清潔さを表せず、この文の意味に合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74db7eed-5d9a-45a8-a0e9-e766affdf1f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39343, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼の報告は確かだ根拠に基づいている。", "corrected_sentence": "彼の報告は確かな根拠に基づいている。", "error_description": "名詞「根拠」を修飾するには連体形「確かな」が必要。「確かだ」は終止形なので、名詞の前には置けない。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "確かな", "is_correct": true, "explanation": "連体形。後ろの名詞「品質」を修飾する形。"}, {"text": "確かだ", "is_correct": false, "explanation": "終止形で、名詞の前には続かない。"}, {"text": "確かで", "is_correct": false, "explanation": "連用形で、「品質で」のように後ろへ続く形。名詞を修飾できない。"}, {"text": "確かなら", "is_correct": false, "explanation": "仮定形で、「〜なら」の条件を表す。名詞を修飾する形ではない。"}], "correct_form": "確かな", "base_form": "確か", "form_label": "連体形", "sentence_index": 1, "explanations": {"確かな": "連体形。後ろの名詞「品質」を修飾する形。", "確かだ": "終止形で、名詞の前には続かない。", "確かで": "連用形で、「品質で」のように後ろへ続く形。名詞を修飾できない。", "確かなら": "仮定形で、「〜なら」の条件を表す。名詞を修飾する形ではない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74db7eed-5d9a-45a8-a0e9-e766affdf1f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39343, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "その結論には確か根拠がある。", "corrected_sentence": "その結論には確かな根拠がある。", "error_description": "形容動詞の連体形「確かな」が必要。「確か」だけでは副詞になり、名詞「根拠」を修飾できない。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "確かな", "is_correct": true, "explanation": "連体形。後ろの名詞「筋」を修飾する形。"}, {"text": "確か", "is_correct": false, "explanation": "語幹だけでは名詞「筋」を直接修飾できず、「確か筋」とは言えない。"}, {"text": "確かに", "is_correct": false, "explanation": "副詞の形で、名詞「筋」の前には置けない。「確かに筋」は成り立たない。"}, {"text": "確かでした", "is_correct": false, "explanation": "丁寧な過去の述語形で、名詞を修飾しない。「確かでした筋」は文として続かない。"}], "correct_form": "確かな", "base_form": "確か", "form_label": "連体形", "sentence_index": 7, "explanations": {"確かな": "連体形。後ろの名詞「筋」を修飾する形。", "確か": "語幹だけでは名詞「筋」を直接修飾できず、「確か筋」とは言えない。", "確かに": "副詞の形で、名詞「筋」の前には置けない。「確かに筋」は成り立たない。", "確かでした": "丁寧な過去の述語形で、名詞を修飾しない。「確かでした筋」は文として続かない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74db7eed-5d9a-45a8-a0e9-e766affdf1f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
