INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39344, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '200928e1-834d-4fbc-b025-75ea69bf040e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39344, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "息を強く出すこと。", "primary_collocate": null, "pronunciation": "いきづく", "ipa": "ikizɯkɯ", "syllable_count": 4, "sentences": [{"text": "走り終えた彼は、肩で大きく息衝いた。", "target_word": "息衝いた", "complexity_tier": "T3", "furigana": "走[はし]り終[お]えた彼[かれ]は、肩[かた]で大[おお]きく息衝[いきづ]いた。", "sentence_source": "generated"}, {"text": "重い荷物を運び終えて、激しく息衝いた。", "target_word": "息衝いた", "complexity_tier": "T3", "furigana": "重[おも]い荷物[にもつ]を運[はこ]び終[お]えて、激[はげ]しく息衝[いきづ]いた。", "sentence_source": "generated"}, {"text": "寒い朝、学校まで走り通して、荒く息衝きながら教室に入った。", "target_word": "息衝きながら", "complexity_tier": "T3", "furigana": "寒[さむ]い朝[あさ]、学校[がっこう]まで走[はし]り通[とお]して、荒[あら]く息衝[いきづ]きながら教室[きょうしつ]に入[はい]った。", "sentence_source": "generated"}, {"text": "彼女は怒りをこらえきれず、強く息衝いた。", "target_word": "息衝いた", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は怒[いか]りをこらえきれず、強[つよ]く息衝[いきづ]いた。", "sentence_source": "generated"}, {"text": "坂を登りきると、みんな息衝いて座り込んだ。", "target_word": "息衝いて", "complexity_tier": "T3", "furigana": "坂[さか]を登[のぼ]りきると、みんな息衝[いきづ]いて座[すわ]り込[こ]んだ。", "sentence_source": "generated"}, {"text": "ろうそくを消そうと、少年は力いっぱい息衝いた。", "target_word": "息衝いた", "complexity_tier": "T3", "furigana": "ろうそくを消[け]そうと、少年[しょうねん]は力[ちから]いっぱい息衝[いきづ]いた。", "sentence_source": "generated"}, {"text": "子どもは窓ガラスに強く息衝いて、白く曇らせて遊んだ。", "target_word": "息衝いて", "complexity_tier": "T3", "furigana": "子[こ]どもは窓[まど]ガラスに強[つよ]く息衝[いきづ]いて、白[しろ]く曇[くも]らせて遊[あそ]んだ。", "sentence_source": "generated"}, {"text": "試合に負けた選手は、悔しそうに息衝いていた。", "target_word": "息衝いて", "complexity_tier": "T3", "furigana": "試合[しあい]に負[ま]けた選手[せんしゅ]は、悔[くや]しそうに息衝[いきづ]いていた。", "sentence_source": "generated"}, {"text": "彼は何も言わず、ふいに肩を震わせて強く息衝いた。", "target_word": "息衝いた", "complexity_tier": "T3", "furigana": "彼[かれ]は何[なに]も言[い]わず、ふいに肩[かた]を震[ふる]わせて強[つよ]く息衝[いきづ]いた。", "sentence_source": "generated"}, {"text": "驚いた馬が、荒く息衝いている。", "target_word": "息衝いて", "complexity_tier": "T3", "furigana": "驚[おどろ]いた馬[うま]が、荒[あら]く息衝[いきづ]いている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "息衝く", "label": "辞書形"}, {"form": "息衝いた", "label": "過去形"}, {"form": "息衝いて", "label": "て形"}, {"form": "息衝かない", "label": "否定形"}, {"form": "息衝きます", "label": "丁寧形"}], "register": "一般", "sense_fingerprint": "息を強く吐き出す（疲れ・怒り・安心・力を込めたとき）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '755579f7-4a87-4e7f-897a-270cbb3c668d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39344, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "息衝いた", "is_correct": true, "explanation": "息を強く出す動作を表し、「肩で大きく」と合う。"}, {"text": "眠った", "is_correct": false, "explanation": "眠るのは寝ることで、「肩で大きく」とは結びつかず文が成り立たない。"}, {"text": "凍った", "is_correct": false, "explanation": "凍るは状態の変化で、息を出す動作を表さないので合わない。"}, {"text": "踊った", "is_correct": false, "explanation": "踊るは体の動きで、息を強く出す動作ではないので文脈に合わない。"}], "explanations": {"息衝いた": "息を強く出す動作を表し、「肩で大きく」と合う。", "眠った": "眠るのは寝ることで、「肩で大きく」とは結びつかず文が成り立たない。", "凍った": "凍るは状態の変化で、息を出す動作を表さないので合わない。", "踊った": "踊るは体の動きで、息を強く出す動作ではないので文脈に合わない。"}, "sentence_index": 0, "correct_answer": "息衝いた"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "冷たい空気を、彼は胸いっぱいに息衝いた。", "explanation": "ここは〈吸い込む〉（空気を胸に取り込む）の意味。息衝くは息を強く出す動作なので、空気を取り込む場面には合わない。"}, {"text": "時計が息衝いた。", "explanation": "ここは〈動く〉（機械が作動する）の意味。息衝くは人や動物が強く息を出す動作で、時計には使わない。"}, {"text": "新しい町に、古い文化が息衝き始めた。", "explanation": "ここは〈生き生きと感じられる〉（生命感が現れる）の意味。息衝くは息を強く出す動作で、文化には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '200928e1-834d-4fbc-b025-75ea69bf040e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39344, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "息衝いて", "is_correct": true, "explanation": "「強く」と合い、窓ガラスに息を強く吹きかける動作を表す。"}, {"text": "眺めて", "is_correct": false, "explanation": "眺めるは見ることで、息を強く出して窓を曇らせる動作ではない。"}, {"text": "割って", "is_correct": false, "explanation": "割るは窓ガラスを壊す動作で、白く曇らせる文脈に合わない。"}, {"text": "数えて", "is_correct": false, "explanation": "数えるは数を確かめる動作で、窓を曇らせる行為とは結びつかない。"}], "explanations": {"息衝いて": "「強く」と合い、窓ガラスに息を強く吹きかける動作を表す。", "眺めて": "眺めるは見ることで、息を強く出して窓を曇らせる動作ではない。", "割って": "割るは窓ガラスを壊す動作で、白く曇らせる文脈に合わない。", "数えて": "数えるは数を確かめる動作で、窓を曇らせる行為とは結びつかない。"}, "sentence_index": 6, "correct_answer": "息衝いて"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "図書館で、彼は本を息衝いて読み終えた。", "explanation": "ここは〈目を通す〉（文字を目で追う）の意味。息衝くは息を強く出す動作で、本に目を通す動作とは合わない。"}, {"text": "物音に息衝いて、じっとしていた。", "explanation": "ここは〈息をひそめる〉（息を殺して静かにする）の意味。息衝くは息を強く出す動作なので、静かに潜む場面には合わない。"}, {"text": "夜空の星を、彼は息衝いて見上げた。", "explanation": "ここは〈眺める〉（景色に目を向ける）の意味。息衝くは息を強く出す動作で、星を眺める動作とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '200928e1-834d-4fbc-b025-75ea69bf040e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39344, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "坂を走り終えた彼女は、肩で大きく息衝かた。", "corrected_sentence": "坂を走り終えた彼女は、肩で大きく息衝いた。", "error_description": "「息衝く」の過去形は「息衝いた」。「息衝かた」は活用が誤った形。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "息衝いた", "is_correct": true, "explanation": "過去形で、文末の出来事を過去として述べる形。ここに入る。"}, {"text": "息衝く", "is_correct": false, "explanation": "辞書形は現在や未来の動作を表すので、既に終わった出来事には合わない。"}, {"text": "息衝かない", "is_correct": false, "explanation": "否定形なので「息をしなかった」の意味になり、激しく息を出した文脈と逆になる。"}, {"text": "息衝いて", "is_correct": false, "explanation": "て形は文を終えられず、文末で過去を表せない。"}], "correct_form": "息衝いた", "base_form": "息衝く", "form_label": "過去形", "sentence_index": 1, "explanations": {"息衝いた": "過去形で、文末の出来事を過去として述べる形。ここに入る。", "息衝く": "辞書形は現在や未来の動作を表すので、既に終わった出来事には合わない。", "息衝かない": "否定形なので「息をしなかった」の意味になり、激しく息を出した文脈と逆になる。", "息衝いて": "て形は文を終えられず、文末で過去を表せない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '200928e1-834d-4fbc-b025-75ea69bf040e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39344, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "子どもは窓ガラスに強く息衝きて、白く曇らせて帰った。", "corrected_sentence": "子どもは窓ガラスに強く息衝いて、白く曇らせて帰った。", "error_description": "「息衝く」のて形は「息衝いて」。「息衝きて」は活用が誤った形で、日本語として使わない。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "息衝いて", "is_correct": true, "explanation": "て形で、「いた」と続けて動作の継続を表す。ここに入る。"}, {"text": "息衝きます", "is_correct": false, "explanation": "丁寧形は文末で使う形なので、「ていた」の前には続かず文が成り立たない。"}, {"text": "息衝け", "is_correct": false, "explanation": "命令形は「ていた」に続かず、「息衝けていた」では別の可能の意味になり文脈に合わない。"}, {"text": "息衝こう", "is_correct": false, "explanation": "意志形は「ていた」の前に続かず、「息衝こうていた」では文が成り立たない。"}], "correct_form": "息衝いて", "base_form": "息衝く", "form_label": "て形", "sentence_index": 7, "explanations": {"息衝いて": "て形で、「いた」と続けて動作の継続を表す。ここに入る。", "息衝きます": "丁寧形は文末で使う形なので、「ていた」の前には続かず文が成り立たない。", "息衝け": "命令形は「ていた」に続かず、「息衝けていた」では別の可能の意味になり文脈に合わない。", "息衝こう": "意志形は「ていた」の前に続かず、「息衝こうていた」では文が成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '200928e1-834d-4fbc-b025-75ea69bf040e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
