INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39345, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '200928e1-834d-4fbc-b025-75ea69bf040e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39345, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "息を勢いよく吐き出すこと。また、呼吸すること。", "primary_collocate": null, "pronunciation": "いきづく", "ipa": "ikizɯkɯ", "syllable_count": 4, "sentences": [{"text": "寒い朝は、息衝くたびに白い煙のように見える。", "target_word": "息衝く", "complexity_tier": "T3", "furigana": "寒[さむ]い朝[あさ]は、息衝[いきづ]くたびに白[しろ]い煙[けむり]のように見[み]える。", "sentence_source": "generated"}, {"text": "ゴールした選手は、ぜえぜえと息衝いていた。", "target_word": "息衝いて", "complexity_tier": "T3", "furigana": "ゴールした選手[せんしゅ]は、ぜえぜえと息衝[いきづ]いていた。", "sentence_source": "generated"}, {"text": "赤ちゃんは静かに息衝いて、ぐっすり眠っている。", "target_word": "息衝いて", "complexity_tier": "T3", "furigana": "赤[あか]ちゃんは静[しず]かに息衝[いきづ]いて、ぐっすり眠[ねむ]っている。", "sentence_source": "generated"}, {"text": "水から顔を出して、思いきり息衝いた。", "target_word": "息衝いた", "complexity_tier": "T3", "furigana": "水[みず]から顔[かお]を出[だ]して、思[おも]いきり息衝[いきづ]いた。", "sentence_source": "generated"}, {"text": "病気の祖父は、弱いながらもまだ息衝いている。", "target_word": "息衝いて", "complexity_tier": "T3", "furigana": "病気[びょうき]の祖父[そふ]は、弱[よわ]いながらもまだ息衝[いきづ]いている。", "sentence_source": "generated"}, {"text": "深く吸ってから、ゆっくり息衝く練習をした。", "target_word": "息衝く", "complexity_tier": "T3", "furigana": "深[ふか]く吸[す]ってから、ゆっくり息衝[いきづ]く練習[れんしゅう]をした。", "sentence_source": "generated"}, {"text": "重い扉を押し開けて、彼は荒く息衝いた。", "target_word": "息衝いた", "complexity_tier": "T3", "furigana": "重[おも]い扉[とびら]を押[お]し開[あ]けて、彼[かれ]は荒[あら]く息衝[いきづ]いた。", "sentence_source": "generated"}, {"text": "医者は、まだかすかに息衝いている患者を見て、急いで手当てを始めた。", "target_word": "息衝いている", "complexity_tier": "T3", "furigana": "医者[いしゃ]は、まだかすかに息衝[いきづ]いている患者[かんじゃ]を見[み]て、急[いそ]いで手当[てあて]を始[はじ]めた。", "sentence_source": "generated"}, {"text": "暗い洞窟の中で、彼は恐る恐る息衝いた。", "target_word": "息衝いた", "complexity_tier": "T3", "furigana": "暗[くら]い洞窟[どうくつ]の中[なか]で、彼[かれ]は恐[おそ]る恐[おそ]る息衝[いきづ]いた。", "sentence_source": "generated"}, {"text": "風船をふくらませようと、勢いよく息衝いた。", "target_word": "息衝いた", "complexity_tier": "T3", "furigana": "風船[ふうせん]をふくらませようと、勢[いきお]いよく息衝[いきづ]いた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "息衝く", "label": "辞書形"}, {"form": "息衝いた", "label": "過去形"}, {"form": "息衝いて", "label": "て形"}, {"form": "息衝かない", "label": "否定形"}, {"form": "息衝きます", "label": "丁寧形"}], "register": "一般", "sense_fingerprint": "息を勢いよく吐く、また息をする（呼吸する）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '755579f7-4a87-4e7f-897a-270cbb3c668d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39345, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "息衝く", "is_correct": true, "explanation": "息を強く出す動作を表し、白い煙のように見える場面に合う。"}, {"text": "凍る", "is_correct": false, "explanation": "凍るは寒さで固まる変化で、白い煙が出る動作を表さないので合わない。"}, {"text": "眠る", "is_correct": false, "explanation": "眠るは寝ることで、息の白さを示す動作として文が成り立たない。"}, {"text": "踏む", "is_correct": false, "explanation": "踏むは足で押す動作で、白い煙とは結びつかないので合わない。"}], "explanations": {"息衝く": "息を強く出す動作を表し、白い煙のように見える場面に合う。", "凍る": "凍るは寒さで固まる変化で、白い煙が出る動作を表さないので合わない。", "眠る": "眠るは寝ることで、息の白さを示す動作として文が成り立たない。", "踏む": "踏むは足で押す動作で、白い煙とは結びつかないので合わない。"}, "sentence_index": 0, "correct_answer": "息衝く"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "古い町に、祭りの熱気が息衝いている。", "explanation": "ここは〈生き生きと感じられる〉（生命感がある）の意味。息衝くは息を吐いたり呼吸したりする動作で、熱気には使わない。"}, {"text": "風船が大きく息衝いた。", "explanation": "ここは〈膨らむ〉の意味。息衝くは人や動物が呼吸する動作で、風船には使わない。"}, {"text": "春の庭に、草花が息衝き始めた。", "explanation": "ここは〈生き生きと感じられる〉（生命感が現れる）の意味。息衝くは息を吐く動作で、草花には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '200928e1-834d-4fbc-b025-75ea69bf040e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39345, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "息衝いた", "is_correct": true, "explanation": "荒い呼吸を強く出す動作を表し、扉を押した後の様子に合う。"}, {"text": "笑った", "is_correct": false, "explanation": "笑うは声や表情の動作で、荒い息の動作にはならないので合わない。"}, {"text": "微笑んだ", "is_correct": false, "explanation": "微笑むは静かな表情を表し、「荒く」という様子と合わない。"}, {"text": "瞬いた", "is_correct": false, "explanation": "瞬くは目の動作で、「荒く」という様子を表さないので合わない。"}], "explanations": {"息衝いた": "荒い呼吸を強く出す動作を表し、扉を押した後の様子に合う。", "笑った": "笑うは声や表情の動作で、荒い息の動作にはならないので合わない。", "微笑んだ": "微笑むは静かな表情を表し、「荒く」という様子と合わない。", "瞬いた": "瞬くは目の動作で、「荒く」という様子を表さないので合わない。"}, "sentence_index": 6, "correct_answer": "息衝いた"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "ボールを勢いよく息衝いた。", "explanation": "ここは〈投げる〉の意味。息衝くは息を出す動作で、物を投げる動作にはならない。"}, {"text": "夕焼けの空を、彼は息衝いて見上げた。", "explanation": "ここは〈眺める〉（景色に目を向ける）の意味。息衝くは息を勢いよく出す動作で、空を眺める動作には合わない。"}, {"text": "大きな箱を両手で息衝いた。", "explanation": "ここは〈押す〉の意味。息衝くは息を出す動作で、物を押す力を表さないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '200928e1-834d-4fbc-b025-75ea69bf040e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39345, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "寒い朝は、息衝いたびに白い煙のように見えた。", "corrected_sentence": "寒い朝は、息衝くたびに白い煙のように見えた。", "error_description": "「〜たびに」は辞書形につく。「息衝いた」は過去形なので、「息衝くたびに」が正しい。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "息衝いて", "is_correct": true, "explanation": "て形で、「いた」と続けて動作の継続を表す。ここに入る。"}, {"text": "息衝く", "is_correct": false, "explanation": "辞書形は「ていた」の前に続かず、この形では文が成り立たない。"}, {"text": "息衝かない", "is_correct": false, "explanation": "否定形は「息をしていなかった」の意味になり、ぜえぜえと息をする様子と逆になる。"}, {"text": "息衝きます", "is_correct": false, "explanation": "丁寧形は文体が合わず、「ていた」と続けられない。"}], "correct_form": "息衝いて", "base_form": "息衝く", "form_label": "て形", "sentence_index": 1, "explanations": {"息衝いて": "て形で、「いた」と続けて動作の継続を表す。ここに入る。", "息衝く": "辞書形は「ていた」の前に続かず、この形では文が成り立たない。", "息衝かない": "否定形は「息をしていなかった」の意味になり、ぜえぜえと息をする様子と逆になる。", "息衝きます": "丁寧形は文体が合わず、「ていた」と続けられない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '200928e1-834d-4fbc-b025-75ea69bf040e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39345, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "暗い洞窟の奥で、彼は恐る恐る息衝いる。", "corrected_sentence": "暗い洞窟の奥で、彼は恐る恐る息衝いた。", "error_description": "「息衝く」の過去形は「息衝いた」。「息衝いる」は活用が誤った形で、存在しない。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "息衝いている", "is_correct": true, "explanation": "「ている」の形で、今まさに続いている様子を表す。ここに入る。"}, {"text": "息衝いた", "is_correct": false, "explanation": "過去形は「まだ」で表す今も続く様子と合わず、患者の描写にならない。"}, {"text": "息衝け", "is_correct": false, "explanation": "命令形は患者を修飾する節に使えず、文が成り立たない。"}, {"text": "息衝かせる", "is_correct": false, "explanation": "使役形は他人に息をさせる意味になり、患者が自分で息をしている描写と逆になる。"}], "correct_form": "息衝いている", "base_form": "息衝く", "form_label": "ている形", "sentence_index": 7, "explanations": {"息衝いている": "「ている」の形で、今まさに続いている様子を表す。ここに入る。", "息衝いた": "過去形は「まだ」で表す今も続く様子と合わず、患者の描写にならない。", "息衝け": "命令形は患者を修飾する節に使えず、文が成り立たない。", "息衝かせる": "使役形は他人に息をさせる意味になり、患者が自分で息をしている描写と逆になる。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '200928e1-834d-4fbc-b025-75ea69bf040e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39346, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "正解。「電気をつけた」の「を」は、つける（点ける）の目的語を示す。"}, {"text": "が", "is_correct": false, "explanation": "主格の「が」では「電気がつけた」となり、目的語が欠けて文が成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "帰着の「に」では「電気につけた」となり、つける対象として成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "共同・引用の「と」では「電気とつけた」となり、文が成り立たない。"}], "correct_answer": "を", "explanations": {"を": "正解。「電気をつけた」の「を」は、つける（点ける）の目的語を示す。", "が": "主格の「が」では「電気がつけた」となり、目的語が欠けて文が成り立たない。", "に": "帰着の「に」では「電気につけた」となり、つける対象として成り立たない。", "と": "共同・引用の「と」では「電気とつけた」となり、文が成り立たない。"}, "error_tags": {"が": "主格", "に": "帰着・相手", "と": "共同・引用"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'acd1f4a8-eb16-4a36-ad41-5791be3ae06d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39346, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "正解。「電気がきれいに光る」の「が」は、光る主体（主語）を示す。"}, {"text": "を", "is_correct": false, "explanation": "目的語の「を」では「電気を光る」となり、「光る」は目的語を取らないので合わない。"}, {"text": "の", "is_correct": false, "explanation": "連体の「の」では「電気の光る」となり、主語として文が成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "共同・引用の「と」では「電気と光る」となり、主語にならない。"}], "correct_answer": "が", "explanations": {"が": "正解。「電気がきれいに光る」の「が」は、光る主体（主語）を示す。", "を": "目的語の「を」では「電気を光る」となり、「光る」は目的語を取らないので合わない。", "の": "連体の「の」では「電気の光る」となり、主語として文が成り立たない。", "と": "共同・引用の「と」では「電気と光る」となり、主語にならない。"}, "error_tags": {"を": "対象格", "の": "連体", "と": "共同・引用"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'acd1f4a8-eb16-4a36-ad41-5791be3ae06d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39346, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "でんきのことで、あかりをつけたり、くるまをうごかしたりするもとになるものです。", "primary_collocate": null, "pronunciation": "でんき", "ipa": "deŋki", "syllable_count": 3, "sentences": [{"text": "部屋を出るときは、電気を消してください。", "target_word": "電気", "complexity_tier": "T3", "furigana": "部屋[へや]を出[で]るときは、電気[でんき]を消[け]してください。", "sentence_source": "generated"}, {"text": "暗くなったので、電気をつけた。", "target_word": "電気", "complexity_tier": "T3", "furigana": "暗[くら]くなったので、電気[でんき]をつけた。", "sentence_source": "generated"}, {"text": "電気がないと、冷蔵庫も使えない。", "target_word": "電気", "complexity_tier": "T3", "furigana": "電気[でんき]がないと、冷蔵庫[れいぞうこ]も使[つか]えない。", "sentence_source": "generated"}, {"text": "台風で電気が止まって、夜はろうそくを使った。", "target_word": "電気", "complexity_tier": "T3", "furigana": "台風[たいふう]で電気[でんき]が止[と]まって、夜[よる]はろうそくを使[つか]った。", "sentence_source": "generated"}, {"text": "この電車は電気で走っている。", "target_word": "電気", "complexity_tier": "T3", "furigana": "この電車[でんしゃ]は電気[でんき]で走[はし]っている。", "sentence_source": "generated"}, {"text": "使わない部屋の電気はこまめに消している。", "target_word": "電気", "complexity_tier": "T3", "furigana": "使[つか]わない部屋[へや]の電気[でんき]はこまめに消[け]している。", "sentence_source": "generated"}, {"text": "太陽の光から電気をつくる屋根が増えている。", "target_word": "電気", "complexity_tier": "T3", "furigana": "太陽[たいよう]の光[ひかり]から電気[でんき]をつくる屋根[やね]が増[ふ]えている。", "sentence_source": "generated"}, {"text": "夜になると、町じゅうの電気がきれいに光る。", "target_word": "電気", "complexity_tier": "T3", "furigana": "夜[よる]になると、町[まち]じゅうの電気[でんき]がきれいに光[ひか]る。", "sentence_source": "generated"}, {"text": "雷が落ちて、このあたりの電気が消えた。", "target_word": "電気", "complexity_tier": "T3", "furigana": "雷[かみなり]が落[お]ちて、このあたりの電気[でんき]が消[き]えた。", "sentence_source": "generated"}, {"text": "電気で動く車は、ガソリンを使わない。", "target_word": "電気", "complexity_tier": "T3", "furigana": "電気[でんき]で動[うご]く車[くるま]は、ガソリンを使[つか]わない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "電気", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "明かりをつけたり乗り物や物を動かしたりするもとになる、身近な生活の電気", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b5f4a63-69ff-4d35-93ef-31c84933d968') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39346, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "電気", "is_correct": true, "explanation": "正解。部屋を出るときに消すのは明かりの電気なので、空欄に入る。"}, {"text": "窓", "is_correct": false, "explanation": "窓は消すものではないので、「窓を消してください」は成り立たない。"}, {"text": "本棚", "is_correct": false, "explanation": "家具で、消す対象にはならないので文が成り立たない。"}, {"text": "玄関", "is_correct": false, "explanation": "出入口で、消す対象にはならないので文が成り立たない。"}], "explanations": {"電気": "正解。部屋を出るときに消すのは明かりの電気なので、空欄に入る。", "窓": "窓は消すものではないので、「窓を消してください」は成り立たない。", "本棚": "家具で、消す対象にはならないので文が成り立たない。", "玄関": "出入口で、消す対象にはならないので文が成り立たない。"}, "sentence_index": 0, "correct_answer": "電気"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "焚き火の電気が、空へ細く立ちのぼった。", "explanation": "ここは〈煙〉の意味。空へ細く立ちのぼるのは煙で、電気は立ちのぼらないので合わない。"}, {"text": "懐中電灯は、電気を入れ替えれば光る。", "explanation": "ここは〈電池〉の意味。電池は入れ替える物だが、電気は目に見えない力なので入れ替えられない。"}, {"text": "夏の昼間は、庭に強い電気が降り注いでいる。", "explanation": "ここは〈日差し〉の意味。庭に降り注ぐのは日差しで、電気は降り注がないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'acd1f4a8-eb16-4a36-ad41-5791be3ae06d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39346, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "電気", "is_correct": true, "explanation": "正解。太陽の光からつくるものは電気なので、空欄に入る。"}, {"text": "砂糖", "is_correct": false, "explanation": "食品で、太陽の光からつくる屋根の製品にはならないので文が成り立たない。"}, {"text": "湯気", "is_correct": false, "explanation": "蒸気の見える状態で、屋根がつくるものとして成り立たない。"}, {"text": "切手", "is_correct": false, "explanation": "郵便の印紙で、屋根がつくるものとして成り立たない。"}], "explanations": {"電気": "正解。太陽の光からつくるものは電気なので、空欄に入る。", "砂糖": "食品で、太陽の光からつくる屋根の製品にはならないので文が成り立たない。", "湯気": "蒸気の見える状態で、屋根がつくるものとして成り立たない。", "切手": "郵便の印紙で、屋根がつくるものとして成り立たない。"}, "sentence_index": 6, "correct_answer": "電気"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "今朝は電気が降って、傘を持って出た。", "explanation": "ここは〈雨〉の意味。電気は空から降るものではないので合わない。"}, {"text": "夏の夜、空に電気を打ち上げた。", "explanation": "ここは〈花火〉の意味。電気は打ち上げて見せる物ではないので合わない。"}, {"text": "紅茶に電気を溶かして飲んだ。", "explanation": "ここは〈砂糖〉の意味。電気は溶かして飲む物ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'acd1f4a8-eb16-4a36-ad41-5791be3ae06d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39346, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "寝る前に部屋の電気を消えた。", "corrected_sentence": "寝る前に部屋の電気を消した。", "error_description": "正しくは「消した」（他動詞）。「消えた」は自動詞で、目的語の「を」と合わない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'acd1f4a8-eb16-4a36-ad41-5791be3ae06d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39346, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "ブレーカーを上げたら、電気が戻らた。", "corrected_sentence": "ブレーカーを上げたら、電気が戻った。", "error_description": "正しくは「戻った」（五段動詞の過去形）。「戻らた」は活用の誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'acd1f4a8-eb16-4a36-ad41-5791be3ae06d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39347, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "正解。「電気は熱や光に変えて使える」の「は」は、電気を主題として示す。"}, {"text": "に", "is_correct": false, "explanation": "帰着の「に」では「電気に熱や光に変えて」となり、変える対象として文が成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "共同・引用の「と」では「電気と熱や光に変えて」となり、文が成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "連体の「の」では「電気の熱や光に変えて」となり、主題の文にならない。"}], "correct_answer": "は", "explanations": {"は": "正解。「電気は熱や光に変えて使える」の「は」は、電気を主題として示す。", "に": "帰着の「に」では「電気に熱や光に変えて」となり、変える対象として文が成り立たない。", "と": "共同・引用の「と」では「電気と熱や光に変えて」となり、文が成り立たない。", "の": "連体の「の」では「電気の熱や光に変えて」となり、主題の文にならない。"}, "error_tags": {"に": "帰着・相手", "と": "共同・引用", "の": "連体"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'acd1f4a8-eb16-4a36-ad41-5791be3ae06d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39347, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "正解。「風の力で電気をつくる風車」の「を」は、つくる対象（目的語）を示す。"}, {"text": "が", "is_correct": false, "explanation": "主格の「が」では「電気がつくる風車」となり、電気が作り手になってしまう。"}, {"text": "の", "is_correct": false, "explanation": "連体の「の」では「電気のつくる」となり、目的語としての文が成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "共同・引用の「と」では「電気とつくる」となり、文が成り立たない。"}], "correct_answer": "を", "explanations": {"を": "正解。「風の力で電気をつくる風車」の「を」は、つくる対象（目的語）を示す。", "が": "主格の「が」では「電気がつくる風車」となり、電気が作り手になってしまう。", "の": "連体の「の」では「電気のつくる」となり、目的語としての文が成り立たない。", "と": "共同・引用の「と」では「電気とつくる」となり、文が成り立たない。"}, "error_tags": {"が": "主格", "の": "連体", "と": "共同・引用"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'acd1f4a8-eb16-4a36-ad41-5791be3ae06d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39347, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "電気とは、エネルギーを運んだり、熱や光に変えたりする力のことです。私たちは、スイッチを押すと明かりがついたり、テレビが映ったりするのはこの電気のおかげです。", "primary_collocate": null, "pronunciation": "でんき", "ipa": "deŋki", "syllable_count": 3, "sentences": [{"text": "スイッチを押すと、電気が流れて明かりがつく。", "target_word": "電気", "complexity_tier": "T3", "furigana": "スイッチを押[お]すと、電気[でんき]が流[なが]れて明[あ]かりがつく。", "sentence_source": "generated"}, {"text": "電気は熱や光に変えて使うことができる。", "target_word": "電気", "complexity_tier": "T3", "furigana": "電気[でんき]は熱[ねつ]や光[ひかり]に変[か]えて使[つか]うことができる。", "sentence_source": "generated"}, {"text": "電気のおかげで、私たちはテレビを見られる。", "target_word": "電気", "complexity_tier": "T3", "furigana": "電気[でんき]のおかげで、私[わたし]たちはテレビを見[み]られる。", "sentence_source": "generated"}, {"text": "発電所でつくられた電気は、電線を通って家に届く。", "target_word": "電気", "complexity_tier": "T3", "furigana": "発電所[はつでんしょ]でつくられた電気[でんき]は、電線[でんせん]を通[とお]って家[いえ]に届[とど]く。", "sentence_source": "generated"}, {"text": "ドライヤーは電気を熱に変えて、髪をかわかす。", "target_word": "電気", "complexity_tier": "T3", "furigana": "ドライヤーは電気[でんき]を熱[ねつ]に変[か]えて、髪[かみ]をかわかす。", "sentence_source": "generated"}, {"text": "電気は目に見えないが、大きな力を持っている。", "target_word": "電気", "complexity_tier": "T3", "furigana": "電気[でんき]は目[め]に見[み]えないが、大[おお]きな力[ちから]を持[も]っている。", "sentence_source": "generated"}, {"text": "ぬれた手でコンセントにさわると、電気が体に流れて危ない。", "target_word": "電気", "complexity_tier": "T3", "furigana": "ぬれた手[て]でコンセントにさわると、電気[でんき]が体[からだ]に流[なが]れて危[あぶ]ない。", "sentence_source": "generated"}, {"text": "風の力で電気をつくる風車が、海の近くに並んでいる。", "target_word": "電気", "complexity_tier": "T3", "furigana": "風[かぜ]の力[ちから]で電気[でんき]をつくる風車[ふうしゃ]が、海[うみ]の近[ちか]くに並[なら]んでいる。", "sentence_source": "generated"}, {"text": "電気をためておく電池の研究が進んでいる。", "target_word": "電気", "complexity_tier": "T3", "furigana": "電気[でんき]をためておく電池[でんち]の研究[けんきゅう]が進[すす]んでいる。", "sentence_source": "generated"}, {"text": "冬は暖房に多くの電気を使うので、使いすぎないようにしたい。", "target_word": "電気", "complexity_tier": "T3", "furigana": "冬[ふゆ]は暖房[だんぼう]に多[おお]くの電気[でんき]を使[つか]うので、使[つか]いすぎないようにしたい。", "sentence_source": "generated"}], "morphological_forms": [{"form": "電気", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "エネルギーを運び、熱や光などに変えて使える力としての電気(説明的な意味)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b5f4a63-69ff-4d35-93ef-31c84933d968') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39347, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "電気", "is_correct": true, "explanation": "正解。スイッチで流れて明かりをつける力は電気なので、空欄に入る。"}, {"text": "水道", "is_correct": false, "explanation": "水を送る設備で、流れて明かりがつくものにはならないので文が成り立たない。"}, {"text": "空気", "is_correct": false, "explanation": "流れても明かりはつかないので、「空気が流れて明かりがつく」は成り立たない。"}, {"text": "砂", "is_correct": false, "explanation": "流れても明かりはつかないので、文として成り立たない。"}], "explanations": {"電気": "正解。スイッチで流れて明かりをつける力は電気なので、空欄に入る。", "水道": "水を送る設備で、流れて明かりがつくものにはならないので文が成り立たない。", "空気": "流れても明かりはつかないので、「空気が流れて明かりがつく」は成り立たない。", "砂": "流れても明かりはつかないので、文として成り立たない。"}, "sentence_index": 0, "correct_answer": "電気"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "夕方、ビルの電気が道路に長く伸びた。", "explanation": "ここは〈影〉の意味。道路に長く伸びるのは影で、電気は伸びないので合わない。"}, {"text": "電気を燃やして、熱をつくる。", "explanation": "ここは〈石油〉の意味。電気は燃やして熱を取り出すものではないので合わない。"}, {"text": "電気を温めて、お湯をつくる。", "explanation": "ここは〈水〉の意味。電気は温めて形を変えるものではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'acd1f4a8-eb16-4a36-ad41-5791be3ae06d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39347, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "電気", "is_correct": true, "explanation": "正解。ぬれた手で触ると体に流れて危ないものは電気なので、空欄に入る。"}, {"text": "砂", "is_correct": false, "explanation": "体に流れるものではないので、「砂が体に流れて危ない」は成り立たない。"}, {"text": "石", "is_correct": false, "explanation": "体に流れるものではないので、文が成り立たない。"}, {"text": "雲", "is_correct": false, "explanation": "体に流れるものではないので、文が成り立たない。"}], "explanations": {"電気": "正解。ぬれた手で触ると体に流れて危ないものは電気なので、空欄に入る。", "砂": "体に流れるものではないので、「砂が体に流れて危ない」は成り立たない。", "石": "体に流れるものではないので、文が成り立たない。", "雲": "体に流れるものではないので、文が成り立たない。"}, "sentence_index": 6, "correct_answer": "電気"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "真夏の道路で電気が溶けた。", "explanation": "ここは〈氷〉の意味。溶けて形を変えるのは氷で、電気は溶けるものではないので合わない。"}, {"text": "春になると、庭に電気が咲く。", "explanation": "ここは〈花〉の意味。咲くのは花で、電気は咲くものではないので合わない。"}, {"text": "子どもは電気をこねて人形を作った。", "explanation": "ここは〈粘土〉の意味。こねて形を作れるのは粘土で、電気はこねられないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'acd1f4a8-eb16-4a36-ad41-5791be3ae06d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39347, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "ソーラーパネルは、光から電気に取り出す。", "corrected_sentence": "ソーラーパネルは、光から電気を取り出す。", "error_description": "正しくは「電気を取り出す」（目的語の「を」）。「に」にすると、取り出す対象として成り立たない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'acd1f4a8-eb16-4a36-ad41-5791be3ae06d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39347, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "雷の影響で、電気が使えなくなかった。", "corrected_sentence": "雷の影響で、電気が使えなくなった。", "error_description": "正しくは「使えなくなった」（「なくなる」の過去形）。「なくなかった」は活用が成立しない誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'acd1f4a8-eb16-4a36-ad41-5791be3ae06d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39348, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "と", "options": [{"text": "と", "is_correct": true, "explanation": "「雀の御八つとして」の「と」。〜として、という役割を表す形。"}, {"text": "で", "is_correct": false, "explanation": "手段を表す「で」は「雀の御八つで して米つぶ」となり、役割の意味にならない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表す「へ」は、役割を示す「して」と続かず成り立たない。"}, {"text": "が", "is_correct": false, "explanation": "主語を示す「が」は「雀の御八つがして米つぶを置いた」となり、文が成り立たない。"}], "correct_answer": "と", "explanations": {"と": "「雀の御八つとして」の「と」。〜として、という役割を表す形。", "で": "手段を表す「で」は「雀の御八つで して米つぶ」となり、役割の意味にならない。", "へ": "方向を表す「へ」は、役割を示す「して」と続かず成り立たない。", "が": "主語を示す「が」は「雀の御八つがして米つぶを置いた」となり、文が成り立たない。"}, "error_tags": {"で": "手段・場所", "へ": "方向", "が": "主語"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '807bae3e-67f7-4a5e-9415-bec4623c0c7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39348, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「雀の御八つを入れる」の「を」。雀の御八つを入れるという目的語を示す。"}, {"text": "より", "is_correct": false, "explanation": "比較の「より」は「雀の御八つより入れる」となり、目的語を示せない。"}, {"text": "から", "is_correct": false, "explanation": "起点を表す「から」は「雀の御八つから入れる」となり、文が成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "共同を表す「と」は「雀の御八つと入れる」となり、目的語を示せない。"}], "correct_answer": "を", "explanations": {"を": "「雀の御八つを入れる」の「を」。雀の御八つを入れるという目的語を示す。", "より": "比較の「より」は「雀の御八つより入れる」となり、目的語を示せない。", "から": "起点を表す「から」は「雀の御八つから入れる」となり、文が成り立たない。", "と": "共同を表す「と」は「雀の御八つと入れる」となり、目的語を示せない。"}, "error_tags": {"より": "比較", "から": "起点", "と": "相手・共同"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '807bae3e-67f7-4a5e-9415-bec4623c0c7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39348, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "すずめがたべるおやつのことです。", "primary_collocate": null, "pronunciation": "すずめのおやつ", "ipa": "sɯzɯme no ojatsɯ", "syllable_count": 7, "sentences": [{"text": "公園で、おばあさんは毎朝、雀の御八つを石の上に置いていた。", "target_word": "雀の御八つ", "complexity_tier": "T3", "furigana": "公園[こうえん]で、おばあさんは毎朝[まいあさ]、雀[すずめ]の御八つ[おやつ]を石[いし]の上[うえ]に置[お]いていた。", "sentence_source": "generated"}, {"text": "朝、庭に雀の御八つとして米つぶを置いた。", "target_word": "雀の御八つ", "complexity_tier": "T3", "furigana": "朝[あさ]、庭[にわ]に雀[すずめ]の御[お]八[や]つとして米[こめ]つぶを置[お]いた。", "sentence_source": "generated"}, {"text": "雀の御八つを食べに、小さな鳥が集まってきた。", "target_word": "雀の御八つ", "complexity_tier": "T3", "furigana": "雀[すずめ]の御[お]八[や]つを食[た]べに、小[ちい]さな鳥[とり]が集[あつ]まってきた。", "sentence_source": "generated"}, {"text": "子どもは、雀の御八つになるように、クッキーのかけらを窓辺に置いた。", "target_word": "雀の御八つ", "complexity_tier": "T3", "furigana": "子[こ]どもは、雀[すずめ]の御[お]八[や]つになるように、クッキーのかけらを窓辺[まどべ]に置[お]いた。", "sentence_source": "generated"}, {"text": "雀の御八つがなくなると、鳥たちはすぐに飛んでいった。", "target_word": "雀の御八つ", "complexity_tier": "T3", "furigana": "雀[すずめ]の御[お]八[や]つがなくなると、鳥[とり]たちはすぐに飛[と]んでいった。", "sentence_source": "generated"}, {"text": "冬は食べ物が少ないので、雀の御八つを用意してあげる。", "target_word": "雀の御八つ", "complexity_tier": "T3", "furigana": "冬[ふゆ]は食[た]べ物[もの]が少[すく]ないので、雀[すずめ]の御[お]八[や]つを用意[ようい]してあげる。", "sentence_source": "generated"}, {"text": "ベランダの雀の御八つは、毎朝すっかりなくなっている。", "target_word": "雀の御八つ", "complexity_tier": "T3", "furigana": "ベランダの雀[すずめ]の御[お]八[や]つは、毎朝[まいあさ]すっかりなくなっている。", "sentence_source": "generated"}, {"text": "私は雀の御八つを入れる小さな皿を買った。", "target_word": "雀の御八つ", "complexity_tier": "T3", "furigana": "私[わたし]は雀[すずめ]の御[お]八[や]つを入[い]れる小[ちい]さな皿[さら]を買[か]った。", "sentence_source": "generated"}, {"text": "祖母はいつも、雀の御八つの用意を忘れない。", "target_word": "雀の御八つ", "complexity_tier": "T3", "furigana": "祖母[そぼ]はいつも、雀[すずめ]の御[お]八[や]つの用意[ようい]を忘[わす]れない。", "sentence_source": "generated"}, {"text": "雨の日は、雀の御八つがぬれないように屋根の下に置く。", "target_word": "雀の御八つ", "complexity_tier": "T3", "furigana": "雨[あめ]の日[ひ]は、雀[すずめ]の御[お]八[や]つがぬれないように屋根[やね]の下[した]に置[お]く。", "sentence_source": "generated"}], "morphological_forms": [{"form": "雀の御八つ", "label": "基本形"}], "register": "中立", "sense_fingerprint": "すずめに食べさせるパンくずや米つぶなどの軽い食べ物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8b339ca1-4d9a-445d-b929-d025d7d80de9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39348, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "雀の御八つ", "is_correct": true, "explanation": "ここでは〈雀に与える食べ物〉の意味。石の上に置くものとして自然。"}, {"text": "試験", "is_correct": false, "explanation": "物ではないので、「試験を石の上に置いていた」は成り立たない。"}, {"text": "窓口", "is_correct": false, "explanation": "置くことのできる物ではないので、「窓口を石の上に置いていた」は意味が通らない。"}, {"text": "時間割", "is_correct": false, "explanation": "紙の予定表で、餌として石の上に置く文脈に合わない。"}], "explanations": {"雀の御八つ": "ここでは〈雀に与える食べ物〉の意味。石の上に置くものとして自然。", "試験": "物ではないので、「試験を石の上に置いていた」は成り立たない。", "窓口": "置くことのできる物ではないので、「窓口を石の上に置いていた」は意味が通らない。", "時間割": "紙の予定表で、餌として石の上に置く文脈に合わない。"}, "sentence_index": 0, "correct_answer": "雀の御八つ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "朝の散歩を雀の御八つにして、家に帰った。", "explanation": "ここは〈朝ご飯〉の意味。雀の御八つは雀向けの食べ物で、人の朝食の代わりにはならない。"}, {"text": "庭で、雀の御八つが大きな声で鳴いている。", "explanation": "ここは〈雀の子〉の意味。雀の御八つは食べ物の名で、鳴く雀の子を指さない。"}, {"text": "庭の隅で、雀の御八つの鉢が静かに咲いている。", "explanation": "ここは〈植物の名〉の意味。雀の御八つは食べ物の名で、花の名には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '807bae3e-67f7-4a5e-9415-bec4623c0c7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39348, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "雀の御八つ", "is_correct": true, "explanation": "ここでは〈雀に与える食べ物〉の意味。ベランダに置かれ、毎朝なくなるものとして自然。"}, {"text": "手帳", "is_correct": false, "explanation": "食べ物ではなく、毎朝なくなるという文脈に合わない。"}, {"text": "定規", "is_correct": false, "explanation": "食べ物ではなく、「ベランダの定規は毎朝なくなっている」は不自然。"}, {"text": "時刻表", "is_correct": false, "explanation": "食べ物ではなく、「なくなっている」という文脈に合わない。"}], "explanations": {"雀の御八つ": "ここでは〈雀に与える食べ物〉の意味。ベランダに置かれ、毎朝なくなるものとして自然。", "手帳": "食べ物ではなく、毎朝なくなるという文脈に合わない。", "定規": "食べ物ではなく、「ベランダの定規は毎朝なくなっている」は不自然。", "時刻表": "食べ物ではなく、「なくなっている」という文脈に合わない。"}, "sentence_index": 6, "correct_answer": "雀の御八つ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "祖母は炊いたご飯を、家族の雀の御八つとして食卓に並べた。", "explanation": "ここは〈人の食事〉の意味。雀の御八つは雀向けの食べ物なので、家族の食卓には使えない。"}, {"text": "春になると、庭の雀の御八つに白い花が咲いた。", "explanation": "ここは〈植物の名〉の意味。雀の御八つは食べ物の名で、花の名には使えない。"}, {"text": "客に出すお菓子として、雀の御八つを皿に盛った。", "explanation": "ここは〈客用の菓子〉の意味。雀の御八つは雀向けの食べ物なので、客に出す菓子には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '807bae3e-67f7-4a5e-9415-bec4623c0c7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39348, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "庭先の雀の御八つを、朝のうちにすっかりなくなった。", "corrected_sentence": "庭先の雀の御八つは、朝のうちにすっかりなくなった。", "error_description": "「雀の御八つは」の「は」を「を」に変えると目的語になるが、「なくなった」は自動詞なので文が成り立たない。正しくは「は」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '807bae3e-67f7-4a5e-9415-bec4623c0c7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39348, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "雨上がりの庭では、雀の御八つをすぐになくなる。", "corrected_sentence": "雨上がりの庭では、雀の御八つがすぐになくなる。", "error_description": "「雀の御八つが」の「が」を「を」に変えると、「なくなる」と合わず文が成り立たない。正しくは「が」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '807bae3e-67f7-4a5e-9415-bec4623c0c7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39350, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "正解。「風邪で」は熱が出る原因を表す。"}, {"text": "を", "is_correct": false, "explanation": "「風邪を熱が出た」は不自然。「出る」は目的語をとらない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表すが、風邪は熱が出る方向ではない。"}, {"text": "に", "is_correct": false, "explanation": "「風邪に熱が出た」は「に」が熱の出る場所や相手を表せず、不自然。"}], "correct_answer": "で", "explanations": {"で": "正解。「風邪で」は熱が出る原因を表す。", "を": "「風邪を熱が出た」は不自然。「出る」は目的語をとらない。", "へ": "「へ」は方向を表すが、風邪は熱が出る方向ではない。", "に": "「風邪に熱が出た」は「に」が熱の出る場所や相手を表せず、不自然。"}, "error_tags": {"を": "目的語", "へ": "方向", "に": "対象"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'acd1f4a8-eb16-4a36-ad41-5791be3ae06d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
