INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39350, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "ねつや せきが でる びょうき。", "primary_collocate": null, "pronunciation": "かぜ", "ipa": "kaze", "syllable_count": 2, "sentences": [{"text": "風邪をひいて、きのうは学校を休んだ。", "target_word": "風邪", "complexity_tier": "T3", "furigana": "風邪[かぜ]をひいて、きのうは学校[がっこう]を休[やす]んだ。", "sentence_source": "generated"}, {"text": "風邪で熱が出たので、早く寝ます。", "target_word": "風邪", "complexity_tier": "T3", "furigana": "風邪[かぜ]で熱[ねつ]が出[で]たので、早[はや]く寝[ね]ます。", "sentence_source": "generated"}, {"text": "風邪がなおるまで、プールには入れない。", "target_word": "風邪", "complexity_tier": "T3", "furigana": "風邪[かぜ]がなおるまで、プールには入[はい]れない。", "sentence_source": "generated"}, {"text": "弟は風邪のせいで、せきが止まらない。", "target_word": "風邪", "complexity_tier": "T3", "furigana": "弟[おとうと]は風邪[かぜ]のせいで、せきが止[と]まらない。", "sentence_source": "generated"}, {"text": "冬は風邪をひきやすいから、手をよく洗おう。", "target_word": "風邪", "complexity_tier": "T3", "furigana": "冬[ふゆ]は風邪[かぜ]をひきやすいから、手[て]をよく洗[あら]おう。", "sentence_source": "generated"}, {"text": "風邪を引いたとき、母がおかゆを作ってくれた。", "target_word": "風邪", "complexity_tier": "T3", "furigana": "風邪[かぜ]を引[ひ]いたとき、母[はは]がおかゆを作[つく]ってくれた。", "sentence_source": "generated"}, {"text": "風邪がはやっているので、教室ではマスクをつけている。", "target_word": "風邪", "complexity_tier": "T3", "furigana": "風邪[かぜ]がはやっているので、教室[きょうしつ]ではマスクをつけている。", "sentence_source": "generated"}, {"text": "雨にぬれて帰ったら、次の日に熱が出て、風邪だと言われた。", "target_word": "風邪", "complexity_tier": "T3", "furigana": "雨[あめ]にぬれて帰[かえ]ったら、次[つぎ]の日[ひ]に熱[ねつ]が出[で]て、風邪[かぜ]だと言[い]われた。", "sentence_source": "generated"}, {"text": "風邪の人は、ほかの人にうつさないように気をつけてください。", "target_word": "風邪", "complexity_tier": "T3", "furigana": "風邪[かぜ]の人[ひと]は、ほかの人[ひと]にうつさないように気[き]をつけてください。", "sentence_source": "generated"}, {"text": "医者に風邪だと言われて、薬をもらった。", "target_word": "風邪", "complexity_tier": "T3", "furigana": "医者[いしゃ]に風邪[かぜ]だと言[い]われて、薬[くすり]をもらった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "風邪", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "熱やせきが出る、ふだんの生活でよくかかる軽い病気(かぜ)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 2 above tier T2: contains vocabulary far above tier T2: なおる (Zipf 2.48)']::text[], '9b5f4a63-69ff-4d35-93ef-31c84933d968') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39350, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "風邪", "is_correct": true, "explanation": "正解。「風邪をひく」の形で、ここでは「風邪」が入る。"}, {"text": "咳", "is_correct": false, "explanation": "「咳をひく」とは言わない。咳は「出る」「する」と結びつく。"}, {"text": "鼻水", "is_correct": false, "explanation": "「鼻水をひく」とは言わない。鼻水は「出る」と結びつく。"}, {"text": "花粉症", "is_correct": false, "explanation": "「花粉症をひく」とは言わない。花粉症は「なる」で表す。"}], "explanations": {"風邪": "正解。「風邪をひく」の形で、ここでは「風邪」が入る。", "咳": "「咳をひく」とは言わない。咳は「出る」「する」と結びつく。", "鼻水": "「鼻水をひく」とは言わない。鼻水は「出る」と結びつく。", "花粉症": "「花粉症をひく」とは言わない。花粉症は「なる」で表す。"}, "sentence_index": 0, "correct_answer": "風邪"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "春になると、風邪で毎年くしゃみと目のかゆみが止まらない。", "explanation": "ここは〈花粉症〉の意味。花粉によるくしゃみや目のかゆみには風邪を使わず、花粉症と言う。風邪は熱やせきを伴う病気。"}, {"text": "熱いお湯に手をつけて、風邪で指が赤くなった。", "explanation": "ここは〈火傷〉の意味。熱いもので皮膚が赤くなったりただれたりするのは火傷で、風邪とは言わない。"}, {"text": "真夏に外で長時間働いて、風邪で倒れた。", "explanation": "ここは〈熱中症〉の意味。暑さで体調を崩すことは熱中症と言い、風邪とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'acd1f4a8-eb16-4a36-ad41-5791be3ae06d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39350, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "風邪", "is_correct": true, "explanation": "正解。「風邪がはやる」は流行を表す自然な形。"}, {"text": "熱", "is_correct": false, "explanation": "「熱がはやる」とは言わない。熱は症状で、流行するものではない。"}, {"text": "頭痛", "is_correct": false, "explanation": "「頭痛がはやる」とは言わない。頭痛は個人の症状を指す。"}, {"text": "腹痛", "is_correct": false, "explanation": "「腹痛がはやる」とは言わない。腹痛は個人の症状を指す。"}], "explanations": {"風邪": "正解。「風邪がはやる」は流行を表す自然な形。", "熱": "「熱がはやる」とは言わない。熱は症状で、流行するものではない。", "頭痛": "「頭痛がはやる」とは言わない。頭痛は個人の症状を指す。", "腹痛": "「腹痛がはやる」とは言わない。腹痛は個人の症状を指す。"}, "sentence_index": 6, "correct_answer": "風邪"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "昨夜飲みすぎて、朝は風邪で頭が痛かった。", "explanation": "ここは〈二日酔い〉の意味。飲みすぎによる頭痛は二日酔いと言い、風邪とは言わない。"}, {"text": "海で長時間遊んで、風邪で肩が真っ赤になった。", "explanation": "ここは〈日焼け〉の意味。紫外線で皮膚が赤くなるのは日焼けで、風邪とは言わない。"}, {"text": "夜ふかしして風邪で、一日中眠かった。", "explanation": "ここは〈寝不足〉の意味。睡眠が足りないための眠気は寝不足と言い、風邪とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'acd1f4a8-eb16-4a36-ad41-5791be3ae06d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39350, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "風邪がひいたので、今日は早めに寝ました。", "corrected_sentence": "風邪をひいたので、今日は早めに寝ました。", "error_description": "誤り：「風邪が」→正：「風邪を」。「ひく」は「風邪を」を目的語にとるので、「が」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'acd1f4a8-eb16-4a36-ad41-5791be3ae06d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39350, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "風邪がはやるているので、今週は手洗いを続けよう。", "corrected_sentence": "風邪がはやっているので、今週は手洗いを続けよう。", "error_description": "誤り：「はやるている」→正：「はやっている」。「はやる」は五段動詞なので、「はやっている」の形になる。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'acd1f4a8-eb16-4a36-ad41-5791be3ae06d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39351, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "正解。「風邪は」で定義文の主題を示す。"}, {"text": "に", "is_correct": false, "explanation": "「風邪に、」は対象を示すが、定義文の主題にならない。"}, {"text": "で", "is_correct": false, "explanation": "「風邪で、」は原因の意味になり、定義文として不自然。"}, {"text": "と", "is_correct": false, "explanation": "「風邪と、」は並列になり、ウイルスが病気を起こすという文が成り立たない。"}], "correct_answer": "は", "explanations": {"は": "正解。「風邪は」で定義文の主題を示す。", "に": "「風邪に、」は対象を示すが、定義文の主題にならない。", "で": "「風邪で、」は原因の意味になり、定義文として不自然。", "と": "「風邪と、」は並列になり、ウイルスが病気を起こすという文が成り立たない。"}, "error_tags": {"に": "対象", "で": "原因", "と": "並列"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'acd1f4a8-eb16-4a36-ad41-5791be3ae06d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39351, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "正解。「風邪を押して」は「体調が悪くても」の意味で、「を」が対象を示す。"}, {"text": "へ", "is_correct": false, "explanation": "「風邪へ押して」は方向を表すが、「押す」の対象にならない。"}, {"text": "より", "is_correct": false, "explanation": "「風邪より押して」は比較の意味になり、文が成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "「風邪の押して」は所属を表すが、「押す」の対象にならない。"}], "correct_answer": "を", "explanations": {"を": "正解。「風邪を押して」は「体調が悪くても」の意味で、「を」が対象を示す。", "へ": "「風邪へ押して」は方向を表すが、「押す」の対象にならない。", "より": "「風邪より押して」は比較の意味になり、文が成り立たない。", "の": "「風邪の押して」は所属を表すが、「押す」の対象にならない。"}, "error_tags": {"へ": "方向", "より": "比較", "の": "所属"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'acd1f4a8-eb16-4a36-ad41-5791be3ae06d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39351, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "寒気・発熱・せき・鼻水などが出る、呼吸器の病気。", "primary_collocate": null, "pronunciation": "かぜ", "ipa": "kaze", "syllable_count": 2, "sentences": [{"text": "寒気と鼻水があるので、風邪かもしれない。", "target_word": "風邪", "complexity_tier": "T3", "furigana": "寒気[さむけ]と鼻水[はなみず]があるので、風邪[かぜ]かもしれない。", "sentence_source": "generated"}, {"text": "風邪は、ウイルスが鼻やのどに入って起こる病気だ。", "target_word": "風邪", "complexity_tier": "T3", "furigana": "風邪[かぜ]は、ウイルスが鼻[はな]やのどに入[はい]って起[お]こる病気[びょうき]だ。", "sentence_source": "generated"}, {"text": "風邪で鼻がつまり、夜よく眠れなかった。", "target_word": "風邪", "complexity_tier": "T3", "furigana": "風邪[かぜ]で鼻[はな]がつまり、夜[よる]よく眠[ねむ]れなかった。", "sentence_source": "generated"}, {"text": "季節の変わり目は、風邪を引く人が多い。", "target_word": "風邪", "complexity_tier": "T3", "furigana": "季節[きせつ]の変[か]わり目[め]は、風邪[かぜ]を引[ひ]く人[ひと]が多[おお]い。", "sentence_source": "generated"}, {"text": "風邪をこじらせて、一週間ほど会社を休んだ。", "target_word": "風邪", "complexity_tier": "T3", "furigana": "風邪[かぜ]をこじらせて、一週間[いっしゅうかん]ほど会社[かいしゃ]を休[やす]んだ。", "sentence_source": "generated"}, {"text": "のどが痛くなったら、風邪の始まりかもしれない。", "target_word": "風邪", "complexity_tier": "T3", "furigana": "のどが痛[いた]くなったら、風邪[かぜ]の始[はじ]まりかもしれない。", "sentence_source": "generated"}, {"text": "風邪には、ゆっくり休んで水分をとるのがいちばんだ。", "target_word": "風邪", "complexity_tier": "T3", "furigana": "風邪[かぜ]には、ゆっくり休[やす]んで水分[すいぶん]をとるのがいちばんだ。", "sentence_source": "generated"}, {"text": "彼女は風邪を押して、大切な発表に出た。", "target_word": "風邪", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は風邪[かぜ]を押[お]して、大切[たいせつ]な発表[はっぴょう]に出[で]た。", "sentence_source": "generated"}, {"text": "風邪がうつるといけないので、祖母の見舞いは延期した。", "target_word": "風邪", "complexity_tier": "T3", "furigana": "風邪[かぜ]がうつるといけないので、祖母[そぼ]の見舞[みま]いは延期[えんき]した。", "sentence_source": "generated"}, {"text": "風邪の症状が三日たっても続くなら、病院で診てもらったほうがいい。", "target_word": "風邪", "complexity_tier": "T3", "furigana": "風邪[かぜ]の症状[しょうじょう]が三日[みっか]たっても続[つづ]くなら、病院[びょういん]で診[み]てもらったほうがいい。", "sentence_source": "generated"}], "morphological_forms": [{"form": "風邪", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "寒気・発熱・せき・鼻水などの症状が出る呼吸器の病気(感冒)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b5f4a63-69ff-4d35-93ef-31c84933d968') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39351, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "風邪", "is_correct": true, "explanation": "正解。寒気や鼻水の症状から、風邪の可能性を述べる文になる。"}, {"text": "骨折", "is_correct": false, "explanation": "骨が折れる怪我で、寒気や鼻水の症状とは結びつかない。"}, {"text": "火傷", "is_correct": false, "explanation": "熱いもので皮膚を傷つける怪我で、寒気や鼻水とは結びつかない。"}, {"text": "脱臼", "is_correct": false, "explanation": "関節が外れる怪我で、寒気や鼻水とは結びつかない。"}], "explanations": {"風邪": "正解。寒気や鼻水の症状から、風邪の可能性を述べる文になる。", "骨折": "骨が折れる怪我で、寒気や鼻水の症状とは結びつかない。", "火傷": "熱いもので皮膚を傷つける怪我で、寒気や鼻水とは結びつかない。", "脱臼": "関節が外れる怪我で、寒気や鼻水とは結びつかない。"}, "sentence_index": 0, "correct_answer": "風邪"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "重い荷物を持ち上げて、風邪で一週間動けなかった。", "explanation": "ここは〈腰痛〉の意味。重い物を持って腰を痛めた場合は腰痛と言い、風邪とは言わない。"}, {"text": "夏の草むらで遊んで、風邪で腕がかゆくなった。", "explanation": "ここは〈虫刺され〉の意味。虫に刺されて皮膚がかゆくなるのは虫刺されで、風邪とは言わない。"}, {"text": "転んで足を痛めて、風邪のためにギプスをはめた。", "explanation": "ここは〈骨折〉の意味。骨が折れた治療にギプスを使うので、風邪とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'acd1f4a8-eb16-4a36-ad41-5791be3ae06d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39351, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "風邪", "is_correct": true, "explanation": "正解。風邪は、ゆっくり休んで水分をとる対処が合う病気。"}, {"text": "打撲", "is_correct": false, "explanation": "打撲は冷やして安静にする対処が一般的で、水分をとる対処とは合わない。"}, {"text": "切り傷", "is_correct": false, "explanation": "切り傷は傷を洗って手当てするもので、水分をとる対処とは合わない。"}, {"text": "虫歯", "is_correct": false, "explanation": "虫歯は歯医者で治療するもので、ゆっくり休んで水分をとる対処とは合わない。"}], "explanations": {"風邪": "正解。風邪は、ゆっくり休んで水分をとる対処が合う病気。", "打撲": "打撲は冷やして安静にする対処が一般的で、水分をとる対処とは合わない。", "切り傷": "切り傷は傷を洗って手当てするもので、水分をとる対処とは合わない。", "虫歯": "虫歯は歯医者で治療するもので、ゆっくり休んで水分をとる対処とは合わない。"}, "sentence_index": 6, "correct_answer": "風邪"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "急に立ち上がったら、風邪で目の前が暗くなった。", "explanation": "ここは〈立ちくらみ〉の意味。急な立ち上がりで一時的に目の前が暗くなることは、風邪とは言わない。"}, {"text": "夏の間、靴の中で風邪がひどくなった。", "explanation": "ここは〈水虫〉の意味。足の皮膚の病気は水虫と言い、風邪とは言わない。"}, {"text": "血が足りなくて風邪になり、立っていられなかった。", "explanation": "ここは〈貧血〉の意味。血液が不足する症状は貧血と言い、風邪とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'acd1f4a8-eb16-4a36-ad41-5791be3ae06d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39351, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "寒い日は、風邪に引く人が増える。", "corrected_sentence": "寒い日は、風邪を引く人が増える。", "error_description": "誤り：「風邪に」→正：「風邪を」。「引く」は「風邪を引く」の形で、目的語に「を」をとる。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'acd1f4a8-eb16-4a36-ad41-5791be3ae06d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39351, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "風邪に続くなら、早めに受診しよう。", "corrected_sentence": "風邪が続くなら、早めに受診しよう。", "error_description": "誤り：「風邪に」→正：「風邪が」。「続く」は主語に「が」をとるので、「に」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'acd1f4a8-eb16-4a36-ad41-5791be3ae06d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39352, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "正解。「碑が建てられた」は受身の主語を示す。"}, {"text": "を", "is_correct": false, "explanation": "「碑を建てられた」は不自然。受身の文では「碑が」が主語になる。"}, {"text": "へ", "is_correct": false, "explanation": "「碑へ建てられた」は方向を表すが、建てられる対象にはならない。"}, {"text": "と", "is_correct": false, "explanation": "「碑と建てられた」は並列になり、文が成り立たない。"}], "correct_answer": "が", "explanations": {"が": "正解。「碑が建てられた」は受身の主語を示す。", "を": "「碑を建てられた」は不自然。受身の文では「碑が」が主語になる。", "へ": "「碑へ建てられた」は方向を表すが、建てられる対象にはならない。", "と": "「碑と建てられた」は並列になり、文が成り立たない。"}, "error_tags": {"を": "目的語", "へ": "方向", "と": "並列"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'acd1f4a8-eb16-4a36-ad41-5791be3ae06d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
