INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39352, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "いしをたてて、そのひょうじやきねんのためのもの。", "primary_collocate": null, "pronunciation": "ひ", "ipa": "çi", "syllable_count": 1, "sentences": [{"text": "公園の入り口に、町の歴史を記した碑が立っている。", "target_word": "碑", "complexity_tier": "T3", "furigana": "公園[こうえん]の入[い]り口[ぐち]に、町[まち]の歴史[れきし]を記[しる]した碑[ひ]が立[た]っている。", "sentence_source": "generated"}, {"text": "地震で亡くなった人を忘れないために、海辺に碑が建てられた。", "target_word": "碑", "complexity_tier": "T3", "furigana": "地震[じしん]で亡[な]くなった人[ひと]を忘[わす]れないために、海辺[うみべ]に碑[ひ]が建[た]てられた。", "sentence_source": "generated"}, {"text": "碑には有名な詩の一節が刻まれている。", "target_word": "碑", "complexity_tier": "T3", "furigana": "碑[ひ]には有名[ゆうめい]な詩[し]の一節[いっせつ]が刻[きざ]まれている。", "sentence_source": "generated"}, {"text": "古い碑の文字は、雨と風で読みにくくなった。", "target_word": "碑", "complexity_tier": "T3", "furigana": "古[ふる]い碑[ひ]の文字[もじ]は、雨[あめ]と風[かぜ]で読[よ]みにくくなった。", "sentence_source": "generated"}, {"text": "祖父は戦争で亡くなった友人のために、村に碑を建てた。", "target_word": "碑", "complexity_tier": "T3", "furigana": "祖父[そふ]は戦争[せんそう]で亡[な]くなった友人[ゆうじん]のために、村[むら]に碑[ひ]を建[た]てた。", "sentence_source": "generated"}, {"text": "山道の途中にある碑の前で、私たちは写真を撮った。", "target_word": "碑", "complexity_tier": "T3", "furigana": "山道[やまみち]の途中[とちゅう]にある碑[ひ]の前[まえ]で、私[わたし]たちは写真[しゃしん]を撮[と]った。", "sentence_source": "generated"}, {"text": "碑に刻まれた名前を、ゆっくり指でなぞった。", "target_word": "碑", "complexity_tier": "T3", "furigana": "碑[ひ]に刻[きざ]まれた名前[なまえ]を、ゆっくり指[ゆび]でなぞった。", "sentence_source": "generated"}, {"text": "町の人は毎年、碑の周りの草をきれいに取っている。", "target_word": "碑", "complexity_tier": "T3", "furigana": "町[まち]の人[ひと]は毎年[まいとし]、碑[ひ]の周[まわ]りの草[くさ]をきれいに取[と]っている。", "sentence_source": "generated"}, {"text": "この碑は、百年前の大きな火事があったことを今に伝えている。", "target_word": "碑", "complexity_tier": "T3", "furigana": "この碑[ひ]は、百年前[ひゃくねんまえ]の大[おお]きな火事[かじ]があったことを今[いま]に伝[つた]えている。", "sentence_source": "generated"}, {"text": "観光客が碑の説明を読んで、この場所の歴史を知った。", "target_word": "碑", "complexity_tier": "T3", "furigana": "観光客[かんこうきゃく]が碑[ひ]の説明[せつめい]を読[よ]んで、この場所[ばしょ]の歴史[れきし]を知[し]った。", "sentence_source": "generated"}], "morphological_forms": [{"form": "碑", "label": "基本形"}], "register": "中立", "sense_fingerprint": "出来事や人を記念し、文字を刻んで石で建てたもの", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b5f4a63-69ff-4d35-93ef-31c84933d968') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39352, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "碑", "is_correct": true, "explanation": "正解。「碑が立っている」は、文字を刻んで建てた石として自然。"}, {"text": "財布", "is_correct": false, "explanation": "財布は立てて置くものではなく、「立っている」とは言わない。"}, {"text": "切手", "is_correct": false, "explanation": "切手は貼るもので、立っているものではないので「立っている」とは言わない。"}, {"text": "手紙", "is_correct": false, "explanation": "手紙は立つものではなく、「立っている」とは言わない。"}], "explanations": {"碑": "正解。「碑が立っている」は、文字を刻んで建てた石として自然。", "財布": "財布は立てて置くものではなく、「立っている」とは言わない。", "切手": "切手は貼るもので、立っているものではないので「立っている」とは言わない。", "手紙": "手紙は立つものではなく、「立っている」とは言わない。"}, "sentence_index": 0, "correct_answer": "碑"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "店の名前を書いた碑を、通りに向けて掛けた。", "explanation": "ここは〈看板〉の意味。店の名前を掲げて掛ける物は看板で、碑とは言わない。"}, {"text": "玄関の碑に、毎朝新聞が入っている。", "explanation": "ここは〈郵便受け〉の意味。新聞や手紙を受け取る箱は郵便受けで、碑とは言わない。"}, {"text": "教室の碑に、今日の授業の内容を書いた。", "explanation": "ここは〈黒板〉の意味。授業内容を書く板は黒板で、碑とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'acd1f4a8-eb16-4a36-ad41-5791be3ae06d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39352, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "碑", "is_correct": true, "explanation": "正解。「碑に刻まれた名前」は石などに彫られた文字を指す自然な表現。"}, {"text": "日記", "is_correct": false, "explanation": "「刻まれた」は石や金属に使う。日記には刻まないので不自然。"}, {"text": "新聞", "is_correct": false, "explanation": "「刻まれた」は石や金属に使う。新聞には刻まないので不自然。"}, {"text": "手帳", "is_correct": false, "explanation": "「刻まれた」は石や金属に使う。手帳には刻まないので不自然。"}], "explanations": {"碑": "正解。「碑に刻まれた名前」は石などに彫られた文字を指す自然な表現。", "日記": "「刻まれた」は石や金属に使う。日記には刻まないので不自然。", "新聞": "「刻まれた」は石や金属に使う。新聞には刻まないので不自然。", "手帳": "「刻まれた」は石や金属に使う。手帳には刻まないので不自然。"}, "sentence_index": 6, "correct_answer": "碑"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "観光客に碑を配って、この場所の歴史を知らせた。", "explanation": "ここは〈パンフレット〉の意味。案内の紙を配って伝えるのはパンフレットで、碑とは言わない。"}, {"text": "わからない単語は、碑で意味を調べた。", "explanation": "ここは〈辞書〉の意味。単語の意味を調べる本は辞書で、碑とは言わない。"}, {"text": "古い碑を集めて、アルバムに貼った。", "explanation": "ここは〈切手〉の意味。郵便に使い、アルバムに貼る紙は切手で、碑とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'acd1f4a8-eb16-4a36-ad41-5791be3ae06d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39352, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "公園の広場に、戦争の記録を刻んだ碑で建っている。", "corrected_sentence": "公園の広場に、戦争の記録を刻んだ碑が建っている。", "error_description": "誤り：「碑で」→正：「碑が」。「建っている」の主語は「碑が」で、「で」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'acd1f4a8-eb16-4a36-ad41-5791be3ae06d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39352, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "碑に刻むれた文字を、祖母は毎年なぞっている。", "corrected_sentence": "碑に刻まれた文字を、祖母は毎年なぞっている。", "error_description": "誤り：「刻むれた」→正：「刻まれた」。「刻む」の受身は「刻まれる」で、「刻むれる」とは言わない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'acd1f4a8-eb16-4a36-ad41-5791be3ae06d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39353, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "正解。「碑には」で、文字が彫られている場所を示す。"}, {"text": "を", "is_correct": false, "explanation": "「碑を、…彫られている」は目的語になり、文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「碑へ、…彫られている」は方向を表し、彫られている場所を示せない。"}, {"text": "が", "is_correct": false, "explanation": "「碑がは」は「が」と「は」が重なり、成立しない。"}], "correct_answer": "に", "explanations": {"に": "正解。「碑には」で、文字が彫られている場所を示す。", "を": "「碑を、…彫られている」は目的語になり、文が成り立たない。", "へ": "「碑へ、…彫られている」は方向を表し、彫られている場所を示せない。", "が": "「碑がは」は「が」と「は」が重なり、成立しない。"}, "error_tags": {"を": "目的語", "へ": "方向", "が": "助詞の重複"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'acd1f4a8-eb16-4a36-ad41-5791be3ae06d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39353, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "正解。「碑の表面」は碑に属する表面を表す。"}, {"text": "を", "is_correct": false, "explanation": "「碑を表面に苔が生えて」は、生えるが目的語をとらず不自然。"}, {"text": "に", "is_correct": false, "explanation": "「碑に表面に苔が生えて」は場所を二つ重ねることになり、不自然。"}, {"text": "より", "is_correct": false, "explanation": "「碑より表面に苔が生えて」は比較の意味になり、文が成り立たない。"}], "correct_answer": "の", "explanations": {"の": "正解。「碑の表面」は碑に属する表面を表す。", "を": "「碑を表面に苔が生えて」は、生えるが目的語をとらず不自然。", "に": "「碑に表面に苔が生えて」は場所を二つ重ねることになり、不自然。", "より": "「碑より表面に苔が生えて」は比較の意味になり、文が成り立たない。"}, "error_tags": {"に": "場所の重複", "より": "比較", "を": "目的語"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'acd1f4a8-eb16-4a36-ad41-5791be3ae06d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39353, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "石や金属などで作られた、文字や絵を刻んだりして建てたもの。記念や案内のために使われる。", "primary_collocate": null, "pronunciation": "ひ", "ipa": "çi", "syllable_count": 1, "sentences": [{"text": "駅の前に、町の名前の由来を書いた碑がある。", "target_word": "碑", "complexity_tier": "T3", "furigana": "駅[えき]の前[まえ]に、町[まち]の名前[なまえ]の由来[ゆらい]を書[か]いた碑[ひ]がある。", "sentence_source": "generated"}, {"text": "青銅でできた碑には、この橋を作った人の名前が彫られている。", "target_word": "碑", "complexity_tier": "T3", "furigana": "青銅[せいどう]でできた碑[ひ]には、この橋[はし]を作[つく]った人[ひと]の名前[なまえ]が彫[ほ]られている。", "sentence_source": "generated"}, {"text": "森の入り口の碑には、散歩道の地図が刻まれている。", "target_word": "碑", "complexity_tier": "T3", "furigana": "森[もり]の入り口[いりぐち]の碑[ひ]には、散歩道[さんぽみち]の地図[ちず]が刻[きざ]まれている。", "sentence_source": "generated"}, {"text": "校庭の隅に、卒業生が贈った碑が静かに立っている。", "target_word": "碑", "complexity_tier": "T3", "furigana": "校庭[こうてい]の隅[すみ]に、卒業生[そつぎょうせい]が贈[おく]った碑[ひ]が静[しず]かに立[た]っている。", "sentence_source": "generated"}, {"text": "碑の前には、いつも誰かが花を供えている。", "target_word": "碑", "complexity_tier": "T3", "furigana": "碑[ひ]の前[まえ]には、いつも誰[だれ]かが花[はな]を供[そな]えている。", "sentence_source": "generated"}, {"text": "大きな石の碑に、この土地を開いた人々の言葉が彫られていた。", "target_word": "碑", "complexity_tier": "T3", "furigana": "大[おお]きな石[いし]の碑[ひ]に、この土地[とち]を開[ひら]いた人々[ひとびと]の言葉[ことば]が彫[ほ]られていた。", "sentence_source": "generated"}, {"text": "新しい碑ができた日、町の人が集まって手を合わせた。", "target_word": "碑", "complexity_tier": "T3", "furigana": "新[あたら]しい碑[ひ]ができた日[ひ]、町[まち]の人[ひと]が集[あつ]まって手[て]を合[あ]わせた。", "sentence_source": "generated"}, {"text": "碑の表面に苔が生えて、字がほとんど見えなくなった。", "target_word": "碑", "complexity_tier": "T3", "furigana": "碑[ひ]の表面[ひょうめん]に苔[こけ]が生[は]えて、字[じ]がほとんど見[み]えなくなった。", "sentence_source": "generated"}, {"text": "歴史の先生は、碑を見ながら、この戦いの話をしてくれた。", "target_word": "碑", "complexity_tier": "T3", "furigana": "歴史[れきし]の先生[せんせい]は、碑[ひ]を見[み]ながら、この戦[たたか]いの話[はなし]をしてくれた。", "sentence_source": "generated"}, {"text": "川のそばの碑は、昔の洪水の高さを示している。", "target_word": "碑", "complexity_tier": "T3", "furigana": "川[かわ]のそばの碑[ひ]は、昔[むかし]の洪水[こうずい]の高[たか]さを示[しめ]している。", "sentence_source": "generated"}], "morphological_forms": [{"form": "碑", "label": "基本形"}], "register": "中立", "sense_fingerprint": "石や金属に文字や絵を刻み、記念や案内のために建てた物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b5f4a63-69ff-4d35-93ef-31c84933d968') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39353, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "碑", "is_correct": true, "explanation": "正解。「碑がある」で、町の由来を刻んだ碑の存在を示す。"}, {"text": "電柱", "is_correct": false, "explanation": "電柱は電線を支える柱で、由来を書いたものではない。"}, {"text": "信号機", "is_correct": false, "explanation": "信号機は交通を制御する装置で、由来を書いたものではない。"}, {"text": "自動販売機", "is_correct": false, "explanation": "自動販売機は飲み物を売る機械で、由来を書いたものではない。"}], "explanations": {"碑": "正解。「碑がある」で、町の由来を刻んだ碑の存在を示す。", "電柱": "電柱は電線を支える柱で、由来を書いたものではない。", "信号機": "信号機は交通を制御する装置で、由来を書いたものではない。", "自動販売機": "自動販売機は飲み物を売る機械で、由来を書いたものではない。"}, "sentence_index": 0, "correct_answer": "碑"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "校門の横に、行事のお知らせを貼る碑がある。", "explanation": "ここは〈掲示板〉の意味。紙を貼って知らせる板は掲示板で、碑とは言わない。"}, {"text": "台所の碑に、牛乳を入れて冷やした。", "explanation": "ここは〈冷蔵庫〉の意味。食品を入れて冷やす箱は冷蔵庫で、碑とは言わない。"}, {"text": "角の碑に、手紙を入れた。", "explanation": "ここは〈郵便ポスト〉の意味。手紙を入れて投函する箱は郵便ポストで、碑とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'acd1f4a8-eb16-4a36-ad41-5791be3ae06d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39353, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "碑", "is_correct": true, "explanation": "正解。「新しい碑ができた日」は記念の碑の完成を表し、手を合わせる場面に合う。"}, {"text": "冷蔵庫", "is_correct": false, "explanation": "冷蔵庫では、町の人が手を合わせる場面と文の流れが合わない。"}, {"text": "洗濯機", "is_correct": false, "explanation": "洗濯機では、町の人が手を合わせる場面と文の流れが合わない。"}, {"text": "自転車", "is_correct": false, "explanation": "自転車では、町の人が手を合わせる場面と文の流れが合わない。"}], "explanations": {"碑": "正解。「新しい碑ができた日」は記念の碑の完成を表し、手を合わせる場面に合う。", "冷蔵庫": "冷蔵庫では、町の人が手を合わせる場面と文の流れが合わない。", "洗濯機": "洗濯機では、町の人が手を合わせる場面と文の流れが合わない。", "自転車": "自転車では、町の人が手を合わせる場面と文の流れが合わない。"}, "sentence_index": 6, "correct_answer": "碑"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "交差点の碑は、制限速度を示している。", "explanation": "ここは〈標識〉の意味。道路で規制や速度を知らせるのは標識で、碑とは言わない。"}, {"text": "窓の外の碑は、今日の気温を示している。", "explanation": "ここは〈温度計〉の意味。気温を測って示す器具は温度計で、碑とは言わない。"}, {"text": "洗面所の碑は、毎朝の体重を示している。", "explanation": "ここは〈体重計〉の意味。体重を量る器具は体重計で、碑とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'acd1f4a8-eb16-4a36-ad41-5791be3ae06d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39353, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "橋のたもとに、この川の洪水の記録を刻んだ碑を立っている。", "corrected_sentence": "橋のたもとに、この川の洪水の記録を刻んだ碑が立っている。", "error_description": "誤り：「碑を」→正：「碑が」。「立っている」は主語の「が」をとるので、「を」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'acd1f4a8-eb16-4a36-ad41-5791be3ae06d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39353, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "新しい碑が建たった日、町の人は集まって祈った。", "corrected_sentence": "新しい碑が建った日、町の人は集まって祈った。", "error_description": "誤り：「建たった」→正：「建った」。「建つ」の過去形は「建った」で、「建たった」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'acd1f4a8-eb16-4a36-ad41-5791be3ae06d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39354, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「買い物をしました」の「を」は、する対象を示す。"}, {"text": "で", "is_correct": false, "explanation": "「買い物でしました」は、手段や場所の「で」になり、文の構造が合わない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す「へ」は、「買い物へしました」の形では意味が通らない。"}, {"text": "が", "is_correct": false, "explanation": "「買い物がしました」は主語を示す「が」になり、文の意味が合わない。"}], "correct_answer": "を", "explanations": {"を": "「買い物をしました」の「を」は、する対象を示す。", "で": "「買い物でしました」は、手段や場所の「で」になり、文の構造が合わない。", "へ": "方向を示す「へ」は、「買い物へしました」の形では意味が通らない。", "が": "「買い物がしました」は主語を示す「が」になり、文の意味が合わない。"}, "error_tags": {"で": "場所・手段", "へ": "方向", "が": "主語"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '857b05e2-117b-40fe-ab0d-ff0f63daa36d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39354, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '857b05e2-117b-40fe-ab0d-ff0f63daa36d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39354, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "何かの行為を行うこと。散歩・買い物・運動などに使う。", "primary_collocate": null, "pronunciation": "する", "ipa": "sɯɾɯ", "syllable_count": 2, "sentences": [{"text": "毎朝、公園で散歩をします。", "target_word": "します", "complexity_tier": "T3", "furigana": "毎朝[まいあさ]、公園[こうえん]で散歩[さんぽ]をします。", "sentence_source": "generated"}, {"text": "昨日は友達と買い物をしました。", "target_word": "しました", "complexity_tier": "T3", "furigana": "昨日[きのう]は友達[ともだち]と買[か]い物[もの]をしました。", "sentence_source": "generated"}, {"text": "休みの日は、あまり何もしません。", "target_word": "しません", "complexity_tier": "T3", "furigana": "休[やす]みの日[ひ]は、あまり何[なに]もしません。", "sentence_source": "generated"}, {"text": "夕食のあとで、宿題をします。", "target_word": "します", "complexity_tier": "T3", "furigana": "夕食[ゆうしょく]のあとで、宿題[しゅくだい]をします。", "sentence_source": "generated"}, {"text": "週末に、いっしょにサッカーをしましょう。", "target_word": "しましょう", "complexity_tier": "T3", "furigana": "週末[しゅうまつ]に、いっしょにサッカーをしましょう。", "sentence_source": "generated"}, {"text": "去年の夏、家族と旅行をしました。", "target_word": "しました", "complexity_tier": "T3", "furigana": "去年[きょねん]の夏[なつ]、家族[かぞく]と旅行[りょこう]をしました。", "sentence_source": "generated"}, {"text": "寝る前に、少し運動をします。", "target_word": "します", "complexity_tier": "T3", "furigana": "寝[ね]る前[まえ]に、少[すこ]し運動[うんどう]をします。", "sentence_source": "generated"}, {"text": "日曜日は何をしますか。", "target_word": "します", "complexity_tier": "T3", "furigana": "日曜日[にちようび]は何[なに]をしますか。", "sentence_source": "generated"}, {"text": "風邪をひいたので、今日は運動をしません。", "target_word": "しません", "complexity_tier": "T3", "furigana": "風邪[かぜ]をひいたので、今日[きょう]は運動[うんどう]をしません。", "sentence_source": "generated"}, {"text": "先週、駅の前で友達と待ち合わせをしました。", "target_word": "しました", "complexity_tier": "T3", "furigana": "先週[せんしゅう]、駅[えき]の前[まえ]で友達[ともだち]と待[ま]ち合[あ]わせをしました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "します", "label": "ます形"}, {"form": "しました", "label": "過去形（ました）"}, {"form": "しません", "label": "否定形（ません）"}, {"form": "しませんでした", "label": "過去否定形"}, {"form": "しましょう", "label": "意向形（ましょう）"}], "register": "polite", "sense_fingerprint": "散歩・買い物・運動など、何らかの行為を行う", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8451f182-b416-4156-a958-f234e1ab7309') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39354, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "します", "is_correct": true, "explanation": "「散歩をします」は、散歩という行為をするという意味になり、文に合う。"}, {"text": "食べます", "is_correct": false, "explanation": "食べるは食べ物を口にすること。「散歩を食べます」は意味が通らない。"}, {"text": "読みます", "is_correct": false, "explanation": "読むは文字や文章を見て理解すること。散歩とは結びつかない。"}, {"text": "眠ります", "is_correct": false, "explanation": "眠るは寝ること。「散歩を眠ります」は意味が通らない。"}], "explanations": {"します": "「散歩をします」は、散歩という行為をするという意味になり、文に合う。", "食べます": "食べるは食べ物を口にすること。「散歩を食べます」は意味が通らない。", "読みます": "読むは文字や文章を見て理解すること。散歩とは結びつかない。", "眠ります": "眠るは寝ること。「散歩を眠ります」は意味が通らない。"}, "sentence_index": 0, "correct_answer": "します"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "教室には、古い机がします。", "explanation": "ここは〈ある〉の意味。「する」は人や物の動作を表すので、物があることを表す文には使わない。"}, {"text": "私は英語がします。", "explanation": "ここは〈できる〉の意味。「する」は行為を表すので、能力があることを表す文には使わない。"}, {"text": "この説明の意味がします。", "explanation": "ここは〈わかる〉の意味。「する」は行為を表すので、内容を理解する意味では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '857b05e2-117b-40fe-ab0d-ff0f63daa36d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39354, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "します", "is_correct": true, "explanation": "「運動をします」は、運動という行為をするという意味になり、文に合う。"}, {"text": "思います", "is_correct": false, "explanation": "思うは考えること。「運動を思います」は意味が通らない。"}, {"text": "聞きます", "is_correct": false, "explanation": "聞くは音や話を受け取ること。「運動を聞きます」は意味が通らない。"}, {"text": "書きます", "is_correct": false, "explanation": "書くは文字を記すこと。「運動を書きます」は意味が通らない。"}], "explanations": {"します": "「運動をします」は、運動という行為をするという意味になり、文に合う。", "思います": "思うは考えること。「運動を思います」は意味が通らない。", "聞きます": "聞くは音や話を受け取ること。「運動を聞きます」は意味が通らない。", "書きます": "書くは文字を記すこと。「運動を書きます」は意味が通らない。"}, "sentence_index": 6, "correct_answer": "します"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "昨日、ようやく荷物がしました。", "explanation": "ここは〈届く〉の意味。「する」は行為を表すので、品物が到着する意味では使わない。"}, {"text": "古いパソコンが、突然しました。", "explanation": "ここは〈壊れる〉の意味。「する」は行為を表すので、機械が故障する意味では使わない。"}, {"text": "午後から雨がしました。", "explanation": "ここは〈降る〉の意味。「する」は行為を表すので、雨が落ちてくる現象には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '857b05e2-117b-40fe-ab0d-ff0f63daa36d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39354, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "昨日は弟と公園で運動をするました。", "corrected_sentence": "昨日は弟と公園で運動をしました。", "error_description": "活用の誤り。「する」の丁寧な過去形は「し」に「ました」をつけた「しました」で、「するました」とは言わない。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "しました", "is_correct": true, "explanation": "過去の出来事を丁寧に述べる「ました形」で、文に合う。"}, {"text": "しません", "is_correct": false, "explanation": "否定の丁寧形で「しない」の意味。過去にした行為を述べる文には合わない。"}, {"text": "しませんでした", "is_correct": false, "explanation": "過去の否定形で「買い物をしなかった」の意味。文は買い物をしたことを述べているので逆になる。"}, {"text": "しましょう", "is_correct": false, "explanation": "勧誘や意向を表す形。過去の出来事には使わない。"}], "correct_form": "しました", "base_form": "する", "form_label": "過去形（ました）", "sentence_index": 1, "explanations": {"しました": "過去の出来事を丁寧に述べる「ました形」で、文に合う。", "しません": "否定の丁寧形で「しない」の意味。過去にした行為を述べる文には合わない。", "しませんでした": "過去の否定形で「買い物をしなかった」の意味。文は買い物をしたことを述べているので逆になる。", "しましょう": "勧誘や意向を表す形。過去の出来事には使わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '857b05e2-117b-40fe-ab0d-ff0f63daa36d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39354, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "毎晩、家で少し運動がします。", "corrected_sentence": "毎晩、家で少し運動をします。", "error_description": "助詞の誤り。「運動をする」の対象は「を」で示す。「が」にすると、運動が主語になり意味が通らない。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "します", "is_correct": true, "explanation": "丁寧な現在の形で、質問「何をしますか」として正しい。"}, {"text": "した", "is_correct": false, "explanation": "過去の形。日曜日の予定を聞く質問には合わない。"}, {"text": "して", "is_correct": false, "explanation": "て形で、単独で文を終えられない。"}, {"text": "しない", "is_correct": false, "explanation": "否定の形で「何もしない」の意味になり、予定を尋ねる文と合わない。"}], "correct_form": "します", "base_form": "する", "form_label": "ます形", "sentence_index": 7, "explanations": {"します": "丁寧な現在の形で、質問「何をしますか」として正しい。", "した": "過去の形。日曜日の予定を聞く質問には合わない。", "して": "て形で、単独で文を終えられない。", "しない": "否定の形で「何もしない」の意味になり、予定を尋ねる文と合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '857b05e2-117b-40fe-ab0d-ff0f63daa36d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39356, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「封をせずに」の「封」は「する」の対象なので、対象を示す「を」が正しい。"}, {"text": "が", "is_correct": false, "explanation": "「封がせずに」は、封が何かをする形にならず文が成り立たない。「せずに」は対象を「を」で取る。"}, {"text": "で", "is_correct": false, "explanation": "「封でせずに」は手段の意味にならず、「せずに」の対象を示せない。"}, {"text": "から", "is_correct": false, "explanation": "「封からせずに」は起点を表すが、「せずに」の対象を示すことはできない。"}], "correct_answer": "を", "explanations": {"を": "「封をせずに」の「封」は「する」の対象なので、対象を示す「を」が正しい。", "が": "「封がせずに」は、封が何かをする形にならず文が成り立たない。「せずに」は対象を「を」で取る。", "で": "「封でせずに」は手段の意味にならず、「せずに」の対象を示せない。", "から": "「封からせずに」は起点を表すが、「せずに」の対象を示すことはできない。"}, "error_tags": {"が": "主格", "で": "手段", "から": "起点"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'acd1f4a8-eb16-4a36-ad41-5791be3ae06d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39356, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'acd1f4a8-eb16-4a36-ad41-5791be3ae06d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39356, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "ふくろや てがみの くちを とじる こと。", "primary_collocate": null, "pronunciation": "ふう", "ipa": "ɸɯː", "syllable_count": 2, "sentences": [{"text": "手紙を書き終えて、封をした。", "target_word": "封", "complexity_tier": "T3", "furigana": "手紙[てがみ]を書[か]き終[お]えて、封[ふう]をした。", "sentence_source": "generated"}, {"text": "急いでいたので、封をせずに手紙を出してしまった。", "target_word": "封", "complexity_tier": "T3", "furigana": "急[いそ]いでいたので、封[ふう]をせずに手紙[てがみ]を出[だ]してしまった。", "sentence_source": "generated"}, {"text": "封の仕方が雑だったので、手紙が途中で開いてしまった。", "target_word": "封", "complexity_tier": "T3", "furigana": "封[ふう]の仕方[しかた]が雑[ざつ]だったので、手紙[てがみ]が途中[とちゅう]で開[ひら]いてしまった。", "sentence_source": "generated"}, {"text": "袋の封をしっかり閉じないと、お菓子が湿ってしまう。", "target_word": "封", "complexity_tier": "T3", "furigana": "袋[ふくろ]の封[ふう]をしっかり閉[と]じないと、お菓子[かし]が湿[しめ]ってしまう。", "sentence_source": "generated"}, {"text": "大切な書類なので、封をする前にもう一度確かめた。", "target_word": "封", "complexity_tier": "T3", "furigana": "大切[たいせつ]な書類[しょるい]なので、封[ふう]をする前[まえ]にもう一度[いちど]確[たし]かめた。", "sentence_source": "generated"}, {"text": "封をしたあとで、宛名を書き忘れたことに気づいた。", "target_word": "封", "complexity_tier": "T3", "furigana": "封[ふう]をしたあとで、宛名[あてな]を書[か]き忘[わす]れたことに気[き]づいた。", "sentence_source": "generated"}, {"text": "封を忘れたまま送ったので、中身が途中で飛び出してしまった。", "target_word": "封", "complexity_tier": "T3", "furigana": "封[ふう]を忘[わす]れたまま送[おく]ったので、中身[なかみ]が途中[とちゅう]で飛[と]び出[だ]してしまった。", "sentence_source": "generated"}, {"text": "荷物を送る前に、袋の封をテープで留めた。", "target_word": "封", "complexity_tier": "T3", "furigana": "荷物[にもつ]を送[おく]る前[まえ]に、袋[ふくろ]の封[ふう]をテープで留[と]めた。", "sentence_source": "generated"}, {"text": "昔は手紙に封をするとき、ろうを使うことが多かった。", "target_word": "封", "complexity_tier": "T3", "furigana": "昔[むかし]は手紙[てがみ]に封[ふう]をするとき、ろうを使[つか]うことが多[おお]かった。", "sentence_source": "generated"}, {"text": "封がされていない手紙は、途中で中身を見られるかもしれない。", "target_word": "封", "complexity_tier": "T3", "furigana": "封[ふう]がされていない手紙[てがみ]は、途中[とちゅう]で中身[なかみ]を見[み]られるかもしれない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "封", "label": "基本形"}], "register": "中立", "sense_fingerprint": "手紙や袋の口を閉じて中身が出ないようにすること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b5f4a63-69ff-4d35-93ef-31c84933d968') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39356, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "封", "is_correct": true, "explanation": "「手紙を書き終えて、封をした」で、手紙の口を閉じる動作を表す。正しい。"}, {"text": "紙", "is_correct": false, "explanation": "「紙をした」は成り立たない。手紙の口を閉じる動作の対象にならない。"}, {"text": "箱", "is_correct": false, "explanation": "「箱をした」は手紙の文脈で意味が通らない。封は袋や手紙の口を閉じる行為を指す。"}, {"text": "切手", "is_correct": false, "explanation": "「切手をした」は不自然。切手は貼るもので、封をする対象ではない。"}], "explanations": {"封": "「手紙を書き終えて、封をした」で、手紙の口を閉じる動作を表す。正しい。", "紙": "「紙をした」は成り立たない。手紙の口を閉じる動作の対象にならない。", "箱": "「箱をした」は手紙の文脈で意味が通らない。封は袋や手紙の口を閉じる行為を指す。", "切手": "「切手をした」は不自然。切手は貼るもので、封をする対象ではない。"}, "sentence_index": 0, "correct_answer": "封"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "瓶の封をしっかり閉めて、中身がこぼれないようにした。", "explanation": "ここは〈栓〉の意味。瓶には栓を使い、封は手紙や袋の口に使うので合わない。"}, {"text": "鍋の封を閉じたまま煮込んだので、蒸気が出なかった。", "explanation": "ここは〈蓋〉の意味。鍋には蓋を使い、封は手紙や袋の口を閉じることに使うので合わない。"}, {"text": "映画の封は来週だ。", "explanation": "ここは〈封切り〉の意味。映画の初公開は封切りと言い、封だけでは意味が通らない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'acd1f4a8-eb16-4a36-ad41-5791be3ae06d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39356, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "封", "is_correct": true, "explanation": "「封を忘れたまま送った」なら、口を閉じ忘れて中身が飛び出す流れが成り立つ。正しい。"}, {"text": "消印", "is_correct": false, "explanation": "消印は郵便局が押すもので、忘れて送る対象にはならない。「消印を忘れた」は不自然。"}, {"text": "郵便局", "is_correct": false, "explanation": "郵便局は忘れて送る対象ではなく、「郵便局を忘れたまま送った」は文が成り立たない。"}, {"text": "配達員", "is_correct": false, "explanation": "配達員は人であり、忘れたまま送る対象ではない。文脈にも合わない。"}], "explanations": {"封": "「封を忘れたまま送った」なら、口を閉じ忘れて中身が飛び出す流れが成り立つ。正しい。", "消印": "消印は郵便局が押すもので、忘れて送る対象にはならない。「消印を忘れた」は不自然。", "郵便局": "郵便局は忘れて送る対象ではなく、「郵便局を忘れたまま送った」は文が成り立たない。", "配達員": "配達員は人であり、忘れたまま送る対象ではない。文脈にも合わない。"}, "sentence_index": 6, "correct_answer": "封"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "玄関に封をかけて、旅行に出かけた。", "explanation": "ここは〈錠〉の意味。玄関には錠をかけ、封は手紙や袋の口に使うので合わない。"}, {"text": "申請書に封を押して、受理された。", "explanation": "ここは〈印〉の意味。押して承認を示すのは印で、封は口を閉じることを表すので合わない。"}, {"text": "手紙に写真を封して送った。", "explanation": "ここは〈封入〉の意味。中に入れることは封入と言い、封は口を閉じる動作を表すので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'acd1f4a8-eb16-4a36-ad41-5791be3ae06d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39356, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "手紙を書いて、最後に封に閉じた。", "corrected_sentence": "手紙を書いて、最後に封を閉じた。", "error_description": "「封を閉じた」の「を」が「に」になっている。「閉じる」は動作の対象を「を」で示すので、「に」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'acd1f4a8-eb16-4a36-ad41-5791be3ae06d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39356, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "封に切って、中の手紙を取り出した。", "corrected_sentence": "封を切って、中の手紙を取り出した。", "error_description": "「封を切る」の「を」が「に」になっている。「切る」は対象を「を」で示すので、「に」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'acd1f4a8-eb16-4a36-ad41-5791be3ae06d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39357, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「封を閉じる」の「封」は「閉じる」の対象なので、対象を示す「を」が正しい。"}, {"text": "に", "is_correct": false, "explanation": "「封に閉じる」は閉じる対象を示せず、不自然で文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「封へ閉じる」は方向の意味になり、閉じる動作の対象にはならない。"}, {"text": "から", "is_correct": false, "explanation": "「封から閉じる」は起点の意味になり、閉じる対象を示すことができない。"}], "correct_answer": "を", "explanations": {"を": "「封を閉じる」の「封」は「閉じる」の対象なので、対象を示す「を」が正しい。", "に": "「封に閉じる」は閉じる対象を示せず、不自然で文が成り立たない。", "へ": "「封へ閉じる」は方向の意味になり、閉じる動作の対象にはならない。", "から": "「封から閉じる」は起点の意味になり、閉じる対象を示すことができない。"}, "error_tags": {"に": "位置", "へ": "方向", "から": "起点"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'acd1f4a8-eb16-4a36-ad41-5791be3ae06d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
