INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39357, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "手紙や袋などの口を閉じること。また、閉じた所。", "primary_collocate": null, "pronunciation": "ふう", "ipa": "ɸɯː", "syllable_count": 2, "sentences": [{"text": "彼女は手紙を入れて、のりで封を閉じた。", "target_word": "封", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は手紙[てがみ]を入[い]れて、のりで封[ふう]を閉[と]じた。", "sentence_source": "generated"}, {"text": "封を閉じる前に、中の手紙を一度読み返した。", "target_word": "封", "complexity_tier": "T3", "furigana": "封[ふう]を閉[と]じる前[まえ]に、中[なか]の手紙[てがみ]を一度[いちど]読[よ]み返[かえ]した。", "sentence_source": "generated"}, {"text": "封のところが破れていたので、荷物を取り替えてもらった。", "target_word": "封", "complexity_tier": "T3", "furigana": "封[ふう]のところが破[やぶ]れていたので、荷物[にもつ]を取[と]り替[か]えてもらった。", "sentence_source": "generated"}, {"text": "契約書は、封をしてから担当者に渡してください。", "target_word": "封", "complexity_tier": "T3", "furigana": "契約書[けいやくしょ]は、封[ふう]をしてから担当者[たんとうしゃ]に渡[わた]してください。", "sentence_source": "generated"}, {"text": "封の部分にのりを付けるのを忘れて、手紙が開いてしまった。", "target_word": "封", "complexity_tier": "T3", "furigana": "封[ふう]の部分[ぶぶん]にのりを付[つ]けるのを忘[わす]れて、手紙[てがみ]が開[ひら]いてしまった。", "sentence_source": "generated"}, {"text": "入学の案内は、封がしてある状態で届いた。", "target_word": "封", "complexity_tier": "T3", "furigana": "入学[にゅうがく]の案内[あんない]は、封[ふう]がしてある状態[じょうたい]で届[とど]いた。", "sentence_source": "generated"}, {"text": "試験の問題用紙は、時間が始まるまで封を開けてはいけない。", "target_word": "封", "complexity_tier": "T3", "furigana": "試験[しけん]の問題用紙[もんだいようし]は、時間[じかん]が始[はじ]まるまで封[ふう]を開[あ]けてはいけない。", "sentence_source": "generated"}, {"text": "袋の封を閉じるときは、空気を抜くときれいに保てる。", "target_word": "封", "complexity_tier": "T3", "furigana": "袋[ふくろ]の封[ふう]を閉[と]じるときは、空気[くうき]を抜[ぬ]くときれいに保[たも]てる。", "sentence_source": "generated"}, {"text": "友達に渡す手紙の封に、小さなシールを貼った。", "target_word": "封", "complexity_tier": "T3", "furigana": "友達[ともだち]に渡[わた]す手紙[てがみ]の封[ふう]に、小[ちい]さなシールを貼[は]った。", "sentence_source": "generated"}, {"text": "封がきれいに残っているので、まだ誰も開けていないと分かる。", "target_word": "封", "complexity_tier": "T3", "furigana": "封[ふう]がきれいに残[のこ]っているので、まだ誰[だれ]も開[あ]けていないと分[わ]かる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "封", "label": "基本形"}], "register": "中立", "sense_fingerprint": "手紙や袋の口を閉じること、またその閉じた部分", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b5f4a63-69ff-4d35-93ef-31c84933d968') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39357, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "封", "is_correct": true, "explanation": "「のりで封を閉じた」は、封筒の口を閉じた意味になり正しい。"}, {"text": "切手", "is_correct": false, "explanation": "切手はのりで閉じるものではない。「切手を閉じた」は不自然。"}, {"text": "宛名", "is_correct": false, "explanation": "宛名は閉じる対象ではなく、「宛名を閉じた」は成り立たない。"}, {"text": "郵便", "is_correct": false, "explanation": "郵便は閉じる対象ではなく、「郵便を閉じた」は文脈にも合わない。"}], "explanations": {"封": "「のりで封を閉じた」は、封筒の口を閉じた意味になり正しい。", "切手": "切手はのりで閉じるものではない。「切手を閉じた」は不自然。", "宛名": "宛名は閉じる対象ではなく、「宛名を閉じた」は成り立たない。", "郵便": "郵便は閉じる対象ではなく、「郵便を閉じた」は文脈にも合わない。"}, "sentence_index": 0, "correct_answer": "封"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "水道の封をひねって、水を止めた。", "explanation": "ここは〈栓〉の意味。水道は栓をひねって止めるもので、封は手紙や袋の口に使うので合わない。"}, {"text": "玄関に封をかけて、旅行に出かけた。", "explanation": "ここは〈錠〉の意味。鍵をかける錠の働きで、封は口を閉じることを表すので合わない。"}, {"text": "その映画の封は、来月に決まった。", "explanation": "ここは〈封切り〉の意味。映画の初公開は封切りと言い、封だけでは意味が通らない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'acd1f4a8-eb16-4a36-ad41-5791be3ae06d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39357, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "封", "is_correct": true, "explanation": "「封を開けてはいけない」は、封を開くことを禁じる意味になり、文脈に合う。正しい。"}, {"text": "鉛筆", "is_correct": false, "explanation": "鉛筆は開ける対象ではなく、「鉛筆を開けてはいけない」は試験の文脈で意味が通らない。"}, {"text": "消しゴム", "is_correct": false, "explanation": "消しゴムを開けるという行為は不自然で、試験の文脈に合わない。"}, {"text": "定規", "is_correct": false, "explanation": "定規を開けるという行為は不自然で、試験の文脈に合わない。"}], "explanations": {"封": "「封を開けてはいけない」は、封を開くことを禁じる意味になり、文脈に合う。正しい。", "鉛筆": "鉛筆は開ける対象ではなく、「鉛筆を開けてはいけない」は試験の文脈で意味が通らない。", "消しゴム": "消しゴムを開けるという行為は不自然で、試験の文脈に合わない。", "定規": "定規を開けるという行為は不自然で、試験の文脈に合わない。"}, "sentence_index": 6, "correct_answer": "封"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "ドアの封を回して、鍵をかけた。", "explanation": "ここは〈錠〉の意味。鍵をかける錠の動作で、封は手紙や袋の口に使うので合わない。"}, {"text": "申請書に封を押して、受理された。", "explanation": "ここは〈印〉の意味。受理や承認は印を押して示すもので、封は口を閉じることを表すので合わない。"}, {"text": "カードに写真を封して、友達に送った。", "explanation": "ここは〈封入〉の意味。中に入れることは封入と言い、封は口を閉じる動作を表すので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'acd1f4a8-eb16-4a36-ad41-5791be3ae06d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39357, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "封が開けて、中身を読んだ。", "corrected_sentence": "封を開けて、中身を読んだ。", "error_description": "「開ける」は他動詞なので、対象の「封」には「を」が必要。「が」は「開く」のような自動詞と組み合わさる。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'acd1f4a8-eb16-4a36-ad41-5791be3ae06d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39357, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "封をきれいに残っていたので、中身は無事だった。", "corrected_sentence": "封がきれいに残っていたので、中身は無事だった。", "error_description": "「残る」は自動詞なので、主語の「封」には「が」が必要。「を」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'acd1f4a8-eb16-4a36-ad41-5791be3ae06d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39362, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「パネルを三枚つなげて」は、つなげる対象を示し、文が通る。"}, {"text": "へ", "is_correct": false, "explanation": "「パネルへ三枚つなげて」は方向を示すが、つなげる対象にはならず不自然。"}, {"text": "と", "is_correct": false, "explanation": "「パネルと三枚つなげて」は並べる相手になり、文として意味が通らない。"}, {"text": "から", "is_correct": false, "explanation": "「パネルから三枚つなげて」は起点になり、つなげる対象を示せない。"}], "correct_answer": "を", "explanations": {"を": "「パネルを三枚つなげて」は、つなげる対象を示し、文が通る。", "へ": "「パネルへ三枚つなげて」は方向を示すが、つなげる対象にはならず不自然。", "と": "「パネルと三枚つなげて」は並べる相手になり、文として意味が通らない。", "から": "「パネルから三枚つなげて」は起点になり、つなげる対象を示せない。"}, "error_tags": {"へ": "方向", "と": "並列・相手", "から": "起点"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7cad1d42-0f01-42ba-9a46-23712a171364') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39362, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7cad1d42-0f01-42ba-9a46-23712a171364') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39362, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "たいらな いたの こと。", "primary_collocate": null, "pronunciation": "ぱねる", "ipa": "paneɾɯ", "syllable_count": 3, "sentences": [{"text": "壁に白いパネルを取りつけて、部屋を明るくした。", "target_word": "パネル", "complexity_tier": "T3", "furigana": "壁(かべ)に白(しろ)いパネルを取(と)りつけて、部屋(へや)を明(あか)るくした。", "sentence_source": "generated"}, {"text": "木のパネルを三枚つなげて、小さな棚を作った。", "target_word": "パネル", "complexity_tier": "T3", "furigana": "木(き)のパネルを三枚(さんまい)つなげて、小(ちい)さな棚(たな)を作(つく)った。", "sentence_source": "generated"}, {"text": "古い床がいたんだので、新しいパネルに取りかえる。", "target_word": "パネル", "complexity_tier": "T3", "furigana": "古(ふる)い床(ゆか)がいたんだので、新(あたら)しいパネルに取(と)りかえる。", "sentence_source": "generated"}, {"text": "このパネルは軽くて平らだから、持ち運びがらくだ。", "target_word": "パネル", "complexity_tier": "T3", "furigana": "このパネルは軽(かる)くて平(たいら)だから、持(も)ち運(はこ)びがらくだ。", "sentence_source": "generated"}, {"text": "大工さんは、屋根にパネルをのせて、くぎでとめた。", "target_word": "パネル", "complexity_tier": "T3", "furigana": "大工(だいく)さんは、屋根(やね)にパネルをのせて、くぎでとめた。", "sentence_source": "generated"}, {"text": "床の穴をふさぐために、大きなパネルを切って打ちつけた。", "target_word": "パネル", "complexity_tier": "T3", "furigana": "床(ゆか)の穴(あな)をふさぐために、大(おお)きなパネルを切(き)って打(う)ちつけた。", "sentence_source": "generated"}, {"text": "パネルがぬれて曲がってしまったので、使えなくなった。", "target_word": "パネル", "complexity_tier": "T3", "furigana": "パネルがぬれて曲(ま)がってしまったので、使(つか)えなくなった。", "sentence_source": "generated"}, {"text": "兄は板を切って、パネルを何枚も作っている。", "target_word": "パネル", "complexity_tier": "T3", "furigana": "兄(あに)は板(いた)を切(き)って、パネルを何枚(なんまい)も作(つく)っている。", "sentence_source": "generated"}, {"text": "風でパネルがたおれて、そばの自転車に当たった。", "target_word": "パネル", "complexity_tier": "T3", "furigana": "風(かぜ)でパネルがたおれて、そばの自転車(じてんしゃ)に当(あ)たった。", "sentence_source": "generated"}, {"text": "このパネルは厚さが二センチあるので、とても丈夫だ。", "target_word": "パネル", "complexity_tier": "T3", "furigana": "このパネルは厚(あつ)さが二(に)センチあるので、とても丈夫(じょうぶ)だ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "パネル", "label": "基本形"}], "register": "plain", "sense_fingerprint": "壁や床などに使う平らな板", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 8 above tier T3: contains vocabulary far above tier T3: たおれ (Zipf 1.74)']::text[], '06e3467d-5cea-4b54-9930-14d540bd33b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39362, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "パネル", "is_correct": true, "explanation": "「白いパネルを取りつける」は、壁に付ける平らな板という意味になり、文に合う。"}, {"text": "花瓶", "is_correct": false, "explanation": "花瓶は花を生ける器で、壁に取りつけて部屋を明るくするものにはならない。"}, {"text": "布団", "is_correct": false, "explanation": "布団は寝具で、壁に取りつけて部屋を明るくするものにはならない。"}, {"text": "傘", "is_correct": false, "explanation": "傘は雨具で、壁に取りつけて部屋を明るくするものにはならない。"}], "explanations": {"パネル": "「白いパネルを取りつける」は、壁に付ける平らな板という意味になり、文に合う。", "花瓶": "花瓶は花を生ける器で、壁に取りつけて部屋を明るくするものにはならない。", "布団": "布団は寝具で、壁に取りつけて部屋を明るくするものにはならない。", "傘": "傘は雨具で、壁に取りつけて部屋を明るくするものにはならない。"}, "sentence_index": 0, "correct_answer": "パネル"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "母はパネルを溶かして、甘いシロップを作った。", "explanation": "ここは〈砂糖〉の意味。溶かすのは砂糖などの固体の食材で、板のパネルは溶けないので合わない。"}, {"text": "大きなパネルを火にかけて、スープを煮た。", "explanation": "ここは〈鍋〉の意味。火にかける調理器具は鍋で、壁や床に使う板のパネルは火にかけられないので合わない。"}, {"text": "母はパネルをこねて、パンを作った。", "explanation": "ここは〈小麦粉〉の意味。こねるのは小麦粉などの粉で、板のパネルはこねられないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7cad1d42-0f01-42ba-9a46-23712a171364') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39362, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "パネル", "is_correct": true, "explanation": "「パネルがぬれて曲がって」は、ぬれて反る板という意味になり、ここに入る。"}, {"text": "砂糖", "is_correct": false, "explanation": "砂糖はぬれるととけるもので、曲がるわけではないので合わない。"}, {"text": "石鹸", "is_correct": false, "explanation": "石鹸は洗浄剤で、ぬれて曲がるものではないので、ここには入らない。"}, {"text": "茶碗", "is_correct": false, "explanation": "茶碗は食器で、ぬれて曲がって使えなくなるものではないので、ここには入らない。"}], "explanations": {"パネル": "「パネルがぬれて曲がって」は、ぬれて反る板という意味になり、ここに入る。", "砂糖": "砂糖はぬれるととけるもので、曲がるわけではないので合わない。", "石鹸": "石鹸は洗浄剤で、ぬれて曲がるものではないので、ここには入らない。", "茶碗": "茶碗は食器で、ぬれて曲がって使えなくなるものではないので、ここには入らない。"}, "sentence_index": 6, "correct_answer": "パネル"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "母は赤いパネルを縫って、かわいい人形を作った。", "explanation": "ここは〈布〉の意味。縫うのは布などの布地で、板のパネルは縫えないので合わない。"}, {"text": "赤と青のパネルを混ぜて、紫色を作った。", "explanation": "ここは〈絵の具〉の意味。混ぜて色を作るのは絵の具などの色材で、板のパネルは混ぜられないので合わない。"}, {"text": "母はパネルに糸を通して、ボタンを付けた。", "explanation": "ここは〈針〉の意味。糸を通す道具は針で、板のパネルは糸を通せないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7cad1d42-0f01-42ba-9a46-23712a171364') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39362, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "玄関に木のパネルが取りつけて、雨をよけた。", "corrected_sentence": "玄関に木のパネルを取りつけて、雨をよけた。", "error_description": "「取りつける」の目的語には「を」を使うので、「が」は誤り。正しくは「パネルを」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7cad1d42-0f01-42ba-9a46-23712a171364') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39362, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "冬の寒さを、薄いパネルにふせいだ。", "corrected_sentence": "冬の寒さを、薄いパネルでふせいだ。", "error_description": "「ふせぐ」の手段は「で」で示すので、「に」は誤り。正しくは「パネルで」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7cad1d42-0f01-42ba-9a46-23712a171364') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39363, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「パネルのボタン」でパネルとボタンを結ぶ「の」。ここでの正解。"}, {"text": "を", "is_correct": false, "explanation": "「を」は対象を示すが、「パネルをボタン」では名詞同士が結べず不自然。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を示すが、ここはパネルがボタンを修飾する関係なので合わない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すので、名詞同士をつなぐこの位置には入らない。"}], "correct_answer": "の", "explanations": {"の": "「パネルのボタン」でパネルとボタンを結ぶ「の」。ここでの正解。", "を": "「を」は対象を示すが、「パネルをボタン」では名詞同士が結べず不自然。", "が": "「が」は主語を示すが、ここはパネルがボタンを修飾する関係なので合わない。", "へ": "「へ」は方向を示すので、名詞同士をつなぐこの位置には入らない。"}, "error_tags": {"の": "修飾（〜の）", "を": "対象（〜を）", "が": "主語（〜が）", "へ": "方向（〜へ）"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7cad1d42-0f01-42ba-9a46-23712a171364') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39363, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "「パネルで」でパネルを使って設定したことを示す「で」。ここでの正解。"}, {"text": "を", "is_correct": false, "explanation": "「を」は設定の対象を示すが、パネルを対象にすると文の意味が通らないので合わない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すが、パネルに向かって設定するという意味にならず合わない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並べる相手を示すが、パネルと温度を並べる文脈ではなく合わない。"}], "correct_answer": "で", "explanations": {"で": "「パネルで」でパネルを使って設定したことを示す「で」。ここでの正解。", "を": "「を」は設定の対象を示すが、パネルを対象にすると文の意味が通らないので合わない。", "へ": "「へ」は方向を示すが、パネルに向かって設定するという意味にならず合わない。", "と": "「と」は並べる相手を示すが、パネルと温度を並べる文脈ではなく合わない。"}, "error_tags": {"で": "手段（〜で）", "を": "対象（〜を）", "へ": "方向（〜へ）", "と": "並列（〜と）"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7cad1d42-0f01-42ba-9a46-23712a171364') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39363, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "板状のもの。展示用の板や、機器の操作・表示に使う板など。", "primary_collocate": null, "pronunciation": "ぱねる", "ipa": "paneɾɯ", "syllable_count": 3, "sentences": [{"text": "博物館の入り口に、町の歴史を説明するパネルが並んでいる。", "target_word": "パネル", "complexity_tier": "T3", "furigana": "博物館(はくぶつかん)の入(い)り口(ぐち)に、町(まち)の歴史(れきし)を説明(せつめい)するパネルが並(なら)んでいる。", "sentence_source": "generated"}, {"text": "エレベーターのパネルのボタンを押して、五階へ行った。", "target_word": "パネル", "complexity_tier": "T3", "furigana": "エレベーターのパネルのボタンを押(お)して、五階(ごかい)へ行(い)った。", "sentence_source": "generated"}, {"text": "洗濯機の操作パネルが暗くて、文字が読みにくい。", "target_word": "パネル", "complexity_tier": "T3", "furigana": "洗濯機(せんたくき)の操作(そうさ)パネルが暗(くら)くて、文字(もじ)が読(よ)みにくい。", "sentence_source": "generated"}, {"text": "発表会では、研究の結果をまとめたパネルを壁にはった。", "target_word": "パネル", "complexity_tier": "T3", "furigana": "発表会(はっぴょうかい)では、研究(けんきゅう)の結果(けっか)をまとめたパネルを壁(かべ)にはった。", "sentence_source": "generated"}, {"text": "機械のパネルに「エラー」と出たので、先生を呼んだ。", "target_word": "パネル", "complexity_tier": "T3", "furigana": "機械(きかい)のパネルに「エラー」と出(で)たので、先生(せんせい)を呼(よ)んだ。", "sentence_source": "generated"}, {"text": "このパネルを見ると、電車がどこを走っているかわかる。", "target_word": "パネル", "complexity_tier": "T3", "furigana": "このパネルを見(み)ると、電車(でんしゃ)がどこを走(はし)っているかわかる。", "sentence_source": "generated"}, {"text": "展覧会の会場では、写真のパネルを見ながら話を聞いた。", "target_word": "パネル", "complexity_tier": "T3", "furigana": "展覧会(てんらんかい)の会場(かいじょう)では、写真(しゃしん)のパネルを見(み)ながら話(はなし)を聞(き)いた。", "sentence_source": "generated"}, {"text": "エアコンのパネルで、温度を二十五度に設定した。", "target_word": "パネル", "complexity_tier": "T3", "furigana": "エアコンのパネルで、温度(おんど)を二十五度(にじゅうごど)に設定(せってい)した。", "sentence_source": "generated"}, {"text": "駅の案内パネルには、英語の説明も書いてある。", "target_word": "パネル", "complexity_tier": "T3", "furigana": "駅(えき)の案内(あんない)パネルには、英語(えいご)の説明(せつめい)も書(か)いてある。", "sentence_source": "generated"}, {"text": "パネルに指でふれると、画面が明るくなった。", "target_word": "パネル", "complexity_tier": "T3", "furigana": "パネルに指(ゆび)でふれると、画面(がめん)が明(あか)るくなった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "パネル", "label": "基本形"}], "register": "plain", "sense_fingerprint": "展示や機器の操作・表示に使う板", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06e3467d-5cea-4b54-9930-14d540bd33b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39363, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "パネル", "is_correct": true, "explanation": "「並んでいる」「説明する」に合う板状の展示物なので、この空所に入るのはこの語だけ。"}, {"text": "カーテン", "is_correct": false, "explanation": "窓や仕切りに掛ける布で、歴史の説明を書いて並べる物ではないので合わない。"}, {"text": "ベンチ", "is_correct": false, "explanation": "人が座る物で、説明を並べて見せる物ではないので合わない。"}, {"text": "花瓶", "is_correct": false, "explanation": "花を生ける容器で、町の歴史を説明する物ではないので合わない。"}], "explanations": {"パネル": "「並んでいる」「説明する」に合う板状の展示物なので、この空所に入るのはこの語だけ。", "カーテン": "窓や仕切りに掛ける布で、歴史の説明を書いて並べる物ではないので合わない。", "ベンチ": "人が座る物で、説明を並べて見せる物ではないので合わない。", "花瓶": "花を生ける容器で、町の歴史を説明する物ではないので合わない。"}, "sentence_index": 0, "correct_answer": "パネル"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "夕食の材料を、パネルの上で切った。", "explanation": "ここは〈まな板〉の意味。食材を切る台は〈まな板〉で、パネルは切る台として使わないので合わない。"}, {"text": "朝、パネルで寝ぐせを直してから出かけた。", "explanation": "ここは〈鏡〉の意味。姿を映して身だしなみを整える道具で、パネルは映す用途がないので合わない。"}, {"text": "夕食の料理を、パネルに盛りつけた。", "explanation": "ここは〈皿〉の意味。料理を盛る器の皿を指す場面で、パネルは料理を盛る器ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7cad1d42-0f01-42ba-9a46-23712a171364') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39363, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "パネル", "is_correct": true, "explanation": "写真を掲示した板状の展示物を指し、「写真の」「見ながら」に合う唯一の語。"}, {"text": "ハンドル", "is_correct": false, "explanation": "乗り物や回す器具の取っ手で、写真を見るものではないので合わない。"}, {"text": "ストーブ", "is_correct": false, "explanation": "暖房器具で、写真を見ながら話を聞く場面には合わない。"}, {"text": "傘", "is_correct": false, "explanation": "雨具で、写真の説明を見る対象にはならないので合わない。"}], "explanations": {"パネル": "写真を掲示した板状の展示物を指し、「写真の」「見ながら」に合う唯一の語。", "ハンドル": "乗り物や回す器具の取っ手で、写真を見るものではないので合わない。", "ストーブ": "暖房器具で、写真を見ながら話を聞く場面には合わない。", "傘": "雨具で、写真の説明を見る対象にはならないので合わない。"}, "sentence_index": 6, "correct_answer": "パネル"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "友だちに、パネルを書いて送った。", "explanation": "ここは〈手紙〉の意味。書いて送る物は手紙で、パネルは書いて送る物ではないので合わない。"}, {"text": "みんなの前で、パネルを歌った。", "explanation": "ここは〈音を奏でる〉の意味。板状の物は音を奏でないので、この文は誤り。"}, {"text": "暑いので、パネルをかぶった。", "explanation": "ここは〈帽子〉の意味。頭にかぶる物は帽子で、パネルはかぶる物ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7cad1d42-0f01-42ba-9a46-23712a171364') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39363, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "展示室の奥に、古い写真のパネルを並んでいる。", "corrected_sentence": "展示室の奥に、古い写真のパネルが並んでいる。", "error_description": "「パネル」に続く助詞が誤り。「並んでいる」の主語は「が」で示すので、「を」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7cad1d42-0f01-42ba-9a46-23712a171364') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39363, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "展示室で、年表のパネルに見ながら、昔の道具の話を聞いた。", "corrected_sentence": "展示室で、年表のパネルを見ながら、昔の道具の話を聞いた。", "error_description": "「パネル」に続く助詞が誤り。見る対象は「を」で示すので、「に」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7cad1d42-0f01-42ba-9a46-23712a171364') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39366, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「電気を作る」の目的語を示す「を」。作る対象が電気であることを表す。"}, {"text": "に", "is_correct": false, "explanation": "「電気に作る」では作る対象を示せず、文が成り立たない。"}, {"text": "が", "is_correct": false, "explanation": "「電気が作る」では電気が主語になり、電気が自ら作るという誤った意味になる。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す「へ」は作る動作の対象にならず、「電気へ作る」は成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「電気を作る」の目的語を示す「を」。作る対象が電気であることを表す。", "に": "「電気に作る」では作る対象を示せず、文が成り立たない。", "が": "「電気が作る」では電気が主語になり、電気が自ら作るという誤った意味になる。", "へ": "方向を示す「へ」は作る動作の対象にならず、「電気へ作る」は成り立たない。"}, "error_tags": {"に": "対象の誤り", "が": "主語の誤り", "へ": "方向の誤り"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1c725cd-60e6-48da-9c21-cb8af8e2abbd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39366, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1c725cd-60e6-48da-9c21-cb8af8e2abbd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39366, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "発電などによって電気を生み出すこと。", "primary_collocate": null, "pronunciation": "でんきをつくる", "ipa": "deŋkiotsɯkɯɾɯ", "syllable_count": 7, "sentences": [{"text": "太陽の光で電気を作る家が増えている。", "target_word": "電気を作る", "complexity_tier": "T3", "furigana": "太陽[たいよう]の光[ひかり]で電気[でんき]を作[つく]る家[いえ]が増[ふ]えている。", "sentence_source": "generated"}, {"text": "この発電所は、水の力で電気を作る。", "target_word": "電気を作る", "complexity_tier": "T3", "furigana": "この発電所[はつでんしょ]は、水[みず]の力[ちから]で電気[でんき]を作[つく]る。", "sentence_source": "generated"}, {"text": "風車は風の力を使って電気を作る。", "target_word": "電気を作る", "complexity_tier": "T3", "furigana": "風車[ふうしゃ]は風[かぜ]の力[ちから]を使[つか]って電気[でんき]を作[つく]る。", "sentence_source": "generated"}, {"text": "山の小さな村では、川の水で電気を作って暮らしている。", "target_word": "電気を作って", "complexity_tier": "T3", "furigana": "山[やま]の小[ちい]さな村[むら]では、川[かわ]の水[みず]で電気[でんき]を作[つく]って暮[く]らしている。", "sentence_source": "generated"}, {"text": "停電のとき、自転車をこいで電気を作る道具がある。", "target_word": "電気を作る", "complexity_tier": "T3", "furigana": "停電[ていでん]のとき、自転車[じてんしゃ]をこいで電気[でんき]を作[つく]る道具[どうぐ]がある。", "sentence_source": "generated"}, {"text": "学校の屋根のパネルは、晴れた日にたくさん電気を作る。", "target_word": "電気を作る", "complexity_tier": "T3", "furigana": "学校[がっこう]の屋根[やね]のパネルは、晴[は]れた日[ひ]にたくさん電気[でんき]を作[つく]る。", "sentence_source": "generated"}, {"text": "ごみを燃やした熱で電気を作る工場を見学した。", "target_word": "電気を作る", "complexity_tier": "T3", "furigana": "ごみを燃[も]やした熱[ねつ]で電気[でんき]を作[つく]る工場[こうじょう]を見学[けんがく]した。", "sentence_source": "generated"}, {"text": "火力発電所は、石炭や天然ガスを燃やして電気を作る。", "target_word": "電気を作る", "complexity_tier": "T3", "furigana": "火力発電所[かりょくはつでんしょ]は、石炭[せきたん]や天然[てんねん]ガスを燃[も]やして電気[でんき]を作[つく]る。", "sentence_source": "generated"}, {"text": "兄は理科の実験で、レモンを使って電気を作ってみた。", "target_word": "電気を作って", "complexity_tier": "T3", "furigana": "兄[あに]は理科[りか]の実験[じっけん]で、レモンを使[つか]って電気[でんき]を作[つく]ってみた。", "sentence_source": "generated"}, {"text": "夜は太陽が出ないので、太陽光パネルは電気を作らない。", "target_word": "電気を作らない", "complexity_tier": "T3", "furigana": "夜[よる]は太陽[たいよう]が出[で]ないので、太陽光[たいようこう]パネルは電気[でんき]を作[つく]らない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "電気を作る", "label": "辞書形"}, {"form": "電気を作った", "label": "過去形"}, {"form": "電気を作って", "label": "て形"}, {"form": "電気を作らない", "label": "否定形"}, {"form": "電気を作ります", "label": "丁寧形"}], "register": "中立", "sense_fingerprint": "発電などによって電気を生み出す", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6723961-33ca-4712-8f1a-8170a5f30020') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39366, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "電気を作る", "is_correct": true, "explanation": "発電して電気を生み出す意味で、「太陽の光で電気を作る家」という文脈に合う。"}, {"text": "電気を消す", "is_correct": false, "explanation": "照明などの電気を止める意味。太陽の光で電気を消す家では話がつながらない。"}, {"text": "電気をつける", "is_correct": false, "explanation": "照明などを点ける意味。太陽の光で電気をつける家が増えるという文は成り立たない。"}, {"text": "電気を盗む", "is_correct": false, "explanation": "他人の電気を無断で使う意味。太陽光発電の文脈では意味が合わない。"}], "explanations": {"電気を作る": "発電して電気を生み出す意味で、「太陽の光で電気を作る家」という文脈に合う。", "電気を消す": "照明などの電気を止める意味。太陽の光で電気を消す家では話がつながらない。", "電気をつける": "照明などを点ける意味。太陽の光で電気をつける家が増えるという文は成り立たない。", "電気を盗む": "他人の電気を無断で使う意味。太陽光発電の文脈では意味が合わない。"}, "sentence_index": 0, "correct_answer": "電気を作る"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "夜になったので、玄関の電気を作って家に入った。", "explanation": "玄関の明かりを点けるのは「作る」では表せず、明かりを点ける文として不自然。"}, {"text": "この銅線は、よく電気を作るので電線に使われている。", "explanation": "銅線の性質は電流を通すことで、電気を生み出す「作る」とは結びつかず不自然。"}, {"text": "ケーブルを隣の家まで延ばして、電気を作った。", "explanation": "電線で供給を受ける場面は「作る」では表せず、この文では不自然。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1c725cd-60e6-48da-9c21-cb8af8e2abbd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39366, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "電気を作る", "is_correct": true, "explanation": "発電して電気を生み出す意味で、ごみを燃やした熱で発電する工場の文脈に合う。"}, {"text": "電気を切る", "is_correct": false, "explanation": "電気の供給を止める意味。電気を切る工場を見学したという文は話がつながらない。"}, {"text": "電気を失う", "is_correct": false, "explanation": "電気を無くす意味。工場が電気を失うという文脈では見学の対象にならない。"}, {"text": "電気を壊す", "is_correct": false, "explanation": "電気設備を壊す意味。熱で電気を壊す工場という文は意味が成り立たない。"}], "explanations": {"電気を作る": "発電して電気を生み出す意味で、ごみを燃やした熱で発電する工場の文脈に合う。", "電気を切る": "電気の供給を止める意味。電気を切る工場を見学したという文は話がつながらない。", "電気を失う": "電気を無くす意味。工場が電気を失うという文脈では見学の対象にならない。", "電気を壊す": "電気設備を壊す意味。熱で電気を壊す工場という文は意味が成り立たない。"}, "sentence_index": 6, "correct_answer": "電気を作る"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "夏は冷房を弱めて、家の電気を作る。", "explanation": "冷房を弱めて電気を減らす場面は「作る」では表せず、節約の文として不自然。"}, {"text": "夜のうちに、スマホの電気を作っておく。", "explanation": "外から電気を補うのは充電で、電気を生み出す「作る」とは合わず不自然。"}, {"text": "台風で村の電気を作った。", "explanation": "停電させる場面は「作る」では表せず、台風の文として不自然。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1c725cd-60e6-48da-9c21-cb8af8e2abbd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39366, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この施設は、ダムの水の力で電気に作る。", "corrected_sentence": "この施設は、ダムの水の力で電気を作る。", "error_description": "「作る」の目的語を示す助詞が「に」になっている。「電気を作る」の「を」が正しく、「に」では文として成り立たない。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "電気を作る", "is_correct": true, "explanation": "辞書形で、発電所の現在の発電を述べる文末に使われる。"}, {"text": "電気を作って", "is_correct": false, "explanation": "て形は文を続ける途中の形で、文末に置くと文が終わらず不自然。"}, {"text": "電気を作らない", "is_correct": false, "explanation": "否定形なので、発電所が発電しないという意味になり文の内容と逆になる。"}, {"text": "電気を作れ", "is_correct": false, "explanation": "命令形なので、発電所の説明を述べる文では命令になり意味が合わない。"}], "correct_form": "電気を作る", "base_form": "電気を作る", "form_label": "辞書形", "sentence_index": 1, "explanations": {"電気を作る": "辞書形で、発電所の現在の発電を述べる文末に使われる。", "電気を作って": "て形は文を続ける途中の形で、文末に置くと文が終わらず不自然。", "電気を作らない": "否定形なので、発電所が発電しないという意味になり文の内容と逆になる。", "電気を作れ": "命令形なので、発電所の説明を述べる文では命令になり意味が合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1c725cd-60e6-48da-9c21-cb8af8e2abbd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39366, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "ダムの水の力で、この工場は電気が作る。", "corrected_sentence": "ダムの水の力で、この工場は電気を作る。", "error_description": "「作る」の目的語に付く助詞が「が」になっている。「電気を作る」の「を」が正しい。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "電気を作る", "is_correct": true, "explanation": "辞書形で、火力発電所が石炭などを燃やして発電するという事実を述べる文末に使われる。"}, {"text": "電気を作って", "is_correct": false, "explanation": "て形なので、文末には置けず、文を続ける途中の形になる。"}, {"text": "電気を作ろう", "is_correct": false, "explanation": "意志形で、これからの意図を表すため、一般的な発電の事実を述べる文には合わない。"}, {"text": "電気を作られる", "is_correct": false, "explanation": "受身形でも「電気が作られる」の形にしないと成り立たず、「電気を作られる」は文として不成立。"}], "correct_form": "電気を作る", "base_form": "電気を作る", "form_label": "辞書形", "sentence_index": 7, "explanations": {"電気を作る": "辞書形で、火力発電所が石炭などを燃やして発電するという事実を述べる文末に使われる。", "電気を作って": "て形なので、文末には置けず、文を続ける途中の形になる。", "電気を作ろう": "意志形で、これからの意図を表すため、一般的な発電の事実を述べる文には合わない。", "電気を作られる": "受身形でも「電気が作られる」の形にしないと成り立たず、「電気を作られる」は文として不成立。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1c725cd-60e6-48da-9c21-cb8af8e2abbd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
