INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39368, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "あたらしい ものごとや しくみを つくりだす ことです。", "primary_collocate": null, "pronunciation": "いのべーしょん", "ipa": "inobeːɕoɴ", "syllable_count": 6, "sentences": [{"text": "この会社は、イノベーションを大切にしています。", "target_word": "イノベーション", "complexity_tier": "T3", "furigana": "この会社[かいしゃ]は、イノベーションを大切[たいせつ]にしています。", "sentence_source": "generated"}, {"text": "新しい技術が生まれると、社会にイノベーションが起こる。", "target_word": "イノベーション", "complexity_tier": "T3", "furigana": "新[あたら]しい技術[ぎじゅつ]が生[う]まれると、社会[しゃかい]にイノベーションが起[お]こる。", "sentence_source": "generated"}, {"text": "イノベーションのおかげで、スマートフォンは世界中に広がった。", "target_word": "イノベーション", "complexity_tier": "T3", "furigana": "イノベーションのおかげで、スマートフォンは世界中[せかいじゅう]に広[ひろ]がった。", "sentence_source": "generated"}, {"text": "小さな工夫から、大きなイノベーションが生まれることもある。", "target_word": "イノベーション", "complexity_tier": "T3", "furigana": "小[ちい]さな工夫[くふう]から、大[おお]きなイノベーションが生[う]まれることもある。", "sentence_source": "generated"}, {"text": "古いやり方を守るだけでは、イノベーションは起こせません。", "target_word": "イノベーション", "complexity_tier": "T3", "furigana": "古[ふる]いやり方[かた]を守[まも]るだけでは、イノベーションは起[お]こせません。", "sentence_source": "generated"}, {"text": "若い人の自由な考えが、会社のイノベーションにつながった。", "target_word": "イノベーション", "complexity_tier": "T3", "furigana": "若[わか]い人[ひと]の自由[じゆう]な考[かんが]えが、会社[かいしゃ]のイノベーションにつながった。", "sentence_source": "generated"}, {"text": "医療の分野でも、イノベーションが求められています。", "target_word": "イノベーション", "complexity_tier": "T3", "furigana": "医療[いりょう]の分野[ぶんや]でも、イノベーションが求[もと]められています。", "sentence_source": "generated"}, {"text": "イノベーションには、失敗をおそれない気持ちが必要だ。", "target_word": "イノベーション", "complexity_tier": "T3", "furigana": "イノベーションには、失敗[しっぱい]をおそれない気持[きも]ちが必要[ひつよう]だ。", "sentence_source": "generated"}, {"text": "彼の発明は、料理の世界にイノベーションをもたらした。", "target_word": "イノベーション", "complexity_tier": "T3", "furigana": "彼[かれ]の発明[はつめい]は、料理[りょうり]の世界[せかい]にイノベーションをもたらした。", "sentence_source": "generated"}, {"text": "国は、イノベーションを進めるために研究にお金を出している。", "target_word": "イノベーション", "complexity_tier": "T3", "furigana": "国[くに]は、イノベーションを進[すす]めるために研究[けんきゅう]にお金[かね]を出[だ]している。", "sentence_source": "generated"}], "morphological_forms": [{"form": "イノベーション", "label": "dictionary form"}, {"form": "イノベーションの", "label": "attributive form"}, {"form": "イノベーションが", "label": "subject form"}, {"form": "イノベーションを", "label": "object form"}], "register": "neutral", "sense_fingerprint": "新しい技術・方法・仕組みを生み出して社会や仕事を変えること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce891cbc-2525-4fa3-868e-3c2cf3f81b11') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39368, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "イノベーション", "is_correct": true, "explanation": "「大切にする」の対象として、会社の方針を表す語であるイノベーションが入る。"}, {"text": "誤解", "is_correct": false, "explanation": "「誤解を大切にする」は意味が通らない。誤解は大切にする対象にならない。"}, {"text": "混乱", "is_correct": false, "explanation": "混乱は避けたい状態で、「大切にする」の対象にはならない。"}, {"text": "偏見", "is_correct": false, "explanation": "偏見は取り除くべきものなので、「大切にする」とは結びつかない。"}], "explanations": {"イノベーション": "「大切にする」の対象として、会社の方針を表す語であるイノベーションが入る。", "誤解": "「誤解を大切にする」は意味が通らない。誤解は大切にする対象にならない。", "混乱": "混乱は避けたい状態で、「大切にする」の対象にはならない。", "偏見": "偏見は取り除くべきものなので、「大切にする」とは結びつかない。"}, "sentence_index": 0, "correct_answer": "イノベーション"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "雨が降ってきたので、イノベーションを開いた。", "explanation": "ここは〈傘〉の意味。雨の日に使う傘は開くものだが、仕組みを生み出すイノベーションは開けないので合わない。"}, {"text": "この店は、昔からのイノベーションを守ることを大切にしている。", "explanation": "ここは〈伝統〉の意味。昔から守り続けるものを指すので、新しく変えるイノベーションとは合わない。"}, {"text": "この工場は、他社の製品をほぼそのまま作るイノベーションで有名だ。", "explanation": "ここは〈模倣〉の意味。他人のまねを指すので、新しい仕組みを生み出すイノベーションとは別のものだ。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e815395-38fb-44bd-a5d9-4f260295d4be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39368, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "イノベーション", "is_correct": true, "explanation": "「求められている」対象として、医療分野で必要とされる変革を表すイノベーションが入る。"}, {"text": "孤独", "is_correct": false, "explanation": "孤独は求められるものではないので、「求められています」とは合わない。"}, {"text": "衰退", "is_correct": false, "explanation": "衰退は避けるべき状態で、「求められている」対象にはならない。"}, {"text": "偶然", "is_correct": false, "explanation": "偶然は狙って求めるものではないので、この文脈では意味が通らない。"}], "explanations": {"イノベーション": "「求められている」対象として、医療分野で必要とされる変革を表すイノベーションが入る。", "孤独": "孤独は求められるものではないので、「求められています」とは合わない。", "衰退": "衰退は避けるべき状態で、「求められている」対象にはならない。", "偶然": "偶然は狙って求めるものではないので、この文脈では意味が通らない。"}, "sentence_index": 6, "correct_answer": "イノベーション"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "家計を見直して、毎月のイノベーションに成功した。", "explanation": "ここは〈節約〉の意味。出費を抑えることを指すので、仕組みを新しく生み出すイノベーションは合わない。"}, {"text": "昼食のあと、強いイノベーションがまぶたを重くした。", "explanation": "ここは〈眠気〉の意味。まぶたを重くするのは眠気で、仕組みを生み出すイノベーションには当てはまらないので合わない。"}, {"text": "彼の一言に、イノベーションがこみ上げた。", "explanation": "ここは〈怒り〉の意味。怒りがこみ上げるのであって、仕組みを生み出すイノベーションはこみ上げないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e815395-38fb-44bd-a5d9-4f260295d4be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39368, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この研究が進めば、町の産業にイノベーションを起こるだろう。", "corrected_sentence": "この研究が進めば、町の産業にイノベーションが起こるだろう。", "error_description": "「起こる」は自動詞なので、目的語を示す「を」ではなく主語を示す「が」を取る。「を」が誤りで、正しくは「が」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e815395-38fb-44bd-a5d9-4f260295d4be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39368, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "新しい仕組みで、業界にイノベーションを起これた。", "corrected_sentence": "新しい仕組みで、業界にイノベーションを起こせた。", "error_description": "他動詞「起こす」の可能過去形は「起こせた」が正しい。「起これた」という形はない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e815395-38fb-44bd-a5d9-4f260295d4be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
