INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39370, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "よごれていないこと。きれいなこと。", "primary_collocate": null, "pronunciation": "くりーん", "ipa": "kɯɾiːɴ", "syllable_count": 4, "sentences": [{"text": "彼はいつもクリーンな印象の服を着ている。", "target_word": "クリーン", "complexity_tier": "T3", "furigana": "彼[かれ]はいつもクリーンな印象[いんしょう]の服[ふく]を着[き]ている。", "sentence_source": "generated"}, {"text": "台所をクリーンに保つのは大切だ。", "target_word": "クリーン", "complexity_tier": "T3", "furigana": "台所[だいどころ]をクリーンに保[たも]つのは大切[たいせつ]だ。", "sentence_source": "generated"}, {"text": "掃除のあと、部屋はとてもクリーンになった。", "target_word": "クリーン", "complexity_tier": "T3", "furigana": "掃除[そうじ]のあと、部屋[へや]はとてもクリーンになった。", "sentence_source": "generated"}, {"text": "手術室はクリーンでなければならない。", "target_word": "クリーン", "complexity_tier": "T3", "furigana": "手術室[しゅじゅつしつ]はクリーンでなければならない。", "sentence_source": "generated"}, {"text": "クリーンなタオルで顔をふいた。", "target_word": "クリーン", "complexity_tier": "T3", "furigana": "クリーンなタオルで顔[かお]をふいた。", "sentence_source": "generated"}, {"text": "このホテルは、どの部屋もクリーンで気持ちがいい。", "target_word": "クリーン", "complexity_tier": "T3", "furigana": "このホテルは、どの部屋[へや]もクリーンで気持[きも]ちがいい。", "sentence_source": "generated"}, {"text": "洗ったばかりのシーツは、クリーンでいい香りがした。", "target_word": "クリーン", "complexity_tier": "T3", "furigana": "洗[あら]ったばかりのシーツは、クリーンでいい香[かお]りがした。", "sentence_source": "generated"}, {"text": "店の中がクリーンなので、安心して食べられる。", "target_word": "クリーン", "complexity_tier": "T3", "furigana": "店[みせ]の中[なか]がクリーンなので、安心[あんしん]して食[た]べられる。", "sentence_source": "generated"}, {"text": "毎日洗えば、手はクリーンに保てる。", "target_word": "クリーン", "complexity_tier": "T3", "furigana": "毎日[まいにち]洗[あら]えば、手[て]はクリーンに保[たも]てる。", "sentence_source": "generated"}, {"text": "病院では、いつもクリーンな状態を守っている。", "target_word": "クリーン", "complexity_tier": "T3", "furigana": "病院[びょういん]では、いつもクリーンな状態[じょうたい]を守[まも]っている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "クリーンな", "label": "連体形"}, {"form": "クリーンに", "label": "連用形"}, {"form": "クリーンだ", "label": "終止形"}], "register": "neutral", "sense_fingerprint": "汚れがなくきれいな状態", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ba24b57-71af-43be-bb65-9109da6c8bd6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39370, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "クリーン", "is_correct": true, "explanation": "「〜な印象の服」の形状を表す正解。汚れがなくきれいな様子に合う。"}, {"text": "無料", "is_correct": false, "explanation": "「無料な印象の服」は意味が通らず、服の様子を表せないためここには入らない。"}, {"text": "不要", "is_correct": false, "explanation": "「不要な印象の服」は意味が通らず、服の見た目を表せないためここには入らない。"}, {"text": "空腹", "is_correct": false, "explanation": "「空腹な印象の服」は成り立たず、服の見た目を表す語としてここには入らない。"}], "explanations": {"クリーン": "「〜な印象の服」の形状を表す正解。汚れがなくきれいな様子に合う。", "無料": "「無料な印象の服」は意味が通らず、服の様子を表せないためここには入らない。", "不要": "「不要な印象の服」は意味が通らず、服の見た目を表せないためここには入らない。", "空腹": "「空腹な印象の服」は成り立たず、服の見た目を表す語としてここには入らない。"}, "sentence_index": 0, "correct_answer": "クリーン"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "ゲームのステージをクリーンした。", "explanation": "ここは〈クリア〉（課題を達成する）の意味。クリーンは汚れがない状態を表し、ゲームの課題達成には使わない。"}, {"text": "借金をクリーンした。", "explanation": "ここは〈清算〉（借金を返し切る）の意味。クリーンは汚れのない状態を表し、金銭の返済には使わない。"}, {"text": "害虫をクリーンした。", "explanation": "ここは〈駆除〉（害虫を取り除く）の意味。クリーンは汚れのない状態を表し、害虫を取り除く行為には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea5ab694-501e-4bcd-88e8-65cd964b3418') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39370, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "クリーン", "is_correct": true, "explanation": "洗ったばかりのシーツの清潔な様子を表す正解。"}, {"text": "静寂", "is_correct": false, "explanation": "「静寂でいい香りがした」は意味が通らず、ここには入らない。"}, {"text": "満腹", "is_correct": false, "explanation": "「満腹でいい香りがした」は成り立たず、ここには入らない。"}, {"text": "寝不足", "is_correct": false, "explanation": "「寝不足でいい香りがした」は成り立たず、ここには入らない。"}], "explanations": {"クリーン": "洗ったばかりのシーツの清潔な様子を表す正解。", "静寂": "「静寂でいい香りがした」は意味が通らず、ここには入らない。", "満腹": "「満腹でいい香りがした」は成り立たず、ここには入らない。", "寝不足": "「寝不足でいい香りがした」は成り立たず、ここには入らない。"}, "sentence_index": 6, "correct_answer": "クリーン"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この魚は鮮度がクリーンだ。", "explanation": "ここは〈新鮮〉の意味。クリーンは汚れがないことを表し、鮮度を言う文には使わない。"}, {"text": "彼は迷いなくクリーンに決断した。", "explanation": "ここは〈きっぱり〉（迷わず決める）の意味。クリーンは汚れのないことを表し、決断の仕方には使わない。"}, {"text": "その病気は三週間でクリーンに治った。", "explanation": "ここは〈完治〉（病気が完全に治る）の意味。クリーンは汚れのない状態を表し、病気の治癒には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea5ab694-501e-4bcd-88e8-65cd964b3418') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39370, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "窓ガラスをクリーンな磨いて、部屋を明るくした。", "corrected_sentence": "窓ガラスをクリーンに磨いて、部屋を明るくした。", "error_description": "動詞「磨く」を修飾する形は連用形「クリーンに」。連体形「クリーンな」は動詞を修飾できないので誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "クリーンに", "is_correct": true, "explanation": "「保つ」を修飾する連用形で、文中の形と一致する正解。"}, {"text": "クリーンな", "is_correct": false, "explanation": "連体形で、後ろの動詞「保つ」を修飾できないのでここには入らない。"}, {"text": "クリーンだ", "is_correct": false, "explanation": "終止形で文を言い切る形のため、「保つ」の前には置けない。"}, {"text": "クリーンで", "is_correct": false, "explanation": "て形で、「保つ」を修飾する形にはならないためここには入らない。"}], "correct_form": "クリーンに", "base_form": "クリーン", "form_label": "連用形", "sentence_index": 1, "explanations": {"クリーンに": "「保つ」を修飾する連用形で、文中の形と一致する正解。", "クリーンな": "連体形で、後ろの動詞「保つ」を修飾できないのでここには入らない。", "クリーンだ": "終止形で文を言い切る形のため、「保つ」の前には置けない。", "クリーンで": "て形で、「保つ」を修飾する形にはならないためここには入らない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea5ab694-501e-4bcd-88e8-65cd964b3418') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39370, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "生徒たちは、教室をクリーンで保つため毎朝掃除をしている。", "corrected_sentence": "生徒たちは、教室をクリーンに保つため毎朝掃除をしている。", "error_description": "動詞「保つ」を修飾する形は連用形「クリーンに」。「クリーンで」は動詞を修飾する形にならず誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "クリーンな", "is_correct": true, "explanation": "「店の中が」の後で「なので」につながる連体形で、文中の形と一致する正解。"}, {"text": "クリーンくて", "is_correct": false, "explanation": "形容詞のて形で、形状詞「クリーン」には付かないため「クリーンくてので」となり非文。"}, {"text": "クリーンだろう", "is_correct": false, "explanation": "推量形で、「ので」の前には続かないため「クリーンだろうので」は非文。"}, {"text": "クリーンの", "is_correct": false, "explanation": "「の」は名詞に付く助詞のため、「クリーンので」となり非文。"}], "correct_form": "クリーンな", "base_form": "クリーン", "form_label": "連体形", "sentence_index": 7, "explanations": {"クリーンな": "「店の中が」の後で「なので」につながる連体形で、文中の形と一致する正解。", "クリーンくて": "形容詞のて形で、形状詞「クリーン」には付かないため「クリーンくてので」となり非文。", "クリーンだろう": "推量形で、「ので」の前には続かないため「クリーンだろうので」は非文。", "クリーンの": "「の」は名詞に付く助詞のため、「クリーンので」となり非文。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea5ab694-501e-4bcd-88e8-65cd964b3418') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
