INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39371, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "環境にやさしく、汚染がないこと。", "primary_collocate": null, "pronunciation": "くりーん", "ipa": "kɯɾiːɴ", "syllable_count": 4, "sentences": [{"text": "太陽光は、電気を作るときに燃料を使わないクリーンなエネルギーだ。", "target_word": "クリーン", "complexity_tier": "T3", "furigana": "太陽光[たいようこう]は、電気[でんき]を作[つく]るときに燃料[ねんりょう]を使[つか]わないクリーンなエネルギーだ。", "sentence_source": "generated"}, {"text": "この町はクリーンな空気で有名だ。", "target_word": "クリーン", "complexity_tier": "T3", "furigana": "この町[まち]はクリーンな空気[くうき]で有名[ゆうめい]だ。", "sentence_source": "generated"}, {"text": "電気で走る車は、クリーンな乗り物と言われる。", "target_word": "クリーン", "complexity_tier": "T3", "furigana": "電気[でんき]で走[はし]る車[くるま]は、クリーンな乗[の]り物[もの]と言[い]われる。", "sentence_source": "generated"}, {"text": "風力発電は、汚染が出ないのでクリーンだ。", "target_word": "クリーン", "complexity_tier": "T3", "furigana": "風力発電[ふうりょくはつでん]は、汚染[おせん]が出[で]ないのでクリーンだ。", "sentence_source": "generated"}, {"text": "政府はクリーンなエネルギーを増やす計画を発表した。", "target_word": "クリーン", "complexity_tier": "T3", "furigana": "政府[せいふ]はクリーンなエネルギーを増[ふ]やす計画[けいかく]を発表[はっぴょう]した。", "sentence_source": "generated"}, {"text": "石炭と比べて、天然ガスはクリーンだ。", "target_word": "クリーン", "complexity_tier": "T3", "furigana": "石炭[せきたん]と比[くら]べて、天然[てんねん]ガスはクリーンだ。", "sentence_source": "generated"}, {"text": "工場はクリーンな技術を取り入れ、排水を減らした。", "target_word": "クリーン", "complexity_tier": "T3", "furigana": "工場[こうじょう]はクリーンな技術[ぎじゅつ]を取[と]り入[い]れ、排水[はいすい]を減[へ]らした。", "sentence_source": "generated"}, {"text": "海をクリーンに保つため、みんなで協力している。", "target_word": "クリーン", "complexity_tier": "T3", "furigana": "海[うみ]をクリーンに保[たも]つため、みんなで協力[きょうりょく]している。", "sentence_source": "generated"}, {"text": "クリーンな社会を作るには、ごみを減らすことが必要だ。", "target_word": "クリーン", "complexity_tier": "T3", "furigana": "クリーンな社会[しゃかい]を作[つく]るには、ごみを減[へ]らすことが必要[ひつよう]だ。", "sentence_source": "generated"}, {"text": "煙を出さないクリーンな工場が建った。", "target_word": "クリーン", "complexity_tier": "T3", "furigana": "煙[けむり]を出[だ]さないクリーンな工場[こうじょう]が建[た]った。", "sentence_source": "generated"}], "morphological_forms": [{"form": "クリーンな", "label": "連体形"}, {"form": "クリーンに", "label": "連用形"}, {"form": "クリーンだ", "label": "終止形"}], "register": "neutral", "sense_fingerprint": "環境を汚さず汚染が出ない性質", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ba24b57-71af-43be-bb65-9109da6c8bd6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39371, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "クリーン", "is_correct": true, "explanation": "燃料を使わず環境を汚さないエネルギーを表す正解。"}, {"text": "静寂", "is_correct": false, "explanation": "「静寂なエネルギー」は意味が通らず、エネルギーの性質を表せないためここには入らない。"}, {"text": "満腹", "is_correct": false, "explanation": "「満腹なエネルギー」は成り立たず、ここには入らない。"}, {"text": "寝不足", "is_correct": false, "explanation": "「寝不足なエネルギー」は成り立たず、ここには入らない。"}], "explanations": {"クリーン": "燃料を使わず環境を汚さないエネルギーを表す正解。", "静寂": "「静寂なエネルギー」は意味が通らず、エネルギーの性質を表せないためここには入らない。", "満腹": "「満腹なエネルギー」は成り立たず、ここには入らない。", "寝不足": "「寝不足なエネルギー」は成り立たず、ここには入らない。"}, "sentence_index": 0, "correct_answer": "クリーン"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "政府は感染症をクリーンすると宣言した。", "explanation": "ここは〈撲滅〉（すべて消し去る）の意味。クリーンは汚れがない状態を表し、病気を消し去る意味では使わない。"}, {"text": "彼は会議で、議論をクリーンして結論を出した。", "explanation": "ここは〈収束〉（議論をまとめる）の意味。クリーンは汚れのない状態を表し、議論をまとめる行為には使わない。"}, {"text": "この町は、渋滞をクリーンした。", "explanation": "ここは〈解消〉（障害を取り除く）の意味。クリーンは汚れのない状態を表し、渋滞を解く行為には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea5ab694-501e-4bcd-88e8-65cd964b3418') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39371, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "クリーン", "is_correct": true, "explanation": "環境に配慮した技術を表す正解。排水を減らす文脈に合う。"}, {"text": "空腹", "is_correct": false, "explanation": "「空腹な技術」は意味が通らず、ここには入らない。"}, {"text": "寝坊", "is_correct": false, "explanation": "「寝坊な技術」は成り立たず、ここには入らない。"}, {"text": "不要", "is_correct": false, "explanation": "「不要な技術を取り入れ」は文脈に合わず、性質を表す語として成り立たない。"}], "explanations": {"クリーン": "環境に配慮した技術を表す正解。排水を減らす文脈に合う。", "空腹": "「空腹な技術」は意味が通らず、ここには入らない。", "寝坊": "「寝坊な技術」は成り立たず、ここには入らない。", "不要": "「不要な技術を取り入れ」は文脈に合わず、性質を表す語として成り立たない。"}, "sentence_index": 6, "correct_answer": "クリーン"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼女は質問に対して、クリーンに即答した。", "explanation": "ここは〈即座〉（すぐに）の意味。クリーンは汚れのない状態を表し、答える速さには使わない。"}, {"text": "その病気は三週間でクリーンに治った。", "explanation": "ここは〈完治〉（病気が完全に治る）の意味。クリーンは汚れのない状態を表し、病気の治癒には使わない。"}, {"text": "この野菜は鮮度がクリーンだ。", "explanation": "ここは〈新鮮〉の意味。クリーンは汚れがないことを表し、鮮度を言う文には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea5ab694-501e-4bcd-88e8-65cd964b3418') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39371, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "市は車の排ガスを減らし、空気をクリーンな保っている。", "corrected_sentence": "市は車の排ガスを減らし、空気をクリーンに保っている。", "error_description": "動詞「保つ」を修飾する形は連用形「クリーンに」。連体形「クリーンな」は誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "クリーンな", "is_correct": true, "explanation": "「空気」を修飾する連体形で、文中の形と一致する正解。"}, {"text": "クリーンに", "is_correct": false, "explanation": "連用形で、名詞「空気」を修飾できないためここには入らない。"}, {"text": "クリーンだ", "is_correct": false, "explanation": "終止形で、「この町はクリーンな空気で」の形に合わない。"}, {"text": "クリーンで", "is_correct": false, "explanation": "て形で、名詞「空気」を修飾できないためここには入らない。"}], "correct_form": "クリーンな", "base_form": "クリーン", "form_label": "連体形", "sentence_index": 1, "explanations": {"クリーンな": "「空気」を修飾する連体形で、文中の形と一致する正解。", "クリーンに": "連用形で、名詞「空気」を修飾できないためここには入らない。", "クリーンだ": "終止形で、「この町はクリーンな空気で」の形に合わない。", "クリーンで": "て形で、名詞「空気」を修飾できないためここには入らない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea5ab694-501e-4bcd-88e8-65cd964b3418') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39371, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工場は、排水を浄化して川をクリーンな保っている。", "corrected_sentence": "工場は、排水を浄化して川をクリーンに保っている。", "error_description": "動詞「保つ」を修飾する形は連用形「クリーンに」。連体形「クリーンな」は誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "クリーンに", "is_correct": true, "explanation": "「保つため」の「保つ」を修飾する連用形で、文中の形と一致する正解。"}, {"text": "クリーンです", "is_correct": false, "explanation": "丁寧形で、「海をクリーンです保つ」のように動詞「保つ」を修飾できないため、ここには入らない。"}, {"text": "クリーンだった", "is_correct": false, "explanation": "過去の形で、「保つ」の前には置けないため、ここには入らない。"}, {"text": "クリーンではない", "is_correct": false, "explanation": "否定の形で、「保つ」を修飾する語順にならず、「海をクリーンではない保つ」は成り立たないためここには入らない。"}], "correct_form": "クリーンに", "base_form": "クリーン", "form_label": "連用形", "sentence_index": 7, "explanations": {"クリーンに": "「保つため」の「保つ」を修飾する連用形で、文中の形と一致する正解。", "クリーンです": "丁寧形で、「海をクリーンです保つ」のように動詞「保つ」を修飾できないため、ここには入らない。", "クリーンだった": "過去の形で、「保つ」の前には置けないため、ここには入らない。", "クリーンではない": "否定の形で、「保つ」を修飾する語順にならず、「海をクリーンではない保つ」は成り立たないためここには入らない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea5ab694-501e-4bcd-88e8-65cd964b3418') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39374, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「疾風が吹く」の主語を示す「が」。風が吹くという文の形に合う。"}, {"text": "を", "is_correct": false, "explanation": "「疾風を吹く」と目的語にすると、風が吹かれるものになり意味が通らない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すが、「疾風へ吹く」では風が向かう先を示せず、文が成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "「疾風と吹き」は並列の形になり、動詞「吹き」の主体が定まらず不自然。"}], "correct_answer": "が", "explanations": {"が": "「疾風が吹く」の主語を示す「が」。風が吹くという文の形に合う。", "を": "「疾風を吹く」と目的語にすると、風が吹かれるものになり意味が通らない。", "へ": "「へ」は方向を示すが、「疾風へ吹く」では風が向かう先を示せず、文が成り立たない。", "と": "「疾風と吹き」は並列の形になり、動詞「吹き」の主体が定まらず不自然。"}, "error_tags": {"を": "目的語", "へ": "方向", "と": "並列"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3cf92071-1d16-456b-80e1-4ce44bb16a1a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39374, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「疾風のように」の「の」で、疾風にたとえる修飾を作る。"}, {"text": "が", "is_correct": false, "explanation": "「疾風がように」と主語を置くと、比喩の「ように」につながらず不自然。"}, {"text": "を", "is_correct": false, "explanation": "「疾風をように」と目的語にすると、比喩の形が作れず文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「疾風へように」は方向を示す「へ」が比喩の形に続かず、文が成り立たない。"}], "correct_answer": "の", "explanations": {"の": "「疾風のように」の「の」で、疾風にたとえる修飾を作る。", "が": "「疾風がように」と主語を置くと、比喩の「ように」につながらず不自然。", "を": "「疾風をように」と目的語にすると、比喩の形が作れず文が成り立たない。", "へ": "「疾風へように」は方向を示す「へ」が比喩の形に続かず、文が成り立たない。"}, "error_tags": {"が": "主語", "を": "目的語", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3cf92071-1d16-456b-80e1-4ce44bb16a1a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39374, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "とてもはやいかぜのこと。", "primary_collocate": null, "pronunciation": "しっぷう", "ipa": "ɕippɯː", "syllable_count": 4, "sentences": [{"text": "疾風のように走る馬を見て、みんなが驚いた。", "target_word": "疾風", "complexity_tier": "T3", "furigana": "疾風[しっぷう]のように走[はし]る馬[うま]を見[み]て、みんなが驚[おどろ]いた。", "sentence_source": "generated"}, {"text": "山の上で疾風が吹き、木が大きく揺れた。", "target_word": "疾風", "complexity_tier": "T3", "furigana": "山[やま]の上[うえ]で疾風[しっぷう]が吹[ふ]き、木[き]が大[おお]きく揺[ゆ]れた。", "sentence_source": "generated"}, {"text": "彼は疾風のような速さで教室を出ていった。", "target_word": "疾風", "complexity_tier": "T3", "furigana": "彼[かれ]は疾風[しっぷう]のような速[はや]さで教室[きょうしつ]を出[で]ていった。", "sentence_source": "generated"}, {"text": "疾風が通り過ぎたあと、町はしずかになった。", "target_word": "疾風", "complexity_tier": "T3", "furigana": "疾風[しっぷう]が通[とお]り過[す]ぎたあと、町[まち]はしずかになった。", "sentence_source": "generated"}, {"text": "昨日の夜、疾風のせいで窓がガタガタ鳴った。", "target_word": "疾風", "complexity_tier": "T3", "furigana": "昨日[きのう]の夜[よる]、疾風[しっぷう]のせいで窓[まど]がガタガタ鳴[な]った。", "sentence_source": "generated"}, {"text": "疾風の中を歩くのは大変なので、家で待つことにした。", "target_word": "疾風", "complexity_tier": "T3", "furigana": "疾風[しっぷう]の中[なか]を歩[ある]くのは大変[たいへん]なので、家[いえ]で待[ま]つことにした。", "sentence_source": "generated"}, {"text": "海の近くでは、ときどき疾風が帆を大きくふくらませる。", "target_word": "疾風", "complexity_tier": "T3", "furigana": "海[うみ]の近[ちか]くでは、ときどき疾風[しっぷう]が帆[ほ]を大[おお]きくふくらませる。", "sentence_source": "generated"}, {"text": "忍者は疾風のように屋根の上を走った。", "target_word": "疾風", "complexity_tier": "T3", "furigana": "忍者[にんじゃ]は疾風[しっぷう]のように屋根[やね]の上[うえ]を走[はし]った。", "sentence_source": "generated"}, {"text": "疾風にぼうしを飛ばされて、あわてて追いかけた。", "target_word": "疾風", "complexity_tier": "T3", "furigana": "疾風[しっぷう]にぼうしを飛[と]ばされて、あわてて追[お]いかけた。", "sentence_source": "generated"}, {"text": "疾風が吹いたので、洗濯物が全部飛んでしまった。", "target_word": "疾風", "complexity_tier": "T3", "furigana": "疾風[しっぷう]が吹[ふ]いたので、洗濯物[せんたくもの]が全部[ぜんぶ]飛[と]んでしまった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "疾風", "label": "基本形"}, {"form": "疾風の", "label": "連体形(の)"}], "register": "文語的", "sense_fingerprint": "非常に速く吹く強い風。たとえとしても使う", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80d5caf6-f21d-47d6-aabb-a8ee0a91932d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39374, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "疾風", "is_correct": true, "explanation": "「のように走る」の比喩として、非常に速い風を表す語で、速く走る馬の様子に合う。"}, {"text": "微風", "is_correct": false, "explanation": "微風はそよ風のような弱い風で、驚くほど速く走る馬の比喩にはならない。"}, {"text": "薫風", "is_correct": false, "explanation": "薫風は初夏の心地よい穏やかな風で、速く走る様子の比喩には合わない。"}, {"text": "季節風", "is_correct": false, "explanation": "季節風は季節ごとに決まって吹く風で、速さを表す比喩としては使えない。"}], "explanations": {"疾風": "「のように走る」の比喩として、非常に速い風を表す語で、速く走る馬の様子に合う。", "微風": "微風はそよ風のような弱い風で、驚くほど速く走る馬の比喩にはならない。", "薫風": "薫風は初夏の心地よい穏やかな風で、速く走る様子の比喩には合わない。", "季節風": "季節風は季節ごとに決まって吹く風で、速さを表す比喩としては使えない。"}, "sentence_index": 0, "correct_answer": "疾風"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "夏の夕方、疾風が心地よく頬をなでていった。", "explanation": "ここは〈微風〉の意味。疾風は激しく速い風なので、心地よい穏やかな風には合わない。"}, {"text": "母は心臓の疾風で三週間入院した。", "explanation": "ここは〈疾患〉（病気）と取り違えている。疾風は風のことで、病気には使わない。"}, {"text": "春の疾風が桜の花びらを優しく散らした。", "explanation": "ここは〈春風〉の意味。疾風は激しく速い風で、春の穏やかな風の代わりにはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3cf92071-1d16-456b-80e1-4ce44bb16a1a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39374, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "疾風", "is_correct": true, "explanation": "帆をふくらませるほどの強い風を表し、文の主語として自然に合う。"}, {"text": "霧", "is_correct": false, "explanation": "霧は立ちこめるもので、帆をふくらませる力はない。"}, {"text": "雹", "is_correct": false, "explanation": "雹は空から降ってくるもので、帆を大きくふくらませることはない。"}, {"text": "雪", "is_correct": false, "explanation": "雪は降り積もるもので、帆をふくらませる働きは持たない。"}], "explanations": {"疾風": "帆をふくらませるほどの強い風を表し、文の主語として自然に合う。", "霧": "霧は立ちこめるもので、帆をふくらませる力はない。", "雹": "雹は空から降ってくるもので、帆を大きくふくらませることはない。", "雪": "雪は降り積もるもので、帆をふくらませる働きは持たない。"}, "sentence_index": 6, "correct_answer": "疾風"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "窓辺で疾風がそよそよと髪を揺らしている。", "explanation": "ここは〈そよ風〉の意味。疾風は激しく速い風なので、そよそよ揺れる穏やかな風には合わない。"}, {"text": "その研究所は子どもに多い疾風を調べている。", "explanation": "ここは〈疾病〉（病気）の意味。疾風は風のことで、病気の名前には使わない。"}, {"text": "夏の夕暮れ、疾風がほどよい涼しさを運んできた。", "explanation": "ここは〈涼風〉の意味。疾風は激しく速い風で、ほどよい涼しさを運ぶ風とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3cf92071-1d16-456b-80e1-4ce44bb16a1a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39374, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "疾風を吹いて、窓がガタガタ鳴った。", "corrected_sentence": "疾風が吹いて、窓がガタガタ鳴った。", "error_description": "「疾風」は「吹く」の主語なので「が」が正しい。「を」は目的語を示す助詞で、「疾風を吹く」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3cf92071-1d16-456b-80e1-4ce44bb16a1a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39374, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "海の近くでは、ときどき疾風を帆をふくらませる。", "corrected_sentence": "海の近くでは、ときどき疾風が帆をふくらませる。", "error_description": "「疾風」は「ふくらませる」の主語なので「が」が正しい。「を」にすると「を」が二つ続いて文が壊れ、誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3cf92071-1d16-456b-80e1-4ce44bb16a1a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39376, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "主題を示す「は」。風車が文の主題（主語）になる。"}, {"text": "を", "is_correct": false, "explanation": "目的語を示す「を」。ここでは「つくる」の目的語は「電気」なので、風車には「を」が付かない。"}, {"text": "に", "is_correct": false, "explanation": "相手・場所を示す「に」。風車を発電の相手にする文は不自然。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す「へ」。風車が向かう先を表さないので合わない。"}], "correct_answer": "は", "explanations": {"は": "主題を示す「は」。風車が文の主題（主語）になる。", "を": "目的語を示す「を」。ここでは「つくる」の目的語は「電気」なので、風車には「を」が付かない。", "に": "相手・場所を示す「に」。風車を発電の相手にする文は不自然。", "へ": "方向を示す「へ」。風車が向かう先を表さないので合わない。"}, "error_tags": {"を": "目的語", "に": "相手・場所", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '14797358-abb1-41c2-b4e0-49bf54ce91a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39376, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '14797358-abb1-41c2-b4e0-49bf54ce91a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39376, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "かぜでまわるくるまだよ。でんきをつくるはたらきがあるよ。", "primary_collocate": null, "pronunciation": "かざぐるま", "ipa": "kazaɡɯɾɯma", "syllable_count": 5, "sentences": [{"text": "風が強いので、風車がくるくる回っています。", "target_word": "風車", "complexity_tier": "T3", "furigana": "風[かぜ]が強[つよ]いので、風車[かざぐるま]がくるくる回[まわ]っています。", "sentence_source": "generated"}, {"text": "丘の上の風車は、風の力で電気をつくります。", "target_word": "風車", "complexity_tier": "T3", "furigana": "丘[おか]の上[うえ]の風車[かざぐるま]は、風[かぜ]の力[ちから]で電気[でんき]をつくります。", "sentence_source": "generated"}, {"text": "この町には大きな風車が三つあります。", "target_word": "風車", "complexity_tier": "T3", "furigana": "この町[まち]には大[おお]きな風車[かざぐるま]が三[みっ]つあります。", "sentence_source": "generated"}, {"text": "風がやんだので、風車は止まってしまいました。", "target_word": "風車", "complexity_tier": "T3", "furigana": "風[かぜ]がやんだので、風車[かざぐるま]は止[と]まってしまいました。", "sentence_source": "generated"}, {"text": "風車のおかげで、学校の電気がつきました。", "target_word": "風車", "complexity_tier": "T3", "furigana": "風車[かざぐるま]のおかげで、学校[がっこう]の電気[でんき]がつきました。", "sentence_source": "generated"}, {"text": "海の近くは風が強いから、風車をたくさん建てます。", "target_word": "風車", "complexity_tier": "T3", "furigana": "海[うみ]の近[ちか]くは風[かぜ]が強[つよ]いから、風車[かざぐるま]をたくさん建[た]てます。", "sentence_source": "generated"}, {"text": "風車が回ると、電気ができて、みんなの家に届きます。", "target_word": "風車", "complexity_tier": "T3", "furigana": "風車[かざぐるま]が回[まわ]ると、電気[でんき]ができて、みんなの家[いえ]に届[とど]きます。", "sentence_source": "generated"}, {"text": "弱い風では、風車はあまり回りません。", "target_word": "風車", "complexity_tier": "T3", "furigana": "弱[よわ]い風[かぜ]では、風車[かざぐるま]はあまり回[まわ]りません。", "sentence_source": "generated"}, {"text": "先生は風車を指さして、「これが電気をつくる機械です」と教えてくれました。", "target_word": "風車", "complexity_tier": "T3", "furigana": "先生[せんせい]は風車[かざぐるま]を指[ゆび]さして、「これが電気[でんき]をつくる機械[きかい]です」と教[おし]えてくれました。", "sentence_source": "generated"}, {"text": "夜になっても、風があれば風車は電気をつくりつづけます。", "target_word": "風車", "complexity_tier": "T3", "furigana": "夜[よる]になっても、風[かぜ]があれば風車[かざぐるま]は電気[でんき]をつくりつづけます。", "sentence_source": "generated"}], "morphological_forms": [{"form": "風車", "label": "基本形"}], "register": "子ども向けのやさしい丁寧体", "sense_fingerprint": "風の力で回って電気をつくる大きな羽根の機械", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4930162-e49e-4526-a312-ee6d7f8dd798') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39376, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "風車", "is_correct": true, "explanation": "風の力で羽根が回る装置で、「くるくる回っています」に合う。"}, {"text": "煙突", "is_correct": false, "explanation": "筒状の設備で回転しないので、「くるくる回る」とは合わない。"}, {"text": "鉄塔", "is_correct": false, "explanation": "電線を支える骨組みで、回転しないので合わない。"}, {"text": "旗", "is_correct": false, "explanation": "風になびくだけで、くるくる回る動きはしない。"}], "explanations": {"風車": "風の力で羽根が回る装置で、「くるくる回っています」に合う。", "煙突": "筒状の設備で回転しないので、「くるくる回る」とは合わない。", "鉄塔": "電線を支える骨組みで、回転しないので合わない。", "旗": "風になびくだけで、くるくる回る動きはしない。"}, "sentence_index": 0, "correct_answer": "風車"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "縁側の風車が、ちりんと涼しい音を鳴らしています。", "explanation": "ここは〈風鈴〉の意味。風鈴は風で音を鳴らす涼しげな飾りで、風車は風の力で発電する装置なので、音を鳴らす物としては合わない。"}, {"text": "夏の暑い日は、風車を回して部屋を涼しくします。", "explanation": "ここは〈扇風機〉の意味。風車は風の力で発電する装置で、部屋を冷やす道具ではない。"}, {"text": "工場の換気では、風車で空気を大きく送ります。", "explanation": "ここは〈送風機〉の意味。風車は風の力で発電する装置で、空気を送る機械ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '14797358-abb1-41c2-b4e0-49bf54ce91a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39376, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "風車", "is_correct": true, "explanation": "回って電気を生む装置で、「回ると、電気ができて」の主語に合う。"}, {"text": "蛇口", "is_correct": false, "explanation": "回すと水が出るもので、電気は生まないので合わない。"}, {"text": "洗濯機", "is_correct": false, "explanation": "回って衣類を洗う家電で、電気を届ける元にはならないので合わない。"}, {"text": "時計", "is_correct": false, "explanation": "針が回って時刻を示す道具で、電気をつくる働きはないので合わない。"}], "explanations": {"風車": "回って電気を生む装置で、「回ると、電気ができて」の主語に合う。", "蛇口": "回すと水が出るもので、電気は生まないので合わない。", "洗濯機": "回って衣類を洗う家電で、電気を届ける元にはならないので合わない。", "時計": "針が回って時刻を示す道具で、電気をつくる働きはないので合わない。"}, "sentence_index": 6, "correct_answer": "風車"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "風車が川の流れで回り、田んぼに水を送ります。", "explanation": "ここは〈水車〉の意味。風車は風の力で回る装置で、川の流れでは回らない。"}, {"text": "屋根の上の風車が、風向きを示しています。", "explanation": "ここは〈風見鶏〉の意味。風車は風の力で発電する装置で、風向きを示す飾りではない。"}, {"text": "暑い日は、風車を手に持って顔をあおぎます。", "explanation": "ここは〈扇子〉の意味。扇子は手に持って顔をあおぐ道具で、風車は風の力で発電する装置なので、あおぐ道具としては合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '14797358-abb1-41c2-b4e0-49bf54ce91a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39376, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "海辺の風車を、風の力で回っています。", "corrected_sentence": "海辺の風車は、風の力で回っています。", "error_description": "「風車」に続く助詞が「を」になっている。「回る」は自動詞で主語を「は」「が」で示すので、正しくは「は」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '14797358-abb1-41c2-b4e0-49bf54ce91a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39376, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "風が弱い日は、風車に発電量が減ります。", "corrected_sentence": "風が弱い日は、風車の発電量が減ります。", "error_description": "「風車」に続く助詞が「に」になっている。「発電量」は風車の量を表すので、所属の「の」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '14797358-abb1-41c2-b4e0-49bf54ce91a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39377, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "主題を示す「は」。風車が文の主語になる。"}, {"text": "に", "is_correct": false, "explanation": "相手・場所を示す「に」。風車に電気を供給する相手として合わない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す「へ」。電気を届ける先を風車に付けるのは不自然。"}, {"text": "と", "is_correct": false, "explanation": "並列を示す「と」。風車と一年が並ぶ文にはならない。"}], "correct_answer": "は", "explanations": {"は": "主題を示す「は」。風車が文の主語になる。", "に": "相手・場所を示す「に」。風車に電気を供給する相手として合わない。", "へ": "方向を示す「へ」。電気を届ける先を風車に付けるのは不自然。", "と": "並列を示す「と」。風車と一年が並ぶ文にはならない。"}, "error_tags": {"に": "相手・場所", "へ": "方向", "と": "並列"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '14797358-abb1-41c2-b4e0-49bf54ce91a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39377, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "手段を示す「で」。風車が電気をまかなう手段になる。"}, {"text": "を", "is_correct": false, "explanation": "目的語の「を」。「まかなわれる」の文は目的語を取らず、風車には「を」が付かない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す「へ」。電気をまかなう動作主や手段にはならないので合わない。"}, {"text": "と", "is_correct": false, "explanation": "並列・共同の「と」。手段を表せない。"}], "correct_answer": "で", "explanations": {"で": "手段を示す「で」。風車が電気をまかなう手段になる。", "を": "目的語の「を」。「まかなわれる」の文は目的語を取らず、風車には「を」が付かない。", "へ": "方向を示す「へ」。電気をまかなう動作主や手段にはならないので合わない。", "と": "並列・共同の「と」。手段を表せない。"}, "error_tags": {"を": "目的語", "へ": "方向", "と": "並列・共同"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '14797358-abb1-41c2-b4e0-49bf54ce91a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39377, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "風の力で羽根が回り、その力で発電する装置です。", "primary_collocate": null, "pronunciation": "かざぐるま", "ipa": "kazaɡɯɾɯma", "syllable_count": 5, "sentences": [{"text": "山の上に建てられた風車が、強い風を受けて回っている。", "target_word": "風車", "complexity_tier": "T3", "furigana": "山[やま]の上[うえ]に建[た]てられた風車[かざぐるま]が、強[つよ]い風[かぜ]を受[う]けて回[まわ]っている。", "sentence_source": "generated"}, {"text": "この風車は一年で百軒分の電気をまかなえる。", "target_word": "風車", "complexity_tier": "T3", "furigana": "この風車[かざぐるま]は一年[いちねん]で百軒分[ひゃっけんぶん]の電気[でんき]をまかなえる。", "sentence_source": "generated"}, {"text": "風が弱い日は、風車の発電量が減る。", "target_word": "風車", "complexity_tier": "T3", "furigana": "風[かぜ]が弱[よわ]い日[ひ]は、風車[かざぐるま]の発電量[はつでんりょう]が減[へ]る。", "sentence_source": "generated"}, {"text": "海沿いの町では、新しい風車の建設が進んでいる。", "target_word": "風車", "complexity_tier": "T3", "furigana": "海沿[うみぞ]いの町[まち]では、新[あたら]しい風車[かざぐるま]の建設[けんせつ]が進[すす]んでいる。", "sentence_source": "generated"}, {"text": "台風の前に、風車の羽根を止めて安全を確保した。", "target_word": "風車", "complexity_tier": "T3", "furigana": "台風[たいふう]の前[まえ]に、風車[かざぐるま]の羽根[はね]を止[と]めて安全[あんぜん]を確保[かくほ]した。", "sentence_source": "generated"}, {"text": "風車は風の力を電気に変える装置である。", "target_word": "風車", "complexity_tier": "T3", "furigana": "風車[かざぐるま]は風[かぜ]の力[ちから]を電気[でんき]に変[か]える装置[そうち]である。", "sentence_source": "generated"}, {"text": "騒音が出るため、風車は住宅から離れた場所に建てる。", "target_word": "風車", "complexity_tier": "T3", "furigana": "騒音[そうおん]が出[で]るため、風車[かざぐるま]は住宅[じゅうたく]から離[はな]れた場所[ばしょ]に建[た]てる。", "sentence_source": "generated"}, {"text": "町の電気の一部は、湖のそばの風車でまかなわれている。", "target_word": "風車", "complexity_tier": "T3", "furigana": "町[まち]の電気[でんき]の一部[いちぶ]は、湖[みずうみ]のそばの風車[かざぐるま]でまかなわれている。", "sentence_source": "generated"}, {"text": "羽根が長い風車ほど、多くの風を受けることができる。", "target_word": "風車", "complexity_tier": "T3", "furigana": "羽根[はね]が長[なが]い風車[かざぐるま]ほど、多[おお]くの風[かぜ]を受[う]けることができる。", "sentence_source": "generated"}, {"text": "風がないと、どんなに大きな風車でも発電できない。", "target_word": "風車", "complexity_tier": "T3", "furigana": "風[かぜ]がないと、どんなに大[おお]きな風車[かざぐるま]でも発電[はつでん]できない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "風車", "label": "基本形"}], "register": "標準的な書き言葉(常体)", "sense_fingerprint": "風力で羽根を回して発電する装置", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4930162-e49e-4526-a312-ee6d7f8dd798') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39377, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "風車", "is_correct": true, "explanation": "風で羽根が回る装置で、「強い風を受けて回っている」の主語に合う。"}, {"text": "煙突", "is_correct": false, "explanation": "建てられた筒状の設備で、強い風を受けても回らないので合わない。"}, {"text": "電柱", "is_correct": false, "explanation": "電線を支える柱で、回転しないので合わない。"}, {"text": "旗", "is_correct": false, "explanation": "風になびくだけで、回転はしないので合わない。"}], "explanations": {"風車": "風で羽根が回る装置で、「強い風を受けて回っている」の主語に合う。", "煙突": "建てられた筒状の設備で、強い風を受けても回らないので合わない。", "電柱": "電線を支える柱で、回転しないので合わない。", "旗": "風になびくだけで、回転はしないので合わない。"}, "sentence_index": 0, "correct_answer": "風車"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "蒸し暑い夜、風車を開いて顔をあおいだ。", "explanation": "ここは〈扇子〉の意味。扇子は開いて顔をあおぐ道具で、風車は風の力で発電する装置なので、あおぐ道具としては合わない。"}, {"text": "工場の風車が、空気を大きく送っている。", "explanation": "ここは〈送風機〉の意味。風車は風の力で発電する装置で、空気を送る機械ではない。"}, {"text": "川の水で風車を回して、米をつく。", "explanation": "ここは〈水車〉の意味。風車は風で回る装置で、水の流れで回すものではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '14797358-abb1-41c2-b4e0-49bf54ce91a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39377, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "風車", "is_correct": true, "explanation": "騒音を出す装置で、住宅から離して建てる主語に合う。"}, {"text": "花壇", "is_correct": false, "explanation": "建てる対象ではなく、騒音も出さないので合わない。"}, {"text": "芝生", "is_correct": false, "explanation": "建てるものではないので合わない。"}, {"text": "植木鉢", "is_correct": false, "explanation": "建てるものではなく、騒音も出さないので合わない。"}], "explanations": {"風車": "騒音を出す装置で、住宅から離して建てる主語に合う。", "花壇": "建てる対象ではなく、騒音も出さないので合わない。", "芝生": "建てるものではないので合わない。", "植木鉢": "建てるものではなく、騒音も出さないので合わない。"}, "sentence_index": 6, "correct_answer": "風車"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "軒先の風車が、涼しい音を鳴らしている。", "explanation": "ここは〈風鈴〉の意味。風鈴は風で音を鳴らす飾りで、風車は風の力で発電する装置なので、音を鳴らす物としては合わない。"}, {"text": "蒸し暑い夜は、風車を回して寝室を涼しくする。", "explanation": "ここは〈扇風機〉の意味。扇風機は電気で風を送る道具で、風車は風の力で発電する装置なので、部屋を涼しくする機械ではない。"}, {"text": "風車が屋根の上で、風向きを示している。", "explanation": "ここは〈風見鶏〉の意味。風車は風の力で回り発電する装置で、風向きを示す飾りではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '14797358-abb1-41c2-b4e0-49bf54ce91a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39377, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "強い風が吹くと、風車を羽根が速く回る。", "corrected_sentence": "強い風が吹くと、風車の羽根が速く回る。", "error_description": "「風車」に続く助詞が「を」になっている。「羽根」は風車の一部なので、所属の「の」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '14797358-abb1-41c2-b4e0-49bf54ce91a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39377, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "湖のそばでは、新しい風車を建設が進んでいる。", "corrected_sentence": "湖のそばでは、新しい風車の建設が進んでいる。", "error_description": "「風車」に続く助詞が「を」になっている。「建設」は名詞なので、所属の「の」で続けるのが正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '14797358-abb1-41c2-b4e0-49bf54ce91a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39378, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「自転車のタイヤ」の「の」で、タイヤが自転車の一部だと示す。"}, {"text": "を", "is_correct": false, "explanation": "「自転車をタイヤに空気を入れた」では、自転車が目的語になり意味が通らない。"}, {"text": "に", "is_correct": false, "explanation": "「自転車にタイヤに」と「に」が二つ続き、文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「自転車へタイヤに」は方向を示すが、空気を入れる文の中では成り立たない。"}], "correct_answer": "の", "explanations": {"の": "「自転車のタイヤ」の「の」で、タイヤが自転車の一部だと示す。", "を": "「自転車をタイヤに空気を入れた」では、自転車が目的語になり意味が通らない。", "に": "「自転車にタイヤに」と「に」が二つ続き、文が成り立たない。", "へ": "「自転車へタイヤに」は方向を示すが、空気を入れる文の中では成り立たない。"}, "error_tags": {"を": "目的語", "に": "着点", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3cf92071-1d16-456b-80e1-4ce44bb16a1a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39378, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「自転車が止めてある」の主語を示す「が」で、止められた自転車の状態を述べる。"}, {"text": "に", "is_correct": false, "explanation": "「自転車にたくさん止めてある」では、止める対象の関係が成り立たず不自然。"}, {"text": "へ", "is_correct": false, "explanation": "「自転車へたくさん止めてある」は方向を示す「へ」が合わず、文が成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "「自転車で止めてある」は手段を示すことになり、自転車を止める道具のような意味になって不自然。"}], "correct_answer": "が", "explanations": {"が": "「自転車が止めてある」の主語を示す「が」で、止められた自転車の状態を述べる。", "に": "「自転車にたくさん止めてある」では、止める対象の関係が成り立たず不自然。", "へ": "「自転車へたくさん止めてある」は方向を示す「へ」が合わず、文が成り立たない。", "で": "「自転車で止めてある」は手段を示すことになり、自転車を止める道具のような意味になって不自然。"}, "error_tags": {"に": "着点", "へ": "方向", "で": "手段"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3cf92071-1d16-456b-80e1-4ce44bb16a1a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39378, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "ペダルをこいで自分で走らせる二輪の乗り物。", "primary_collocate": null, "pronunciation": "じてんしゃ", "ipa": "dʑitenɕa", "syllable_count": 4, "sentences": [{"text": "毎朝、自転車で駅まで行きます。", "target_word": "自転車", "complexity_tier": "T3", "furigana": "毎朝[まいあさ]、自転車[じてんしゃ]で駅[えき]まで行[い]きます。", "sentence_source": "generated"}, {"text": "自転車のタイヤに空気を入れた。", "target_word": "自転車", "complexity_tier": "T3", "furigana": "自転車[じてんしゃ]のタイヤに空気[くうき]を入[い]れた。", "sentence_source": "generated"}, {"text": "雨の日は自転車に乗らないで、バスを使う。", "target_word": "自転車", "complexity_tier": "T3", "furigana": "雨[あめ]の日[ひ]は自転車[じてんしゃ]に乗[の]らないで、バスを使[つか]う。", "sentence_source": "generated"}, {"text": "兄は新しい自転車を買ってもらってうれしそうだ。", "target_word": "自転車", "complexity_tier": "T3", "furigana": "兄[あに]は新[あたら]しい自転車[じてんしゃ]を買[か]ってもらってうれしそうだ。", "sentence_source": "generated"}, {"text": "自転車が壊れたので、店で直してもらった。", "target_word": "自転車", "complexity_tier": "T3", "furigana": "自転車[じてんしゃ]が壊[こわ]れたので、店[みせ]で直[なお]してもらった。", "sentence_source": "generated"}, {"text": "公園で子どもが自転車の練習をしている。", "target_word": "自転車", "complexity_tier": "T3", "furigana": "公園[こうえん]で子[こ]どもが自転車[じてんしゃ]の練習[れんしゅう]をしている。", "sentence_source": "generated"}, {"text": "坂道では自転車をおして歩いたほうが安全だ。", "target_word": "自転車", "complexity_tier": "T3", "furigana": "坂道[さかみち]では自転車[じてんしゃ]をおして歩[ある]いたほうが安全[あんぜん]だ。", "sentence_source": "generated"}, {"text": "駅の前に自転車がたくさん止めてある。", "target_word": "自転車", "complexity_tier": "T3", "furigana": "駅[えき]の前[まえ]に自転車[じてんしゃ]がたくさん止[と]めてある。", "sentence_source": "generated"}, {"text": "自転車は電車より遅いが、好きな所で止まれる。", "target_word": "自転車", "complexity_tier": "T3", "furigana": "自転車[じてんしゃ]は電車[でんしゃ]より遅[おそ]いが、好[す]きな所[ところ]で止[と]まれる。", "sentence_source": "generated"}, {"text": "夜は自転車のライトをつけなければならない。", "target_word": "自転車", "complexity_tier": "T3", "furigana": "夜[よる]は自転車[じてんしゃ]のライトをつけなければならない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "自転車", "label": "基本形"}, {"form": "自転車で", "label": "手段(で)"}], "register": "中立", "sense_fingerprint": "ペダルをこいで走る二輪の乗り物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80d5caf6-f21d-47d6-aabb-a8ee0a91932d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39378, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "自転車", "is_correct": true, "explanation": "「で駅まで行く」の手段を表し、ペダルで走る乗り物として文に合う。"}, {"text": "車輪", "is_correct": false, "explanation": "車輪は自転車の部品で、乗って駅まで行く手段の名前にはならない。"}, {"text": "駐輪場", "is_correct": false, "explanation": "駐輪場は自転車を止める場所で、「駐輪場で駅まで行く」とは言えない。"}, {"text": "ペダル", "is_correct": false, "explanation": "ペダルは自転車を漕ぐ部品で、駅まで行く手段の名前にはならない。"}], "explanations": {"自転車": "「で駅まで行く」の手段を表し、ペダルで走る乗り物として文に合う。", "車輪": "車輪は自転車の部品で、乗って駅まで行く手段の名前にはならない。", "駐輪場": "駐輪場は自転車を止める場所で、「駐輪場で駅まで行く」とは言えない。", "ペダル": "ペダルは自転車を漕ぐ部品で、駅まで行く手段の名前にはならない。"}, "sentence_index": 0, "correct_answer": "自転車"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "兄は新しい自転車のエンジンを試運転している。", "explanation": "ここは〈自動車〉と取り違えている。自転車はペダルで動くので、エンジンはない。"}, {"text": "地球の自転車によって、昼と夜が生まれる。", "explanation": "ここは〈自転〉（天体の回転）の意味。自転車は乗り物なので、地球の回転の意味にはならない。"}, {"text": "兄は自転車を操縦する練習を続けている。", "explanation": "操縦は飛行機などに使う語で、自転車には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3cf92071-1d16-456b-80e1-4ce44bb16a1a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39378, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "自転車", "is_correct": true, "explanation": "押して歩ける乗り物で、「をおして歩く」の目的語として自然に合う。"}, {"text": "電車", "is_correct": false, "explanation": "電車は押して歩くものではなく、「電車をおして歩く」は不自然。"}, {"text": "飛行機", "is_correct": false, "explanation": "飛行機を押して歩くことは成り立たず、文に合わない。"}, {"text": "新幹線", "is_correct": false, "explanation": "新幹線は線路の上を走るもので、押して歩くものではない。"}], "explanations": {"自転車": "押して歩ける乗り物で、「をおして歩く」の目的語として自然に合う。", "電車": "電車は押して歩くものではなく、「電車をおして歩く」は不自然。", "飛行機": "飛行機を押して歩くことは成り立たず、文に合わない。", "新幹線": "新幹線は線路の上を走るもので、押して歩くものではない。"}, "sentence_index": 6, "correct_answer": "自転車"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "雨の日は自転車のマフラーを交換した。", "explanation": "ここは〈バイク〉（エンジン付きの二輪車）と取り違えている。マフラーは自転車にはない部品。"}, {"text": "牧場の人は自転車の手綱を引いて、草原へ歩いて行った。", "explanation": "ここは〈馬〉の意味。手綱は馬を導く道具なので、自転車には使わない。"}, {"text": "観光客は京都で、自転車を引く車夫に行き先を告げた。", "explanation": "ここは〈人力車〉の意味。車夫が引く乗り物なので、自転車を引く人の話としては合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3cf92071-1d16-456b-80e1-4ce44bb16a1a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39378, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "毎朝、自転車に学校まで行きます。", "corrected_sentence": "毎朝、自転車で学校まで行きます。", "error_description": "手段を示すには「で」が正しい。「に」は到着点や相手を示すので、「自転車に行く」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3cf92071-1d16-456b-80e1-4ce44bb16a1a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39378, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "夜、自転車を乗るときは、ライトをつけなければならない。", "corrected_sentence": "夜、自転車に乗るときは、ライトをつけなければならない。", "error_description": "「乗る」は「に」を取るので「自転車に乗る」が正しい。「を」は目的語を示し、「自転車を乗る」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3cf92071-1d16-456b-80e1-4ce44bb16a1a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39380, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「見えた」の主語を示す「が」。これが正解。"}, {"text": "を", "is_correct": false, "explanation": "「見える」は自動詞なので、目的語の「を」は取らない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列や引用を表すので、この文の主語は作らない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表すが、「見えた」の主語にはならない。"}], "correct_answer": "が", "explanations": {"が": "「見えた」の主語を示す「が」。これが正解。", "を": "「見える」は自動詞なので、目的語の「を」は取らない。", "と": "「と」は並列や引用を表すので、この文の主語は作らない。", "へ": "「へ」は方向を表すが、「見えた」の主語にはならない。"}, "error_tags": {"が": "主語", "を": "目的語", "と": "並列・引用", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea5ab694-501e-4bcd-88e8-65cd964b3418') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39380, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「暗くする」の対象を示す「を」。これが正解。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を示すので、「暗くした」の対象にはならない。"}, {"text": "に", "is_correct": false, "explanation": "「に」は結果を表すが、「暗くした」の対象には使わない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表すが、「暗くした」の対象にはならない。"}], "correct_answer": "を", "explanations": {"を": "「暗くする」の対象を示す「を」。これが正解。", "が": "「が」は主語を示すので、「暗くした」の対象にはならない。", "に": "「に」は結果を表すが、「暗くした」の対象には使わない。", "へ": "「へ」は方向を表すが、「暗くした」の対象にはならない。"}, "error_tags": {"を": "目的語", "が": "主語", "に": "結果", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea5ab694-501e-4bcd-88e8-65cd964b3418') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39380, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "車や懐中電灯など、持ち運んだり乗り物に付いたりして、前方や暗い所を照らす光源。", "primary_collocate": null, "pronunciation": "らいと", "ipa": "ɾaito", "syllable_count": 3, "sentences": [{"text": "暗い道で、車のライトが前を照らした。", "target_word": "ライト", "complexity_tier": "T3", "furigana": "暗[くら]い道[みち]で、車[くるま]のライトが前[まえ]を照[て]らした。", "sentence_source": "generated"}, {"text": "夜、窓の外にライトが見えた。", "target_word": "ライト", "complexity_tier": "T3", "furigana": "夜[よる]、窓[まど]の外[そと]にライトが見[み]えた。", "sentence_source": "generated"}, {"text": "停電の夜、ライトをつけて廊下を歩いた。", "target_word": "ライト", "complexity_tier": "T3", "furigana": "停電[ていでん]の夜[よる]、ライトをつけて廊下[ろうか]を歩[ある]いた。", "sentence_source": "generated"}, {"text": "山道は暗いから、ライトを持って行こう。", "target_word": "ライト", "complexity_tier": "T3", "furigana": "山道[やまみち]は暗[くら]いから、ライトを持[も]って行[い]こう。", "sentence_source": "generated"}, {"text": "霧の中、対向車のライトがまぶしかった。", "target_word": "ライト", "complexity_tier": "T3", "furigana": "霧[きり]の中[なか]、対向車[たいこうしゃ]のライトがまぶしかった。", "sentence_source": "generated"}, {"text": "車のライトが消えて、道は真っ暗になった。", "target_word": "ライト", "complexity_tier": "T3", "furigana": "車[くるま]のライトが消[き]えて、道[みち]は真[ま]っ暗[くら]になった。", "sentence_source": "generated"}, {"text": "自転車のライトが切れていて、夜は危ない。", "target_word": "ライト", "complexity_tier": "T3", "furigana": "自転車[じてんしゃ]のライトが切[き]れていて、夜[よる]は危[あぶ]ない。", "sentence_source": "generated"}, {"text": "眠る前に、ライトを暗くした。", "target_word": "ライト", "complexity_tier": "T3", "furigana": "眠[ねむ]る前[まえ]に、ライトを暗[くら]くした。", "sentence_source": "generated"}, {"text": "強いライトが目に入り、まぶしかった。", "target_word": "ライト", "complexity_tier": "T3", "furigana": "強[つよ]いライトが目[め]に入[はい]り、まぶしかった。", "sentence_source": "generated"}, {"text": "海の上で、船のライトがゆっくり動いていた。", "target_word": "ライト", "complexity_tier": "T3", "furigana": "海[うみ]の上[うえ]で、船[ふね]のライトがゆっくり動[うご]いていた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "ライト", "label": "基本形"}, {"form": "ライトを", "label": "を格"}], "register": "neutral", "sense_fingerprint": "車のライトや懐中電灯など、前方や暗所を照らす光源", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 4 above tier T2: contains vocabulary far above tier T2: まぶしかっ (Zipf 1.88)','sentence 8 above tier T2: contains vocabulary far above tier T2: まぶしかっ (Zipf 1.88)']::text[], '6ba24b57-71af-43be-bb65-9109da6c8bd6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39380, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "ライト", "is_correct": true, "explanation": "光を出す装置として、「車のライトが前を照らす」の主語に自然に入る。"}, {"text": "タイヤ", "is_correct": false, "explanation": "タイヤは光を出さないので、前を照らす主語にならない。"}, {"text": "ミラー", "is_correct": false, "explanation": "ミラーは光を反射するだけで照らさないため、「照らした」と合わない。"}, {"text": "ブレーキ", "is_correct": false, "explanation": "ブレーキは止めるための部品で、光を出して前を照らすことはない。"}], "explanations": {"ライト": "光を出す装置として、「車のライトが前を照らす」の主語に自然に入る。", "タイヤ": "タイヤは光を出さないので、前を照らす主語にならない。", "ミラー": "ミラーは光を反射するだけで照らさないため、「照らした」と合わない。", "ブレーキ": "ブレーキは止めるための部品で、光を出して前を照らすことはない。"}, "sentence_index": 0, "correct_answer": "ライト"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "草むらで、ライトが一匹ずつ瞬いていた。", "explanation": "〈蛍〉（虫が出す光）と混同した使い方。ライトは虫の光を指さないので、この文には合わない。"}, {"text": "夜の部屋で、ライトの芯を短く切って、炎を弱めた。", "explanation": "〈ろうそく〉（芯と炎のある灯り）と混同した使い方。ライトには芯がないので、芯を切る文には合わない。"}, {"text": "夕方のライトが、部屋を赤く染めた。", "explanation": "〈夕日〉（夕方の赤い日差し）と混同した使い方。夕日は〈ライト〉とは言わないので、この文には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea5ab694-501e-4bcd-88e8-65cd964b3418') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39380, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "ライト", "is_correct": true, "explanation": "「切れている」光源として、夜の危なさの文脈に合う。"}, {"text": "鍵", "is_correct": false, "explanation": "鍵は光を出さないので、夜の危なさを説明する主語として合わない。"}, {"text": "ペダル", "is_correct": false, "explanation": "ペダルは光を出さないので、夜の危なさの文脈と合わない。"}, {"text": "ベル", "is_correct": false, "explanation": "ベルは音を出す部品で、光の話には合わない。"}], "explanations": {"ライト": "「切れている」光源として、夜の危なさの文脈に合う。", "鍵": "鍵は光を出さないので、夜の危なさを説明する主語として合わない。", "ペダル": "ペダルは光を出さないので、夜の危なさの文脈と合わない。", "ベル": "ベルは音を出す部品で、光の話には合わない。"}, "sentence_index": 6, "correct_answer": "ライト"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "雷の夜、空でライトが光って、窓がびりびり震えた。", "explanation": "〈稲妻〉と混同した使い方。空を走る稲妻は〈ライト〉とは言わないので、この文には合わない。"}, {"text": "ライトの火が風で揺れて、部屋が暗くなった。", "explanation": "〈ランプ〉（炎のある照明）と混同した使い方。〈ライト〉は炎を指さないので、火が揺れる文には合わない。"}, {"text": "朝のライトが、カーテンの隙間から差し込んだ。", "explanation": "〈日差し〉と混同した使い方。太陽の光を〈ライト〉とは言わないので、この文には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea5ab694-501e-4bcd-88e8-65cd964b3418') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39380, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "雨の夜、バイクのライトに道を照らしていた。", "corrected_sentence": "雨の夜、バイクのライトが道を照らしていた。", "error_description": "「照らす」の主語を示すのは「が」。「ライトに」は誤りで、正しくは「ライトが」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea5ab694-501e-4bcd-88e8-65cd964b3418') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39380, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "自転車のライトを点かないので、夜道は危ない。", "corrected_sentence": "自転車のライトが点かないので、夜道は危ない。", "error_description": "「点く」は自動詞なので、主語を「が」で示す。「ライトを」は誤りで、正しくは「ライトが」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea5ab694-501e-4bcd-88e8-65cd964b3418') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39381, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「付ける」の対象を示す「を」。これが正解。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を示すので、「付けた」の対象にはならない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列や引用を表すので、ここでは対象を作らない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表すが、「付けた」の対象にはならない。"}], "correct_answer": "を", "explanations": {"を": "「付ける」の対象を示す「を」。これが正解。", "が": "「が」は主語を示すので、「付けた」の対象にはならない。", "と": "「と」は並列や引用を表すので、ここでは対象を作らない。", "へ": "「へ」は方向を表すが、「付けた」の対象にはならない。"}, "error_tags": {"を": "目的語", "が": "主語", "と": "並列・引用", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea5ab694-501e-4bcd-88e8-65cd964b3418') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
