INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39381, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "照明のために室内や店内などに置く電灯や照明器具。", "primary_collocate": null, "pronunciation": "らいと", "ipa": "ɾaito", "syllable_count": 3, "sentences": [{"text": "机の上のライトで、本を読んだ。", "target_word": "ライト", "complexity_tier": "T3", "furigana": "机[つくえ]の上[うえ]のライトで、本[ほん]を読[よ]んだ。", "sentence_source": "generated"}, {"text": "玄関に、人が来ると光るライトを付けた。", "target_word": "ライト", "complexity_tier": "T3", "furigana": "玄関[げんかん]に、人[ひと]が来[く]ると光[ひか]るライトを付[つ]けた。", "sentence_source": "generated"}, {"text": "店は、おしゃれなライトで飾られている。", "target_word": "ライト", "complexity_tier": "T3", "furigana": "店[みせ]は、おしゃれなライトで飾[かざ]られている。", "sentence_source": "generated"}, {"text": "写真を撮るとき、ライトの位置を変えた。", "target_word": "ライト", "complexity_tier": "T3", "furigana": "写真[しゃしん]を撮[と]るとき、ライトの位置[いち]を変[か]えた。", "sentence_source": "generated"}, {"text": "電池で点くライトを、災害用に買った。", "target_word": "ライト", "complexity_tier": "T3", "furigana": "電池[でんち]で点[つ]くライトを、災害用[さいがいよう]に買[か]った。", "sentence_source": "generated"}, {"text": "台所のライトを新しいものに替えた。", "target_word": "ライト", "complexity_tier": "T3", "furigana": "台所[だいどころ]のライトを新[あたら]しいものに替[か]えた。", "sentence_source": "generated"}, {"text": "弟は暗い部屋で、小さなライトを使って絵を描いた。", "target_word": "ライト", "complexity_tier": "T3", "furigana": "弟[おとうと]は暗[くら]い部屋[へや]で、小[ちい]さなライトを使[つか]って絵[え]を描[か]いた。", "sentence_source": "generated"}, {"text": "部屋のライトが切れたので、買いに行く。", "target_word": "ライト", "complexity_tier": "T3", "furigana": "部屋[へや]のライトが切[き]れたので、買[か]いに行[い]く。", "sentence_source": "generated"}, {"text": "夜のサッカー場では、大きなライトが使われる。", "target_word": "ライト", "complexity_tier": "T3", "furigana": "夜[よる]のサッカー場[じょう]では、大[おお]きなライトが使[つか]われる。", "sentence_source": "generated"}, {"text": "犬の散歩用に、首につけるライトを買った。", "target_word": "ライト", "complexity_tier": "T3", "furigana": "犬[いぬ]の散歩用[さんぽよう]に、首[くび]につけるライトを買[か]った。", "sentence_source": "generated"}], "morphological_forms": [{"form": "ライト", "label": "基本形"}, {"form": "ライトの", "label": "の格"}], "register": "neutral", "sense_fingerprint": "照明用の電灯や照明器具", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 4 above tier T2: contains vocabulary far above tier T2: 点く (Zipf 2.43)']::text[], '6ba24b57-71af-43be-bb65-9109da6c8bd6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39381, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "ライト", "is_correct": true, "explanation": "机の上に置く照明器具として、本を読む明かりに合う。"}, {"text": "マグカップ", "is_correct": false, "explanation": "マグカップで本を読むことはないので、文の意味が通らない。"}, {"text": "ティッシュ", "is_correct": false, "explanation": "ティッシュは読書の道具ではないので、この文には合わない。"}, {"text": "鉛筆", "is_correct": false, "explanation": "鉛筆で本を読むことはないので、文脈に合わない。"}], "explanations": {"ライト": "机の上に置く照明器具として、本を読む明かりに合う。", "マグカップ": "マグカップで本を読むことはないので、文の意味が通らない。", "ティッシュ": "ティッシュは読書の道具ではないので、この文には合わない。", "鉛筆": "鉛筆で本を読むことはないので、文脈に合わない。"}, "sentence_index": 0, "correct_answer": "ライト"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "夜空では、星のライトが瞬いていた。", "explanation": "〈星〉（夜空の光）と混同した使い方。星の光を〈ライト〉とは言わないので、この文には合わない。"}, {"text": "夜の作業場で、ライトの油を足して、火を強くした。", "explanation": "〈ランプ〉（油で燃やす灯り）と混同した使い方。ライトは油を足して燃やすものではないので、この文には合わない。"}, {"text": "ライトの炎が、風でゆらゆらと揺れた。", "explanation": "〈ろうそく〉（炎を出す灯り）と混同した使い方。〈ライト〉は炎を指さないので、この文には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea5ab694-501e-4bcd-88e8-65cd964b3418') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39381, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "ライト", "is_correct": true, "explanation": "小さな照明として、絵を描くときに光を当てる道具に合う。"}, {"text": "ドライヤー", "is_correct": false, "explanation": "ドライヤーは髪を乾かす道具で、絵を描く道具としては合わない。"}, {"text": "掃除機", "is_correct": false, "explanation": "掃除機は掃除の道具で、絵を描くのには使わない。"}, {"text": "洗濯機", "is_correct": false, "explanation": "洗濯機は洗濯の道具で、絵を描く文脈には合わない。"}], "explanations": {"ライト": "小さな照明として、絵を描くときに光を当てる道具に合う。", "ドライヤー": "ドライヤーは髪を乾かす道具で、絵を描く道具としては合わない。", "掃除機": "掃除機は掃除の道具で、絵を描くのには使わない。", "洗濯機": "洗濯機は洗濯の道具で、絵を描く文脈には合わない。"}, "sentence_index": 6, "correct_answer": "ライト"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "嵐の夜、ライトが空を走って、窓がびりびり震えた。", "explanation": "〈稲妻〉と混同した使い方。空を走る稲妻は〈ライト〉とは言わないので、この文には合わない。"}, {"text": "ライトが空にかかり、七色に輝いていた。", "explanation": "〈虹〉と混同した使い方。照明器具の〈ライト〉は空にかかるものではない。"}, {"text": "ライトが、川の水面を赤く染めていた。", "explanation": "〈夕焼け〉と混同した使い方。自然の赤い光を〈ライト〉とは言わないので、この文には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea5ab694-501e-4bcd-88e8-65cd964b3418') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39381, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "玄関のライトに点いていたので、帰りやすかった。", "corrected_sentence": "玄関のライトが点いていたので、帰りやすかった。", "error_description": "「点く」は自動詞なので、主語を「が」で示す。「ライトに」は誤りで、正しくは「ライトが」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea5ab694-501e-4bcd-88e8-65cd964b3418') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39381, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "ベッドのライトを消えてから、眠った。", "corrected_sentence": "ベッドのライトが消えてから、眠った。", "error_description": "「消える」は自動詞なので、主語を「が」で示す。「ライトを」は誤りで、正しくは「ライトが」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea5ab694-501e-4bcd-88e8-65cd964b3418') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39384, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "悲しむ", "is_correct": true, "explanation": "〈うれしく思う〉の対義語。出来事や知らせを悲しく思うという意味で、感情が反対になる。"}, {"text": "楽しむ", "is_correct": false, "explanation": "〈うれしく思う〉と近い意味の類義語で、対義語ではない。"}, {"text": "笑う", "is_correct": false, "explanation": "表情や声で表す動作で、うれしさの反対の感情を表す語ではない。"}, {"text": "眠る", "is_correct": false, "explanation": "体が休む動作を表し、感情の対義語にはならない。"}], "correct_answer": "悲しむ", "explanations": {"悲しむ": "〈うれしく思う〉の対義語。出来事や知らせを悲しく思うという意味で、感情が反対になる。", "楽しむ": "〈うれしく思う〉と近い意味の類義語で、対義語ではない。", "笑う": "表情や声で表す動作で、うれしさの反対の感情を表す語ではない。", "眠る": "体が休む動作を表し、感情の対義語にはならない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'afc7ec28-a387-4bb1-bfd6-5477845bd053') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39384, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "悲しむ", "is_correct": true, "explanation": "〈うれしく思う〉の対義語。顔を見てうれしくなる意味の反対で、悲しく思うことを表す。"}, {"text": "走る", "is_correct": false, "explanation": "体を速く動かす動作で、感情の対義語ではない。"}, {"text": "考える", "is_correct": false, "explanation": "頭で思いをめぐらす動作で、うれしさの反対の感情を表さない。"}, {"text": "磨く", "is_correct": false, "explanation": "物をこすって光らせる動作で、感情の対義語にはならない。"}], "correct_answer": "悲しむ", "explanations": {"悲しむ": "〈うれしく思う〉の対義語。顔を見てうれしくなる意味の反対で、悲しく思うことを表す。", "走る": "体を速く動かす動作で、感情の対義語ではない。", "考える": "頭で思いをめぐらす動作で、うれしさの反対の感情を表さない。", "磨く": "物をこすって光らせる動作で、感情の対義語にはならない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'afc7ec28-a387-4bb1-bfd6-5477845bd053') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39384, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "うれしく思うこと。", "primary_collocate": null, "pronunciation": "よろこぶ", "ipa": "joɾokobɯ", "syllable_count": 4, "sentences": [{"text": "母は私の合格の知らせを聞いて、とても喜んだ。", "target_word": "喜んだ", "complexity_tier": "T3", "furigana": "母(はは)は私(わたし)の合格(ごうかく)の知(し)らせを聞(き)いて、とても喜(よろこ)んだ。", "sentence_source": "generated"}, {"text": "子どもたちはプレゼントをもらって喜んでいる。", "target_word": "喜んでいる", "complexity_tier": "T3", "furigana": "子(こ)どもたちはプレゼントをもらって喜(よろこ)んでいる。", "sentence_source": "generated"}, {"text": "友達は、私が来たことを喜んでくれた。", "target_word": "喜んで", "complexity_tier": "T3", "furigana": "友達(ともだち)は、私(わたし)が来(き)たことを喜(よろこ)んでくれた。", "sentence_source": "generated"}, {"text": "犬は飼い主が帰ってくると、しっぽを振って喜ぶ。", "target_word": "喜ぶ", "complexity_tier": "T3", "furigana": "犬(いぬ)は飼(か)い主(ぬし)が帰(かえ)ってくると、しっぽを振(ふ)って喜(よろこ)ぶ。", "sentence_source": "generated"}, {"text": "祖父は孫の成長を心から喜んでいる。", "target_word": "喜んでいる", "complexity_tier": "T3", "furigana": "祖父(そふ)は孫(まご)の成長(せいちょう)を心(こころ)から喜(よろこ)んでいる。", "sentence_source": "generated"}, {"text": "彼女は新しい仕事が決まって喜んだ。", "target_word": "喜んだ", "complexity_tier": "T3", "furigana": "彼女(かのじょ)は新(あたら)しい仕事(しごと)が決(き)まって喜(よろこ)んだ。", "sentence_source": "generated"}, {"text": "試合に勝って、選手たちは抱き合って喜んだ。", "target_word": "喜んだ", "complexity_tier": "T3", "furigana": "試合(しあい)に勝(か)って、選手(せんしゅ)たちは抱(だ)き合(あ)って喜(よろこ)んだ。", "sentence_source": "generated"}, {"text": "手紙を送ったら、先生はとても喜んでくれた。", "target_word": "喜んで", "complexity_tier": "T3", "furigana": "手紙(てがみ)を送(おく)ったら、先生(せんせい)はとても喜(よろこ)んでくれた。", "sentence_source": "generated"}, {"text": "弟は、お小遣いが増えたと喜んだ。", "target_word": "喜んだ", "complexity_tier": "T3", "furigana": "弟(おとうと)は、お小遣(こづか)いが増(ふ)えたと喜(よろこ)んだ。", "sentence_source": "generated"}, {"text": "みんなが喜ぶ顔を見ると、私もうれしくなる。", "target_word": "喜ぶ", "complexity_tier": "T3", "furigana": "みんなが喜(よろこ)ぶ顔(かお)を見(み)ると、私(わたし)もうれしくなる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "喜ぶ", "label": "dictionary form"}, {"form": "喜んだ", "label": "past"}, {"form": "喜んで", "label": "te-form"}, {"form": "喜ばない", "label": "negative"}, {"form": "喜びます", "label": "polite"}], "register": "neutral", "sense_fingerprint": "出来事や知らせをうれしく思う", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a6c39368-b1a1-4be5-ad73-c3324aee30fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39384, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "喜んだ", "is_correct": true, "explanation": "過去形の終止形。合格の知らせを聞いた場面で、母がうれしく思った反応を述べる。"}, {"text": "喜ばない", "is_correct": false, "explanation": "否定形なので、うれしく思った反応と反対になる。"}, {"text": "喜びます", "is_correct": false, "explanation": "丁寧体なので、地の文の普通体（「聞いて、〜た。」）と文体が合わない。"}, {"text": "喜ぼう", "is_correct": false, "explanation": "意志形で「〜しよう」の意味になり、過去の出来事に対する反応を述べる文には合わない。"}], "explanations": {"喜んだ": "過去形の終止形。合格の知らせを聞いた場面で、母がうれしく思った反応を述べる。", "喜ばない": "否定形なので、うれしく思った反応と反対になる。", "喜びます": "丁寧体なので、地の文の普通体（「聞いて、〜た。」）と文体が合わない。", "喜ぼう": "意志形で「〜しよう」の意味になり、過去の出来事に対する反応を述べる文には合わない。"}, "sentence_index": 0, "correct_answer": "喜んだ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "週末は友人とゆっくり喜んだ。", "explanation": "ここは〈楽しむ〉の意味。喜ぶは知らせや出来事に対するうれしさを表し、過ごし方の楽しさには使わない。"}, {"text": "しつこい勧誘の電話に、私は喜んだ。", "explanation": "ここは〈困る〉の意味。喜ぶは良いことへのうれしさで、迷惑に困る気持ちは表せない。"}, {"text": "突然の大きな雷の音に、彼は喜んだ。", "explanation": "ここは〈驚く〉の意味。喜ぶは良い出来事へのうれしさで、突然の物音に対する驚きには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'afc7ec28-a387-4bb1-bfd6-5477845bd053') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39384, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "喜んだ", "is_correct": true, "explanation": "過去形の終止形。試合に勝った場面で、選手たちが喜んだ出来事を述べる。"}, {"text": "喜ばれる", "is_correct": false, "explanation": "受け身の形で「人に喜ばれる」の意味になり、選手たちが自ら喜ぶ文には合わない。"}, {"text": "喜べ", "is_correct": false, "explanation": "命令形なので、過去の出来事を語る地の文には入らない。"}, {"text": "喜ばない", "is_correct": false, "explanation": "否定形なので、勝って喜んだという出来事と反対になる。"}], "explanations": {"喜んだ": "過去形の終止形。試合に勝った場面で、選手たちが喜んだ出来事を述べる。", "喜ばれる": "受け身の形で「人に喜ばれる」の意味になり、選手たちが自ら喜ぶ文には合わない。", "喜べ": "命令形なので、過去の出来事を語る地の文には入らない。", "喜ばない": "否定形なので、勝って喜んだという出来事と反対になる。"}, "sentence_index": 6, "correct_answer": "喜んだ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "迷惑をかけて、彼は深く喜んだ。", "explanation": "ここは〈謝る〉の意味。喜ぶは自分がうれしく思う気持ちで、わびの気持ちは表せない。"}, {"text": "負けた試合の後、選手たちは静かに喜んだ。", "explanation": "ここは〈悔しがる〉の意味。喜ぶは良い出来事へのうれしさで、負けて残念に思う気持ちには使わない。"}, {"text": "熱が下がらない子を見て、母は喜んでうなだれた。", "explanation": "ここは〈心配する〉の意味。喜ぶは良いことへのうれしさで、病気の子を案じる気持ちは表せない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'afc7ec28-a387-4bb1-bfd6-5477845bd053') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39384, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "帰国した息子に会えて、母は喜ぶました。", "corrected_sentence": "帰国した息子に会えて、母は喜びました。", "error_description": "動詞「喜ぶ」は連用形「喜び」に「ました」を続けて丁寧形にする。「喜ぶました」は誤りで、正しくは「喜びました」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "喜んでいる", "is_correct": true, "explanation": "ている形の現在形。もらったプレゼントを受けて、今まさにうれしく思っている状態を表す。"}, {"text": "喜んでいない", "is_correct": false, "explanation": "否定形なので、もらった喜びの状態と反対になる。"}, {"text": "喜べ", "is_correct": false, "explanation": "命令形なので、子どもたちの状態を述べる文の述語にはならない。"}, {"text": "喜ばない", "is_correct": false, "explanation": "否定形なので、うれしく思っているという肯定の内容と逆になる。"}], "correct_form": "喜んでいる", "base_form": "喜ぶ", "form_label": "〜ている形（現在の継続・状態）", "sentence_index": 1, "explanations": {"喜んでいる": "ている形の現在形。もらったプレゼントを受けて、今まさにうれしく思っている状態を表す。", "喜んでいない": "否定形なので、もらった喜びの状態と反対になる。", "喜べ": "命令形なので、子どもたちの状態を述べる文の述語にはならない。", "喜ばない": "否定形なので、うれしく思っているという肯定の内容と逆になる。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'afc7ec28-a387-4bb1-bfd6-5477845bd053') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39384, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "家族は届いた知らせが喜んだ。", "corrected_sentence": "家族は届いた知らせを喜んだ。", "error_description": "「喜ぶ」は、喜ぶ対象を「を」で示す。「知らせが」と「が」を使うと、知らせ自体が喜ぶという意味になり誤り。正しくは「知らせを喜んだ」。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "喜んで", "is_correct": true, "explanation": "て形。「〜てくれた」と続けて、先生が喜んでくれた行為を述べる。"}, {"text": "喜ぶ", "is_correct": false, "explanation": "辞書形は「〜てくれた」に直接つながらず、文の流れが切れてしまう。"}, {"text": "喜びません", "is_correct": false, "explanation": "否定の丁寧形で、先生が喜んでくれたという肯定の内容と合わない。"}, {"text": "喜べる", "is_correct": false, "explanation": "可能形で「喜ぶことができる」の意味になり、実際に喜んでくれた出来事を表さない。"}], "correct_form": "喜んで", "base_form": "喜ぶ", "form_label": "て形（〜くれた に続く）", "sentence_index": 7, "explanations": {"喜んで": "て形。「〜てくれた」と続けて、先生が喜んでくれた行為を述べる。", "喜ぶ": "辞書形は「〜てくれた」に直接つながらず、文の流れが切れてしまう。", "喜びません": "否定の丁寧形で、先生が喜んでくれたという肯定の内容と合わない。", "喜べる": "可能形で「喜ぶことができる」の意味になり、実際に喜んでくれた出来事を表さない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'afc7ec28-a387-4bb1-bfd6-5477845bd053') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39385, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "目的語を示す格助詞。「この味を喜ぶ」で、味を気に入って喜ぶ対象を示す。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表す助詞で、喜ぶ対象を示すことはできない。"}, {"text": "と", "is_correct": false, "explanation": "共同・引用を表す助詞で、「この味と喜ぶ」では対象を示せない。"}, {"text": "の", "is_correct": false, "explanation": "連体修飾の助詞で、動詞の対象を示せず、「この味の喜ぶだろう」は不自然。"}], "correct_answer": "を", "explanations": {"を": "目的語を示す格助詞。「この味を喜ぶ」で、味を気に入って喜ぶ対象を示す。", "へ": "方向を表す助詞で、喜ぶ対象を示すことはできない。", "と": "共同・引用を表す助詞で、「この味と喜ぶ」では対象を示せない。", "の": "連体修飾の助詞で、動詞の対象を示せず、「この味の喜ぶだろう」は不自然。"}, "error_tags": {"へ": "方向（対象を示さない）", "と": "共同・引用（対象を示さない）", "の": "連体修飾（対象を示さない）"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'afc7ec28-a387-4bb1-bfd6-5477845bd053') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39385, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "目的語を示す格助詞。「温泉の旅を喜んでくれた」で、母が喜んだ対象を示す。"}, {"text": "が", "is_correct": false, "explanation": "主語を示す助詞で、「温泉の旅が喜んでくれた」では旅が主語になり、母が喜ぶ文と合わない。"}, {"text": "と", "is_correct": false, "explanation": "共同や引用を表す助詞で、「温泉の旅と喜んでくれた」では喜ぶ対象を示せない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表す助詞で、喜ぶ対象を示すことはできない。"}], "correct_answer": "を", "explanations": {"を": "目的語を示す格助詞。「温泉の旅を喜んでくれた」で、母が喜んだ対象を示す。", "が": "主語を示す助詞で、「温泉の旅が喜んでくれた」では旅が主語になり、母が喜ぶ文と合わない。", "と": "共同や引用を表す助詞で、「温泉の旅と喜んでくれた」では喜ぶ対象を示せない。", "へ": "方向を表す助詞で、喜ぶ対象を示すことはできない。"}, "error_tags": {"が": "主語（対象を示さない）", "と": "共同・引用（対象を示さない）", "へ": "方向（対象を示さない）"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'afc7ec28-a387-4bb1-bfd6-5477845bd053') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39385, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "何かが自分の気持ちに合っていて、明るく元気な気持ちになること。", "primary_collocate": null, "pronunciation": "よろこぶ", "ipa": "joɾokobɯ", "syllable_count": 4, "sentences": [{"text": "子どもはこの甘いお菓子を喜んで食べる。", "target_word": "喜んで", "complexity_tier": "T3", "furigana": "子(こ)どもはこの甘(あま)いお菓子(かし)を喜(よろこ)んで食(た)べる。", "sentence_source": "generated"}, {"text": "辛い物が好きな父は、この味を喜ぶだろう。", "target_word": "喜ぶ", "complexity_tier": "T3", "furigana": "辛(から)い物(もの)が好(す)きな父(ちち)は、この味(あじ)を喜(よろこ)ぶだろう。", "sentence_source": "generated"}, {"text": "明るい色の部屋を、祖母は喜んでいた。", "target_word": "喜んでいた", "complexity_tier": "T3", "furigana": "明(あか)るい色(いろ)の部屋(へや)を、祖母(そぼ)は喜(よろこ)んでいた。", "sentence_source": "generated"}, {"text": "猫は日当たりのいい場所を喜ぶ。", "target_word": "喜ぶ", "complexity_tier": "T3", "furigana": "猫(ねこ)は日当(ひあ)たりのいい場所(ばしょ)を喜(よろこ)ぶ。", "sentence_source": "generated"}, {"text": "赤ちゃんは、この歌を喜んで聞いている。", "target_word": "喜んで", "complexity_tier": "T3", "furigana": "赤(あか)ちゃんは、この歌(うた)を喜(よろこ)んで聞(き)いている。", "sentence_source": "generated"}, {"text": "花は水と太陽を喜ぶように、元気に葉を広げた。", "target_word": "喜ぶ", "complexity_tier": "T3", "furigana": "花(はな)は水(みず)と太陽(たいよう)を喜(よろこ)ぶように、元気(げんき)に葉(は)を広(ひろ)げた。", "sentence_source": "generated"}, {"text": "若者が喜ぶデザインの服を、この店では作っている。", "target_word": "喜ぶ", "complexity_tier": "T3", "furigana": "若者(わかもの)が喜(よろこ)ぶデザインの服(ふく)を、この店(みせ)では作(つく)っている。", "sentence_source": "generated"}, {"text": "旅行が好きな母は、温泉の旅を喜んでくれた。", "target_word": "喜んで", "complexity_tier": "T3", "furigana": "旅行(りょこう)が好(す)きな母(はは)は、温泉(おんせん)の旅(たび)を喜(よろこ)んでくれた。", "sentence_source": "generated"}, {"text": "犬は雨上がりの散歩を喜んで走り回った。", "target_word": "喜んで", "complexity_tier": "T3", "furigana": "犬(いぬ)は雨上(あめあ)がりの散歩(さんぽ)を喜(よろこ)んで走(はし)り回(まわ)った。", "sentence_source": "generated"}, {"text": "生徒たちは、新しい遊び道具を喜んで使っている。", "target_word": "喜んで", "complexity_tier": "T3", "furigana": "生徒(せいと)たちは、新(あたら)しい遊(あそ)び道具(どうぐ)を喜(よろこ)んで使(つか)っている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "喜ぶ", "label": "dictionary form"}, {"form": "喜んだ", "label": "past"}, {"form": "喜んで", "label": "te-form"}, {"form": "喜ばない", "label": "negative"}, {"form": "喜びます", "label": "polite"}], "register": "neutral", "sense_fingerprint": "好みに合うものを気に入って元気になる", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a6c39368-b1a1-4be5-ad73-c3324aee30fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39385, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "喜んで", "is_correct": true, "explanation": "て形で「〜て食べる」と続き、喜んで食べるという様子を表す。"}, {"text": "喜んだ", "is_correct": false, "explanation": "過去形なので、後ろの「食べる」に続けると文が成り立たない。"}, {"text": "喜ぶ", "is_correct": false, "explanation": "辞書形は「食べる」の前に直接置けず、修飾の形としても不自然。"}, {"text": "喜ばない", "is_correct": false, "explanation": "否定形なので「喜ばない食べる」となり、後ろの「食べる」と続けられない。"}], "explanations": {"喜んで": "て形で「〜て食べる」と続き、喜んで食べるという様子を表す。", "喜んだ": "過去形なので、後ろの「食べる」に続けると文が成り立たない。", "喜ぶ": "辞書形は「食べる」の前に直接置けず、修飾の形としても不自然。", "喜ばない": "否定形なので「喜ばない食べる」となり、後ろの「食べる」と続けられない。"}, "sentence_index": 0, "correct_answer": "喜んで"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "苦手な食べ物が出されて、子どもは喜んだ。", "explanation": "ここは〈嫌がる〉の意味。喜ぶは気に入って元気になることで、嫌いなものを前にした反応には使わない。"}, {"text": "長い講義が続いて、学生たちは喜んでいる。", "explanation": "ここは〈退屈する〉の意味。喜ぶは気に入って元気になる意味で、時間が長く感じられる退屈は表せない。"}, {"text": "勝手に物を動かされ、祖母は喜んだ。", "explanation": "ここは〈怒る〉の意味。喜ぶは気に入って明るくなる意味で、勝手に物を動かされた怒りには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'afc7ec28-a387-4bb1-bfd6-5477845bd053') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39385, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "喜ぶ", "is_correct": true, "explanation": "連体形で「デザイン」を修飾し、若者が気に入って喜ぶデザインという意味になる。"}, {"text": "喜び", "is_correct": false, "explanation": "連用形や名詞の形で、「喜びデザイン」と続けてデザインを修飾することはできない。"}, {"text": "喜べ", "is_correct": false, "explanation": "命令形なので、後ろの「デザイン」を修飾できない。"}, {"text": "喜ぼう", "is_correct": false, "explanation": "意志形なので、後ろの「デザイン」を修飾できず、文が成り立たない。"}], "explanations": {"喜ぶ": "連体形で「デザイン」を修飾し、若者が気に入って喜ぶデザインという意味になる。", "喜び": "連用形や名詞の形で、「喜びデザイン」と続けてデザインを修飾することはできない。", "喜べ": "命令形なので、後ろの「デザイン」を修飾できない。", "喜ぼう": "意志形なので、後ろの「デザイン」を修飾できず、文が成り立たない。"}, "sentence_index": 6, "correct_answer": "喜ぶ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "真冬の寒さに、旅人は喜んで凍えた。", "explanation": "ここは〈寒がる〉の意味。喜ぶは気持ちに合って明るくなることで、寒さで体が冷えることは表せない。"}, {"text": "大切な品を失って、彼女は喜んでいる。", "explanation": "ここは〈悲しむ〉の意味。喜ぶは気に入って明るくなることで、大切なものを失った悲しみには使わない。"}, {"text": "暗い夜道で物音がして、彼女は喜んで震えた。", "explanation": "ここは〈怖がる〉の意味。喜ぶは気に入って元気になることで、暗がりへの恐怖は表せない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'afc7ec28-a387-4bb1-bfd6-5477845bd053') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39385, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "子どもは、新しいおもちゃを喜ぶで遊んだ。", "corrected_sentence": "子どもは、新しいおもちゃを喜んで遊んだ。", "error_description": "「喜ぶ」の連用形は「喜んで」。「喜ぶで」は誤りで、正しくは「喜んで遊んだ」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "喜ぶ", "is_correct": true, "explanation": "辞書形。「〜だろう」に続く推量の文で、父が味を気に入って喜ぶだろうという予測を述べる。"}, {"text": "喜んで", "is_correct": false, "explanation": "て形なので、「〜だろう」の前に置くと文が成り立たない。"}, {"text": "喜べ", "is_correct": false, "explanation": "命令形なので、推量の「〜だろう」と続けられず文が成り立たない。"}, {"text": "喜びます", "is_correct": false, "explanation": "丁寧形なので、普通体の推量「〜だろう」と続かない。"}], "correct_form": "喜ぶ", "base_form": "喜ぶ", "form_label": "辞書形（〜だろう の前）", "sentence_index": 1, "explanations": {"喜ぶ": "辞書形。「〜だろう」に続く推量の文で、父が味を気に入って喜ぶだろうという予測を述べる。", "喜んで": "て形なので、「〜だろう」の前に置くと文が成り立たない。", "喜べ": "命令形なので、推量の「〜だろう」と続けられず文が成り立たない。", "喜びます": "丁寧形なので、普通体の推量「〜だろう」と続かない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'afc7ec28-a387-4bb1-bfd6-5477845bd053') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39385, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "子どもは新しいゲームへ喜んだ。", "corrected_sentence": "子どもは新しいゲームを喜んだ。", "error_description": "「喜ぶ」が対象を示すときの助詞は「を」。「へ」は方向を表すので誤り。正しくは「新しいゲームを喜んだ」。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "喜んで", "is_correct": true, "explanation": "て形。「〜くれた」と続けて、母が温泉の旅を喜んでくれたという行為を述べる。"}, {"text": "喜べる", "is_correct": false, "explanation": "可能形で「喜ぶことができる」の意味になり、実際に喜んでくれた出来事を表さない。"}, {"text": "喜ばれる", "is_correct": false, "explanation": "受け身形で「人に喜ばれる」の意味になり、母が自分から喜んだ文と合わない。"}, {"text": "喜ぼう", "is_correct": false, "explanation": "意志形なので、過去に母が喜んでくれた出来事を述べる文には合わない。"}], "correct_form": "喜んで", "base_form": "喜ぶ", "form_label": "て形（〜くれた に続く）", "sentence_index": 7, "explanations": {"喜んで": "て形。「〜くれた」と続けて、母が温泉の旅を喜んでくれたという行為を述べる。", "喜べる": "可能形で「喜ぶことができる」の意味になり、実際に喜んでくれた出来事を表さない。", "喜ばれる": "受け身形で「人に喜ばれる」の意味になり、母が自分から喜んだ文と合わない。", "喜ぼう": "意志形なので、過去に母が喜んでくれた出来事を述べる文には合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'afc7ec28-a387-4bb1-bfd6-5477845bd053') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
