INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39386, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "空気が動くこと。", "primary_collocate": null, "pronunciation": "かぜ", "ipa": "kaze", "syllable_count": 2, "sentences": [{"text": "今日は風が強くて、かさをさしても歩きにくい。", "target_word": "風", "complexity_tier": "T3", "furigana": "今日[きょう]は風[かぜ]が強[つよ]くて、かさをさしても歩[ある]きにくい。", "sentence_source": "generated"}, {"text": "窓を開けると、すずしい風が入ってきた。", "target_word": "風", "complexity_tier": "T3", "furigana": "窓[まど]を開[あ]けると、すずしい風[かぜ]が入[はい]ってきた。", "sentence_source": "generated"}, {"text": "風がやんだので、ぼうしをかぶって外に出た。", "target_word": "風", "complexity_tier": "T3", "furigana": "風[かぜ]がやんだので、ぼうしをかぶって外[そと]に出[で]た。", "sentence_source": "generated"}, {"text": "風で木の葉がゆれている。", "target_word": "風", "complexity_tier": "T3", "furigana": "風[かぜ]で木[き]の葉[は]がゆれている。", "sentence_source": "generated"}, {"text": "海から風が吹いて、少し寒くなった。", "target_word": "風", "complexity_tier": "T3", "furigana": "海[うみ]から風[かぜ]が吹[ふ]いて、少[すこ]し寒[さむ]くなった。", "sentence_source": "generated"}, {"text": "風のない日は、たこが上がらない。", "target_word": "風", "complexity_tier": "T3", "furigana": "風[かぜ]のない日[ひ]は、たこが上[あ]がらない。", "sentence_source": "generated"}, {"text": "夏は扇風機の風に当たりながら本を読む。", "target_word": "風", "complexity_tier": "T3", "furigana": "夏[なつ]は扇風機[せんぷうき]の風[かぜ]に当[あ]たりながら本[ほん]を読[よ]む。", "sentence_source": "generated"}, {"text": "風が冷たいので、マフラーをした。", "target_word": "風", "complexity_tier": "T3", "furigana": "風[かぜ]が冷[つめ]たいので、マフラーをした。", "sentence_source": "generated"}, {"text": "朝から風が吹いて、洗濯物がよく乾いた。", "target_word": "風", "complexity_tier": "T3", "furigana": "朝[あさ]から風[かぜ]が吹[ふ]いて、洗濯物[せんたくもの]がよく乾[かわ]いた。", "sentence_source": "generated"}, {"text": "台風が近づくと、風の音が大きくなる。", "target_word": "風", "complexity_tier": "T3", "furigana": "台風[たいふう]が近[ちか]づくと、風[かぜ]の音[おと]が大[おお]きくなる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "風", "label": "基本形"}, {"form": "風の", "label": "連体形(の)"}], "register": "中立", "sense_fingerprint": "肌で感じる、空気の動き", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 1 above tier T1: contains vocabulary far above tier T1: すずしい (Zipf 2.04)']::text[], '80d5caf6-f21d-47d6-aabb-a8ee0a91932d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39386, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "風", "is_correct": true, "explanation": "「風が強くて」と続き、強く吹く空気の動きとして文に合う。"}, {"text": "気温", "is_correct": false, "explanation": "気温は高い低いで表すもので、「気温が強い」とは言わない。"}, {"text": "湿度", "is_correct": false, "explanation": "湿度は高い低いで表すもので、「湿度が強い」とは言わない。"}, {"text": "霜", "is_correct": false, "explanation": "霜は降りるもので、「霜が強い」と表すのは不自然。"}], "explanations": {"風": "「風が強くて」と続き、強く吹く空気の動きとして文に合う。", "気温": "気温は高い低いで表すもので、「気温が強い」とは言わない。", "湿度": "湿度は高い低いで表すもので、「湿度が強い」とは言わない。", "霜": "霜は降りるもので、「霜が強い」と表すのは不自然。"}, "sentence_index": 0, "correct_answer": "風"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "部屋の風が重くて、息苦しかった。", "explanation": "ここは〈空気〉の意味。風は動いている空気なので、よどんで重い空気の意味には合わない。"}, {"text": "子どもが赤い風を飛ばして遊んでいる。", "explanation": "ここは〈風船〉の意味。風は目に見えない空気の流れで、飛ばして遊ぶものではない。"}, {"text": "寒くて、白い風が口から出た。", "explanation": "ここは〈息〉の意味。風は外の空気の流れで、口から出る白い息の意味では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3cf92071-1d16-456b-80e1-4ce44bb16a1a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39386, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "風", "is_correct": true, "explanation": "扇風機が送るものとして、「風に当たる」の形に合う。"}, {"text": "雷", "is_correct": false, "explanation": "雷は空で起こるもので、扇風機から送られるものではない。"}, {"text": "雪", "is_correct": false, "explanation": "扇風機から出てくるのは風で、雪が出ることはない。"}, {"text": "雹", "is_correct": false, "explanation": "扇風機が送るのは風で、雹を送ることはできない。"}], "explanations": {"風": "扇風機が送るものとして、「風に当たる」の形に合う。", "雷": "雷は空で起こるもので、扇風機から送られるものではない。", "雪": "扇風機から出てくるのは風で、雪が出ることはない。", "雹": "扇風機が送るのは風で、雹を送ることはできない。"}, "sentence_index": 6, "correct_answer": "風"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "風が降ると、地面がぬれる。", "explanation": "ここは〈雨〉の意味。風は降るものではないので、降って地面をぬらす意味には使わない。"}, {"text": "寝る前に、風に入ってさっぱりした。", "explanation": "ここは〈風呂〉の意味。風は中に入るものではないので、入浴の意味には使わない。"}, {"text": "たき火の風が立ち上って、空へ消えた。", "explanation": "ここは〈煙〉の意味。風は目に見えて立ち上るものではないので、煙の動きには合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3cf92071-1d16-456b-80e1-4ce44bb16a1a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39386, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "今日は風を強くて、かさをさしても歩きづらい。", "corrected_sentence": "今日は風が強くて、かさをさしても歩きづらい。", "error_description": "「風」は「強い」の主語なので「が」が正しい。「を」は目的語を示す助詞で、「風を強い」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3cf92071-1d16-456b-80e1-4ce44bb16a1a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39386, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "夏は扇風機の風を当たりながら、本を読んだ。", "corrected_sentence": "夏は扇風機の風にあたりながら、本を読んだ。", "error_description": "「当たる」は「に」を取るので「風に当たる」が正しい。「を」は目的語を示し、「風を当たる」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3cf92071-1d16-456b-80e1-4ce44bb16a1a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39387, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "「風は」で主題を示し、流れる主体を表す。"}, {"text": "を", "is_correct": false, "explanation": "「流れる」は自動詞なので、目的語の「を」は取らない。"}, {"text": "に", "is_correct": false, "explanation": "「に」は到着点や相手を示す。主語の位置に置くと文が成り立たない。"}, {"text": "より", "is_correct": false, "explanation": "比較を表す「より」は、主語と動詞の関係をつくれないので合わない。"}], "correct_answer": "は", "explanations": {"は": "「風は」で主題を示し、流れる主体を表す。", "を": "「流れる」は自動詞なので、目的語の「を」は取らない。", "に": "「に」は到着点や相手を示す。主語の位置に置くと文が成り立たない。", "より": "比較を表す「より」は、主語と動詞の関係をつくれないので合わない。"}, "error_tags": {"を": "目的語（他動詞用）", "に": "到着点・相手", "より": "比較"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3cf92071-1d16-456b-80e1-4ce44bb16a1a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39387, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「風の強さ」と名詞どうしを結ぶ連体修飾の「の」。"}, {"text": "が", "is_correct": false, "explanation": "「風が強さ」では主語と述語が結びつかず、文が成り立たない。"}, {"text": "を", "is_correct": false, "explanation": "「風を強さ」では目的語にならず、名詞の関係も作れない。"}, {"text": "に", "is_correct": false, "explanation": "「風に強さ」では場所や相手の関係になり、名詞を結ぶ形として不自然。"}], "correct_answer": "の", "explanations": {"の": "「風の強さ」と名詞どうしを結ぶ連体修飾の「の」。", "が": "「風が強さ」では主語と述語が結びつかず、文が成り立たない。", "を": "「風を強さ」では目的語にならず、名詞の関係も作れない。", "に": "「風に強さ」では場所や相手の関係になり、名詞を結ぶ形として不自然。"}, "error_tags": {"が": "主語", "を": "目的語", "に": "方向・相手"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3cf92071-1d16-456b-80e1-4ce44bb16a1a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39387, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "大気が移動してできる空気の流れ。", "primary_collocate": null, "pronunciation": "かぜ", "ipa": "kaze", "syllable_count": 2, "sentences": [{"text": "天気予報によると、明日は北から風が吹くそうだ。", "target_word": "風", "complexity_tier": "T3", "furigana": "天気予報[てんきよほう]によると、明日[あした]は北[きた]から風[かぜ]が吹[ふ]くそうだ。", "sentence_source": "generated"}, {"text": "風は気圧の高い所から低い所へ流れる。", "target_word": "風", "complexity_tier": "T3", "furigana": "風[かぜ]は気圧[きあつ]の高[たか]い所[ところ]から低[ひく]い所[ところ]へ流[なが]れる。", "sentence_source": "generated"}, {"text": "風の向きが変わって、雲が東へ動き出した。", "target_word": "風", "complexity_tier": "T3", "furigana": "風[かぜ]の向[む]きが変[か]わって、雲[くも]が東[ひがし]へ動[うご]き出[だ]した。", "sentence_source": "generated"}, {"text": "風力発電は、風の力で電気をつくる。", "target_word": "風", "complexity_tier": "T3", "furigana": "風力発電[ふうりょくはつでん]は、風[かぜ]の力[ちから]で電気[でんき]をつくる。", "sentence_source": "generated"}, {"text": "この島は一年中、強い風が吹いている。", "target_word": "風", "complexity_tier": "T3", "furigana": "この島[しま]は一年中[いちねんじゅう]、強[つよ]い風[かぜ]が吹[ふ]いている。", "sentence_source": "generated"}, {"text": "風が強まる前に、船は港にもどった。", "target_word": "風", "complexity_tier": "T3", "furigana": "風[かぜ]が強[つよ]まる前[まえ]に、船[ふね]は港[みなと]にもどった。", "sentence_source": "generated"}, {"text": "山に当たった風は、上にのぼって雲になる。", "target_word": "風", "complexity_tier": "T3", "furigana": "山[やま]に当[あ]たった風[かぜ]は、上[うえ]にのぼって雲[くも]になる。", "sentence_source": "generated"}, {"text": "風の強さは数字で表される。", "target_word": "風", "complexity_tier": "T3", "furigana": "風[かぜ]の強[つよ]さは数字[すうじ]で表[あらわ]される。", "sentence_source": "generated"}, {"text": "夕方になると、海からの風が陸に向かって吹く。", "target_word": "風", "complexity_tier": "T3", "furigana": "夕方[ゆうがた]になると、海[うみ]からの風[かぜ]が陸[りく]に向[む]かって吹[ふ]く。", "sentence_source": "generated"}, {"text": "風が止まると、湖の水面は鏡のように静かになった。", "target_word": "風", "complexity_tier": "T3", "furigana": "風[かぜ]が止[と]まると、湖[みずうみ]の水面[すいめん]は鏡[かがみ]のように静[しず]かになった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "風", "label": "基本形"}], "register": "中立", "sense_fingerprint": "気圧の差などで大気が動いてできる空気の流れ", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80d5caf6-f21d-47d6-aabb-a8ee0a91932d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39387, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "光", "is_correct": false, "explanation": "光は吹くものではないので、「北から光が吹く」は成り立たない。"}, {"text": "風", "is_correct": true, "explanation": "大気の流れが「吹く」の主語になる。北から来る空気の流れとして文脈に合う。"}, {"text": "波", "is_correct": false, "explanation": "波は水面に立つもので、北から「吹く」ものではないので合わない。"}, {"text": "雲", "is_correct": false, "explanation": "雲は空に浮かぶもので、「吹く」の主語にはならないので合わない。"}], "explanations": {"光": "光は吹くものではないので、「北から光が吹く」は成り立たない。", "風": "大気の流れが「吹く」の主語になる。北から来る空気の流れとして文脈に合う。", "波": "波は水面に立つもので、北から「吹く」ものではないので合わない。", "雲": "雲は空に浮かぶもので、「吹く」の主語にはならないので合わない。"}, "sentence_index": 0, "correct_answer": "風"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "時代の風潮に逆らって、新しい考えを広めた。", "explanation": "ここは〈風潮〉の意味（時代の傾向）。大気の流れを指す定義では、社会の傾向は表せないので合わない。"}, {"text": "彼は風采が上がらず、いつも地味な服を着ている。", "explanation": "ここは〈風采〉（身なりや外見）の意味。大気の流れを指す定義では、人の見た目は表せないので合わない。"}, {"text": "彼は少し風変わりな人で、みんなを驚かせる。", "explanation": "ここは〈風変わり〉（普通と違うこと）の意味。大気の流れを指す定義では、人の性格は表せないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3cf92071-1d16-456b-80e1-4ce44bb16a1a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39387, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "風", "is_correct": true, "explanation": "山に当たって上へのぼる空気の流れを指し、雲になる文脈に合う。"}, {"text": "音", "is_correct": false, "explanation": "音は山に当たって上へのぼり雲になるものではないので合わない。"}, {"text": "声", "is_correct": false, "explanation": "声は空気の振動で、山に当たっても上へのぼって雲になることはないので合わない。"}, {"text": "石", "is_correct": false, "explanation": "石は山に当たっても上へのぼらず、雲になることもないので合わない。"}], "explanations": {"風": "山に当たって上へのぼる空気の流れを指し、雲になる文脈に合う。", "音": "音は山に当たって上へのぼり雲になるものではないので合わない。", "声": "声は空気の振動で、山に当たっても上へのぼって雲になることはないので合わない。", "石": "石は山に当たっても上へのぼらず、雲になることもないので合わない。"}, "sentence_index": 6, "correct_answer": "風"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "風邪をひいたので、今日は学校を休んだ。", "explanation": "ここは〈風邪〉（病気）の意味。大気の流れを指す定義では、病気は表せないので合わない。"}, {"text": "昔からの風習で、正月には餅を食べる。", "explanation": "ここは〈風習〉（ならわし）の意味。大気の流れを指す定義では、習慣は表せないので合わない。"}, {"text": "彼の漫画は社会を風刺して、人気がある。", "explanation": "ここは〈風刺〉（皮肉を込めた批判）の意味。大気の流れを指す定義では、批判は表せないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3cf92071-1d16-456b-80e1-4ce44bb16a1a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39387, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "窓を開けると、部屋に風を入ってくる。", "corrected_sentence": "窓を開けると、部屋に風が入ってくる。", "error_description": "「風を入ってくる」は誤り。「入ってくる」は自動詞で、動作の主体である風には「が」を使う。「を」（目的語）では文が成り立たないので、正しくは「風が入ってくる」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3cf92071-1d16-456b-80e1-4ce44bb16a1a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39387, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "昼過ぎ、風が止めて、港は静かになった。", "corrected_sentence": "昼過ぎ、風が止んで、港は静かになった。", "error_description": "「止めて」は他動詞の形で、主語の「風」が自然にやむ場合には自動詞「止む」を使う。正しくは「風が止んで」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3cf92071-1d16-456b-80e1-4ce44bb16a1a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39388, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「地下の水を汲み上げる」で、汲み上げる動作の対象を示す目的語の「を」。"}, {"text": "が", "is_correct": false, "explanation": "「地下の水が汲み上げている」は水が主体になり、汲む動作の対象を表せない。"}, {"text": "に", "is_correct": false, "explanation": "「地下の水に汲み上げる」は到着点や相手を示し、汲む対象にならない。"}, {"text": "と", "is_correct": false, "explanation": "「地下の水と汲み上げる」は並列や共同を表し、汲む対象は示せない。"}], "correct_answer": "を", "explanations": {"を": "「地下の水を汲み上げる」で、汲み上げる動作の対象を示す目的語の「を」。", "が": "「地下の水が汲み上げている」は水が主体になり、汲む動作の対象を表せない。", "に": "「地下の水に汲み上げる」は到着点や相手を示し、汲む対象にならない。", "と": "「地下の水と汲み上げる」は並列や共同を表し、汲む対象は示せない。"}, "error_tags": {"が": "主語", "に": "到着点・相手", "と": "並列・相手"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3cf92071-1d16-456b-80e1-4ce44bb16a1a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39388, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "「ポンプで」と道具や手段を示す「で」。"}, {"text": "へ", "is_correct": false, "explanation": "「ポンプへ汲み上げて」は方向を示すが、汲む手段は表せない。"}, {"text": "より", "is_correct": false, "explanation": "比較の「より」は「ポンプより汲み上げて」で成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "「ポンプの汲み上げて」は名詞を結ぶ形で、動詞にかからず不自然。"}], "correct_answer": "で", "explanations": {"で": "「ポンプで」と道具や手段を示す「で」。", "へ": "「ポンプへ汲み上げて」は方向を示すが、汲む手段は表せない。", "より": "比較の「より」は「ポンプより汲み上げて」で成り立たない。", "の": "「ポンプの汲み上げて」は名詞を結ぶ形で、動詞にかからず不自然。"}, "error_tags": {"へ": "方向", "より": "比較", "の": "連体修飾"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3cf92071-1d16-456b-80e1-4ce44bb16a1a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39388, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "水や油などを、下から上に、道具を使って取り出すこと。", "primary_collocate": null, "pronunciation": "くみあげる", "ipa": "kɯmiaɡeɾɯ", "syllable_count": 5, "sentences": [{"text": "井戸から水を汲み上げて、畑にまいた。", "target_word": "汲み上げて", "complexity_tier": "T3", "furigana": "井戸[いど]から水[みず]を汲[く]み上[あ]げて、畑[はたけ]にまいた。", "sentence_source": "generated"}, {"text": "ポンプで地下の水を汲み上げている。", "target_word": "汲み上げ", "complexity_tier": "T3", "furigana": "ポンプで地下[ちか]の水[みず]を汲[く]み上[あ]げている。", "sentence_source": "generated"}, {"text": "祖父はバケツで川の水を汲み上げた。", "target_word": "汲み上げた", "complexity_tier": "T3", "furigana": "祖父[そふ]はバケツで川[かわ]の水[みず]を汲[く]み上[あ]げた。", "sentence_source": "generated"}, {"text": "船の底にたまった水を汲み上げないと、沈んでしまう。", "target_word": "汲み上げない", "complexity_tier": "T3", "furigana": "船[ふね]の底[そこ]にたまった水[みず]を汲[く]み上[あ]げないと、沈[しず]んでしまう。", "sentence_source": "generated"}, {"text": "古い油田では、油を汲み上げる機械が動いていた。", "target_word": "汲み上げる", "complexity_tier": "T3", "furigana": "古[ふる]い油田[ゆでん]では、油[あぶら]を汲[く]み上[あ]げる機械[きかい]が動[うご]いていた。", "sentence_source": "generated"}, {"text": "汲み上げた水を、大きなタンクにためておく。", "target_word": "汲み上げた", "complexity_tier": "T3", "furigana": "汲[く]み上[あ]げた水[みず]を、大[おお]きなタンクにためておく。", "sentence_source": "generated"}, {"text": "雨が少ない年は、深い井戸から水を汲み上げる。", "target_word": "汲み上げる", "complexity_tier": "T3", "furigana": "雨[あめ]が少[すく]ない年[とし]は、深[ふか]い井戸[いど]から水[みず]を汲[く]み上[あ]げる。", "sentence_source": "generated"}, {"text": "彼は池の水をポンプで汲み上げて、庭に流した。", "target_word": "汲み上げて", "complexity_tier": "T3", "furigana": "彼[かれ]は池[いけ]の水[みず]をポンプで汲[く]み上[あ]げて、庭[にわ]に流[なが]した。", "sentence_source": "generated"}, {"text": "重い桶で水を汲み上げるのは、子どもには大変だ。", "target_word": "汲み上げる", "complexity_tier": "T3", "furigana": "重[おも]い桶[おけ]で水[みず]を汲[く]み上[あ]げるのは、子[こ]どもには大変[たいへん]だ。", "sentence_source": "generated"}, {"text": "機械が海水を汲み上げて、塩をつくっている。", "target_word": "汲み上げて", "complexity_tier": "T3", "furigana": "機械[きかい]が海水[かいすい]を汲[く]み上[あ]げて、塩[しお]をつくっている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "汲み上げる", "label": "辞書形"}, {"form": "汲み上げます", "label": "丁寧形"}, {"form": "汲み上げて", "label": "て形"}, {"form": "汲み上げた", "label": "た形"}, {"form": "汲み上げない", "label": "ない形"}], "register": "中立", "sense_fingerprint": "桶やポンプなどで、液体を低い所から高い所へ取り出す", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80d5caf6-f21d-47d6-aabb-a8ee0a91932d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39388, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "汲み上げて", "is_correct": true, "explanation": "井戸の水を下から上へ取り出す動作で、「畑にまいた」へ続く文脈に合う。"}, {"text": "凍らせて", "is_correct": false, "explanation": "水を凍らせる動作は汲み上げる意味にならず、畑にまく流れにも合わない。"}, {"text": "燃やして", "is_correct": false, "explanation": "水は燃やせないので、井戸から水を取り出す動作としては成り立たない。"}, {"text": "砕いて", "is_correct": false, "explanation": "水は砕けないので、取り出す動作として意味が通らない。"}], "explanations": {"汲み上げて": "井戸の水を下から上へ取り出す動作で、「畑にまいた」へ続く文脈に合う。", "凍らせて": "水を凍らせる動作は汲み上げる意味にならず、畑にまく流れにも合わない。", "燃やして": "水は燃やせないので、井戸から水を取り出す動作としては成り立たない。", "砕いて": "水は砕けないので、取り出す動作として意味が通らない。"}, "sentence_index": 0, "correct_answer": "汲み上げて"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "漁師が網を汲み上げて、船に積んだ。", "explanation": "ここは〈引き上げる〉の意味。網など物を持ち上げる場面では汲み上げるは使わない。汲み上げるは液体を下から上へ移す語。"}, {"text": "作業員が地中から古い石を汲み上げた。", "explanation": "ここは〈掘り出す〉の意味。土の中の固体を取り出す場面で、液体を汲む語は使わない。"}, {"text": "足場の鉄骨を汲み上げて、ビルを建てた。", "explanation": "ここは〈組み上げる〉の意味（組んで高く上げる）。液体を汲むのではないので、汲み上げるとは言えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3cf92071-1d16-456b-80e1-4ce44bb16a1a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39388, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "汲み上げる", "is_correct": true, "explanation": "深い井戸から水を引き上げる動作を表し、文脈に合う。"}, {"text": "焦がす", "is_correct": false, "explanation": "水は焦がせないので、井戸から水を取り出す動作にはならない。"}, {"text": "踏む", "is_correct": false, "explanation": "水を踏むことはできず、井戸から水を取り出す動作として成り立たない。"}, {"text": "放り投げる", "is_correct": false, "explanation": "水を放り投げるのは不自然で、井戸から水を引き上げる意味にはならない。"}], "explanations": {"汲み上げる": "深い井戸から水を引き上げる動作を表し、文脈に合う。", "焦がす": "水は焦がせないので、井戸から水を取り出す動作にはならない。", "踏む": "水を踏むことはできず、井戸から水を取り出す動作として成り立たない。", "放り投げる": "水を放り投げるのは不自然で、井戸から水を引き上げる意味にはならない。"}, "sentence_index": 6, "correct_answer": "汲み上げる"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "カップに紅茶を汲み上げる。", "explanation": "ここは〈注ぐ〉の意味。下から上へ引き上げる動きではないので、汲み上げるは使えない。"}, {"text": "池の金魚を網で汲み上げて、水槽に移した。", "explanation": "ここは〈掬う〉の意味。生き物を網で取る動きで、液体を道具で下から上へ移す定義とは合わない。"}, {"text": "重い荷物を汲み上げて、トラックに運んだ。", "explanation": "ここは〈運ぶ〉の意味。荷物を移動させる語で、液体を下から上へ移す定義には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3cf92071-1d16-456b-80e1-4ce44bb16a1a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39388, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "明け方、祖母は井戸から水が汲み上げて、畑に撒いた。", "corrected_sentence": "明け方、祖母は井戸から水を汲み上げて、畑に撒いた。", "error_description": "「水が汲み上げて」は誤り。「汲み上げる」は他動詞なので、目的語の「水」には「を」を使う。「が」は主語用なので不適切。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "汲み上げ", "is_correct": true, "explanation": "連用形で、「ている」に続けて「汲み上げている」となる。"}, {"text": "汲み上げない", "is_correct": false, "explanation": "ない形は「ている」に続かず、「汲み上げないている」は成り立たない。"}, {"text": "汲み上げた", "is_correct": false, "explanation": "過去形は「ている」の前に置けず、「汲み上げたている」は成り立たない。"}, {"text": "汲み上げます", "is_correct": false, "explanation": "丁寧形は「ている」に直接続かず、「汲み上げますている」は成り立たない。"}], "correct_form": "汲み上げ", "base_form": "汲み上げる", "form_label": "連用形（ている前）", "sentence_index": 1, "explanations": {"汲み上げ": "連用形で、「ている」に続けて「汲み上げている」となる。", "汲み上げない": "ない形は「ている」に続かず、「汲み上げないている」は成り立たない。", "汲み上げた": "過去形は「ている」の前に置けず、「汲み上げたている」は成り立たない。", "汲み上げます": "丁寧形は「ている」に直接続かず、「汲み上げますている」は成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3cf92071-1d16-456b-80e1-4ce44bb16a1a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39388, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "機械は海水を汲み上げらないと、塩ができない。", "corrected_sentence": "機械は海水を汲み上げないと、塩ができない。", "error_description": "「汲み上げらない」は誤り。正しくは「汲み上げない」。「られる」を付けると可能や受身の形になり、ここでは意味が通らない。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "汲み上げて", "is_correct": true, "explanation": "テ形で、「汲み上げて、庭に流した」と動作を順に続ける形。"}, {"text": "汲み上げよう", "is_correct": false, "explanation": "意志の形は文を続ける形になれず、「汲み上げよう、庭に流した」は成り立たない。"}, {"text": "汲み上げれば", "is_correct": false, "explanation": "仮定の形は動作を順に続けられず、過去の文の流れに合わない。"}, {"text": "汲み上げます", "is_correct": false, "explanation": "丁寧形は文中で動作を続けられず、「汲み上げます、庭に流した」は成り立たない。"}], "correct_form": "汲み上げて", "base_form": "汲み上げる", "form_label": "テ形", "sentence_index": 7, "explanations": {"汲み上げて": "テ形で、「汲み上げて、庭に流した」と動作を順に続ける形。", "汲み上げよう": "意志の形は文を続ける形になれず、「汲み上げよう、庭に流した」は成り立たない。", "汲み上げれば": "仮定の形は動作を順に続けられず、過去の文の流れに合わない。", "汲み上げます": "丁寧形は文中で動作を続けられず、「汲み上げます、庭に流した」は成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3cf92071-1d16-456b-80e1-4ce44bb16a1a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39390, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "「風車で発電する」と、発電の手段を示す「で」。"}, {"text": "を", "is_correct": false, "explanation": "「風車を発電する」では、発電の目的語として成り立たず不自然。"}, {"text": "へ", "is_correct": false, "explanation": "「風車へ発電する」は方向を示すが、発電の手段は表せない。"}, {"text": "より", "is_correct": false, "explanation": "「風車より発電する量」は比較として成り立たず、文の流れに合わない。"}], "correct_answer": "で", "explanations": {"で": "「風車で発電する」と、発電の手段を示す「で」。", "を": "「風車を発電する」では、発電の目的語として成り立たず不自然。", "へ": "「風車へ発電する」は方向を示すが、発電の手段は表せない。", "より": "「風車より発電する量」は比較として成り立たず、文の流れに合わない。"}, "error_tags": {"を": "目的語", "へ": "方向", "より": "比較"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3cf92071-1d16-456b-80e1-4ce44bb16a1a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
