INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39390, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "電気を作り出すこと。", "primary_collocate": null, "pronunciation": "はつでん", "ipa": "hatsɯdeɴ", "syllable_count": 4, "sentences": [{"text": "この工場では、太陽の光を使って発電している。", "target_word": "発電", "complexity_tier": "T3", "furigana": "この工場[こうじょう]では、太陽[たいよう]の光[ひかり]を使[つか]って発電[はつでん]している。", "sentence_source": "generated"}, {"text": "風が強い日は、風車で発電する量が増える。", "target_word": "発電する", "complexity_tier": "T3", "furigana": "風[かぜ]が強[つよ]い日[ひ]は、風車[ふうしゃ]で発電[はつでん]する量[りょう]が増[ふ]える。", "sentence_source": "generated"}, {"text": "水の力を利用した発電は、環境にやさしいと言われている。", "target_word": "発電", "complexity_tier": "T3", "furigana": "水[みず]の力[ちから]を利用[りよう]した発電[はつでん]は、環境[かんきょう]にやさしいと言[い]われている。", "sentence_source": "generated"}, {"text": "発電にはたくさんの燃料が必要だが、風力ならその心配はない。", "target_word": "発電", "complexity_tier": "T3", "furigana": "発電[はつでん]にはたくさんの燃料[ねんりょう]が必要[ひつよう]だが、風力[ふうりょく]ならその心配[しんぱい]はない。", "sentence_source": "generated"}, {"text": "山の上に大きな風車を建てて、発電を始めた。", "target_word": "発電", "complexity_tier": "T3", "furigana": "山[やま]の上[うえ]に大[おお]きな風車[ふうしゃ]を建[た]てて、発電[はつでん]を始[はじ]めた。", "sentence_source": "generated"}, {"text": "自転車をこぐと、ライトが発電してくれる。", "target_word": "発電して", "complexity_tier": "T3", "furigana": "自転車[じてんしゃ]をこぐと、ライトが発電[はつでん]してくれる。", "sentence_source": "generated"}, {"text": "この町では、ごみを燃やした熱で発電している。", "target_word": "発電して", "complexity_tier": "T3", "furigana": "この町[まち]では、ごみを燃[も]やした熱[ねつ]で発電[はつでん]している。", "sentence_source": "generated"}, {"text": "夜は太陽が出ないので、太陽光では発電できない。", "target_word": "発電できない", "complexity_tier": "T3", "furigana": "夜[よる]は太陽[たいよう]が出[で]ないので、太陽光[たいようこう]では発電[はつでん]できない。", "sentence_source": "generated"}, {"text": "国は、原子力に頼らない発電の方法を研究している。", "target_word": "発電", "complexity_tier": "T3", "furigana": "国[くに]は、原子力[げんしりょく]に頼[たよ]らない発電[はつでん]の方法[ほうほう]を研究[けんきゅう]している。", "sentence_source": "generated"}, {"text": "台風で風車が止まり、発電が一時止まった。", "target_word": "発電", "complexity_tier": "T3", "furigana": "台風[たいふう]で風車[ふうしゃ]が止[と]まり、発電[はつでん]が一時[いちじ]止[と]まった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "発電", "label": "名詞形"}, {"form": "発電する", "label": "辞書形"}, {"form": "発電した", "label": "タ形"}, {"form": "発電して", "label": "テ形"}, {"form": "発電しない", "label": "ナイ形"}, {"form": "発電できる", "label": "可能形"}], "register": "neutral", "sense_fingerprint": "電気を作り出すこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80d5caf6-f21d-47d6-aabb-a8ee0a91932d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39390, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "発電", "is_correct": true, "explanation": "太陽の光から電気を作る意味で、「使って〜している」の文脈に合う。"}, {"text": "採掘", "is_correct": false, "explanation": "太陽の光で鉱物を掘り出す意味にはならず、工場の文脈に合わない。"}, {"text": "解体", "is_correct": false, "explanation": "太陽の光を使って建物などを壊す意味にはならず、文脈に合わない。"}, {"text": "通訳", "is_correct": false, "explanation": "太陽の光を使って言葉を訳すことはできず、意味が通らない。"}], "explanations": {"発電": "太陽の光から電気を作る意味で、「使って〜している」の文脈に合う。", "採掘": "太陽の光で鉱物を掘り出す意味にはならず、工場の文脈に合わない。", "解体": "太陽の光を使って建物などを壊す意味にはならず、文脈に合わない。", "通訳": "太陽の光を使って言葉を訳すことはできず、意味が通らない。"}, "sentence_index": 0, "correct_answer": "発電"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "新しい発電所が完成して、町に明かりが増えた。", "explanation": "ここは〈発電所〉（施設）の意味。電気を作る行為を表す定義では、建物は表せないので合わない。"}, {"text": "非常用の発電機が、停電のときに動き出した。", "explanation": "ここは〈発電機〉（装置）の意味。行為ではなく機械を指すので合わない。"}, {"text": "発電所の所長が、町の集会で話をした。", "explanation": "ここは〈発電所〉（組織・施設）の意味。電気を作る行為は表せないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3cf92071-1d16-456b-80e1-4ce44bb16a1a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39390, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "発電して", "is_correct": true, "explanation": "ごみを燃やした熱で電気を作る意味で、「している」の文脈に合う。"}, {"text": "翻訳して", "is_correct": false, "explanation": "熱で文章を訳すことはできず、ごみ処理の文脈に合わない。"}, {"text": "製図して", "is_correct": false, "explanation": "熱で図面を描くことはできず、意味が通らない。"}, {"text": "採点して", "is_correct": false, "explanation": "熱で答案を採点することはできず、文脈に合わない。"}], "explanations": {"発電して": "ごみを燃やした熱で電気を作る意味で、「している」の文脈に合う。", "翻訳して": "熱で文章を訳すことはできず、ごみ処理の文脈に合わない。", "製図して": "熱で図面を描くことはできず、意味が通らない。", "採点して": "熱で答案を採点することはできず、文脈に合わない。"}, "sentence_index": 6, "correct_answer": "発電して"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "海辺の火力発電所の煙突が、遠くから見える。", "explanation": "ここは〈発電所〉（施設）の意味。電気を作る行為を表す定義では、建物は表せないので合わない。"}, {"text": "家庭用の発電機を買って、キャンプに持っていった。", "explanation": "ここは〈発電機〉（装置）の意味。行為ではなく機械を指すので合わない。"}, {"text": "発電所で働く父は、夜勤が多い。", "explanation": "ここは〈発電所〉（職場・施設）の意味。電気を作る行為は表せないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3cf92071-1d16-456b-80e1-4ce44bb16a1a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39390, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この川は水の力を発電している。", "corrected_sentence": "この川は水の力で発電している。", "error_description": "「水の力を発電」は誤り。「発電」は手段を表すとき「で」を使う。「を」は目的語用なので、正しくは「水の力で発電」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3cf92071-1d16-456b-80e1-4ce44bb16a1a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39390, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "夜間、太陽光では発電できるない。", "corrected_sentence": "夜間、太陽光では発電できない。", "error_description": "「できるない」は誤り。「できる」の否定は「できない」で、「る」は入らない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3cf92071-1d16-456b-80e1-4ce44bb16a1a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
