INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39391, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "主語を示す「が」で、「発電が可能だ」となって文が成立する。"}, {"text": "を", "is_correct": false, "explanation": "目的語の「を」では「発電を可能だ」となり、「可能だ」の主語にならない。"}, {"text": "に", "is_correct": false, "explanation": "「発電に可能だ」は不自然で、「可能だ」の主語を示せない。"}, {"text": "で", "is_correct": false, "explanation": "手段の「で」では「発電で可能だ」となり、文の主語にならない。"}], "correct_answer": "が", "explanations": {"が": "主語を示す「が」で、「発電が可能だ」となって文が成立する。", "を": "目的語の「を」では「発電を可能だ」となり、「可能だ」の主語にならない。", "に": "「発電に可能だ」は不自然で、「可能だ」の主語を示せない。", "で": "手段の「で」では「発電で可能だ」となり、文の主語にならない。"}, "error_tags": {"を": "目的語", "に": "結果・方向", "で": "手段"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3cf92071-1d16-456b-80e1-4ce44bb16a1a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39391, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "電気エネルギーを生み出すこと。", "primary_collocate": null, "pronunciation": "はつでん", "ipa": "hatsɯdeɴ", "syllable_count": 4, "sentences": [{"text": "火力は石炭やガスを燃やして発電する方法だ。", "target_word": "発電する", "complexity_tier": "T3", "furigana": "火力[かりょく]は石炭[せきたん]やガスを燃[も]やして発電[はつでん]する方法[ほうほう]だ。", "sentence_source": "generated"}, {"text": "地熱を使った発電は、天候に左右されにくい。", "target_word": "発電", "complexity_tier": "T3", "furigana": "地熱[ちねつ]を使[つか]った発電[はつでん]は、天候[てんこう]に左右[さゆう]されにくい。", "sentence_source": "generated"}, {"text": "屋根のパネルで発電した電気を、家で使っている。", "target_word": "発電した", "complexity_tier": "T3", "furigana": "屋根[やね]のパネルで発電[はつでん]した電気[でんき]を、家[いえ]で使[つか]っている。", "sentence_source": "generated"}, {"text": "ダムの水を落とす力で発電するため、雨が少ないと困る。", "target_word": "発電する", "complexity_tier": "T3", "furigana": "ダムの水[みず]を落[お]とす力[ちから]で発電[はつでん]するため、雨[あめ]が少[すく]ないと困[こま]る。", "sentence_source": "generated"}, {"text": "海の波を利用して発電する実験が行われている。", "target_word": "発電する", "complexity_tier": "T3", "furigana": "海[うみ]の波[なみ]を利用[りよう]して発電[はつでん]する実験[じっけん]が行[おこな]われている。", "sentence_source": "generated"}, {"text": "発電の効率を上げるために、新しいパネルが開発された。", "target_word": "発電", "complexity_tier": "T3", "furigana": "発電[はつでん]の効率[こうりつ]を上[あ]げるために、新[あたら]しいパネルが開発[かいはつ]された。", "sentence_source": "generated"}, {"text": "災害に備えて、学校に発電できる設備を置いた。", "target_word": "発電できる", "complexity_tier": "T3", "furigana": "災害[さいがい]に備[そな]えて、学校[がっこう]に発電[はつでん]できる設備[せつび]を置[お]いた。", "sentence_source": "generated"}, {"text": "小さな川でも、流れを利用すれば発電が可能だ。", "target_word": "発電", "complexity_tier": "T3", "furigana": "小[ちい]さな川[かわ]でも、流[なが]れを利用[りよう]すれば発電[はつでん]が可能[かのう]だ。", "sentence_source": "generated"}, {"text": "石油が高くなったので、他の方法で発電する国が増えた。", "target_word": "発電する", "complexity_tier": "T3", "furigana": "石油[せきゆ]が高[たか]くなったので、他[ほか]の方法[ほうほう]で発電[はつでん]する国[くに]が増[ふ]えた。", "sentence_source": "generated"}, {"text": "温泉の熱で発電する試みが、各地で進んでいる。", "target_word": "発電する", "complexity_tier": "T3", "furigana": "温泉[おんせん]の熱[ねつ]で発電[はつでん]する試[こころ]みが、各地[かくち]で進[すす]んでいる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "発電", "label": "名詞形"}, {"form": "発電する", "label": "辞書形"}, {"form": "発電した", "label": "タ形"}, {"form": "発電して", "label": "テ形"}, {"form": "発電しない", "label": "ナイ形"}, {"form": "発電できる", "label": "可能形"}], "register": "neutral", "sense_fingerprint": "熱や水などのエネルギーから電気を生み出すこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80d5caf6-f21d-47d6-aabb-a8ee0a91932d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39391, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "発電する", "is_correct": true, "explanation": "辞書形で名詞「方法」を修飾し、「燃やして発電する方法」となって文が成立する。"}, {"text": "発電して", "is_correct": false, "explanation": "テ形は文を続ける形で、名詞「方法」を直接修飾できない。"}, {"text": "発電し", "is_correct": false, "explanation": "連用中止形は名詞の前に置けず、「方法だ」へ続かない。"}, {"text": "発電を", "is_correct": false, "explanation": "目的語の「を」が付くと「方法」を修飾できず、文が崩れる。"}], "explanations": {"発電する": "辞書形で名詞「方法」を修飾し、「燃やして発電する方法」となって文が成立する。", "発電して": "テ形は文を続ける形で、名詞「方法」を直接修飾できない。", "発電し": "連用中止形は名詞の前に置けず、「方法だ」へ続かない。", "発電を": "目的語の「を」が付くと「方法」を修飾できず、文が崩れる。"}, "sentence_index": 0, "correct_answer": "発電する"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "寝る前に、スマホを発電しておいた。", "explanation": "ここは〈充電〉の意味。電池に電気をためる充電とは違い、発電は電気を新しく生み出すことなので、スマホの充電には使わない。"}, {"text": "冷房の使いすぎを防いで、こまめに発電した。", "explanation": "ここは〈節電〉の意味。電気の使用を減らす節電とは違い、発電は電気を生み出すことなので、「こまめに発電した」とは言わない。"}, {"text": "雷雲に溜まった電気が、地面へ発電された。", "explanation": "ここは〈放電〉の意味。たまった電気が外へ逃げる放電とは違い、発電は電気を生み出す行為なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3cf92071-1d16-456b-80e1-4ce44bb16a1a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39391, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "発電できる", "is_correct": true, "explanation": "可能形で名詞「設備」を修飾し、「学校に発電できる設備を置いた」となって文が成立する。"}, {"text": "発電しよう", "is_correct": false, "explanation": "意向形は名詞を修飾できず、「学校に〜設備」の形が成り立たない。"}, {"text": "発電で", "is_correct": false, "explanation": "「で」は手段や場所を示す助詞で、動詞の形として続かず、「設備」を修飾できない。"}, {"text": "発電させ", "is_correct": false, "explanation": "使役形の連用形は名詞「設備」に直接続かず、「させ設備」となって文が崩れる。"}], "explanations": {"発電できる": "可能形で名詞「設備」を修飾し、「学校に発電できる設備を置いた」となって文が成立する。", "発電しよう": "意向形は名詞を修飾できず、「学校に〜設備」の形が成り立たない。", "発電で": "「で」は手段や場所を示す助詞で、動詞の形として続かず、「設備」を修飾できない。", "発電させ": "使役形の連用形は名詞「設備」に直接続かず、「させ設備」となって文が崩れる。"}, "sentence_index": 6, "correct_answer": "発電できる"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "余った電気を、大きな蓄電池に発電しておく。", "explanation": "ここは〈蓄える〉の意味。電気を貯めておく蓄えることとは違い、発電は電気そのものを生み出すことなので、電池にためる意味では使わない。"}, {"text": "電気は、変電所で電圧を発電してから家庭に届く。", "explanation": "ここは〈電圧を変える〉の意味。電圧を上げ下げする変圧とは違い、発電は電気そのものを生み出すことなので、電圧の変更には使わない。"}, {"text": "この鉄塔は、山から町へ電気を発電している。", "explanation": "ここは〈送電〉の意味。電気を遠くへ送る送電とは違い、鉄塔は電気を生み出さないので、発電とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3cf92071-1d16-456b-80e1-4ce44bb16a1a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39391, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "屋根のパネルで発電の電気を、夜も使っている。", "corrected_sentence": "屋根のパネルで発電した電気を、夜も使っている。", "error_description": "「発電した電気」と動詞の連体形にする必要がある。「発電の電気」は名詞に「の」が付いた形で、「電気」を修飾する形として不自然。正しくは「発電した」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3cf92071-1d16-456b-80e1-4ce44bb16a1a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39391, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "ダムの発電する、夏の電力を支えている。", "corrected_sentence": "ダムの発電が、夏の電力を支えている。", "error_description": "名詞「発電」には「が」を付けて主語にする。「発電する」と動詞にすると、後ろの「夏の電力を支えている」と続かず文が崩れる。正しくは「発電が」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3cf92071-1d16-456b-80e1-4ce44bb16a1a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39392, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「最初の授業」と名詞を修飾する「の」で、授業の始まりを表す。"}, {"text": "が", "is_correct": false, "explanation": "「最初が授業では」は主語にならず、不自然。"}, {"text": "を", "is_correct": false, "explanation": "「最初を授業では」は目的語にならず、文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「最初へ授業では」は方向を示すが、授業の始まりを指す文脈に合わない。"}], "correct_answer": "の", "explanations": {"の": "「最初の授業」と名詞を修飾する「の」で、授業の始まりを表す。", "が": "「最初が授業では」は主語にならず、不自然。", "を": "「最初を授業では」は目的語にならず、文が成り立たない。", "へ": "「最初へ授業では」は方向を示すが、授業の始まりを指す文脈に合わない。"}, "error_tags": {"が": "主語を示す", "を": "目的語を示す", "へ": "方向を示す"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "最後", "is_correct": true, "explanation": "順序の終わりを指し、最初の対義語になる。"}, {"text": "途中", "is_correct": false, "explanation": "始まりと終わりの間を指し、対義語ではない。"}, {"text": "将来", "is_correct": false, "explanation": "今より先の時間を指し、順序の対義語ではない。"}, {"text": "月末", "is_correct": false, "explanation": "月の終わりの時期を指し、順序の対義語にはならない。"}], "correct_answer": "最後", "explanations": {"最後": "順序の終わりを指し、最初の対義語になる。", "途中": "始まりと終わりの間を指し、対義語ではない。", "将来": "今より先の時間を指し、順序の対義語ではない。", "月末": "月の終わりの時期を指し、順序の対義語にはならない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9af296b1-f96d-4031-ab4c-8208a8b01acf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39392, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「最初に」で順序の始まりを示し、書いた時点を表す。"}, {"text": "と", "is_correct": false, "explanation": "「最初と書いた文章」は並列にならず、不自然。"}, {"text": "より", "is_correct": false, "explanation": "「最初より書いた文章」は比較の意味になり、文脈に合わない。"}, {"text": "で", "is_correct": false, "explanation": "「最初で書いた文章」は時点を示すが、書く動作とは結びつかない。"}], "correct_answer": "に", "explanations": {"に": "「最初に」で順序の始まりを示し、書いた時点を表す。", "と": "「最初と書いた文章」は並列にならず、不自然。", "より": "「最初より書いた文章」は比較の意味になり、文脈に合わない。", "で": "「最初で書いた文章」は時点を示すが、書く動作とは結びつかない。"}, "error_tags": {"と": "並列を示す", "より": "比較を示す", "で": "場所・時点を示す"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "最後", "is_correct": true, "explanation": "順序の終わりを指し、最初の対義語になる。"}, {"text": "中盤", "is_correct": false, "explanation": "途中の時期を指し、対義語ではない。"}, {"text": "午後", "is_correct": false, "explanation": "一日の後半の時間を指し、順序の対義語にはならない。"}, {"text": "現在", "is_correct": false, "explanation": "今の時点を指し、最初の対義語ではない。"}], "correct_answer": "最後", "explanations": {"最後": "順序の終わりを指し、最初の対義語になる。", "中盤": "途中の時期を指し、対義語ではない。", "午後": "一日の後半の時間を指し、順序の対義語にはならない。", "現在": "今の時点を指し、最初の対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9af296b1-f96d-4031-ab4c-8208a8b01acf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39392, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "何かが始まる時、一番はじめのことを言います。", "primary_collocate": null, "pronunciation": "さいしょ", "ipa": "saiɕo", "syllable_count": 3, "sentences": [{"text": "映画の最初で、主人公が突然海に落ちるので驚きました。", "target_word": "最初", "complexity_tier": "T3", "furigana": "映画[えいが]の最初[さいしょ]で、主人公[しゅじんこう]が突然[とつぜん]海[うみ]に落[お]ちるので驚[おどろ]きました。", "sentence_source": "generated"}, {"text": "最初の授業では、先生が自己紹介をしてくれました。", "target_word": "最初", "complexity_tier": "T3", "furigana": "最初[さいしょ]の授業[じゅぎょう]では、先生[せんせい]が自己[じこ]紹介[しょうかい]をしてくれました。", "sentence_source": "generated"}, {"text": "最初にこの店を見つけたのは、散歩していた祖母です。", "target_word": "最初", "complexity_tier": "T3", "furigana": "最初[さいしょ]にこの店[みせ]を見[み]つけたのは、散歩[さんぽ]していた祖母[そぼ]です。", "sentence_source": "generated"}, {"text": "話の最初を聞いていなかったので、内容がわかりませんでした。", "target_word": "最初", "complexity_tier": "T3", "furigana": "話[はなし]の最初[さいしょ]を聞[き]いていなかったので、内容[ないよう]がわかりませんでした。", "sentence_source": "generated"}, {"text": "私は最初から、この計画はうまくいかないと思っていました。", "target_word": "最初", "complexity_tier": "T3", "furigana": "私[わたし]は最初[さいしょ]から、この計画[けいかく]はうまくいかないと思[おも]っていました。", "sentence_source": "generated"}, {"text": "最初はみんな緊張していたが、すぐに笑い声が聞こえてきました。", "target_word": "最初", "complexity_tier": "T3", "furigana": "最初[さいしょ]はみんな緊張[きんちょう]していたが、すぐに笑[わら]い声[ごえ]が聞[き]こえてきました。", "sentence_source": "generated"}, {"text": "日本に来て最初の冬は、寒さに慣れなくて大変でした。", "target_word": "最初", "complexity_tier": "T3", "furigana": "日本[にほん]に来[き]て最初[さいしょ]の冬[ふゆ]は、寒[さむ]さに慣[な]れなくて大変[たいへん]でした。", "sentence_source": "generated"}, {"text": "最初に書いた文章を、もう一度読んで直しました。", "target_word": "最初", "complexity_tier": "T3", "furigana": "最初[さいしょ]に書[か]いた文章[ぶんしょう]を、もう一度[いちど]読[よ]んで直[なお]しました。", "sentence_source": "generated"}, {"text": "最初のページに名前を書いてから、問題を解いてください。", "target_word": "最初", "complexity_tier": "T3", "furigana": "最初[さいしょ]のページに名前[なまえ]を書[か]いてから、問題[もんだい]を解[と]いてください。", "sentence_source": "generated"}, {"text": "最初が肝心だと言われるので、初日は早く会社に行きました。", "target_word": "最初", "complexity_tier": "T3", "furigana": "最初[さいしょ]が肝心[かんじん]だと言[い]われるので、初日[しょにち]は早[はや]く会社[かいしゃ]に行[い]きました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "最初", "label": "基本形"}], "register": "中立", "sense_fingerprint": "物事が始まるときの一番はじめの部分・時", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed3d3110-d507-4b02-8197-8f3e9eb5d27a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39392, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "最初", "is_correct": true, "explanation": "映画の始まりの場面を指し、主人公が海に落ちる場面と合う。"}, {"text": "天井", "is_correct": false, "explanation": "「映画の天井で」は場面を指さず、文の意味が成り立たない。"}, {"text": "財布", "is_correct": false, "explanation": "「映画の財布で」は場面を指さず、文の意味が成り立たない。"}, {"text": "湿気", "is_correct": false, "explanation": "「映画の湿気で」は場面を指さず、文脈に合わない。"}], "explanations": {"最初": "映画の始まりの場面を指し、主人公が海に落ちる場面と合う。", "天井": "「映画の天井で」は場面を指さず、文の意味が成り立たない。", "財布": "「映画の財布で」は場面を指さず、文の意味が成り立たない。", "湿気": "「映画の湿気で」は場面を指さず、文脈に合わない。"}, "sentence_index": 0, "correct_answer": "最初"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "入場料は最初で千円です。", "explanation": "ここは〈合計〉の意味。最初は時の始まりを表し、金額の総計には使わない。"}, {"text": "彼女は大会で最初を制して、金メダルをもらった。", "explanation": "ここは〈優勝〉の意味。最初は順序の始まりを指し、大会で勝つ意味では使わない。"}, {"text": "作業は最初で二時間かかります。", "explanation": "ここは〈最低〉の意味。最初は時の始まりを表し、かかる時間の下限は表せない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9af296b1-f96d-4031-ab4c-8208a8b01acf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39392, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "最初", "is_correct": true, "explanation": "日本に来た時から始まる最初の冬を指し、文脈に合う。"}, {"text": "食器", "is_correct": false, "explanation": "「食器の冬」は時期を表さず、文が成り立たない。"}, {"text": "雑草", "is_correct": false, "explanation": "「雑草の冬」は時期を表さず、寒さに慣れる文脈に合わない。"}, {"text": "封筒", "is_correct": false, "explanation": "「封筒の冬」は時期を指せず、意味が通らない。"}], "explanations": {"最初": "日本に来た時から始まる最初の冬を指し、文脈に合う。", "食器": "「食器の冬」は時期を表さず、文が成り立たない。", "雑草": "「雑草の冬」は時期を表さず、寒さに慣れる文脈に合わない。", "封筒": "「封筒の冬」は時期を指せず、意味が通らない。"}, "sentence_index": 6, "correct_answer": "最初"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "会計は最初で五百円でした。", "explanation": "ここは〈全部〉の意味。最初は時の始まりを表し、全体の金額を表すことはできない。"}, {"text": "損害は最初で百万円と見込まれます。", "explanation": "ここは〈最大〉の意味。最初は時間の順序を表し、上限の数量は表せない。"}, {"text": "予選で最初を取り、決勝に進みました。", "explanation": "ここは〈首位〉の意味。最初は時の始まりを表し、順位の一番を表す使い方ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9af296b1-f96d-4031-ab4c-8208a8b01acf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39392, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "試合の最初を、選手が転んだ。", "corrected_sentence": "試合の最初で、選手が転んだ。", "error_description": "場面の始まりを示す「最初」には「で」が必要。「を」は目的語になるので、ここでは誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9af296b1-f96d-4031-ab4c-8208a8b01acf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39392, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "新学期の最初なクラスは、とても静かでした。", "corrected_sentence": "新学期の最初のクラスは、とても静かでした。", "error_description": "名詞の「最初」を修飾するときは「の」を使う。「な」は形容動詞用の形なので誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9af296b1-f96d-4031-ab4c-8208a8b01acf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39393, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「最初に」で順序の始まりの時点を示し、名前を呼ばれた時を表す。"}, {"text": "が", "is_correct": false, "explanation": "「最初が名前を呼ばれた」では最初が主語にならず、不自然。"}, {"text": "を", "is_correct": false, "explanation": "「最初を名前を」は目的語が二つ重なり、文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「最初へ名前を呼ばれた」は方向を示すが、時点の文脈に合わない。"}], "correct_answer": "に", "explanations": {"に": "「最初に」で順序の始まりの時点を示し、名前を呼ばれた時を表す。", "が": "「最初が名前を呼ばれた」では最初が主語にならず、不自然。", "を": "「最初を名前を」は目的語が二つ重なり、文が成り立たない。", "へ": "「最初へ名前を呼ばれた」は方向を示すが、時点の文脈に合わない。"}, "error_tags": {"が": "主語を示す", "を": "目的語を示す", "へ": "方向を示す"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "最後", "is_correct": true, "explanation": "順序の終わりを指し、最初の対義語になる。"}, {"text": "途中", "is_correct": false, "explanation": "始まりと終わりの間を指し、対義語ではない。"}, {"text": "将来", "is_correct": false, "explanation": "今より先の時間を指し、順序の対義語ではない。"}, {"text": "月末", "is_correct": false, "explanation": "月の終わりの時期を指し、順序の対義語にはならない。"}], "correct_answer": "最後", "explanations": {"最後": "順序の終わりを指し、最初の対義語になる。", "途中": "始まりと終わりの間を指し、対義語ではない。", "将来": "今より先の時間を指し、順序の対義語ではない。", "月末": "月の終わりの時期を指し、順序の対義語にはならない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9af296b1-f96d-4031-ab4c-8208a8b01acf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39393, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「最初の試合」と名詞を修飾する「の」で、試合の始まりの段階を表す。"}, {"text": "と", "is_correct": false, "explanation": "「最初と試合に負けても」は並列にならず、不自然。"}, {"text": "より", "is_correct": false, "explanation": "「最初より試合に負けても」は比較の意味になり、文脈に合わない。"}, {"text": "を", "is_correct": false, "explanation": "「最初を試合に負けても」は目的語が成り立たず、文が通らない。"}], "correct_answer": "の", "explanations": {"の": "「最初の試合」と名詞を修飾する「の」で、試合の始まりの段階を表す。", "と": "「最初と試合に負けても」は並列にならず、不自然。", "より": "「最初より試合に負けても」は比較の意味になり、文脈に合わない。", "を": "「最初を試合に負けても」は目的語が成り立たず、文が通らない。"}, "error_tags": {"と": "並列を示す", "より": "比較を示す", "を": "目的語を示す"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "最後", "is_correct": true, "explanation": "順序の終わりを指し、最初の対義語になる。"}, {"text": "中盤", "is_correct": false, "explanation": "途中の時期を指し、対義語ではない。"}, {"text": "午後", "is_correct": false, "explanation": "一日の後半の時間を指し、順序の対義語にはならない。"}, {"text": "現在", "is_correct": false, "explanation": "今の時点を指し、最初の対義語ではない。"}], "correct_answer": "最後", "explanations": {"最後": "順序の終わりを指し、最初の対義語になる。", "中盤": "途中の時期を指し、対義語ではない。", "午後": "一日の後半の時間を指し、順序の対義語にはならない。", "現在": "今の時点を指し、最初の対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9af296b1-f96d-4031-ab4c-8208a8b01acf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39393, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物事の順番で、一番初めの時や状態。", "primary_collocate": null, "pronunciation": "さいしょ", "ipa": "saiɕo", "syllable_count": 3, "sentences": [{"text": "最初の一年は、美しい田園風景とは裏腹に、泥にまみれた過酷な肉体労働の連続でした。", "target_word": "最初", "complexity_tier": "T3", "furigana": "最初[さいしょ]の一年[いちねん]は、美[うつく]しい田園[でんえん]風景[ふうけい]とは裏腹[うらはら]に、泥[どろ]にまみれた過酷[かこく]な肉体[にくたい]労働[ろうどう]の連続[れんぞく]でした。", "sentence_source": "mined"}, {"text": "最初に名前を呼ばれたのは、いちばん後ろに座っていた私でした。", "target_word": "最初", "complexity_tier": "T3", "furigana": "最初[さいしょ]に名前[なまえ]を呼[よ]ばれたのは、いちばん後[うし]ろに座[すわ]っていた私[わたし]でした。", "sentence_source": "generated"}, {"text": "この本は最初がおもしろくないので、多くの人が途中でやめてしまいます。", "target_word": "最初", "complexity_tier": "T3", "furigana": "この本[ほん]は最初[さいしょ]がおもしろくないので、多[おお]くの人[ひと]が途中[とちゅう]でやめてしまいます。", "sentence_source": "generated"}, {"text": "最初は日本語がわからなかったが、今は新聞も読めます。", "target_word": "最初", "complexity_tier": "T3", "furigana": "最初[さいしょ]は日本語[にほんご]がわからなかったが、今[いま]は新聞[しんぶん]も読[よ]めます。", "sentence_source": "generated"}, {"text": "駅に着いて最初にしたことは、切符を買うことでした。", "target_word": "最初", "complexity_tier": "T3", "furigana": "駅[えき]に着[つ]いて最初[さいしょ]にしたことは、切符[きっぷ]を買[か]うことでした。", "sentence_source": "generated"}, {"text": "最初から全部説明するので、メモを取りながら聞いてください。", "target_word": "最初", "complexity_tier": "T3", "furigana": "最初[さいしょ]から全部[ぜんぶ]説明[せつめい]するので、メモを取[と]りながら聞[き]いてください。", "sentence_source": "generated"}, {"text": "走り始めた最初の一キロは、体が重くて苦しかったです。", "target_word": "最初", "complexity_tier": "T3", "furigana": "走[はし]り始[はじ]めた最初[さいしょ]の一[いち]キロは、体[からだ]が重[おも]くて苦[くる]しかったです。", "sentence_source": "generated"}, {"text": "最初の試合に負けても、彼らはあきらめませんでした。", "target_word": "最初", "complexity_tier": "T3", "furigana": "最初[さいしょ]の試合[しあい]に負[ま]けても、彼[かれ]らはあきらめませんでした。", "sentence_source": "generated"}, {"text": "手紙の最初に、お礼の言葉を書きました。", "target_word": "最初", "complexity_tier": "T3", "furigana": "手紙[てがみ]の最初[さいしょ]に、お礼[れい]の言葉[ことば]を書[か]きました。", "sentence_source": "generated"}, {"text": "料理は最初に野菜を切ってから、火をつけます。", "target_word": "最初", "complexity_tier": "T3", "furigana": "料理[りょうり]は最初[さいしょ]に野菜[やさい]を切[き]ってから、火[ひ]をつけます。", "sentence_source": "generated"}], "morphological_forms": [{"form": "最初", "label": "基本形"}], "register": "中立", "sense_fingerprint": "順番や経過の中で一番初めの時点・状態", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T1: 3 words above tier T1 (max 2): 田園 (Zipf 3.16), 裏腹 (Zipf 3.38), 過酷 (Zipf 3.82)']::text[], 'ed3d3110-d507-4b02-8197-8f3e9eb5d27a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39393, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "最初", "is_correct": true, "explanation": "物事の順番の一番初めの時期を示し、「最初の一年」として文の時期を表す。"}, {"text": "演奏", "is_correct": false, "explanation": "「演奏の一年」では時期を表せず、一年を説明する文の意味が通らない。"}, {"text": "天気", "is_correct": false, "explanation": "「天気の一年」は時期を指せず、続く「一年は」と意味がつながらない。"}, {"text": "砂糖", "is_correct": false, "explanation": "「砂糖の一年」は時期を表さず、文の意味が成り立たない。"}], "explanations": {"最初": "物事の順番の一番初めの時期を示し、「最初の一年」として文の時期を表す。", "演奏": "「演奏の一年」では時期を表せず、一年を説明する文の意味が通らない。", "天気": "「天気の一年」は時期を指せず、続く「一年は」と意味がつながらない。", "砂糖": "「砂糖の一年」は時期を表さず、文の意味が成り立たない。"}, "sentence_index": 0, "correct_answer": "最初"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "選手は大会で最初を獲得した。", "explanation": "ここは〈優勝〉の意味。最初は順序の始まりを指し、賞や勝利を得る意味では使わない。"}, {"text": "映画は最初で二時間の長さだ。", "explanation": "ここは〈所要時間〉の意味。最初は時の始まりを表し、かかる時間の長さは表せない。"}, {"text": "会費は最初で三千円です。", "explanation": "ここは〈合計〉の意味。最初は時間の始まりを表し、金額の総計には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9af296b1-f96d-4031-ab4c-8208a8b01acf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39393, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "最初", "is_correct": true, "explanation": "「走り始めた最初の一キロ」として、走り始めた時点を指すので文が通る。"}, {"text": "食卓", "is_correct": false, "explanation": "「走り始めた食卓の一キロ」は意味が通らず、距離の説明にならない。"}, {"text": "洗濯", "is_correct": false, "explanation": "「走り始めた洗濯の一キロ」は走る距離の説明として成り立たない。"}, {"text": "寝床", "is_correct": false, "explanation": "「走り始めた寝床の一キロ」は意味が通らず、文脈に合わない。"}], "explanations": {"最初": "「走り始めた最初の一キロ」として、走り始めた時点を指すので文が通る。", "食卓": "「走り始めた食卓の一キロ」は意味が通らず、距離の説明にならない。", "洗濯": "「走り始めた洗濯の一キロ」は走る距離の説明として成り立たない。", "寝床": "「走り始めた寝床の一キロ」は意味が通らず、文脈に合わない。"}, "sentence_index": 6, "correct_answer": "最初"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "ご注文は最初で五千円です。", "explanation": "ここは〈全部〉の意味。最初は時間の始まりを表し、すべてを合わせた金額の意味にはならない。"}, {"text": "最初でも三日はかかります。", "explanation": "ここは〈最低〉の意味。最初は始まりの時点で、下限の日数を表せない。"}, {"text": "予選で最初を取り、決勝に進みました。", "explanation": "ここは〈首位〉の意味。最初は時の始まりを表し、順位の一番を表す使い方ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9af296b1-f96d-4031-ab4c-8208a8b01acf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39393, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "会議の最初を、社長が挨拶しました。", "corrected_sentence": "会議の最初に、社長が挨拶しました。", "error_description": "時点を表す「最初」には「に」が必要。「を」は目的語を示すので、ここでは誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9af296b1-f96d-4031-ab4c-8208a8b01acf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39393, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "最初な授業は、いつも少し緊張します。", "corrected_sentence": "最初の授業は、いつも少し緊張します。", "error_description": "名詞の「最初」を修飾するときは「の」を使う。「な」は形容動詞用の形なので誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9af296b1-f96d-4031-ab4c-8208a8b01acf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39394, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「隊長に続いて」と後に従う相手を示す。"}, {"text": "を", "is_correct": false, "explanation": "「続く」は自動詞なので「を」は使えない。"}, {"text": "で", "is_correct": false, "explanation": "「隊長で続いて」は文として成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "「隊長の続いて」は文として成り立たない。"}], "correct_answer": "に", "explanations": {"に": "「隊長に続いて」と後に従う相手を示す。", "を": "「続く」は自動詞なので「を」は使えない。", "で": "「隊長で続いて」は文として成り立たない。", "の": "「隊長の続いて」は文として成り立たない。"}, "error_tags": {"を": "transitivity", "で": "means", "の": "possessive"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "先導する", "is_correct": true, "explanation": "人の後に続くことの反対で、先に立って導く意味。"}, {"text": "読む", "is_correct": false, "explanation": "「続く」と反対の関係にない。"}, {"text": "眠る", "is_correct": false, "explanation": "「続く」と反対の関係にない。"}, {"text": "開く", "is_correct": false, "explanation": "「続く」と反対の関係にない。"}], "correct_answer": "先導する", "explanations": {"先導する": "人の後に続くことの反対で、先に立って導く意味。", "読む": "「続く」と反対の関係にない。", "眠る": "「続く」と反対の関係にない。", "開く": "「続く」と反対の関係にない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb16708b-b95b-48c7-a0fa-86ef1023e037') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39394, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「私に続いて」と後に従う相手を示す。"}, {"text": "を", "is_correct": false, "explanation": "「続く」は自動詞なので「を」は使えない。"}, {"text": "の", "is_correct": false, "explanation": "「私の続いて」は文として成り立たない。"}, {"text": "や", "is_correct": false, "explanation": "「私や続いて」は文として成り立たない。"}], "correct_answer": "に", "explanations": {"に": "「私に続いて」と後に従う相手を示す。", "を": "「続く」は自動詞なので「を」は使えない。", "の": "「私の続いて」は文として成り立たない。", "や": "「私や続いて」は文として成り立たない。"}, "error_tags": {"を": "transitivity", "の": "possessive", "や": "listing"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "先立つ", "is_correct": true, "explanation": "彼の後に続くことの反対で、先に行く意味。"}, {"text": "笑う", "is_correct": false, "explanation": "「続く」と反対の関係にない。"}, {"text": "光る", "is_correct": false, "explanation": "「続く」と反対の関係にない。"}, {"text": "閉まる", "is_correct": false, "explanation": "「続く」と反対の関係にない。"}], "correct_answer": "先立つ", "explanations": {"先立つ": "彼の後に続くことの反対で、先に行く意味。", "笑う": "「続く」と反対の関係にない。", "光る": "「続く」と反対の関係にない。", "閉まる": "「続く」と反対の関係にない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb16708b-b95b-48c7-a0fa-86ef1023e037') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39394, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "人や物事が、ほかの人や物事のすぐ後に従って来る、または起こること。", "primary_collocate": null, "pronunciation": "つづく", "ipa": "tsɯdzɯkɯ", "syllable_count": 3, "sentences": [{"text": "先生に続いて、読んでください。", "target_word": "続いて", "complexity_tier": "T2", "furigana": "せんせいにつづいて、よんでください。", "sentence_source": "generated"}, {"text": "隊長に続いて、みんなが山に登った。", "target_word": "続いて", "complexity_tier": "T3", "furigana": "たいちょうにつづいて、みんながやまにのぼった。", "sentence_source": "generated"}, {"text": "母に続いて、子どもが家に入った。", "target_word": "続いて", "complexity_tier": "T3", "furigana": "ははにつづいて、こどもがいえにはいった。", "sentence_source": "generated"}, {"text": "パレードの車に続いて、子どもたちが歩いた。", "target_word": "続いて", "complexity_tier": "T3", "furigana": "パレードのくるまにつづいて、こどもたちがあるいた。", "sentence_source": "generated"}, {"text": "前の車に続いて、バスが止まった。", "target_word": "続いて", "complexity_tier": "T3", "furigana": "まえのくるまにつづいて、バスがとまった。", "sentence_source": "generated"}, {"text": "先頭の選手に続く二人が、同時にゴールした。", "target_word": "続く", "complexity_tier": "T3", "furigana": "せんとうのせんしゅにつづくふたりが、どうじにゴールした。", "sentence_source": "generated"}, {"text": "一人が走り出すと、他の人も続いた。", "target_word": "続いた", "complexity_tier": "T4", "furigana": "ひとりがはしりだすと、ほかのひともつづいた。", "sentence_source": "generated"}, {"text": "私に続いて、同じ言葉を言ってください。", "target_word": "続いて", "complexity_tier": "T3", "furigana": "わたしにつづいて、おなじことばをいってください。", "sentence_source": "generated"}, {"text": "大きな地震に続いて、津波が来た。", "target_word": "続いて", "complexity_tier": "T3", "furigana": "おおきなじしんにつづいて、つなみがきた。", "sentence_source": "generated"}, {"text": "彼に続く人はいなかった。", "target_word": "続く", "complexity_tier": "T3", "furigana": "かれにつづくひとはいなかった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "続いて", "label": "活用"}, {"form": "続いた", "label": "活用"}, {"form": "続き", "label": "派生"}], "register": "plain", "sense_fingerprint": "動詞 | 後から別の物や人が来る", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '530831ed-fe17-4cbf-8f61-bfe726a891b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39394, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "続く", "is_correct": true, "explanation": "見出し語「つづく」そのもの。"}, {"text": "つつく", "is_correct": false, "explanation": "「つつく」は「づ」が「つ」になる一拍違いの別語。"}, {"text": "綴る", "is_correct": false, "explanation": "「つづる」は最後の「く」が「る」になる一拍違いの別語。"}, {"text": "鼓", "is_correct": false, "explanation": "「つづみ」は最後の「く」が「み」になる一拍違いの別語。"}], "explanations": {"続く": "見出し語「つづく」そのもの。", "つつく": "「つつく」は「づ」が「つ」になる一拍違いの別語。", "綴る": "「つづる」は最後の「く」が「る」になる一拍違いの別語。", "鼓": "「つづみ」は最後の「く」が「み」になる一拍違いの別語。"}, "sentence_index": null, "correct_answer": "続く"}, "level_3": {"options": [{"text": "続いて", "is_correct": true, "explanation": "先生の後に続いて読むという意味で文に合う。"}, {"text": "眠って", "is_correct": false, "explanation": "形は合うが、先生に眠ってという意味が合わない。"}, {"text": "光って", "is_correct": false, "explanation": "形は合うが、先生に光ってという意味が合わない。"}, {"text": "割れて", "is_correct": false, "explanation": "形は合うが、先生に割れてという意味が合わない。"}], "explanations": {"続いて": "先生の後に続いて読むという意味で文に合う。", "眠って": "形は合うが、先生に眠ってという意味が合わない。", "光って": "形は合うが、先生に光ってという意味が合わない。", "割れて": "形は合うが、先生に割れてという意味が合わない。"}, "sentence_index": 0, "correct_answer": "続いて"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "パレードの車を続いて、子どもたちが歩いた。", "explanation": "「続く」は自動詞で、後に従う相手は「に」で示す。「を」は誤り。"}, {"text": "冷蔵庫の中にりんごが続く。", "explanation": "「続く」は物が入っている状態には使わず、意味が合わない。"}, {"text": "このスープは塩が続いて、おいしい。", "explanation": "塩が後から来るという意味にならず、「続く」の使い方として合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb16708b-b95b-48c7-a0fa-86ef1023e037') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39394, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "続く", "is_correct": true, "explanation": "見出し語「つづく」そのもの。"}, {"text": "綴り", "is_correct": false, "explanation": "「つづり」は最後の「く」が「り」になる一拍違いの別語。"}, {"text": "葛籠", "is_correct": false, "explanation": "「つづら」は最後の「く」が「ら」になる一拍違いの別語。"}, {"text": "綴る", "is_correct": false, "explanation": "「つづる」は最後の「く」が「る」になる一拍違いの別語。"}], "explanations": {"続く": "見出し語「つづく」そのもの。", "綴り": "「つづり」は最後の「く」が「り」になる一拍違いの別語。", "葛籠": "「つづら」は最後の「く」が「ら」になる一拍違いの別語。", "綴る": "「つづる」は最後の「く」が「る」になる一拍違いの別語。"}, "sentence_index": null, "correct_answer": "続く"}, "level_3": {"options": [{"text": "続いた", "is_correct": true, "explanation": "一人の後に他の人も従ったという意味で文に合う。"}, {"text": "光った", "is_correct": false, "explanation": "形は合うが、他の人も光ったという意味が合わない。"}, {"text": "割れた", "is_correct": false, "explanation": "形は合うが、他の人も割れたという意味が合わない。"}, {"text": "乾いた", "is_correct": false, "explanation": "形は合うが、他の人も乾いたという意味が合わない。"}], "explanations": {"続いた": "一人の後に他の人も従ったという意味で文に合う。", "光った": "形は合うが、他の人も光ったという意味が合わない。", "割れた": "形は合うが、他の人も割れたという意味が合わない。", "乾いた": "形は合うが、他の人も乾いたという意味が合わない。"}, "sentence_index": 6, "correct_answer": "続いた"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼を続く人はいなかった。", "explanation": "「続く」は自動詞で、後に従う相手は「に」で示す。「を」は誤り。"}, {"text": "彼と続く人はいなかった。", "explanation": "後に従う相手は「に」で示す。「と」では意味が通らない。"}, {"text": "彼に続く冷蔵庫はなかった。", "explanation": "後から来る者として冷蔵庫は意味が合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb16708b-b95b-48c7-a0fa-86ef1023e037') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39394, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "社長を続いて、社員が部屋に入った。", "corrected_sentence": "社長に続いて、社員が部屋に入った。", "error_description": "「〜に続いて」と言うべきところを、「を」にしているのが誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "続いて", "is_correct": true, "explanation": "「隊長に続いて、〜」とて形でつなぐ。"}, {"text": "続く", "is_correct": false, "explanation": "終止形では読点の後につながらず不自然。"}, {"text": "続いた", "is_correct": false, "explanation": "過去形では「、みんなが」へ自然につながらない。"}, {"text": "続こう", "is_correct": false, "explanation": "意志形では文が成り立たない。"}], "correct_form": "続いて", "base_form": "続く", "form_label": "て形", "sentence_index": 1, "explanations": {"続いて": "「隊長に続いて、〜」とて形でつなぐ。", "続く": "終止形では読点の後につながらず不自然。", "続いた": "過去形では「、みんなが」へ自然につながらない。", "続こう": "意志形では文が成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb16708b-b95b-48c7-a0fa-86ef1023e037') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39394, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "リーダーで続いて、全員が走った。", "corrected_sentence": "リーダーに続いて、全員が走った。", "error_description": "後に従う相手は「に」で示すべきところを「で」にしているのが誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "続いて", "is_correct": true, "explanation": "「私に続いて、〜言ってください」とて形でつなぐ。"}, {"text": "続いた", "is_correct": false, "explanation": "過去形では依頼の文へ自然につながらない。"}, {"text": "続けば", "is_correct": false, "explanation": "仮定形では「言ってください」と意味がつながらない。"}, {"text": "続かない", "is_correct": false, "explanation": "否定形では依頼の内容と合わない。"}], "correct_form": "続いて", "base_form": "続く", "form_label": "て形", "sentence_index": 7, "explanations": {"続いて": "「私に続いて、〜言ってください」とて形でつなぐ。", "続いた": "過去形では依頼の文へ自然につながらない。", "続けば": "仮定形では「言ってください」と意味がつながらない。", "続かない": "否定形では依頼の内容と合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb16708b-b95b-48c7-a0fa-86ef1023e037') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39395, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「暑さが続く」と主語を示す。"}, {"text": "を", "is_correct": false, "explanation": "「続く」は自動詞なので「を」は使えない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表す「へ」は主語の位置に入らない。"}, {"text": "と", "is_correct": false, "explanation": "「暑さと続く」は文として成り立たない。"}], "correct_answer": "が", "explanations": {"が": "「暑さが続く」と主語を示す。", "を": "「続く」は自動詞なので「を」は使えない。", "へ": "方向を表す「へ」は主語の位置に入らない。", "と": "「暑さと続く」は文として成り立たない。"}, "error_tags": {"を": "transitivity", "へ": "direction", "と": "comitative"}, "sentence_index": 0}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "途切れる", "is_correct": true, "explanation": "道が続くことの反対で、連なりが切れる意味。"}, {"text": "増える", "is_correct": false, "explanation": "数量が多くなる意味で、反対の関係ではない。"}, {"text": "眠る", "is_correct": false, "explanation": "「続く」と反対の関係にない。"}, {"text": "開く", "is_correct": false, "explanation": "「続く」と反対の関係にない。"}], "correct_answer": "途切れる", "explanations": {"途切れる": "道が続くことの反対で、連なりが切れる意味。", "増える": "数量が多くなる意味で、反対の関係ではない。", "眠る": "「続く」と反対の関係にない。", "開く": "「続く」と反対の関係にない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb16708b-b95b-48c7-a0fa-86ef1023e037') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39395, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「努力が続く」と主語を示す。"}, {"text": "を", "is_correct": false, "explanation": "「続く」は自動詞なので「を」は使えない。"}, {"text": "へ", "is_correct": false, "explanation": "方向の「へ」は主語の位置に入らない。"}, {"text": "や", "is_correct": false, "explanation": "「努力や続かなければ」は文として成り立たない。"}], "correct_answer": "が", "explanations": {"が": "「努力が続く」と主語を示す。", "を": "「続く」は自動詞なので「を」は使えない。", "へ": "方向の「へ」は主語の位置に入らない。", "や": "「努力や続かなければ」は文として成り立たない。"}, "error_tags": {"を": "transitivity", "へ": "direction", "や": "listing"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "終わる", "is_correct": true, "explanation": "雨が三日続くことの反対で、続かずに終わる意味。"}, {"text": "近づく", "is_correct": false, "explanation": "「続く」と反対の関係にない。"}, {"text": "光る", "is_correct": false, "explanation": "「続く」と反対の関係にない。"}, {"text": "笑う", "is_correct": false, "explanation": "「続く」と反対の関係にない。"}], "correct_answer": "終わる", "explanations": {"終わる": "雨が三日続くことの反対で、続かずに終わる意味。", "近づく": "「続く」と反対の関係にない。", "光る": "「続く」と反対の関係にない。", "笑う": "「続く」と反対の関係にない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb16708b-b95b-48c7-a0fa-86ef1023e037') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39395, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "動作や状態が時間や空間の上で絶えずにあること。また、そのままの状態が続くこと。", "primary_collocate": null, "pronunciation": "つづく", "ipa": "tsɯdzɯkɯ", "syllable_count": 3, "sentences": [{"text": "記録的な暑さが続く夏の午後、公園の入り方で一人の少年が手作りのレモネードを販売していた。", "target_word": "続く", "complexity_tier": "T6", "furigana": "きろくてきなあつさがつづくなつのごご、こうえんのいりかたでひとりのしょうねんがてづくりのレモネードをはんばいしていた。", "sentence_source": "mined"}, {"text": "雨が続く。", "target_word": "続く", "complexity_tier": "T1", "furigana": "あめがつづく。", "sentence_source": "generated"}, {"text": "いい天気が続いています。", "target_word": "続いています", "complexity_tier": "T2", "furigana": "いいてんきがつづいています。", "sentence_source": "generated"}, {"text": "この道は海まで続いている。", "target_word": "続いている", "complexity_tier": "T3", "furigana": "このみちはうみまでつづいている。", "sentence_source": "generated"}, {"text": "忙しい日が続いて、休めなかった。", "target_word": "続いて", "complexity_tier": "T3", "furigana": "いそがしいひがつづいて、やすめなかった。", "sentence_source": "generated"}, {"text": "寒さが続くなら、旅行は中止だ。", "target_word": "続く", "complexity_tier": "T4", "furigana": "さむさがつづくなら、りょこうはちゅうしだ。", "sentence_source": "generated"}, {"text": "この関係は、いつまで続くのだろうか。", "target_word": "続く", "complexity_tier": "T4", "furigana": "このかんけいは、いつまでつづくのだろうか。", "sentence_source": "generated"}, {"text": "毎日の努力が続かなければ、上達しない。", "target_word": "続かなければ", "complexity_tier": "T4", "furigana": "まいにちのどりょくがつづかなければ、じょうたつしない。", "sentence_source": "generated"}, {"text": "長く続いた戦争がやっと終わった。", "target_word": "続いた", "complexity_tier": "T3", "furigana": "ながくつづいたせんそうがやっとおわった。", "sentence_source": "generated"}, {"text": "雨の日が三日続き、川の水が増えた。", "target_word": "続き", "complexity_tier": "T3", "furigana": "あめのひがみっかつづき、かわのみずがふえた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "続き", "label": "派生"}, {"form": "続いて", "label": "活用"}, {"form": "続いた", "label": "活用"}, {"form": "続かない", "label": "活用"}], "register": "plain", "sense_fingerprint": "動詞 | 状態や動作が途切れず長く続く", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '530831ed-fe17-4cbf-8f61-bfe726a891b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39395, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "続く", "is_correct": true, "explanation": "見出し語「つづく」そのもの。"}, {"text": "つつく", "is_correct": false, "explanation": "「つつく」は「づ」が「つ」になる一拍違いの別語。"}, {"text": "綴る", "is_correct": false, "explanation": "「つづる」は最後の「く」が「る」になる一拍違いの別語。"}, {"text": "鼓", "is_correct": false, "explanation": "「つづみ」は最後の「く」が「み」になる一拍違いの別語。"}], "explanations": {"続く": "見出し語「つづく」そのもの。", "つつく": "「つつく」は「づ」が「つ」になる一拍違いの別語。", "綴る": "「つづる」は最後の「く」が「る」になる一拍違いの別語。", "鼓": "「つづみ」は最後の「く」が「み」になる一拍違いの別語。"}, "sentence_index": null, "correct_answer": "続く"}, "level_3": {"options": [{"text": "続く", "is_correct": true, "explanation": "暑さが途切れず長く続くという意味で文に合う。"}, {"text": "閉まる", "is_correct": false, "explanation": "形は合うが、暑さが閉まるという意味が合わない。"}, {"text": "割れる", "is_correct": false, "explanation": "形は合うが、暑さが割れるという意味が合わない。"}, {"text": "眠る", "is_correct": false, "explanation": "形は合うが、暑さが眠るという意味が合わない。"}], "explanations": {"続く": "暑さが途切れず長く続くという意味で文に合う。", "閉まる": "形は合うが、暑さが閉まるという意味が合わない。", "割れる": "形は合うが、暑さが割れるという意味が合わない。", "眠る": "形は合うが、暑さが眠るという意味が合わない。"}, "sentence_index": 0, "correct_answer": "続く"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "冷蔵庫の中に牛乳が続いている。", "explanation": "「続く」は物が入っている状態には使わず、空間的な連なりを表す用法に合わない。"}, {"text": "彼は毎朝、ジョギングを続いている。", "explanation": "「続く」は自動詞で「を」を取れない。続ける意味なら「続けている」。"}, {"text": "この道は海を続いている。", "explanation": "「続く」の到達点は「まで」「に」で表し、「を」では使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb16708b-b95b-48c7-a0fa-86ef1023e037') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39395, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "続く", "is_correct": true, "explanation": "見出し語「つづく」そのもの。"}, {"text": "綴り", "is_correct": false, "explanation": "「つづり」は最後の「く」が「り」になる一拍違いの別語。"}, {"text": "葛籠", "is_correct": false, "explanation": "「つづら」は最後の「く」が「ら」になる一拍違いの別語。"}, {"text": "綴る", "is_correct": false, "explanation": "「つづる」は最後の「く」が「る」になる一拍違いの別語。"}], "explanations": {"続く": "見出し語「つづく」そのもの。", "綴り": "「つづり」は最後の「く」が「り」になる一拍違いの別語。", "葛籠": "「つづら」は最後の「く」が「ら」になる一拍違いの別語。", "綴る": "「つづる」は最後の「く」が「る」になる一拍違いの別語。"}, "sentence_index": null, "correct_answer": "続く"}, "level_3": {"options": [{"text": "続く", "is_correct": true, "explanation": "関係が長く保たれるという意味で文に合う。"}, {"text": "食べる", "is_correct": false, "explanation": "形は合うが、関係を食べるという意味が合わない。"}, {"text": "光る", "is_correct": false, "explanation": "形は合うが、関係が光るという意味が合わない。"}, {"text": "閉まる", "is_correct": false, "explanation": "形は合うが、関係が閉まるという意味が合わない。"}], "explanations": {"続く": "関係が長く保たれるという意味で文に合う。", "食べる": "形は合うが、関係を食べるという意味が合わない。", "光る": "形は合うが、関係が光るという意味が合わない。", "閉まる": "形は合うが、関係が閉まるという意味が合わない。"}, "sentence_index": 6, "correct_answer": "続く"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "傘が三日続き、川の水が増えた。", "explanation": "「続く」は雨など時間的に連続する事柄に使い、傘という物には使えない。"}, {"text": "雨が三日を続き、川の水が増えた。", "explanation": "「続く」は自動詞なので期間に「を」は付かない。"}, {"text": "雨の日が冷蔵庫に続き、川の水が増えた。", "explanation": "「続く」の到達点に冷蔵庫は合わず、意味が通らない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb16708b-b95b-48c7-a0fa-86ef1023e037') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39395, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "暑い日を一週間続いている。", "corrected_sentence": "暑い日が一週間続いている。", "error_description": "「続く」は自動詞なので、主語は「を」ではなく「が」で示す。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "続く", "is_correct": true, "explanation": "文末の終止形で「雨が続く。」が成り立つ。"}, {"text": "続き", "is_correct": false, "explanation": "連用形は文を終えられず、文末では不自然。"}, {"text": "続こう", "is_correct": false, "explanation": "意志形は雨が主語では使えず、文が成り立たない。"}, {"text": "続かなければ", "is_correct": false, "explanation": "条件の形で、文末に置くと文が成り立たない。"}], "correct_form": "続く", "base_form": "続く", "form_label": "終止形", "sentence_index": 1, "explanations": {"続く": "文末の終止形で「雨が続く。」が成り立つ。", "続き": "連用形は文を終えられず、文末では不自然。", "続こう": "意志形は雨が主語では使えず、文が成り立たない。", "続かなければ": "条件の形で、文末に置くと文が成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb16708b-b95b-48c7-a0fa-86ef1023e037') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39395, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "忙しさを何日も続いて、疲れた。", "corrected_sentence": "忙しさが何日も続いて、疲れた。", "error_description": "「続く」は自動詞なので、主語は「が」で示す。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "続かなければ", "is_correct": true, "explanation": "「〜なければ、上達しない」という条件の形が合う。"}, {"text": "続く", "is_correct": false, "explanation": "終止形では読点の後に「上達しない」へ条件としてつながらない。"}, {"text": "続こう", "is_correct": false, "explanation": "意志形は主語が努力では不自然で、文が成り立たない。"}, {"text": "続いた", "is_correct": false, "explanation": "過去形で読点の後に続かず、条件にならない。"}], "correct_form": "続かなければ", "base_form": "続く", "form_label": "否定条件形", "sentence_index": 7, "explanations": {"続かなければ": "「〜なければ、上達しない」という条件の形が合う。", "続く": "終止形では読点の後に「上達しない」へ条件としてつながらない。", "続こう": "意志形は主語が努力では不自然で、文が成り立たない。", "続いた": "過去形で読点の後に続かず、条件にならない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb16708b-b95b-48c7-a0fa-86ef1023e037') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39396, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "所属を示す「の」。屋根に付いている瓦を表す。"}, {"text": "を", "is_correct": false, "explanation": "目的語の「を」。「飛ぶ」は目的語を取らないので合わない。"}, {"text": "が", "is_correct": false, "explanation": "主語の「が」。屋根が主語になると「瓦が」と重なって不自然。"}, {"text": "で", "is_correct": false, "explanation": "手段・場所の「で」。屋根で瓦を表す文にならない。"}], "correct_answer": "の", "explanations": {"の": "所属を示す「の」。屋根に付いている瓦を表す。", "を": "目的語の「を」。「飛ぶ」は目的語を取らないので合わない。", "が": "主語の「が」。屋根が主語になると「瓦が」と重なって不自然。", "で": "手段・場所の「で」。屋根で瓦を表す文にならない。"}, "error_tags": {"を": "目的語", "が": "主語", "で": "手段・場所"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '14797358-abb1-41c2-b4e0-49bf54ce91a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39396, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "変化の結果を示す「に」。「屋根にする」で、新しい屋根に変えたことを示す。"}, {"text": "と", "is_correct": false, "explanation": "並列・相手の「と」。「屋根とにしてから」では、屋根を相手とする意味にならず文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "方向の「へ」。「屋根へにしてから」では、向かう先を示す形になり文が成り立たない。"}, {"text": "から", "is_correct": false, "explanation": "起点の「から」。「屋根からにしてから」では、屋根を起点とする意味にならず合わない。"}], "correct_answer": "に", "explanations": {"に": "変化の結果を示す「に」。「屋根にする」で、新しい屋根に変えたことを示す。", "と": "並列・相手の「と」。「屋根とにしてから」では、屋根を相手とする意味にならず文が成り立たない。", "へ": "方向の「へ」。「屋根へにしてから」では、向かう先を示す形になり文が成り立たない。", "から": "起点の「から」。「屋根からにしてから」では、屋根を起点とする意味にならず合わない。"}, "error_tags": {"と": "並列・相手", "へ": "方向", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '14797358-abb1-41c2-b4e0-49bf54ce91a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39396, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "家のいちばん上の外側をカバーしているものです。", "primary_collocate": null, "pronunciation": "やね", "ipa": "jane", "syllable_count": 2, "sentences": [{"text": "雪が積もって、屋根が真っ白になりました。", "target_word": "屋根", "complexity_tier": "T3", "furigana": "雪[ゆき]が積[つ]もって、屋根[やね]が真[ま]っ白[しろ]になりました。", "sentence_source": "generated"}, {"text": "台風で屋根の瓦が飛んでしまいました。", "target_word": "屋根", "complexity_tier": "T3", "furigana": "台風[たいふう]で屋根[やね]の瓦[かわら]が飛[と]んでしまいました。", "sentence_source": "generated"}, {"text": "猫が屋根の上で昼寝をしています。", "target_word": "屋根", "complexity_tier": "T3", "furigana": "猫[ねこ]が屋根[やね]の上[うえ]で昼寝[ひるね]をしています。", "sentence_source": "generated"}, {"text": "古い家だったので、雨の日は屋根から水がもれました。", "target_word": "屋根", "complexity_tier": "T3", "furigana": "古[ふる]い家[いえ]だったので、雨[あめ]の日[ひ]は屋根[やね]から水[みず]がもれました。", "sentence_source": "generated"}, {"text": "父は屋根にのぼって、アンテナを直しました。", "target_word": "屋根", "complexity_tier": "T3", "furigana": "父[ちち]は屋根[やね]にのぼって、アンテナを直[なお]しました。", "sentence_source": "generated"}, {"text": "屋根が赤い家が、私の友だちの家です。", "target_word": "屋根", "complexity_tier": "T3", "furigana": "屋根[やね]が赤[あか]い家[いえ]が、私[わたし]の友[とも]だちの家[いえ]です。", "sentence_source": "generated"}, {"text": "夏は屋根が熱くなるので、二階の部屋が暑いです。", "target_word": "屋根", "complexity_tier": "T3", "furigana": "夏[なつ]は屋根[やね]が熱[あつ]くなるので、二階[にかい]の部屋[へや]が暑[あつ]いです。", "sentence_source": "generated"}, {"text": "新しい屋根にしてから、雨の音が小さくなりました。", "target_word": "屋根", "complexity_tier": "T3", "furigana": "新[あたら]しい屋根[やね]にしてから、雨[あめ]の音[おと]が小[ちい]さくなりました。", "sentence_source": "generated"}, {"text": "鳥が屋根にとまって、朝から鳴いています。", "target_word": "屋根", "complexity_tier": "T3", "furigana": "鳥[とり]が屋根[やね]にとまって、朝[あさ]から鳴[な]いています。", "sentence_source": "generated"}, {"text": "屋根の色を青にかえたら、家の感じが明るくなりました。", "target_word": "屋根", "complexity_tier": "T3", "furigana": "屋根[やね]の色[いろ]を青[あお]にかえたら、家[いえ]の感[かん]じが明[あか]るくなりました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "屋根", "label": "基本形"}], "register": "やさしい丁寧体", "sense_fingerprint": "家のいちばん上を外側からおおう部分", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4930162-e49e-4526-a312-ee6d7f8dd798') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39396, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "屋根", "is_correct": true, "explanation": "家の上を覆う部分で、雪が積もって白くなる文脈に合う。"}, {"text": "教科書", "is_correct": false, "explanation": "紙の本で、雪が積もって白くなる対象ではない。"}, {"text": "靴下", "is_correct": false, "explanation": "身に着ける布で、家の上に積もる雪の対象ではない。"}, {"text": "消しゴム", "is_correct": false, "explanation": "文房具で、雪が積もる対象にならない。"}], "explanations": {"屋根": "家の上を覆う部分で、雪が積もって白くなる文脈に合う。", "教科書": "紙の本で、雪が積もって白くなる対象ではない。", "靴下": "身に着ける布で、家の上に積もる雪の対象ではない。", "消しゴム": "文房具で、雪が積もる対象にならない。"}, "sentence_index": 0, "correct_answer": "屋根"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "部屋の屋根から、電球がぶら下がっています。", "explanation": "ここは〈天井〉の意味。屋根は建物の外側の上部で、部屋の中の上側には使わない。"}, {"text": "鍋の屋根を開けて、中身を確かめました。", "explanation": "ここは〈ふた〉の意味。屋根は家の上部のことで、鍋には使わない。"}, {"text": "強い雨の日は、屋根をさして駅まで歩きました。", "explanation": "ここは〈傘〉の意味。屋根は建物の一部で、人がさして歩くものではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '14797358-abb1-41c2-b4e0-49bf54ce91a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39396, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "屋根", "is_correct": true, "explanation": "家の上の外側の部分で、夏に熱くなって二階が暑くなる因果に合う。"}, {"text": "鉛筆", "is_correct": false, "explanation": "文房具で、建物の熱さの原因にならない。"}, {"text": "帽子", "is_correct": false, "explanation": "頭にかぶる布製品で、家の二階を暑くする原因にはならない。"}, {"text": "財布", "is_correct": false, "explanation": "小物入れで、部屋の暑さとは関係がない。"}], "explanations": {"屋根": "家の上の外側の部分で、夏に熱くなって二階が暑くなる因果に合う。", "鉛筆": "文房具で、建物の熱さの原因にならない。", "帽子": "頭にかぶる布製品で、家の二階を暑くする原因にはならない。", "財布": "小物入れで、部屋の暑さとは関係がない。"}, "sentence_index": 6, "correct_answer": "屋根"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "台所の屋根に、食器をしまいます。", "explanation": "ここは〈食器棚〉の意味。屋根は建物の上部を覆う部分で、食器をしまう場所ではない。"}, {"text": "部屋の屋根を白くぬりかえて、明るくしました。", "explanation": "ここは〈壁〉の意味。屋根は建物の上を覆う部分で、部屋の壁の代わりにはならない。"}, {"text": "玄関の屋根を開けて、家の中に入りました。", "explanation": "ここは〈扉〉の意味。屋根は開けて出入りする部分ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '14797358-abb1-41c2-b4e0-49bf54ce91a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39396, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "強風で屋根を瓦が飛んでいきました。", "corrected_sentence": "強風で屋根の瓦が飛んでいきました。", "error_description": "「屋根」に続く助詞が「を」になっている。「瓦」は屋根の一部なので、所属の「の」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '14797358-abb1-41c2-b4e0-49bf54ce91a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39396, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "冬は屋根に冷たくなるので、屋根裏が寒いです。", "corrected_sentence": "冬は屋根が冷たくなるので、屋根裏が寒いです。", "error_description": "「屋根」に続く助詞が「に」になっている。「冷たくなる」の主語は「が」で示すので、正しくは「が」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '14797358-abb1-41c2-b4e0-49bf54ce91a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39397, 3, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '14797358-abb1-41c2-b4e0-49bf54ce91a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39397, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "所属を示す「の」。屋根の広さがおかげの理由になる名詞を続ける。"}, {"text": "を", "is_correct": false, "explanation": "目的語の「を」。「おかげ」の前に「を」は付かない。"}, {"text": "に", "is_correct": false, "explanation": "相手・場所の「に」。「屋根におかげで」では文の形が合わない。"}, {"text": "と", "is_correct": false, "explanation": "並列・共同の「と」。屋根とおかげが並ぶ文にはならない。"}], "correct_answer": "の", "explanations": {"の": "所属を示す「の」。屋根の広さがおかげの理由になる名詞を続ける。", "を": "目的語の「を」。「おかげ」の前に「を」は付かない。", "に": "相手・場所の「に」。「屋根におかげで」では文の形が合わない。", "と": "並列・共同の「と」。屋根とおかげが並ぶ文にはならない。"}, "error_tags": {"を": "目的語", "に": "相手・場所", "と": "並列・共同"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '14797358-abb1-41c2-b4e0-49bf54ce91a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39397, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "家や建物の上部を覆い、雨や日光などを防ぐ部分。", "primary_collocate": null, "pronunciation": "やね", "ipa": "jane", "syllable_count": 2, "sentences": [{"text": "駅のホームには、雨を防ぐための屋根がついている。", "target_word": "屋根", "complexity_tier": "T3", "furigana": "駅[えき]のホームには、雨[あめ]を防[ふせ]ぐための屋根[やね]がついている。", "sentence_source": "generated"}, {"text": "強い日ざしを避けるため、バス停に屋根を取り付けた。", "target_word": "屋根", "complexity_tier": "T3", "furigana": "強[つよ]い日[ひ]ざしを避[さ]けるため、バス停[てい]に屋根[やね]を取[と]り付[つ]けた。", "sentence_source": "generated"}, {"text": "古い倉庫の屋根が、風で一部はがれてしまった。", "target_word": "屋根", "complexity_tier": "T3", "furigana": "古[ふる]い倉庫[そうこ]の屋根[やね]が、風[かぜ]で一部[いちぶ]はがれてしまった。", "sentence_source": "generated"}, {"text": "屋根のない球場では、雨が降ると試合が中止になる。", "target_word": "屋根", "complexity_tier": "T3", "furigana": "屋根[やね]のない球場[きゅうじょう]では、雨[あめ]が降[ふ]ると試合[しあい]が中止[ちゅうし]になる。", "sentence_source": "generated"}, {"text": "瓦の屋根は重いが、雨にも火にも強い。", "target_word": "屋根", "complexity_tier": "T3", "furigana": "瓦[かわら]の屋根[やね]は重[おも]いが、雨[あめ]にも火[ひ]にも強[つよ]い。", "sentence_source": "generated"}, {"text": "職人が、屋根の上で防水シートを張っている。", "target_word": "屋根", "complexity_tier": "T3", "furigana": "職人[しょくにん]が、屋根[やね]の上[うえ]で防水[ぼうすい]シートを張[は]っている。", "sentence_source": "generated"}, {"text": "屋根が傾いているので、雪が自然に滑り落ちる。", "target_word": "屋根", "complexity_tier": "T3", "furigana": "屋根[やね]が傾[かたむ]いているので、雪[ゆき]が自然[しぜん]に滑[すべ]り落[お]ちる。", "sentence_source": "generated"}, {"text": "広い屋根のおかげで、玄関先は雨の日でもぬれない。", "target_word": "屋根", "complexity_tier": "T3", "furigana": "広[ひろ]い屋根[やね]のおかげで、玄関先[げんかんさき]は雨[あめ]の日[ひ]でもぬれない。", "sentence_source": "generated"}, {"text": "市場全体が大きな屋根におおわれ、買い物客は雨でも困らない。", "target_word": "屋根", "complexity_tier": "T3", "furigana": "市場[いちば]全体[ぜんたい]が大[おお]きな屋根[やね]におおわれ、買[か]い物客[ものきゃく]は雨[あめ]でも困[こま]らない。", "sentence_source": "generated"}, {"text": "屋根を白く塗ると、夏の室内の温度が上がりにくくなる。", "target_word": "屋根", "complexity_tier": "T3", "furigana": "屋根[やね]を白[しろ]く塗[ぬ]ると、夏[なつ]の室内[しつない]の温度[おんど]が上[あ]がりにくくなる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "屋根", "label": "基本形"}], "register": "標準的な書き言葉(常体)", "sense_fingerprint": "建物の上部を覆って雨や日ざしを防ぐ部分", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 6 above tier T2: contains vocabulary far above tier T2: 滑り落ちる (Zipf 2.11)']::text[], 'a4930162-e49e-4526-a312-ee6d7f8dd798') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39397, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "屋根", "is_correct": true, "explanation": "雨や日ざしを防ぐための覆いで、「雨を防ぐための」に合う。"}, {"text": "看板", "is_correct": false, "explanation": "文字や絵を掲げるもので、雨を防ぐ目的には合わない。"}, {"text": "手すり", "is_correct": false, "explanation": "体を支える柵で、雨を防がないので合わない。"}, {"text": "時計", "is_correct": false, "explanation": "時刻を示す道具で、雨をよける役には立たない。"}], "explanations": {"屋根": "雨や日ざしを防ぐための覆いで、「雨を防ぐための」に合う。", "看板": "文字や絵を掲げるもので、雨を防ぐ目的には合わない。", "手すり": "体を支える柵で、雨を防がないので合わない。", "時計": "時刻を示す道具で、雨をよける役には立たない。"}, "sentence_index": 0, "correct_answer": "屋根"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "暑い日は、屋根をかぶって外を歩く。", "explanation": "ここは〈帽子〉の意味。屋根は建物の上部で、頭にかぶるものではない。"}, {"text": "部屋の屋根に、ランプがつるされている。", "explanation": "ここは〈天井〉の意味。屋根は建物の外側の上部で、部屋の中の上側には使わない。"}, {"text": "玄関に屋根を敷いて、くつをぬぐ。", "explanation": "ここは〈敷物〉の意味。屋根は建物の上部を覆う部分で、床に敷いて使うものではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '14797358-abb1-41c2-b4e0-49bf54ce91a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39397, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "屋根", "is_correct": true, "explanation": "屋根が傾くと雪が滑り落ちるという因果に合う。"}, {"text": "本棚", "is_correct": false, "explanation": "家具で、傾いて雪が滑り落ちる対象ではない。"}, {"text": "冷蔵庫", "is_correct": false, "explanation": "家電で、雪が滑り落ちる因果とは関係がない。"}, {"text": "水槽", "is_correct": false, "explanation": "水を入れる容器で、雪が滑り落ちる対象ではない。"}], "explanations": {"屋根": "屋根が傾くと雪が滑り落ちるという因果に合う。", "本棚": "家具で、傾いて雪が滑り落ちる対象ではない。", "冷蔵庫": "家電で、雪が滑り落ちる因果とは関係がない。", "水槽": "水を入れる容器で、雪が滑り落ちる対象ではない。"}, "sentence_index": 6, "correct_answer": "屋根"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "屋根を閉めると、客は中に入れない。", "explanation": "ここは〈門〉の意味。屋根は出入りを閉ざす部分ではない。"}, {"text": "庭の屋根を刈って、きれいに整えた。", "explanation": "ここは〈垣根〉の意味。屋根は刈り込んで整える植え込みではない。"}, {"text": "教室の屋根に、先生が今日の予定を書いた。", "explanation": "ここは〈黒板〉の意味。屋根は建物の上部を覆う部分で、文字を書いて見せるものではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '14797358-abb1-41c2-b4e0-49bf54ce91a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39397, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "ホームには、雨をさえぎるための屋根でついている。", "corrected_sentence": "ホームには、雨をさえぎるための屋根がついている。", "error_description": "「屋根」に続く助詞が「で」になっている。「ついている」の主語は「が」で示すので、正しくは「が」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '14797358-abb1-41c2-b4e0-49bf54ce91a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39397, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "屋根に傾いているため、雪が自然に滑り落ちる。", "corrected_sentence": "屋根が傾いているため、雪が自然に滑り落ちる。", "error_description": "「屋根」に続く助詞が「に」になっている。「傾いている」の主語は「が」で示すので、正しくは「が」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '14797358-abb1-41c2-b4e0-49bf54ce91a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39398, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「エアコンを設置する」の目的語を示す助詞。"}, {"text": "が", "is_correct": false, "explanation": "主語を示す助詞で、「設置する」の目的語にはならない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示すが、「エアコンへ設置する」は目的語にならず不自然。"}, {"text": "の", "is_correct": false, "explanation": "名詞をつなぐ助詞で、動詞「設置する」の前には置けない。"}], "correct_answer": "を", "explanations": {"を": "「エアコンを設置する」の目的語を示す助詞。", "が": "主語を示す助詞で、「設置する」の目的語にはならない。", "へ": "方向を示すが、「エアコンへ設置する」は目的語にならず不自然。", "の": "名詞をつなぐ助詞で、動詞「設置する」の前には置けない。"}, "error_tags": {"が": "主語", "へ": "方向", "の": "名詞修飾（動詞の前は不可）"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "撤去", "is_correct": true, "explanation": "設置の対義語。取り付けたものを取り除くこと。"}, {"text": "点検", "is_correct": false, "explanation": "状態を調べることで、設置の対義語ではない。"}, {"text": "配達", "is_correct": false, "explanation": "品物を届けることで、取り付けの反対ではない。"}, {"text": "乗車", "is_correct": false, "explanation": "車などに乗ることで、設置とは関係がない。"}], "correct_answer": "撤去", "explanations": {"撤去": "設置の対義語。取り付けたものを取り除くこと。", "点検": "状態を調べることで、設置の対義語ではない。", "配達": "品物を届けることで、取り付けの反対ではない。", "乗車": "車などに乗ることで、設置とは関係がない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '14797358-abb1-41c2-b4e0-49bf54ce91a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39398, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「火災報知器を設置しました」の目的語を示す助詞。"}, {"text": "で", "is_correct": false, "explanation": "手段や場所を示し、目的語にはならない。"}, {"text": "と", "is_correct": false, "explanation": "並列や相手を示し、設置の目的語にはならない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示し、ここでは目的語を表さない。"}], "correct_answer": "を", "explanations": {"を": "「火災報知器を設置しました」の目的語を示す助詞。", "で": "手段や場所を示し、目的語にはならない。", "と": "並列や相手を示し、設置の目的語にはならない。", "へ": "方向を示し、ここでは目的語を表さない。"}, "error_tags": {"で": "手段", "と": "並列", "へ": "方向"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "撤去", "is_correct": true, "explanation": "設置の対義語。取り付けたものを取り除くこと。"}, {"text": "通話", "is_correct": false, "explanation": "電話などで話すことで、設置とは関係がない。"}, {"text": "清掃", "is_correct": false, "explanation": "汚れを取り除いてきれいにすることで、設置の対義語とはされない。"}, {"text": "撮影", "is_correct": false, "explanation": "写真や映像を撮ることで、設置とは無関係。"}], "correct_answer": "撤去", "explanations": {"撤去": "設置の対義語。取り付けたものを取り除くこと。", "通話": "電話などで話すことで、設置とは関係がない。", "清掃": "汚れを取り除いてきれいにすることで、設置の対義語とはされない。", "撮影": "写真や映像を撮ることで、設置とは無関係。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '14797358-abb1-41c2-b4e0-49bf54ce91a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39398, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "ものを、どこかに置いたり、取り付けたりすること。", "primary_collocate": null, "pronunciation": "せっち", "ipa": "settɕi", "syllable_count": 3, "sentences": [{"text": "公園に新しいベンチを設置しました。", "target_word": "設置", "complexity_tier": "T3", "furigana": "公園[こうえん]に新[あたら]しいベンチを設置[せっち]しました。", "sentence_source": "generated"}, {"text": "教室にエアコンを設置するので、夏も涼しくなります。", "target_word": "設置", "complexity_tier": "T3", "furigana": "教室[きょうしつ]にエアコンを設置[せっち]するので、夏[なつ]も涼[すず]しくなります。", "sentence_source": "generated"}, {"text": "駅の入り口に、防犯カメラが設置されました。", "target_word": "設置", "complexity_tier": "T3", "furigana": "駅[えき]の入[い]り口[ぐち]に、防犯[ぼうはん]カメラが設置[せっち]されました。", "sentence_source": "generated"}, {"text": "工事の人が二人来てくれたので、設置は一時間で終わりました。", "target_word": "設置", "complexity_tier": "T3", "furigana": "工事[こうじ]の人[ひと]が二人[ふたり]来[き]てくれたので、設置[せっち]は一時間[いちじかん]で終[お]わりました。", "sentence_source": "generated"}, {"text": "学校の前に、横断歩道の信号を設置してほしいです。", "target_word": "設置", "complexity_tier": "T3", "furigana": "学校[がっこう]の前[まえ]に、横断歩道[おうだんほどう]の信号[しんごう]を設置[せっち]してほしいです。", "sentence_source": "generated"}, {"text": "洗濯機を設置するには、水道の近くが便利です。", "target_word": "設置", "complexity_tier": "T3", "furigana": "洗濯機[せんたくき]を設置[せっち]するには、水道[すいどう]の近[ちか]くが便利[べんり]です。", "sentence_source": "generated"}, {"text": "町のあちこちにごみ箱が設置されて、道がきれいになりました。", "target_word": "設置", "complexity_tier": "T3", "furigana": "町[まち]のあちこちにごみ箱[ばこ]が設置[せっち]されて、道[みち]がきれいになりました。", "sentence_source": "generated"}, {"text": "火事に備えて、各部屋に火災報知器を設置しました。", "target_word": "設置", "complexity_tier": "T3", "furigana": "火事[かじ]に備[そな]えて、各部屋[かくへや]に火災報知器[かさいほうちき]を設置[せっち]しました。", "sentence_source": "generated"}, {"text": "重い棚なので、設置するときは二人で運びましょう。", "target_word": "設置", "complexity_tier": "T3", "furigana": "重[おも]い棚[たな]なので、設置[せっち]するときは二人[ふたり]で運[はこ]びましょう。", "sentence_source": "generated"}, {"text": "図書館の入り口に、本を返すためのポストが設置されています。", "target_word": "設置", "complexity_tier": "T3", "furigana": "図書館[としょかん]の入[い]り口[ぐち]に、本[ほん]を返[かえ]すためのポストが設置[せっち]されています。", "sentence_source": "generated"}], "morphological_forms": [{"form": "設置する", "label": "終止形"}, {"form": "設置した", "label": "過去形"}, {"form": "設置して", "label": "て形"}, {"form": "設置される", "label": "受身形"}], "register": "やさしい丁寧体", "sense_fingerprint": "機器や設備をある場所に置いて取り付けること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 7 above tier T2: contains vocabulary far above tier T2: 火災報知器 (Zipf 2.37)']::text[], 'a4930162-e49e-4526-a312-ee6d7f8dd798') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39398, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "設置", "is_correct": true, "explanation": "「ベンチを設置しました」で、据え付けるという意味に合う。"}, {"text": "翻訳", "is_correct": false, "explanation": "「翻訳しました」は言葉を別の言語に訳すことで、ベンチには合わない。"}, {"text": "作曲", "is_correct": false, "explanation": "「作曲」は曲を作ることで、ベンチを対象にすると意味が通らない。"}, {"text": "解析", "is_correct": false, "explanation": "「解析」は詳しく分析することで、ベンチを対象にすると不自然。"}], "explanations": {"設置": "「ベンチを設置しました」で、据え付けるという意味に合う。", "翻訳": "「翻訳しました」は言葉を別の言語に訳すことで、ベンチには合わない。", "作曲": "「作曲」は曲を作ることで、ベンチを対象にすると意味が通らない。", "解析": "「解析」は詳しく分析することで、ベンチを対象にすると不自然。"}, "sentence_index": 0, "correct_answer": "設置"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "ゲームの音量を設置し直したら、ちょうどよくなった。", "explanation": "ここは〈設定〉の意味。音量などを調整する場合は設定を使い、設置は物を据え付けるときに使う。"}, {"text": "来年の行事の日程を設置する予定だ。", "explanation": "ここは〈設定〉の意味。日程を決める場合は設定を使い、設置は物に使う。"}, {"text": "新人を営業部に設置したので、来月から忙しくなる。", "explanation": "ここは〈配置〉の意味。人を部署に割り当てる場合は配置を使い、設置は物に使う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '14797358-abb1-41c2-b4e0-49bf54ce91a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39398, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "設置", "is_correct": true, "explanation": "「ごみ箱が設置されて」で、据え付けられるという意味に合う。"}, {"text": "演奏", "is_correct": false, "explanation": "楽器などを奏でることで、ごみ箱には合わない。"}, {"text": "購読", "is_correct": false, "explanation": "新聞などを定期的に読むことで、ごみ箱には合わない。"}, {"text": "採点", "is_correct": false, "explanation": "答案などに点数をつけることで、ごみ箱には合わない。"}], "explanations": {"設置": "「ごみ箱が設置されて」で、据え付けられるという意味に合う。", "演奏": "楽器などを奏でることで、ごみ箱には合わない。", "購読": "新聞などを定期的に読むことで、ごみ箱には合わない。", "採点": "答案などに点数をつけることで、ごみ箱には合わない。"}, "sentence_index": 6, "correct_answer": "設置"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "図書館は毎月、新しい本を設置している。", "explanation": "ここは〈購入〉の意味。買い入れる場合は購入を使い、設置は本の購入には使わない。"}, {"text": "入り口に、休館日のお知らせを設置した。", "explanation": "ここは〈掲示〉の意味。お知らせを人目につくよう貼り出す場合は掲示を使う。"}, {"text": "新しい方法を設置したことで、作業時間が半分になった。", "explanation": "ここは〈採用〉の意味。方法や制度を取り入れる場合は採用を使い、設置は物に使う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '14797358-abb1-41c2-b4e0-49bf54ce91a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39398, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "会場の入り口に、案内板を設置して予定だ。", "corrected_sentence": "会場の入り口に、案内板を設置する予定だ。", "error_description": "「設置して」は「予定」に続かない形で誤り。「予定」の前は辞書形の「設置する」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '14797358-abb1-41c2-b4e0-49bf54ce91a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39398, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "市は駅前に案内所を設置された。", "corrected_sentence": "市は駅前に案内所を設置した。", "error_description": "「設置された」は受身で、案内所が設置される側になる。行為者が「市」なので、能動の「設置した」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '14797358-abb1-41c2-b4e0-49bf54ce91a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39399, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「アンテナを設置する」の目的語を示す助詞。"}, {"text": "が", "is_correct": false, "explanation": "主語を示し、設置の目的語にはならない。"}, {"text": "より", "is_correct": false, "explanation": "比較を示し、ここでは目的語を表さない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示すが、「アンテナへ設置する」は目的語にならず不自然。"}], "correct_answer": "を", "explanations": {"を": "「アンテナを設置する」の目的語を示す助詞。", "が": "主語を示し、設置の目的語にはならない。", "より": "比較を示し、ここでは目的語を表さない。", "へ": "方向を示すが、「アンテナへ設置する」は目的語にならず不自然。"}, "error_tags": {"が": "主語", "より": "比較", "へ": "方向"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "撤去", "is_correct": true, "explanation": "設置の対義語。取り付けたものを取り除くこと。"}, {"text": "点検", "is_correct": false, "explanation": "状態を調べることで、設置の対義語ではない。"}, {"text": "配達", "is_correct": false, "explanation": "品物を届けることで、取り付けの反対ではない。"}, {"text": "乗車", "is_correct": false, "explanation": "車などに乗ることで、設置とは関係がない。"}], "correct_answer": "撤去", "explanations": {"撤去": "設置の対義語。取り付けたものを取り除くこと。", "点検": "状態を調べることで、設置の対義語ではない。", "配達": "品物を届けることで、取り付けの反対ではない。", "乗車": "車などに乗ることで、設置とは関係がない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '14797358-abb1-41c2-b4e0-49bf54ce91a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39399, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「街灯を設置して」の目的語を示す助詞。"}, {"text": "で", "is_correct": false, "explanation": "手段や場所を示し、目的語にはならない。"}, {"text": "と", "is_correct": false, "explanation": "並列を示し、設置の目的語にはならない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示し、目的語を表さない。"}], "correct_answer": "を", "explanations": {"を": "「街灯を設置して」の目的語を示す助詞。", "で": "手段や場所を示し、目的語にはならない。", "と": "並列を示し、設置の目的語にはならない。", "へ": "方向を示し、目的語を表さない。"}, "error_tags": {"で": "手段", "と": "並列", "へ": "方向"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "撤去", "is_correct": true, "explanation": "設置の対義語。取り付けたものを取り除くこと。"}, {"text": "清掃", "is_correct": false, "explanation": "汚れを取り除くことで、設置の対義語とはされない。"}, {"text": "撮影", "is_correct": false, "explanation": "写真や映像を撮ることで、設置とは無関係。"}, {"text": "解説", "is_correct": false, "explanation": "内容をわかりやすく説明することで、設置とは関係がない。"}], "correct_answer": "撤去", "explanations": {"撤去": "設置の対義語。取り付けたものを取り除くこと。", "清掃": "汚れを取り除くことで、設置の対義語とはされない。", "撮影": "写真や映像を撮ることで、設置とは無関係。", "解説": "内容をわかりやすく説明することで、設置とは関係がない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '14797358-abb1-41c2-b4e0-49bf54ce91a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39399, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "ある場所に物を置いたり、取り付けたりすること。", "primary_collocate": null, "pronunciation": "せっち", "ipa": "settɕi", "syllable_count": 3, "sentences": [{"text": "工場の出入り口に、非常用の消火器を設置する。", "target_word": "設置", "complexity_tier": "T3", "furigana": "工場[こうじょう]の出入[でい]り口[ぐち]に、非常用[ひじょうよう]の消火器[しょうかき]を設置[せっち]する。", "sentence_source": "generated"}, {"text": "来週、ビルの屋上にアンテナを設置する予定だ。", "target_word": "設置", "complexity_tier": "T3", "furigana": "来週[らいしゅう]、ビルの屋上[おくじょう]にアンテナを設置[せっち]する予定[よてい]だ。", "sentence_source": "generated"}, {"text": "防犯のため、駐車場に監視カメラが設置された。", "target_word": "設置", "complexity_tier": "T3", "furigana": "防犯[ぼうはん]のため、駐車場[ちゅうしゃじょう]に監視[かんし]カメラが設置[せっち]された。", "sentence_source": "generated"}, {"text": "自動販売機を設置する場合は、床の強度を確認する必要がある。", "target_word": "設置", "complexity_tier": "T3", "furigana": "自動販売機[じどうはんばいき]を設置[せっち]する場合[ばあい]は、床[ゆか]の強度[きょうど]を確認[かくにん]する必要[ひつよう]がある。", "sentence_source": "generated"}, {"text": "機械の設置に二日かかった。", "target_word": "設置", "complexity_tier": "T3", "furigana": "機械[きかい]の設置[せっち]に二日[ふつか]かかった。", "sentence_source": "generated"}, {"text": "川の近くに水位計を設置し、増水をすぐ知らせる仕組みを作った。", "target_word": "設置", "complexity_tier": "T3", "furigana": "川[かわ]の近[ちか]くに水位計[すいいけい]を設置[せっち]し、増水[ぞうすい]をすぐ知[し]らせる仕組[しく]みを作[つく]った。", "sentence_source": "generated"}, {"text": "太陽光パネルの設置には、建物の向きが大きく影響する。", "target_word": "設置", "complexity_tier": "T3", "furigana": "太陽光[たいようこう]パネルの設置[せっち]には、建物[たてもの]の向[む]きが大[おお]きく影響[えいきょう]する。", "sentence_source": "generated"}, {"text": "町は通学路に街灯を設置して、夜道の安全を高めた。", "target_word": "設置", "complexity_tier": "T3", "furigana": "町[まち]は通学路[つうがくろ]に街灯[がいとう]を設置[せっち]して、夜道[よみち]の安全[あんぜん]を高[たか]めた。", "sentence_source": "generated"}, {"text": "設置した後で位置を変えるのは大変なので、事前に図面で確認する。", "target_word": "設置", "complexity_tier": "T3", "furigana": "設置[せっち]した後[あと]で位置[いち]を変[か]えるのは大変[たいへん]なので、事前[じぜん]に図面[ずめん]で確認[かくにん]する。", "sentence_source": "generated"}, {"text": "手すりを設置したことで、高齢者も階段を安全に上り下りできるようになった。", "target_word": "設置", "complexity_tier": "T3", "furigana": "手[て]すりを設置[せっち]したことで、高齢者[こうれいしゃ]も階段[かいだん]を安全[あんぜん]に上[のぼ]り下[お]りできるようになった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "設置する", "label": "終止形"}, {"form": "設置した", "label": "過去形"}, {"form": "設置して", "label": "て形"}, {"form": "設置される", "label": "受身形"}], "register": "標準的な書き言葉(常体)", "sense_fingerprint": "装置や設備を決まった場所に据え付けること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4930162-e49e-4526-a312-ee6d7f8dd798') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39399, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "設置", "is_correct": true, "explanation": "「消火器を設置する」で、据え付けるという意味に合う。"}, {"text": "翻訳", "is_correct": false, "explanation": "言語を訳すことで、消火器には合わない。"}, {"text": "作曲", "is_correct": false, "explanation": "曲を作ることで、消火器には合わない。"}, {"text": "演奏", "is_correct": false, "explanation": "楽器などを奏でることで、消火器には合わない。"}], "explanations": {"設置": "「消火器を設置する」で、据え付けるという意味に合う。", "翻訳": "言語を訳すことで、消火器には合わない。", "作曲": "曲を作ることで、消火器には合わない。", "演奏": "楽器などを奏でることで、消火器には合わない。"}, "sentence_index": 0, "correct_answer": "設置"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "画面の明るさを設置する場合は、電源の種類を確認するとよい。", "explanation": "ここは〈設定〉の意味。明るさの調整には設定を使い、設置は物を据えるときに使う。"}, {"text": "新しい法人を設置するには、資本金が必要だ。", "explanation": "ここは〈設立〉の意味。法人や組織を新しく作る場合は設立を使い、設置は物に使う。"}, {"text": "新しい技術を設置する場合は、説明会を開く予定だ。", "explanation": "ここは〈導入〉の意味。技術や制度を取り入れる場合は導入を使い、設置は物に使う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '14797358-abb1-41c2-b4e0-49bf54ce91a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39399, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "設置", "is_correct": true, "explanation": "「太陽光パネルの設置には」で、据え付けの意味に合う。"}, {"text": "購読", "is_correct": false, "explanation": "新聞などを定期的に読むことで、パネルには合わない。"}, {"text": "採点", "is_correct": false, "explanation": "答案などに点数をつけることで、パネルには合わない。"}, {"text": "通話", "is_correct": false, "explanation": "電話で話すことで、パネルには合わない。"}], "explanations": {"設置": "「太陽光パネルの設置には」で、据え付けの意味に合う。", "購読": "新聞などを定期的に読むことで、パネルには合わない。", "採点": "答案などに点数をつけることで、パネルには合わない。", "通話": "電話で話すことで、パネルには合わない。"}, "sentence_index": 6, "correct_answer": "設置"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "新しい単語を設置したことで、検索が早くなった。", "explanation": "ここは〈登録〉の意味。項目を書き加える場合は登録を使い、設置は物に使う。"}, {"text": "入り口に注意書きを設置したことで、事故が減った。", "explanation": "ここは〈掲示〉の意味。注意書きを人目につくよう貼り出す場合は掲示を使う。"}, {"text": "新しい手順を設置したことで、ミスが減った。", "explanation": "ここは〈採用〉の意味。手順や方法を取り入れる場合は採用を使い、設置は物に使う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '14797358-abb1-41c2-b4e0-49bf54ce91a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39399, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "ビルの入り口に警報器の設置する。", "corrected_sentence": "ビルの入り口に警報器を設置する。", "error_description": "「設置する」は目的語の「を」が必要。「警報器の設置する」は誤りで、「警報器を設置する」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '14797358-abb1-41c2-b4e0-49bf54ce91a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39399, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この場所には消火器を設置ない予定だ。", "corrected_sentence": "この場所には消火器を設置しない予定だ。", "error_description": "「設置ない」は誤った活用。サ変動詞「設置する」の否定形は「設置しない」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '14797358-abb1-41c2-b4e0-49bf54ce91a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39401, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "主語を示す格助詞。「ほとんどない」の主語として「メリット」に付く「が」。"}, {"text": "を", "is_correct": false, "explanation": "対象を示すが、「メリットをほとんどない」では主語と述語が対応せず不自然。"}, {"text": "で", "is_correct": false, "explanation": "手段を示すが、「メリットでほとんどない」は文として成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示すが、「メリットへほとんどない」は意味が通らない。"}], "correct_answer": "が", "explanations": {"が": "主語を示す格助詞。「ほとんどない」の主語として「メリット」に付く「が」。", "を": "対象を示すが、「メリットをほとんどない」では主語と述語が対応せず不自然。", "で": "手段を示すが、「メリットでほとんどない」は文として成り立たない。", "へ": "方向を示すが、「メリットへほとんどない」は意味が通らない。"}, "error_tags": {"を": "対象", "で": "手段", "へ": "方向"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "デメリット", "is_correct": true, "explanation": "メリットの対義語で、不利な点という意味。"}, {"text": "郵便", "is_correct": false, "explanation": "手紙や荷物を届ける制度で、利点の対義語ではない。"}, {"text": "石鹸", "is_correct": false, "explanation": "汚れを落とす洗剤で、利点の対義語ではない。"}, {"text": "山脈", "is_correct": false, "explanation": "山が連なった地形で、利点の対義語ではない。"}], "correct_answer": "デメリット", "explanations": {"デメリット": "メリットの対義語で、不利な点という意味。", "郵便": "手紙や荷物を届ける制度で、利点の対義語ではない。", "石鹸": "汚れを落とす洗剤で、利点の対義語ではない。", "山脈": "山が連なった地形で、利点の対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca5920d4-ba89-425c-8b4e-47cfa4b9d998') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39401, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "主語を示す格助詞。「メリットがある」の「が」で、「メリット」が「ある」の主語になる。"}, {"text": "から", "is_correct": false, "explanation": "起点を示すが、「メリットからある」では存在を表す文に合わない。"}, {"text": "より", "is_correct": false, "explanation": "比較の基準を示すが、「メリットよりある」は文の意味が通らない。"}, {"text": "と", "is_correct": false, "explanation": "並列を示すが、「メリットとある」では主語として存在を表せず不自然。"}], "correct_answer": "が", "explanations": {"が": "主語を示す格助詞。「メリットがある」の「が」で、「メリット」が「ある」の主語になる。", "から": "起点を示すが、「メリットからある」では存在を表す文に合わない。", "より": "比較の基準を示すが、「メリットよりある」は文の意味が通らない。", "と": "並列を示すが、「メリットとある」では主語として存在を表せず不自然。"}, "error_tags": {"から": "起点", "より": "比較", "と": "並列"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "デメリット", "is_correct": true, "explanation": "メリットの対義語で、不利な点という意味。"}, {"text": "時計", "is_correct": false, "explanation": "時刻を示す道具で、利点の対義語ではない。"}, {"text": "海岸", "is_correct": false, "explanation": "海と陸の境目の場所で、利点の対義語ではない。"}, {"text": "食器", "is_correct": false, "explanation": "食事に使う器で、利点の対義語ではない。"}], "correct_answer": "デメリット", "explanations": {"デメリット": "メリットの対義語で、不利な点という意味。", "時計": "時刻を示す道具で、利点の対義語ではない。", "海岸": "海と陸の境目の場所で、利点の対義語ではない。", "食器": "食事に使う器で、利点の対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca5920d4-ba89-425c-8b4e-47cfa4b9d998') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39401, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "良い点や有利な点という意味で、何かをするときに得られるプラスの面を指します。", "primary_collocate": null, "pronunciation": "めりっと", "ipa": "meɾitto", "syllable_count": 4, "sentences": [{"text": "会員になるメリットが大きいので、すぐに申し込んだ。", "target_word": "メリット", "complexity_tier": "T3", "furigana": "会員[かいいん]になるメリットが大[おお]きいので、すぐに申[もう]し込[こ]んだ。", "sentence_source": "generated"}, {"text": "この契約は、私たちにとってメリットがほとんどない。", "target_word": "メリット", "complexity_tier": "T4", "furigana": "この契約[けいやく]は、私[わたし]たちにとってメリットがほとんどない。", "sentence_source": "generated"}, {"text": "値段が高くても、長く使えるならメリットがある。", "target_word": "メリット", "complexity_tier": "T3", "furigana": "値段[ねだん]が高[たか]くても、長[なが]く使[つか]えるならメリットがある。", "sentence_source": "generated"}, {"text": "両方の会社にメリットがある形で、話し合いが終わった。", "target_word": "メリット", "complexity_tier": "T4", "furigana": "両方[りょうほう]の会社[かいしゃ]にメリットがある形[かたち]で、話[はな]し合[あ]いが終[お]わった。", "sentence_source": "generated"}, {"text": "引っ越しのメリットと問題点を紙に書いて比べた。", "target_word": "メリット", "complexity_tier": "T4", "furigana": "引[ひ]っ越[こ]しのメリットと問題点[もんだいてん]を紙[かみ]に書[か]いて比[くら]べた。", "sentence_source": "generated"}, {"text": "早めに予約すると、安く泊まれるメリットがある。", "target_word": "メリット", "complexity_tier": "T3", "furigana": "早[はや]めに予約[よやく]すると、安[やす]く泊[と]まれるメリットがある。", "sentence_source": "generated"}, {"text": "何のメリットもないなら、その仕事は引き受けないつもりだ。", "target_word": "メリット", "complexity_tier": "T4", "furigana": "何[なん]のメリットもないなら、その仕事[しごと]は引[ひ]き受[う]けないつもりだ。", "sentence_source": "generated"}, {"text": "大きな工場には、一度にたくさん作れるメリットがある。", "target_word": "メリット", "complexity_tier": "T4", "furigana": "大[おお]きな工場[こうじょう]には、一度[いちど]にたくさん作[つく]れるメリットがある。", "sentence_source": "generated"}, {"text": "学生は、割引を受けられるというメリットがある。", "target_word": "メリット", "complexity_tier": "T3", "furigana": "学生[がくせい]は、割引[わりびき]を受[う]けられるというメリットがある。", "sentence_source": "generated"}, {"text": "説明を聞いて、この制度のメリットがよくわかった。", "target_word": "メリット", "complexity_tier": "T3", "furigana": "説明[せつめい]を聞[き]いて、この制度[せいど]のメリットがよくわかった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "メリット", "label": "基本形"}], "register": "中立", "sense_fingerprint": "ある行動や選択で得られる有利な点・利益", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '989c883e-1f67-4ecd-80a7-ae7c0f0d1e3d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39401, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "メリット", "is_correct": true, "explanation": "「会員になる利点」の意味で、大きいという説明に合う。"}, {"text": "写真", "is_correct": false, "explanation": "映像を紙などに残したもので、「大きい」と組み合わない。"}, {"text": "照明", "is_correct": false, "explanation": "明かりを与える器具で、会員になることの説明にならない。"}, {"text": "玄関", "is_correct": false, "explanation": "建物の出入り口で、会員になることの説明にならない。"}], "explanations": {"メリット": "「会員になる利点」の意味で、大きいという説明に合う。", "写真": "映像を紙などに残したもので、「大きい」と組み合わない。", "照明": "明かりを与える器具で、会員になることの説明にならない。", "玄関": "建物の出入り口で、会員になることの説明にならない。"}, "sentence_index": 0, "correct_answer": "メリット"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この契約のメリットは、解約料が高いことだ。", "explanation": "ここは〈デメリット〉の意味（不利な点）。解約料が高いことは利点ではないので、メリットとは合わない。"}, {"text": "ルールを破った人には、メリットとして掃除が命じられた。", "explanation": "ここは〈罰〉の意味（悪い行為への処罰）。メリットは有利な点なので、掃除を命じる罰の説明には合わない。"}, {"text": "成功のメリットは、大きな負担だった。", "explanation": "ここは〈代償〉の意味（得るために払う犠牲）。メリットは有利な点なので、負担の説明には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca5920d4-ba89-425c-8b4e-47cfa4b9d998') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39401, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "メリット", "is_correct": true, "explanation": "「何の利点もない」の意味で、仕事を引き受けない理由に合う。"}, {"text": "大工", "is_correct": false, "explanation": "建物を作る職人で、「何の〜もない」の形に合わない。"}, {"text": "植木", "is_correct": false, "explanation": "庭などに植える木で、「何の〜もない」の形に合わない。"}, {"text": "瓦", "is_correct": false, "explanation": "屋根に使う焼き物で、「何の〜もない」の形に合わない。"}], "explanations": {"メリット": "「何の利点もない」の意味で、仕事を引き受けない理由に合う。", "大工": "建物を作る職人で、「何の〜もない」の形に合わない。", "植木": "庭などに植える木で、「何の〜もない」の形に合わない。", "瓦": "屋根に使う焼き物で、「何の〜もない」の形に合わない。"}, "sentence_index": 6, "correct_answer": "メリット"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この電池のメリットは、三年ほどだ。", "explanation": "ここは〈寿命〉の意味（使える期間）。メリットは有利な点なので、使える期間の長さは指せない。"}, {"text": "来週のメリットを決めた。", "explanation": "ここは〈予定〉の意味。メリットは有利な点なので、決める対象にはならない。"}, {"text": "ピアノのメリットを毎日した。", "explanation": "ここは〈練習〉の意味。メリットは有利な点で、毎日行う活動の名前にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca5920d4-ba89-425c-8b4e-47cfa4b9d998') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39401, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この機械には、長く使えるメリットをある。", "corrected_sentence": "この機械には、長く使えるメリットがある。", "error_description": "「ある」は主語に「が」を取るので、「メリットがある」が正しい。「メリットをある」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca5920d4-ba89-425c-8b4e-47cfa4b9d998') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39401, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この薬には、副作用が少ないメリットがする。", "corrected_sentence": "この薬には、副作用が少ないメリットがある。", "error_description": "「メリットがある」の「ある」を「する」にしたのは誤り。「メリットがする」は言わないので、「ある」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca5920d4-ba89-425c-8b4e-47cfa4b9d998') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39402, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「黄色を組み合わせる」で目的語を示す。"}, {"text": "が", "is_correct": false, "explanation": "「黄色が組み合わせます」は主語と動詞が合わず非文になる。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表し、目的語にはならない。"}, {"text": "の", "is_correct": false, "explanation": "「黄色の組み合わせます」は名詞をつなぐ「の」が動詞に続き非文になる。"}], "correct_answer": "を", "explanations": {"を": "「黄色を組み合わせる」で目的語を示す。", "が": "「黄色が組み合わせます」は主語と動詞が合わず非文になる。", "へ": "「へ」は方向を表し、目的語にはならない。", "の": "「黄色の組み合わせます」は名詞をつなぐ「の」が動詞に続き非文になる。"}, "error_tags": {"が": "subject_for_object", "へ": "direction_misuse", "の": "noun_link_before_verb"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "分ける", "is_correct": true, "explanation": "一つに合わせることの反対で、ばらばらにすること。"}, {"text": "重ねる", "is_correct": false, "explanation": "合わせる意味に近く、反対ではない。"}, {"text": "繋ぐ", "is_correct": false, "explanation": "合わせる意味に近く、反対ではない。"}, {"text": "加える", "is_correct": false, "explanation": "合わせる意味に近く、反対ではない。"}], "correct_answer": "分ける", "explanations": {"分ける": "一つに合わせることの反対で、ばらばらにすること。", "重ねる": "合わせる意味に近く、反対ではない。", "繋ぐ": "合わせる意味に近く、反対ではない。", "加える": "合わせる意味に近く、反対ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '377190a8-931a-4215-8d4e-a3c1635395f0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39402, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「組み合わせを考える」で目的語を示す。"}, {"text": "が", "is_correct": false, "explanation": "「組み合わせが考えています」は主語と動詞が合わず非文になる。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表し、「考える」の目的語にならない。"}, {"text": "の", "is_correct": false, "explanation": "「組み合わせの考えています」は名詞が動詞に続かず非文になる。"}], "correct_answer": "を", "explanations": {"を": "「組み合わせを考える」で目的語を示す。", "が": "「組み合わせが考えています」は主語と動詞が合わず非文になる。", "へ": "「へ」は方向を表し、「考える」の目的語にならない。", "の": "「組み合わせの考えています」は名詞が動詞に続かず非文になる。"}, "error_tags": {"が": "subject_for_object", "へ": "direction_misuse", "の": "noun_link_before_verb"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "引き離す", "is_correct": true, "explanation": "合わせたものを離すので反対の意味になる。"}, {"text": "混ぜる", "is_correct": false, "explanation": "合わせる意味に近く、反対ではない。"}, {"text": "束ねる", "is_correct": false, "explanation": "一つにまとめる意味で近く、反対ではない。"}, {"text": "足す", "is_correct": false, "explanation": "合わせる意味に近く、反対ではない。"}], "correct_answer": "引き離す", "explanations": {"引き離す": "合わせたものを離すので反対の意味になる。", "混ぜる": "合わせる意味に近く、反対ではない。", "束ねる": "一つにまとめる意味で近く、反対ではない。", "足す": "合わせる意味に近く、反対ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '377190a8-931a-4215-8d4e-a3c1635395f0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39402, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "二つ以上のものを一つに合わせる。", "primary_collocate": null, "pronunciation": "くみあわせる", "ipa": "kɯmiawaseɾɯ", "syllable_count": 6, "sentences": [{"text": "ブロックを組み合わせて家を作る。", "target_word": "組み合わせて", "complexity_tier": "T3", "furigana": "ブロックを組[く]み合[あ]わせて家[いえ]を作[つく]る。", "sentence_source": "generated"}, {"text": "赤と黄色を組み合わせます。", "target_word": "組み合わせます", "complexity_tier": "T2", "furigana": "赤[あか]と黄色[きいろ]を組[く]み合[あ]わせます。", "sentence_source": "generated"}, {"text": "数字を組み合わせてパスワードを作った。", "target_word": "組み合わせて", "complexity_tier": "T3", "furigana": "数字[すうじ]を組[く]み合[あ]わせてパスワードを作[つく]った。", "sentence_source": "generated"}, {"text": "板を組み合わせた箱です。", "target_word": "組み合わせた", "complexity_tier": "T2", "furigana": "板[いた]を組[く]み合[あ]わせた箱[はこ]です。", "sentence_source": "generated"}, {"text": "好きな具を組み合わせられます。", "target_word": "組み合わせられます", "complexity_tier": "T3", "furigana": "好[す]きな具[ぐ]を組[く]み合[あ]わせられます。", "sentence_source": "generated"}, {"text": "二つの案を組み合わせてみよう。", "target_word": "組み合わせて", "complexity_tier": "T3", "furigana": "二[ふた]つの案[あん]を組[く]み合[あ]わせてみよう。", "sentence_source": "generated"}, {"text": "この組み合わせは悪くない。", "target_word": "組み合わせ", "complexity_tier": "T2", "furigana": "この組[く]み合[あ]わせは悪[わる]くない。", "sentence_source": "generated"}, {"text": "色の組み合わせを考えています。", "target_word": "組み合わせ", "complexity_tier": "T3", "furigana": "色[いろ]の組[く]み合[あ]わせを考[かんが]えています。", "sentence_source": "generated"}, {"text": "組み合わせる前に、形を確認する。", "target_word": "組み合わせる", "complexity_tier": "T3", "furigana": "組[く]み合[あ]わせる前[まえ]に、形[かたち]を確認[かくにん]する。", "sentence_source": "generated"}, {"text": "先生は言葉を組み合わせて文を作らせた。", "target_word": "組み合わせて", "complexity_tier": "T4", "furigana": "先生[せんせい]は言葉[ことば]を組[く]み合[あ]わせて文[ぶん]を作[つく]らせた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "組み合わせます", "label": "活用"}, {"form": "組み合わせて", "label": "活用"}, {"form": "組み合わせた", "label": "活用"}, {"form": "組み合わせ", "label": "派生"}], "register": "plain", "sense_fingerprint": "動詞 | 二つ以上を一つに合わせる", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c382759b-e86d-4137-9cba-73f76c343de2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39402, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "組み合わせて", "is_correct": true, "explanation": "ブロックを合わせて家を作るという意味に合う。"}, {"text": "食べて", "is_correct": false, "explanation": "形は合うが、ブロックを食べて家は作れず意味が合わない。"}, {"text": "読んで", "is_correct": false, "explanation": "形は合うが、ブロックは読むものではなく意味が合わない。"}, {"text": "飲んで", "is_correct": false, "explanation": "形は合うが、ブロックは飲めず意味が合わない。"}], "explanations": {"組み合わせて": "ブロックを合わせて家を作るという意味に合う。", "食べて": "形は合うが、ブロックを食べて家は作れず意味が合わない。", "読んで": "形は合うが、ブロックは読むものではなく意味が合わない。", "飲んで": "形は合うが、ブロックは飲めず意味が合わない。"}, "sentence_index": 0, "correct_answer": "組み合わせて"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "約束を組み合わせた箱です。", "explanation": "「約束」は合わせて箱という物を作れるものではなく、「組み合わせる」の対象として意味が合わない。"}, {"text": "朝を組み合わせた箱です。", "explanation": "「朝」は時間で、物を合わせる「組み合わせる」の対象にならない。"}, {"text": "病気を組み合わせた箱です。", "explanation": "「病気」は合わせて箱にできるものではなく、意味が合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '377190a8-931a-4215-8d4e-a3c1635395f0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39402, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "組み合わせ", "is_correct": true, "explanation": "合わせ方を評価する文で、意味が合う。"}, {"text": "昨日", "is_correct": false, "explanation": "「この昨日」とは言えず、文が成り立たない。"}, {"text": "来週", "is_correct": false, "explanation": "「この来週」とは言えず、文が成り立たない。"}, {"text": "明日", "is_correct": false, "explanation": "「この明日」とは言えず、文が成り立たない。"}], "explanations": {"組み合わせ": "合わせ方を評価する文で、意味が合う。", "昨日": "「この昨日」とは言えず、文が成り立たない。", "来週": "「この来週」とは言えず、文が成り立たない。", "明日": "「この明日」とは言えず、文が成り立たない。"}, "sentence_index": 6, "correct_answer": "組み合わせ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "先生は風邪を組み合わせて文を作らせた。", "explanation": "「風邪」は合わせて一つにできるものではなく、「組み合わせる」の対象にならない。"}, {"text": "先生は昨日を組み合わせて文を作らせた。", "explanation": "「昨日」は過ぎた日で、合わせて一つにできるものではなく意味が合わない。"}, {"text": "先生は黒板を組み合わせて廊下を歩かせた。", "explanation": "「組み合わせる」は黒板を使って人を歩かせる意味にならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '377190a8-931a-4215-8d4e-a3c1635395f0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39402, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "板が組み合わせて箱を作る。", "corrected_sentence": "板を組み合わせて箱を作る。", "error_description": "「組み合わせる」の目的語には「を」を使う。「が」は誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "組み合わせます", "is_correct": true, "explanation": "文末の丁寧な形で、文に合う。"}, {"text": "組み合わせながら", "is_correct": false, "explanation": "「ながら」は後に別の動作が続く形で、文末には置けない。"}, {"text": "組み合わせれば", "is_correct": false, "explanation": "条件を表す形で、文末にならない。"}, {"text": "組み合わせ", "is_correct": false, "explanation": "連用形のままでは文が終わらない。"}], "correct_form": "組み合わせます", "base_form": "組み合わせる", "form_label": "ます形", "sentence_index": 1, "explanations": {"組み合わせます": "文末の丁寧な形で、文に合う。", "組み合わせながら": "「ながら」は後に別の動作が続く形で、文末には置けない。", "組み合わせれば": "条件を表す形で、文末にならない。", "組み合わせ": "連用形のままでは文が終わらない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '377190a8-931a-4215-8d4e-a3c1635395f0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
