INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39403, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「色を組み合わせる」で目的語を示す。"}, {"text": "が", "is_correct": false, "explanation": "「色が組み合わせて」は後の「作った」と主語が合わず非文になる。"}, {"text": "へ", "is_correct": false, "explanation": "「色へ」は方向を表し、目的語として働けない。"}, {"text": "の", "is_correct": false, "explanation": "「色の組み合わせて」は名詞をつなぐ「の」が動詞に続き非文になる。"}], "correct_answer": "を", "explanations": {"を": "「色を組み合わせる」で目的語を示す。", "が": "「色が組み合わせて」は後の「作った」と主語が合わず非文になる。", "へ": "「色へ」は方向を表し、目的語として働けない。", "の": "「色の組み合わせて」は名詞をつなぐ「の」が動詞に続き非文になる。"}, "error_tags": {"が": "subject_for_object", "へ": "direction_misuse", "の": "noun_link_before_verb"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "切り離す", "is_correct": true, "explanation": "一つにまとめたものを分けるので反対の意味になる。"}, {"text": "混ぜる", "is_correct": false, "explanation": "合わせる意味で近く、反対ではない。"}, {"text": "重ねる", "is_correct": false, "explanation": "合わせる意味に近く、反対ではない。"}, {"text": "結びつける", "is_correct": false, "explanation": "一つにする意味で近く、反対ではない。"}], "correct_answer": "切り離す", "explanations": {"切り離す": "一つにまとめたものを分けるので反対の意味になる。", "混ぜる": "合わせる意味で近く、反対ではない。", "重ねる": "合わせる意味に近く、反対ではない。", "結びつける": "一つにする意味で近く、反対ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '377190a8-931a-4215-8d4e-a3c1635395f0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39403, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「スープの組み合わせ」と名詞をつなぐ。"}, {"text": "を", "is_correct": false, "explanation": "「スープを組み合わせが」は名詞の前で目的語にならず非文になる。"}, {"text": "に", "is_correct": false, "explanation": "「スープに組み合わせが」は意味が通らない。"}, {"text": "へ", "is_correct": false, "explanation": "「スープへ組み合わせが」は方向を表し、ここでは成り立たない。"}], "correct_answer": "の", "explanations": {"の": "「スープの組み合わせ」と名詞をつなぐ。", "を": "「スープを組み合わせが」は名詞の前で目的語にならず非文になる。", "に": "「スープに組み合わせが」は意味が通らない。", "へ": "「スープへ組み合わせが」は方向を表し、ここでは成り立たない。"}, "error_tags": {"を": "object_marker_before_noun", "に": "wrong_case_noun_link", "へ": "direction_misuse"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "分解する", "is_correct": true, "explanation": "一つにまとめたものをばらばらにするので反対の意味になる。"}, {"text": "合わせる", "is_correct": false, "explanation": "一つにする意味で近く、反対ではない。"}, {"text": "並べる", "is_correct": false, "explanation": "反対の関係ではなく、合わせる意味とも別の語。"}, {"text": "つなぐ", "is_correct": false, "explanation": "合わせる意味で近く、反対ではない。"}], "correct_answer": "分解する", "explanations": {"分解する": "一つにまとめたものをばらばらにするので反対の意味になる。", "合わせる": "一つにする意味で近く、反対ではない。", "並べる": "反対の関係ではなく、合わせる意味とも別の語。", "つなぐ": "合わせる意味で近く、反対ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '377190a8-931a-4215-8d4e-a3c1635395f0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39403, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "複数のものを合わせて、一つのまとまりにする。", "primary_collocate": null, "pronunciation": "くみあわせる", "ipa": "kɯmiawaseɾɯ", "syllable_count": 6, "sentences": [{"text": "具体的には、無垢材の家具と白壁の組み合わせ、あるいは間接照明による陰影の演出などが効果的です。", "target_word": "組み合わせ", "complexity_tier": "T6", "furigana": "具体的[ぐたいてき]には、無垢材[むくざい]の家具[かぐ]と白壁[しろかべ]の組[く]み合[あ]わせ、あるいは間接照明[かんせつしょうめい]による陰影[いんえい]の演出[えんしゅつ]などが効果的[こうかてき]です。", "sentence_source": "mined"}, {"text": "色を組み合わせて、新しい服を作った。", "target_word": "組み合わせて", "complexity_tier": "T3", "furigana": "色[いろ]を組[く]み合[あ]わせて、新[あたら]しい服[ふく]を作[つく]った。", "sentence_source": "generated"}, {"text": "この組み合わせはとても人気です。", "target_word": "組み合わせ", "complexity_tier": "T2", "furigana": "この組[く]み合[あ]わせはとても人気[にんき]です。", "sentence_source": "generated"}, {"text": "異なる素材を組み合わせると、面白い効果が出ます。", "target_word": "組み合わせる", "complexity_tier": "T4", "furigana": "異[こと]なる素材[そざい]を組[く]み合[あ]わせると、面白[おもしろ]い効果[こうか]が出[で]ます。", "sentence_source": "generated"}, {"text": "白と青を組み合わせます。", "target_word": "組み合わせます", "complexity_tier": "T2", "furigana": "白[しろ]と青[あお]を組[く]み合[あ]わせます。", "sentence_source": "generated"}, {"text": "いろいろな料理を組み合わせたセットがある。", "target_word": "組み合わせた", "complexity_tier": "T3", "furigana": "いろいろな料理[りょうり]を組[く]み合[あ]わせたセットがある。", "sentence_source": "generated"}, {"text": "音楽と映像を組み合わせた作品を見た。", "target_word": "組み合わせた", "complexity_tier": "T3", "furigana": "音楽[おんがく]と映像[えいぞう]を組[く]み合[あ]わせた作品[さくひん]を見[み]た。", "sentence_source": "generated"}, {"text": "パンとスープの組み合わせが好きです。", "target_word": "組み合わせ", "complexity_tier": "T2", "furigana": "パンとスープの組[く]み合[あ]わせが好[す]きです。", "sentence_source": "generated"}, {"text": "二つの方法を組み合わせれば、時間が短くなる。", "target_word": "組み合わせれば", "complexity_tier": "T4", "furigana": "二[ふた]つの方法[ほうほう]を組[く]み合[あ]わせれば、時間[じかん]が短[みじか]くなる。", "sentence_source": "generated"}, {"text": "部品を自由に組み合わせられるおもちゃです。", "target_word": "組み合わせられる", "complexity_tier": "T3", "furigana": "部品[ぶひん]を自由[じゆう]に組[く]み合[あ]わせられるおもちゃです。", "sentence_source": "generated"}], "morphological_forms": [{"form": "組み合わせます", "label": "活用"}, {"form": "組み合わせた", "label": "活用"}, {"form": "組み合わせて", "label": "活用"}, {"form": "組み合わせ", "label": "派生"}], "register": "plain", "sense_fingerprint": "動詞 | 複数のものを一つにまとめて合わせる", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c382759b-e86d-4137-9cba-73f76c343de2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39403, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "組み合わせ", "is_correct": true, "explanation": "家具と白壁を合わせることを表し、文脈に合う。"}, {"text": "欠席", "is_correct": false, "explanation": "形は合うが、家具と白壁の関係として意味が合わない。"}, {"text": "年齢", "is_correct": false, "explanation": "形は合うが、家具と白壁には使えず意味が合わない。"}, {"text": "天気", "is_correct": false, "explanation": "形は合うが、家具と白壁の演出という文脈に意味が合わない。"}], "explanations": {"組み合わせ": "家具と白壁を合わせることを表し、文脈に合う。", "欠席": "形は合うが、家具と白壁の関係として意味が合わない。", "年齢": "形は合うが、家具と白壁には使えず意味が合わない。", "天気": "形は合うが、家具と白壁の演出という文脈に意味が合わない。"}, "sentence_index": 0, "correct_answer": "組み合わせ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "駅で友達を組み合わせて、一緒に帰った。", "explanation": "「組み合わせる」は物を一つに合わせる意味で、人と会う意味には使えない。"}, {"text": "風を組み合わせて、窓を閉めた。", "explanation": "「風」は手で合わせて一つにできるものではなく、「組み合わせる」の対象にならない。"}, {"text": "水を組み合わせて、全部飲んだ。", "explanation": "「組み合わせる」は飲む動作を表さず、意味が合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '377190a8-931a-4215-8d4e-a3c1635395f0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39403, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "組み合わせた", "is_correct": true, "explanation": "音楽と映像を合わせた作品という意味に合う。"}, {"text": "洗った", "is_correct": false, "explanation": "形は合うが、音楽と映像は洗えるものではなく意味が合わない。"}, {"text": "忘れた", "is_correct": false, "explanation": "形は合うが、音楽と映像を忘れた作品では意味が合わない。"}, {"text": "食べた", "is_correct": false, "explanation": "形は合うが、音楽と映像は食べられず意味が合わない。"}], "explanations": {"組み合わせた": "音楽と映像を合わせた作品という意味に合う。", "洗った": "形は合うが、音楽と映像は洗えるものではなく意味が合わない。", "忘れた": "形は合うが、音楽と映像を忘れた作品では意味が合わない。", "食べた": "形は合うが、音楽と映像は食べられず意味が合わない。"}, "sentence_index": 6, "correct_answer": "組み合わせた"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "ボールを遠くまで組み合わせられる選手です。", "explanation": "「組み合わせる」は物を合わせる意味で、ボールを遠くへ飛ばす意味にはならない。"}, {"text": "雨を自由に組み合わせられる傘です。", "explanation": "「組み合わせる」の対象は合わせられる物で、雨は対象にならない。"}, {"text": "昨日を自由に組み合わせられるカレンダーです。", "explanation": "「昨日」は過ぎた日で、合わせて一つにできる物ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '377190a8-931a-4215-8d4e-a3c1635395f0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39403, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "色が組み合わせて服を作った。", "corrected_sentence": "色を組み合わせて服を作った。", "error_description": "「組み合わせる」の目的語には「を」を使う。「が」は誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "組み合わせて", "is_correct": true, "explanation": "動作をつなぐて形で、文に合う。"}, {"text": "組み合わせれば", "is_correct": false, "explanation": "条件を表す形で、「作った」と続けると意味が合わない。"}, {"text": "組み合わせよう", "is_correct": false, "explanation": "意志を表す形で、過去の文に合わない。"}, {"text": "組み合わせたい", "is_correct": false, "explanation": "願望を表す形で、「、作った」にはつながらない。"}], "correct_form": "組み合わせて", "base_form": "組み合わせる", "form_label": "て形", "sentence_index": 1, "explanations": {"組み合わせて": "動作をつなぐて形で、文に合う。", "組み合わせれば": "条件を表す形で、「作った」と続けると意味が合わない。", "組み合わせよう": "意志を表す形で、過去の文に合わない。", "組み合わせたい": "願望を表す形で、「、作った」にはつながらない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '377190a8-931a-4215-8d4e-a3c1635395f0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39403, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "いろいろな料理を組み合わせったセットがある。", "corrected_sentence": "いろいろな料理を組み合わせたセットがある。", "error_description": "「組み合わせる」は一段動詞なので、た形は「組み合わせた」。「組み合わせった」は誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "組み合わせ", "is_correct": true, "explanation": "名詞形で、「パンとスープの」に続けて「が」を取れる。"}, {"text": "組み合わせる", "is_correct": false, "explanation": "動詞の終止形で、「の」の後の名詞の位置に合わない。"}, {"text": "組み合わせて", "is_correct": false, "explanation": "て形で、「が好きです」につながらない。"}, {"text": "組み合わせた", "is_correct": false, "explanation": "過去形で、「が」の前の名詞の位置に合わない。"}], "correct_form": "組み合わせ", "base_form": "組み合わせる", "form_label": "連用形（名詞形）", "sentence_index": 7, "explanations": {"組み合わせ": "名詞形で、「パンとスープの」に続けて「が」を取れる。", "組み合わせる": "動詞の終止形で、「の」の後の名詞の位置に合わない。", "組み合わせて": "て形で、「が好きです」につながらない。", "組み合わせた": "過去形で、「が」の前の名詞の位置に合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '377190a8-931a-4215-8d4e-a3c1635395f0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
