INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39404, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "空のようすのことです。晴れや雨などがあります。", "primary_collocate": null, "pronunciation": "てんき", "ipa": "teŋki", "syllable_count": 3, "sentences": [{"text": "今日はいい天気なので、公園で遊びます。", "target_word": "天気", "complexity_tier": "T3", "furigana": "今日[きょう]はいい天気[てんき]なので、公園[こうえん]で遊[あそ]びます。", "sentence_source": "generated"}, {"text": "天気がいいから、お弁当を持って出かけましょう。", "target_word": "天気", "complexity_tier": "T3", "furigana": "天気[てんき]がいいから、お弁当[べんとう]を持[も]って出[で]かけましょう。", "sentence_source": "generated"}, {"text": "天気が悪い日は、外で遊べないので、家で本を読みます。", "target_word": "天気", "complexity_tier": "T3", "furigana": "天気[てんき]が悪い日は、外で遊べないので、家で本を読みます。", "sentence_source": "generated"}, {"text": "きのうは天気がよかったので、洗濯をしました。", "target_word": "天気", "complexity_tier": "T3", "furigana": "きのうは天気[てんき]がよかったので、洗濯[せんたく]をしました。", "sentence_source": "generated"}, {"text": "明日の天気は晴れのち曇りです。", "target_word": "天気", "complexity_tier": "T3", "furigana": "明日[あした]の天気[てんき]は晴[は]れのち曇[くも]りです。", "sentence_source": "generated"}, {"text": "天気がよくなったら、みんなで山へ行きたいです。", "target_word": "天気", "complexity_tier": "T3", "furigana": "天気[てんき]がよくなったら、みんなで山[やま]へ行[い]きたいです。", "sentence_source": "generated"}, {"text": "スマホで天気を調べてから、家を出ました。", "target_word": "天気", "complexity_tier": "T3", "furigana": "スマホで天気[てんき]を調[しら]べてから、家[いえ]を出[で]ました。", "sentence_source": "generated"}, {"text": "今日は天気が悪いので、傘を持っていきます。", "target_word": "天気", "complexity_tier": "T3", "furigana": "今日[きょう]は天気[てんき]が悪[わる]いので、傘[かさ]を持[も]っていきます。", "sentence_source": "generated"}, {"text": "天気のいい日曜日に、海へ行きました。", "target_word": "天気", "complexity_tier": "T3", "furigana": "天気[てんき]のいい日曜日[にちようび]に、海[うみ]へ行[い]きました。", "sentence_source": "generated"}, {"text": "天気が変わって、急に雨が降り出しました。", "target_word": "天気", "complexity_tier": "T3", "furigana": "天気[てんき]が変[か]わって、急[きゅう]に雨[あめ]が降[ふ]り出[だ]しました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "天気", "label": "名詞形"}], "register": "polite", "sense_fingerprint": "天気:晴れ・雨など空のようす", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '636da3c2-221b-40c9-84b6-330f2c60b543') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39404, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "天気", "is_correct": true, "explanation": "「いい天気」の「天気」。公園で遊ぶ理由になる空の状態を表す唯一の語。"}, {"text": "雨", "is_correct": false, "explanation": "降る水のこと。「いい雨なので公園で遊ぶ」は理由として不自然で、空欄に入らない。"}, {"text": "霧", "is_correct": false, "explanation": "視界を覆う水滴のこと。「いい霧なので公園で遊ぶ」は理由として成り立たない。"}, {"text": "雷", "is_correct": false, "explanation": "鳴る放電現象のこと。「いい雷なので公園で遊ぶ」は理由として成り立たない。"}], "explanations": {"天気": "「いい天気」の「天気」。公園で遊ぶ理由になる空の状態を表す唯一の語。", "雨": "降る水のこと。「いい雨なので公園で遊ぶ」は理由として不自然で、空欄に入らない。", "霧": "視界を覆う水滴のこと。「いい霧なので公園で遊ぶ」は理由として成り立たない。", "雷": "鳴る放電現象のこと。「いい雷なので公園で遊ぶ」は理由として成り立たない。"}, "sentence_index": 0, "correct_answer": "天気"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "真冬は天気がひどく低く、水道管が凍った。", "explanation": "ここは〈気温〉の意味。天気は空のようすを指し、温度の低さは言えないので合わない。"}, {"text": "彼女は天気で、いつも周りを笑わせる。", "explanation": "ここは〈天然〉の意味。素直で少し抜けた人柄を表す語で、天気は空のようすなので人には使えない。"}, {"text": "梅雨になると天気が高く、洗濯物が乾かない。", "explanation": "ここは〈湿度〉の意味。空気の湿り具合の高さは天気では言えないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26f64f78-ef67-4239-8452-c55ac5095b65') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39404, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "天気", "is_correct": true, "explanation": "「天気を調べて」の「天気」。スマホで調べる対象として自然な唯一の語。"}, {"text": "歌声", "is_correct": false, "explanation": "歌う声のこと。「歌声を調べてから」は成り立たず、空欄に入らない。"}, {"text": "笑顔", "is_correct": false, "explanation": "笑っている顔のこと。「笑顔を調べてから」は成り立たず、空欄に入らない。"}, {"text": "足音", "is_correct": false, "explanation": "歩くときの音のこと。「足音を調べてから」は成り立たず、空欄に入らない。"}], "explanations": {"天気": "「天気を調べて」の「天気」。スマホで調べる対象として自然な唯一の語。", "歌声": "歌う声のこと。「歌声を調べてから」は成り立たず、空欄に入らない。", "笑顔": "笑っている顔のこと。「笑顔を調べてから」は成り立たず、空欄に入らない。", "足音": "歩くときの音のこと。「足音を調べてから」は成り立たず、空欄に入らない。"}, "sentence_index": 6, "correct_answer": "天気"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "天気が急に下がると、頭が重くなる人が多い。", "explanation": "ここは〈気圧〉の意味。天気は空のようすで、圧力が下がるとは言えないので合わない。"}, {"text": "彼は天気で、一度聞けばすぐ覚えてしまう。", "explanation": "ここは〈天才〉の意味。人の才能は天才で表す。天気は空のようすなので人には使えない。"}, {"text": "彼女は絵を描くことが天気だと思っている。", "explanation": "ここは〈天職〉の意味。仕事や活動への適性は天職で表す。天気は空のようすなので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26f64f78-ef67-4239-8452-c55ac5095b65') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39404, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "天気をいい日は、窓を開けて部屋の空気を入れ替えます。", "corrected_sentence": "天気がいい日は、窓を開けて部屋の空気を入れ替えます。", "error_description": "「天気」が「いい」の主語なので助詞は「が」が正しい。「を」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26f64f78-ef67-4239-8452-c55ac5095b65') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
