INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39405, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "空の状態。気温や湿度、風、雲、降水など、その地域の大気の様子。", "primary_collocate": null, "pronunciation": "てんき", "ipa": "teŋki", "syllable_count": 3, "sentences": [{"text": "毎朝の天気予報を確認し、気温や湿度に合わせて水を調整する。", "target_word": "天気", "complexity_tier": "T3", "furigana": "毎朝[まいあさ]の天気[てんき]予報[よほう]を確認[かくにん]し、気温[きおん]や湿度[しつど]に合[あ]わせて水[みず]を調整[ちょうせい]する。", "sentence_source": "mined"}, {"text": "山の天気は変わりやすいので、雨具を必ず持って登る。", "target_word": "天気", "complexity_tier": "T3", "furigana": "山[やま]の天気[てんき]は変[か]わりやすいので、雨具[あまぐ]を必[かなら]ず持[も]って登[のぼ]る。", "sentence_source": "generated"}, {"text": "明日の天気が悪ければ、運動会は来週に延期される。", "target_word": "天気", "complexity_tier": "T3", "furigana": "明日[あした]の天気[てんき]が悪[わる]ければ、運動会[うんどうかい]は来週[らいしゅう]に延期[えんき]される。", "sentence_source": "generated"}, {"text": "天気がよいうちに、洗濯物を全部干してしまおう。", "target_word": "天気", "complexity_tier": "T3", "furigana": "天気[てんき]がよいうちに、洗濯物[せんたくもの]を全部[ぜんぶ]干[ほ]してしまおう。", "sentence_source": "generated"}, {"text": "地域によって天気が違うため、旅行の前に各地の予報を調べた。", "target_word": "天気", "complexity_tier": "T3", "furigana": "地域[ちいき]によって天気[てんき]が違[ちが]うため、旅行[りょこう]の前[まえ]に各地[かくち]の予報[よほう]を調[しら]べた。", "sentence_source": "generated"}, {"text": "今日は朝から天気が崩れて、午後には強い風が吹いた。", "target_word": "天気", "complexity_tier": "T3", "furigana": "今日[きょう]は朝[あさ]から天気[てんき]が崩[くず]れて、午後[ごご]には強[つよ]い風[かぜ]が吹[ふ]いた。", "sentence_source": "generated"}, {"text": "この季節は天気が安定せず、晴れても急に雨が降る。", "target_word": "天気", "complexity_tier": "T3", "furigana": "この季節[きせつ]は天気[てんき]が安定[あんてい]せず、晴[は]れても急[きゅう]に雨[あめ]が降[ふ]る。", "sentence_source": "generated"}, {"text": "天気が回復するまで、船は港で待つことになった。", "target_word": "天気", "complexity_tier": "T3", "furigana": "天気[てんき]が回復[かいふく]するまで、船[ふね]は港[みなと]で待[ま]つことになった。", "sentence_source": "generated"}, {"text": "天気の悪い日が続いたせいで、野菜の値段が上がっている。", "target_word": "天気", "complexity_tier": "T3", "furigana": "天気[てんき]の悪[わる]い日[ひ]が続[つづ]いたせいで、野菜[やさい]の値段[ねだん]が上[あ]がっている。", "sentence_source": "generated"}, {"text": "彼は天気の変化に敏感で、雨が降る前に頭が痛くなる。", "target_word": "天気", "complexity_tier": "T3", "furigana": "彼[かれ]は天気[てんき]の変化[へんか]に敏感[びんかん]で、雨[あめ]が降[ふ]る前[まえ]に頭[あたま]が痛[いた]くなる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "天気", "label": "名詞形"}], "register": "neutral", "sense_fingerprint": "天気:その時その場所の大気の状態(晴雨・気温・風など)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 1 above tier T2: contains vocabulary far above tier T2: 雨具 (Zipf 2.46)']::text[], '636da3c2-221b-40c9-84b6-330f2c60b543') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39405, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "天気", "is_correct": true, "explanation": "「天気予報」の「天気」。空の状態を表し、ここに入る唯一の語。"}, {"text": "献立", "is_correct": false, "explanation": "食事の計画を表す。「献立予報」とは言わず、予報の語と結びつかないので空欄に入らない。"}, {"text": "日記", "is_correct": false, "explanation": "書き留める記録を表す。「日記予報」は成り立たず、空欄に入らない。"}, {"text": "手紙", "is_correct": false, "explanation": "人に送る便りを表す。「手紙予報」は成り立たず、空欄に入らない。"}], "explanations": {"天気": "「天気予報」の「天気」。空の状態を表し、ここに入る唯一の語。", "献立": "食事の計画を表す。「献立予報」とは言わず、予報の語と結びつかないので空欄に入らない。", "日記": "書き留める記録を表す。「日記予報」は成り立たず、空欄に入らない。", "手紙": "人に送る便りを表す。「手紙予報」は成り立たず、空欄に入らない。"}, "sentence_index": 0, "correct_answer": "天気"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "朝は天気が低いので、厚手のコートを着て出かけた。", "explanation": "ここは〈気温〉の意味。天気は晴れや雨など空のようすを指し、温度の高さ・低さは言えないので合わない。"}, {"text": "彼女は天気で、いつも周りを笑わせる。", "explanation": "ここは〈天然〉の意味。素直で少し抜けた人柄を表す語で、天気は空のようすなので人には使えない。"}, {"text": "彼女は接客の仕事が天気だと感じている。", "explanation": "ここは〈天職〉の意味。仕事への適性は天職で表す。天気は空のようすなので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26f64f78-ef67-4239-8452-c55ac5095b65') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39405, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "天気", "is_correct": true, "explanation": "「天気が安定せず」の「天気」。季節ごとの空の状態が安定しないという文脈に合う唯一の語。"}, {"text": "名前", "is_correct": false, "explanation": "人や物につける呼び名。「名前が安定せず」は成り立たず、空欄に入らない。"}, {"text": "教科書", "is_correct": false, "explanation": "授業で使う本。「教科書が安定せず」は成り立たず、空欄に入らない。"}, {"text": "辞書", "is_correct": false, "explanation": "語句を調べる本。「辞書が安定せず」は成り立たず、空欄に入らない。"}], "explanations": {"天気": "「天気が安定せず」の「天気」。季節ごとの空の状態が安定しないという文脈に合う唯一の語。", "名前": "人や物につける呼び名。「名前が安定せず」は成り立たず、空欄に入らない。", "教科書": "授業で使う本。「教科書が安定せず」は成り立たず、空欄に入らない。", "辞書": "語句を調べる本。「辞書が安定せず」は成り立たず、空欄に入らない。"}, "sentence_index": 6, "correct_answer": "天気"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "梅雨の時期は天気が高く、洗濯物がなかなか乾かない。", "explanation": "ここは〈湿度〉の意味。天気は空のようすを指し、空気の湿り具合の高さは言えないので合わない。"}, {"text": "会議室の天気が重く、誰も発言しなかった。", "explanation": "ここは〈雰囲気〉の意味。天気は空のようすで、その場の雰囲気は指せないので合わない。"}, {"text": "彼女はとても天気で、いつも周りを笑わせる。", "explanation": "ここは〈天然〉の意味で、素直で少し抜けた人柄を表す。天気は空のようすなので、人の性格には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26f64f78-ef67-4239-8452-c55ac5095b65') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39405, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "天気が良いくて、窓を開けて風を入れた。", "corrected_sentence": "天気が良くて、窓を開けて風を入れた。", "error_description": "形容詞「良い」の連用形は「良く」で、「良くて」が正しい。「良いくて」は活用の誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26f64f78-ef67-4239-8452-c55ac5095b65') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39405, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "天気を悪い日は、屋内で作業することにした。", "corrected_sentence": "天気が悪い日は、屋内で作業することにした。", "error_description": "「天気」が「悪い」の主語なので助詞は「が」が正しい。「を」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26f64f78-ef67-4239-8452-c55ac5095b65') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39406, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "から", "options": [{"text": "から", "is_correct": true, "explanation": "「朝から晴れる」で、時間の起点を示す。"}, {"text": "が", "is_correct": false, "explanation": "主語を示すが、朝は「晴れる」の主語にならない。"}, {"text": "を", "is_correct": false, "explanation": "「晴れる」は自動詞で、目的語の「を」は取れない。"}, {"text": "で", "is_correct": false, "explanation": "手段や場所を示し、「朝で晴れる」は不自然。"}], "correct_answer": "から", "explanations": {"から": "「朝から晴れる」で、時間の起点を示す。", "が": "主語を示すが、朝は「晴れる」の主語にならない。", "を": "「晴れる」は自動詞で、目的語の「を」は取れない。", "で": "手段や場所を示し、「朝で晴れる」は不自然。"}, "error_tags": {"が": "主語", "を": "目的語（自動詞には不可）", "で": "手段・場所"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "曇る", "is_correct": true, "explanation": "晴れの対義語。雲が出て空が暗くなること。"}, {"text": "乾く", "is_correct": false, "explanation": "水分がなくなることで、晴れの対義語ではない。"}, {"text": "焦げる", "is_correct": false, "explanation": "焼けて黒くなることで、関係がない。"}, {"text": "煮える", "is_correct": false, "explanation": "熱で火が通ることで、関係がない。"}], "correct_answer": "曇る", "explanations": {"曇る": "晴れの対義語。雲が出て空が暗くなること。", "乾く": "水分がなくなることで、晴れの対義語ではない。", "焦げる": "焼けて黒くなることで、関係がない。", "煮える": "熱で火が通ることで、関係がない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '14797358-abb1-41c2-b4e0-49bf54ce91a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39406, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "曇る", "is_correct": true, "explanation": "晴れの対義語。雲が出て空が暗くなること。"}, {"text": "眠る", "is_correct": false, "explanation": "眠ることで、天気の反対ではない。"}, {"text": "叫ぶ", "is_correct": false, "explanation": "大声を出すことで、関係がない。"}, {"text": "砕ける", "is_correct": false, "explanation": "壊れることで、関係がない。"}], "correct_answer": "曇る", "explanations": {"曇る": "晴れの対義語。雲が出て空が暗くなること。", "眠る": "眠ることで、天気の反対ではない。", "叫ぶ": "大声を出すことで、関係がない。", "砕ける": "壊れることで、関係がない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '14797358-abb1-41c2-b4e0-49bf54ce91a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39406, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "雲が消えて、空が明るくなること。", "primary_collocate": null, "pronunciation": "はれる", "ipa": "haɾeɾɯ", "syllable_count": 3, "sentences": [{"text": "朝は雨だったが、昼前には空が晴れた。", "target_word": "晴れた", "complexity_tier": "T3", "furigana": "朝[あさ]は雨[あめ]だったが、昼前[ひるまえ]には空[そら]が晴[は]れた。", "sentence_source": "generated"}, {"text": "明日は朝から晴れると天気予報で言っていた。", "target_word": "晴れる", "complexity_tier": "T3", "furigana": "明日[あした]は朝[あさ]から晴[は]れると天気予報[てんきよほう]で言[い]っていた。", "sentence_source": "generated"}, {"text": "雲が切れて、だんだん空が晴れてきた。", "target_word": "晴れて", "complexity_tier": "T3", "furigana": "雲[くも]が切[き]れて、だんだん空[そら]が晴[は]れてきた。", "sentence_source": "generated"}, {"text": "雨がやんで空が晴れたので、洗濯物を外に干した。", "target_word": "晴れた", "complexity_tier": "T3", "furigana": "雨[あめ]がやんで空[そら]が晴[は]れたので、洗濯物[せんたくもの]を外[そと]に干[ほ]した。", "sentence_source": "generated"}, {"text": "梅雨が明けて、空が久しぶりに晴れた。", "target_word": "晴れた", "complexity_tier": "T3", "furigana": "梅雨[つゆ]が明[あ]けて、空[そら]が久[ひさ]しぶりに晴[は]れた。", "sentence_source": "generated"}, {"text": "夕方になって空が晴れ、きれいな夕焼けが見えた。", "target_word": "晴れ", "complexity_tier": "T3", "furigana": "夕方[ゆうがた]になって空[そら]が晴[は]れ、きれいな夕焼[ゆうや]けが見[み]えた。", "sentence_source": "generated"}, {"text": "晴れたら、公園で弁当を食べよう。", "target_word": "晴れたら", "complexity_tier": "T3", "furigana": "晴[は]れたら、公園[こうえん]で弁当[べんとう]を食[た]べよう。", "sentence_source": "generated"}, {"text": "台風が過ぎると、空は嘘のように晴れた。", "target_word": "晴れた", "complexity_tier": "T3", "furigana": "台風[たいふう]が過[す]ぎると、空[そら]は嘘[うそ]のように晴[は]れた。", "sentence_source": "generated"}, {"text": "午後から晴れる予定だったので、遠足は中止にならなかった。", "target_word": "晴れる", "complexity_tier": "T3", "furigana": "午後[ごご]から晴[は]れる予定[よてい]だったので、遠足[えんそく]は中止[ちゅうし]にならなかった。", "sentence_source": "generated"}, {"text": "曇っていた空が晴れて、星がたくさん見えるようになった。", "target_word": "晴れて", "complexity_tier": "T3", "furigana": "曇[くも]っていた空[そら]が晴[は]れて、星[ほし]がたくさん見[み]えるようになった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "晴れる", "label": "終止形"}, {"form": "晴れ", "label": "連用形"}, {"form": "晴れて", "label": "て形"}, {"form": "晴れた", "label": "過去形"}, {"form": "晴れない", "label": "否定形"}, {"form": "晴れれば", "label": "仮定形"}, {"form": "晴れよう", "label": "意向形"}], "register": "neutral", "sense_fingerprint": "雲が消えて空が明るくなる、天気の変化", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4930162-e49e-4526-a312-ee6d7f8dd798') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39406, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "晴れた", "is_correct": true, "explanation": "「空が晴れた」で、雲がなくなり明るくなった意味に合う。"}, {"text": "溶けた", "is_correct": false, "explanation": "空が溶けたとは言わず、天気の変化を表さない。"}, {"text": "濡れた", "is_correct": false, "explanation": "空が濡れたとは言わず、ここでは意味が通らない。"}, {"text": "冷めた", "is_correct": false, "explanation": "空が冷めたとは言わず、天気の変化を表さない。"}], "explanations": {"晴れた": "「空が晴れた」で、雲がなくなり明るくなった意味に合う。", "溶けた": "空が溶けたとは言わず、天気の変化を表さない。", "濡れた": "空が濡れたとは言わず、ここでは意味が通らない。", "冷めた": "空が冷めたとは言わず、天気の変化を表さない。"}, "sentence_index": 0, "correct_answer": "晴れた"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "転んでぶつけた足首が晴れて、歩けなくなった。", "explanation": "ここは〈腫れる〉の意味。皮膚がふくらむことには腫れるを使い、晴れるは空の状態に使う。"}, {"text": "雨がやんだので、洗濯物がすぐ晴れた。", "explanation": "ここは〈乾く〉の意味。洗濯物は晴れるものではなく、乾くもの。"}, {"text": "雨が晴れて、ようやく外を歩けるようになった。", "explanation": "ここは〈止む〉の意味。雨が降り終わることには止むを使い、晴れるは空の状態に使う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '14797358-abb1-41c2-b4e0-49bf54ce91a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39406, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "晴れたら", "is_correct": true, "explanation": "条件を表し、「公園で弁当を食べよう」に自然につながる。"}, {"text": "焦げたら", "is_correct": false, "explanation": "焦げたら公園で弁当を食べるのは意味が通らない。"}, {"text": "煮えたら", "is_correct": false, "explanation": "煮えたら公園で弁当を食べるのは意味が通らない。"}, {"text": "凍ったら", "is_correct": false, "explanation": "凍ったら公園で弁当を食べるのは不自然。"}], "explanations": {"晴れたら": "条件を表し、「公園で弁当を食べよう」に自然につながる。", "焦げたら": "焦げたら公園で弁当を食べるのは意味が通らない。", "煮えたら": "煮えたら公園で弁当を食べるのは意味が通らない。", "凍ったら": "凍ったら公園で弁当を食べるのは不自然。"}, "sentence_index": 6, "correct_answer": "晴れたら"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "午後になると、太陽がじりじり晴れてきた。", "explanation": "ここは〈照る〉の意味。太陽が強く光を放つ様子には照るを使い、晴れるは空の状態に使う。"}, {"text": "川の水が晴れて、底の石まで見えた。", "explanation": "ここは〈澄む〉の意味。水が濁りなく透き通ることには澄むを使い、晴れるは使わない。"}, {"text": "夜になると、星が一つずつ晴れ始めた。", "explanation": "ここは〈光る〉の意味。星が光り出す様子には光るを使い、晴れるは空の天気に使う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '14797358-abb1-41c2-b4e0-49bf54ce91a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39406, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "午後には空を晴れるでしょう。", "corrected_sentence": "午後には空が晴れるでしょう。", "error_description": "「晴れる」は自動詞で「を」は取れない。主語の「空が」を使うのが正しい。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "晴れる", "is_correct": true, "explanation": "「晴れると」の形で、「と」の前には辞書形（終止形）が続く。"}, {"text": "晴れ", "is_correct": false, "explanation": "連用形で、「と」の前には続かない。"}, {"text": "晴れて", "is_correct": false, "explanation": "て形は「と」に続かない。"}, {"text": "晴れれば", "is_correct": false, "explanation": "仮定形で、「と」と併用できない。"}], "correct_form": "晴れる", "base_form": "晴れる", "form_label": "終止形", "sentence_index": 1, "explanations": {"晴れる": "「晴れると」の形で、「と」の前には辞書形（終止形）が続く。", "晴れ": "連用形で、「と」の前には続かない。", "晴れて": "て形は「と」に続かない。", "晴れれば": "仮定形で、「と」と併用できない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '14797358-abb1-41c2-b4e0-49bf54ce91a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39406, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "晴れれたら、公園に行こう。", "corrected_sentence": "晴れたら、公園に行こう。", "error_description": "「晴れる」の過去形「晴れた」に「たら」をつけるのが正しい。「晴れれた」は活用の誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "晴れた", "is_correct": true, "explanation": "過去形で、台風の後に空が一変した状態に合う。"}, {"text": "晴れ", "is_correct": false, "explanation": "連用形で、単独では文の述語にならない。"}, {"text": "晴れよう", "is_correct": false, "explanation": "意向形で、「過ぎると」には続かない。"}, {"text": "晴れない", "is_correct": false, "explanation": "否定形で、「嘘のように」の文脈と合わない。"}], "correct_form": "晴れた", "base_form": "晴れる", "form_label": "過去形", "sentence_index": 7, "explanations": {"晴れた": "過去形で、台風の後に空が一変した状態に合う。", "晴れ": "連用形で、単独では文の述語にならない。", "晴れよう": "意向形で、「過ぎると」には続かない。", "晴れない": "否定形で、「嘘のように」の文脈と合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '14797358-abb1-41c2-b4e0-49bf54ce91a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
