INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39407, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "空に雲がなく、太陽の光が明るく照っている状態。", "primary_collocate": null, "pronunciation": "はれる", "ipa": "haɾeɾɯ", "syllable_count": 3, "sentences": [{"text": "今日は朝からよく晴れていて、とても気持ちがいい。", "target_word": "晴れて", "complexity_tier": "T3", "furigana": "今日[きょう]は朝[あさ]からよく晴[は]れていて、とても気持[きも]ちがいい。", "sentence_source": "generated"}, {"text": "晴れた空の下で、子どもたちが元気に遊んでいる。", "target_word": "晴れた", "complexity_tier": "T3", "furigana": "晴[は]れた空[そら]の下[した]で、子[こ]どもたちが元気[げんき]に遊[あそ]んでいる。", "sentence_source": "generated"}, {"text": "雲ひとつなく晴れているので、洗濯物がよく乾く。", "target_word": "晴れて", "complexity_tier": "T3", "furigana": "雲[くも]ひとつなく晴[は]れているので、洗濯物[せんたくもの]がよく乾[かわ]く。", "sentence_source": "generated"}, {"text": "運動会の日は、青空が広がる晴れた一日だった。", "target_word": "晴れた", "complexity_tier": "T3", "furigana": "運動会[うんどうかい]の日[ひ]は、青空[あおぞら]が広[ひろ]がる晴[は]れた一日[いちにち]だった。", "sentence_source": "generated"}, {"text": "晴れている日は、窓から富士山が見える。", "target_word": "晴れて", "complexity_tier": "T3", "furigana": "晴[は]れている日[ひ]は、窓[まど]から富士山[ふじさん]が見[み]える。", "sentence_source": "generated"}, {"text": "山の上は晴れていて、日差しが強かった。", "target_word": "晴れて", "complexity_tier": "T3", "furigana": "山[やま]の上[うえ]は晴[は]れていて、日差[ひざ]しが強[つよ]かった。", "sentence_source": "generated"}, {"text": "冬は晴れる日が多いが、朝晩はとても寒い。", "target_word": "晴れる", "complexity_tier": "T3", "furigana": "冬[ふゆ]は晴[は]れる日[ひ]が多[おお]いが、朝晩[あさばん]はとても寒[さむ]い。", "sentence_source": "generated"}, {"text": "晴れていても、傘を持っていくと安心だ。", "target_word": "晴れて", "complexity_tier": "T3", "furigana": "晴[は]れていても、傘[かさ]を持[も]っていくと安心[あんしん]だ。", "sentence_source": "generated"}, {"text": "空が高く晴れた秋の日に、家族で散歩に出かけた。", "target_word": "晴れた", "complexity_tier": "T3", "furigana": "空[そら]が高[たか]く晴[は]れた秋[あき]の日[ひ]に、家族[かぞく]で散歩[さんぽ]に出[で]かけた。", "sentence_source": "generated"}, {"text": "空は晴れて、波も静かなので、釣りには最高の日だ。", "target_word": "晴れて", "complexity_tier": "T3", "furigana": "空[そら]は晴[は]れて、波[なみ]も静[しず]かなので、釣[つ]りには最高[さいこう]の日[ひ]だ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "晴れる", "label": "終止形"}, {"form": "晴れ", "label": "連用形"}, {"form": "晴れて", "label": "て形"}, {"form": "晴れた", "label": "過去形"}, {"form": "晴れない", "label": "否定形"}, {"form": "晴れれば", "label": "仮定形"}, {"form": "晴れよう", "label": "意向形"}], "register": "neutral", "sense_fingerprint": "雲がなく日が照っている晴天の状態", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4930162-e49e-4526-a312-ee6d7f8dd798') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39407, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "晴れて", "is_correct": true, "explanation": "「よく晴れていて」で、空が晴れている状態に合う。"}, {"text": "焦げて", "is_correct": false, "explanation": "焦げるは空の状態には使わず、意味が通らない。"}, {"text": "煮えて", "is_correct": false, "explanation": "煮えるは空の状態には使わず、意味が通らない。"}, {"text": "溶けて", "is_correct": false, "explanation": "溶けるは空の状態には使わず、意味が通らない。"}], "explanations": {"晴れて": "「よく晴れていて」で、空が晴れている状態に合う。", "焦げて": "焦げるは空の状態には使わず、意味が通らない。", "煮えて": "煮えるは空の状態には使わず、意味が通らない。", "溶けて": "溶けるは空の状態には使わず、意味が通らない。"}, "sentence_index": 0, "correct_answer": "晴れて"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "海が晴れて、波が静かになった。", "explanation": "ここは〈凪ぐ〉の意味。海の波がおさまる様子には凪ぐを使い、晴れるは空の状態に使う。"}, {"text": "正午過ぎ、太陽がまぶしく晴れていた。", "explanation": "ここは〈照る〉の意味。太陽が光を放つ様子には照るを使い、晴れるは使わない。"}, {"text": "雨が晴れて、グラウンドに水たまりが残った。", "explanation": "ここは〈上がる〉の意味。雨が止むことには上がるを使い、晴れるは空に使う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '14797358-abb1-41c2-b4e0-49bf54ce91a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39407, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "晴れる", "is_correct": true, "explanation": "「晴れる日が多い」で、空が晴れる意味に合う。"}, {"text": "眠る", "is_correct": false, "explanation": "眠る日が多いは天気を表さず、意味が通らない。"}, {"text": "沸く", "is_correct": false, "explanation": "沸く日が多いは天気を表さず、意味が通らない。"}, {"text": "腐る", "is_correct": false, "explanation": "腐る日が多いは天気を表さず、意味が通らない。"}], "explanations": {"晴れる": "「晴れる日が多い」で、空が晴れる意味に合う。", "眠る": "眠る日が多いは天気を表さず、意味が通らない。", "沸く": "沸く日が多いは天気を表さず、意味が通らない。", "腐る": "腐る日が多いは天気を表さず、意味が通らない。"}, "sentence_index": 6, "correct_answer": "晴れる"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "洗濯物がよく晴れたので、午後に取り込んだ。", "explanation": "ここは〈乾く〉の意味。洗濯物は乾くもので、晴れるは空の状態に使う。"}, {"text": "寒さで空気が晴れて、遠くの山まではっきり見えた。", "explanation": "ここは〈冴える〉の意味。寒さで空気が澄んで鋭くなる様子には冴えるを使う。"}, {"text": "海面が朝日に晴れて、きれいだった。", "explanation": "ここは〈輝く〉の意味。光を受けて光る様子には輝くを使い、晴れるは空に使う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '14797358-abb1-41c2-b4e0-49bf54ce91a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39407, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "今日は朝から空がよく晴れさせて、洗濯日和だ。", "corrected_sentence": "今日は朝から空がよく晴れて、洗濯日和だ。", "error_description": "「晴れさせて」は使役形で、人が晴れさせるという意味になり不自然。空が自然に晴れる場合は「晴れて」が正しい。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "晴れた", "is_correct": true, "explanation": "過去形の連体形で、「空」を修飾する形として合う。"}, {"text": "晴れて", "is_correct": false, "explanation": "て形で、名詞を修飾できない。"}, {"text": "晴れよう", "is_correct": false, "explanation": "意向形で、名詞を修飾しない。"}, {"text": "晴れれば", "is_correct": false, "explanation": "仮定形で、名詞を修飾できない。"}], "correct_form": "晴れた", "base_form": "晴れる", "form_label": "過去形", "sentence_index": 1, "explanations": {"晴れた": "過去形の連体形で、「空」を修飾する形として合う。", "晴れて": "て形で、名詞を修飾できない。", "晴れよう": "意向形で、名詞を修飾しない。", "晴れれば": "仮定形で、名詞を修飾できない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '14797358-abb1-41c2-b4e0-49bf54ce91a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39407, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "午後も空が晴れていで、川辺は涼しかった。", "corrected_sentence": "午後も空が晴れていて、川辺は涼しかった。", "error_description": "「晴れていで」は誤った接続の形。「晴れていて」（て形）が正しい。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "晴れて", "is_correct": true, "explanation": "「晴れていても」の て形で、「ている」の形として正しい。"}, {"text": "晴れた", "is_correct": false, "explanation": "過去形で、「ていても」に続かない。"}, {"text": "晴れる", "is_correct": false, "explanation": "終止形で、「ていても」には続かない。"}, {"text": "晴れない", "is_correct": false, "explanation": "否定形で、「ていても」の形と合わない。"}], "correct_form": "晴れて", "base_form": "晴れる", "form_label": "て形", "sentence_index": 7, "explanations": {"晴れて": "「晴れていても」の て形で、「ている」の形として正しい。", "晴れた": "過去形で、「ていても」に続かない。", "晴れる": "終止形で、「ていても」には続かない。", "晴れない": "否定形で、「ていても」の形と合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '14797358-abb1-41c2-b4e0-49bf54ce91a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39408, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「町の存立」の「の」。存立の持ち主を示す格助詞で、ここが正しい。"}, {"text": "を", "is_correct": false, "explanation": "存立は目的語を取らないので、「町を存立そのもの」では文が成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「町に存立そのもの」では、存立がどこに成り立つのかという位置関係が不自然で、文の流れに合わない。"}, {"text": "と", "is_correct": false, "explanation": "「町と存立」は並列の相手を示すが、存立と並べる語として文脈に合わず、主語の働きをしない。"}], "correct_answer": "の", "explanations": {"の": "「町の存立」の「の」。存立の持ち主を示す格助詞で、ここが正しい。", "を": "存立は目的語を取らないので、「町を存立そのもの」では文が成り立たない。", "に": "「町に存立そのもの」では、存立がどこに成り立つのかという位置関係が不自然で、文の流れに合わない。", "と": "「町と存立」は並列の相手を示すが、存立と並べる語として文脈に合わず、主語の働きをしない。"}, "error_tags": {"を": "目的語", "に": "位置", "と": "並列"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '14797358-abb1-41c2-b4e0-49bf54ce91a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39408, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「国家の存立」の「の」。存立の主体を示す格助詞で、ここが正しい。"}, {"text": "を", "is_correct": false, "explanation": "「国家を存立の根拠」では国家が目的語になり、「存立の根拠を定める」の文として成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す「へ」は、国家という語を存立へ向かわせる形になり、文脈に合わない。"}, {"text": "から", "is_correct": false, "explanation": "起点を示す「から」では、国家から根拠が出てくるという意味になり、存立の根拠という意味が通らない。"}], "correct_answer": "の", "explanations": {"の": "「国家の存立」の「の」。存立の主体を示す格助詞で、ここが正しい。", "を": "「国家を存立の根拠」では国家が目的語になり、「存立の根拠を定める」の文として成り立たない。", "へ": "方向を示す「へ」は、国家という語を存立へ向かわせる形になり、文脈に合わない。", "から": "起点を示す「から」では、国家から根拠が出てくるという意味になり、存立の根拠という意味が通らない。"}, "error_tags": {"を": "目的語", "へ": "方向", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '14797358-abb1-41c2-b4e0-49bf54ce91a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39408, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "ものが あって、なりたって いる こと。", "primary_collocate": null, "pronunciation": "そんりつ", "ipa": "soɴɾitsɯ", "syllable_count": 4, "sentences": [{"text": "国の存立は、国民の信頼によって支えられている。", "target_word": "存立", "complexity_tier": "T3", "furigana": "国[くに]の存立[そんりつ]は、国民[こくみん]の信頼[しんらい]によって支[ささ]えられている。", "sentence_source": "generated"}, {"text": "財政が破綻すれば、町の存立そのものが危うくなる。", "target_word": "存立", "complexity_tier": "T3", "furigana": "財政[ざいせい]が破綻[はたん]すれば、町[まち]の存立[そんりつ]そのものが危[あや]うくなる。", "sentence_source": "generated"}, {"text": "この学校は寄付金がなければ存立できない。", "target_word": "存立", "complexity_tier": "T3", "furigana": "この学校[がっこう]は寄付金[きふきん]がなければ存立[そんりつ]できない。", "sentence_source": "generated"}, {"text": "生き物の存立には、水と空気が欠かせない。", "target_word": "存立", "complexity_tier": "T3", "furigana": "生[い]き物[もの]の存立[そんりつ]には、水[みず]と空気[くうき]が欠[か]かせない。", "sentence_source": "generated"}, {"text": "組合は、働く人の権利を守るために存立している。", "target_word": "存立", "complexity_tier": "T3", "furigana": "組合[くみあい]は、働[はたら]く人[ひと]の権利[けんり]を守[まも]るために存立[そんりつ]している。", "sentence_source": "generated"}, {"text": "小さな店でも、客がいなければ存立は難しい。", "target_word": "存立", "complexity_tier": "T3", "furigana": "小[ちい]さな店[みせ]でも、客[きゃく]がいなければ存立[そんりつ]は難[むずか]しい。", "sentence_source": "generated"}, {"text": "会社の存立を脅かすような不正が発覚した。", "target_word": "存立", "complexity_tier": "T3", "furigana": "会社[かいしゃ]の存立[そんりつ]を脅[おびや]かすような不正[ふせい]が発覚[はっかく]した。", "sentence_source": "generated"}, {"text": "憲法は、国家の存立の根拠を定めている。", "target_word": "存立", "complexity_tier": "T3", "furigana": "憲法[けんぽう]は、国家[こっか]の存立[そんりつ]の根拠[こんきょ]を定[さだ]めている。", "sentence_source": "generated"}, {"text": "地域の農業の存立が危ぶまれ、住民は対策を話し合った。", "target_word": "存立", "complexity_tier": "T3", "furigana": "地域[ちいき]の農業[のうぎょう]の存立[そんりつ]が危[あや]ぶまれ、住民[じゅうみん]は対策[たいさく]を話[はな]し合[あ]った。", "sentence_source": "generated"}, {"text": "森が消えれば、そこに住む動物の存立も脅かされる。", "target_word": "存立", "complexity_tier": "T3", "furigana": "森[もり]が消[き]えれば、そこに住[す]む動物[どうぶつ]の存立[そんりつ]も脅[おびや]かされる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "存立", "label": "基本形"}, {"form": "存立する", "label": "サ変動詞"}, {"form": "存立した", "label": "過去形"}, {"form": "存立できない", "label": "可能否定形"}], "register": "formal", "sense_fingerprint": "国・組織・生き物などが存在し成り立っていること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4930162-e49e-4526-a312-ee6d7f8dd798') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39408, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "存立", "is_correct": true, "explanation": "ものがあり、なりたっていることを表す。「国の存立は国民の信頼に支えられている」という文の主題に合う。"}, {"text": "体温", "is_correct": false, "explanation": "人や動物の体の温度で、国の成り立ちを述べる文には入らない。「国の体温は支えられている」は意味が通らない。"}, {"text": "湿度", "is_correct": false, "explanation": "空気中の水分の割合で、国の成り立ちとは関係しない。「国の湿度は支えられている」は文として成り立たない。"}, {"text": "色彩", "is_correct": false, "explanation": "ものの見た目を表す語で、国家の成り立ちや基盤を指さないため、この空所には入らない。"}], "explanations": {"存立": "ものがあり、なりたっていることを表す。「国の存立は国民の信頼に支えられている」という文の主題に合う。", "体温": "人や動物の体の温度で、国の成り立ちを述べる文には入らない。「国の体温は支えられている」は意味が通らない。", "湿度": "空気中の水分の割合で、国の成り立ちとは関係しない。「国の湿度は支えられている」は文として成り立たない。", "色彩": "ものの見た目を表す語で、国家の成り立ちや基盤を指さないため、この空所には入らない。"}, "sentence_index": 0, "correct_answer": "存立"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "祖父は九十歳まで存立した。", "explanation": "ここは〈生存〉の意味。存立は、ものが存在して成り立つことを指すので、人が生き続けることには使わない。"}, {"text": "彼は二十歳で存立し、親元を離れた。", "explanation": "ここは〈独立〉の意味。親元から離れて自立することは独立と言い、存立は合わない。"}, {"text": "地震が存立した。", "explanation": "ここは〈発生〉の意味。地震や災害が起こることには発生を使い、存立は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '14797358-abb1-41c2-b4e0-49bf54ce91a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39408, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "存立", "is_correct": true, "explanation": "会社がなりたち続けることを表す。「会社の存立を脅かす」は、会社が続けられなくなる恐れを述べる自然な表現。"}, {"text": "駐車場", "is_correct": false, "explanation": "会社の施設ではあるが、「会社の駐車場を脅かす」は不自然で、不正が発覚する文脈にも合わない。"}, {"text": "名刺", "is_correct": false, "explanation": "会社の所属を示す物で、不正によって脅かされる対象にはならないため、この空所には入らない。"}, {"text": "社章", "is_correct": false, "explanation": "会社の象徴だが、「会社の社章を脅かすような不正」は意味がつながらず、会社の存続を損なう文脈に合わない。"}], "explanations": {"存立": "会社がなりたち続けることを表す。「会社の存立を脅かす」は、会社が続けられなくなる恐れを述べる自然な表現。", "駐車場": "会社の施設ではあるが、「会社の駐車場を脅かす」は不自然で、不正が発覚する文脈にも合わない。", "名刺": "会社の所属を示す物で、不正によって脅かされる対象にはならないため、この空所には入らない。", "社章": "会社の象徴だが、「会社の社章を脅かすような不正」は意味がつながらず、会社の存続を損なう文脈に合わない。"}, "sentence_index": 6, "correct_answer": "存立"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "その議案は全員の賛成で存立した。", "explanation": "ここは〈成立〉の意味。議案や契約が正式に決まることには成立を使い、存立は合わない。"}, {"text": "彼女のピアノには、聴く人を惹きつける存立がある。", "explanation": "ここは〈存在感〉の意味。人や作品が放つ印象の強さには存在感を使い、存立は使わない。"}, {"text": "長年の夢が存立した。", "explanation": "ここは〈実現〉の意味。夢や計画が現実になることには実現を使い、存立は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '14797358-abb1-41c2-b4e0-49bf54ce91a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39408, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この村は若者が減り、存立を危ぶまれている。", "corrected_sentence": "この村は若者が減り、存立が危ぶまれている。", "error_description": "「危ぶまれる」は「が」を取る動詞なので、主語となる「存立」には「を」ではなく「が」を付ける。誤りは存立に付いた助詞「を」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '14797358-abb1-41c2-b4e0-49bf54ce91a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39408, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "その組合は、市民の支持によって存立されている。", "corrected_sentence": "その組合は、市民の支持によって存立している。", "error_description": "「存立する」は自分の状態を表す自動詞なので、受け身の「存立される」とは言わない。正しくは「存立している」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '14797358-abb1-41c2-b4e0-49bf54ce91a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39409, 3, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '14797358-abb1-41c2-b4e0-49bf54ce91a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39409, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「国家の存立」の「の」。存立の主体を示す格助詞で、ここが正しい。"}, {"text": "で", "is_correct": false, "explanation": "「国家で存立よりも」では、存立が起こる場所のように読め、比べる対象として文が成り立たない。"}, {"text": "から", "is_correct": false, "explanation": "起点を示す「から」では、国家から存立が生じるという意味になり、比較の文脈に合わない。"}, {"text": "に", "is_correct": false, "explanation": "「国家に存立よりも」では、国家がどこに成り立つかという位置関係になり、存立との比較が不自然。"}], "correct_answer": "の", "explanations": {"の": "「国家の存立」の「の」。存立の主体を示す格助詞で、ここが正しい。", "で": "「国家で存立よりも」では、存立が起こる場所のように読め、比べる対象として文が成り立たない。", "から": "起点を示す「から」では、国家から存立が生じるという意味になり、比較の文脈に合わない。", "に": "「国家に存立よりも」では、国家がどこに成り立つかという位置関係になり、存立との比較が不自然。"}, "error_tags": {"で": "場所・手段", "から": "起点", "に": "位置"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '14797358-abb1-41c2-b4e0-49bf54ce91a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39409, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "ある物事が存在し、成り立っていくこと。", "primary_collocate": null, "pronunciation": "そんりつ", "ipa": "soɴɾitsɯ", "syllable_count": 4, "sentences": [{"text": "補助金が打ち切られ、劇団の存立が危ぶまれている。", "target_word": "存立", "complexity_tier": "T3", "furigana": "補助金[ほじょきん]が打[う]ち切[き]られ、劇団[げきだん]の存立[そんりつ]が危[あや]ぶまれている。", "sentence_source": "generated"}, {"text": "市民の支えがあってこそ、この図書館の存立が可能になる。", "target_word": "存立", "complexity_tier": "T3", "furigana": "市民[しみん]の支[ささ]えがあってこそ、この図書館[としょかん]の存立[そんりつ]が可能[かのう]になる。", "sentence_source": "generated"}, {"text": "村は人口が減り続け、存立の危機に立たされている。", "target_word": "存立", "complexity_tier": "T3", "furigana": "村[むら]は人口[じんこう]が減[へ]り続[つづ]け、存立[そんりつ]の危機[きき]に立[た]たされている。", "sentence_source": "generated"}, {"text": "国際社会は、各国が互いを尊重することで存立している。", "target_word": "存立", "complexity_tier": "T3", "furigana": "国際社会[こくさいしゃかい]は、各国[かっこく]が互[たが]いを尊重[そんちょう]することで存立[そんりつ]している。", "sentence_source": "generated"}, {"text": "新しい法律は、中小企業の存立を守ることを目的としている。", "target_word": "存立", "complexity_tier": "T3", "furigana": "新[あたら]しい法律[ほうりつ]は、中小企業[ちゅうしょうきぎょう]の存立[そんりつ]を守[まも]ることを目的[もくてき]としている。", "sentence_source": "generated"}, {"text": "社会の存立には、ルールを守る個人が必要だ。", "target_word": "存立", "complexity_tier": "T3", "furigana": "社会[しゃかい]の存立[そんりつ]には、ルールを守[まも]る個人[こじん]が必要[ひつよう]だ。", "sentence_source": "generated"}, {"text": "売り上げが落ち続け、工場の存立は難しくなった。", "target_word": "存立", "complexity_tier": "T3", "furigana": "売[う]り上[あ]げが落[お]ち続[つづ]け、工場[こうじょう]の存立[そんりつ]は難[むずか]しくなった。", "sentence_source": "generated"}, {"text": "彼は、国家の存立よりも個人の自由を重んじる立場をとった。", "target_word": "存立", "complexity_tier": "T3", "furigana": "彼[かれ]は、国家[こっか]の存立[そんりつ]よりも個人[こじん]の自由[じゆう]を重[おも]んじる立場[たちば]をとった。", "sentence_source": "generated"}, {"text": "研究所は、資金の確保なしには存立していけない。", "target_word": "存立", "complexity_tier": "T3", "furigana": "研究所[けんきゅうじょ]は、資金[しきん]の確保[かくほ]なしには存立[そんりつ]していけない。", "sentence_source": "generated"}, {"text": "病院の存立を支えているのは、地域の人々の協力だ。", "target_word": "存立", "complexity_tier": "T3", "furigana": "病院[びょういん]の存立[そんりつ]を支[ささ]えているのは、地域[ちいき]の人々[ひとびと]の協力[きょうりょく]だ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "存立", "label": "基本形"}, {"form": "存立する", "label": "サ変動詞"}, {"form": "存立している", "label": "状態形"}, {"form": "存立していけない", "label": "可能否定形"}], "register": "formal", "sense_fingerprint": "物事が存在し続け成り立っていく、その維持", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4930162-e49e-4526-a312-ee6d7f8dd798') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39409, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "存立", "is_correct": true, "explanation": "物事が存在し続けて成り立つことを表す。「劇団の存立が危ぶまれている」は、劇団が続けられなくなる恐れを述べる自然な文。"}, {"text": "湿度", "is_correct": false, "explanation": "空気中の水分の割合で、劇団の存続の危機を述べる文には入らない。「劇団の湿度が危ぶまれている」は意味が通らない。"}, {"text": "体温", "is_correct": false, "explanation": "体の温かさを表す語で、劇団が続けられなくなる恐れを述べる文とはつながらない。"}, {"text": "楽譜", "is_correct": false, "explanation": "演奏に使う資料で、劇団の存続の危機を表す文脈では意味が通らない。"}], "explanations": {"存立": "物事が存在し続けて成り立つことを表す。「劇団の存立が危ぶまれている」は、劇団が続けられなくなる恐れを述べる自然な文。", "湿度": "空気中の水分の割合で、劇団の存続の危機を述べる文には入らない。「劇団の湿度が危ぶまれている」は意味が通らない。", "体温": "体の温かさを表す語で、劇団が続けられなくなる恐れを述べる文とはつながらない。", "楽譜": "演奏に使う資料で、劇団の存続の危機を表す文脈では意味が通らない。"}, "sentence_index": 0, "correct_answer": "存立"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "その協定は、三か国の合意によって存立した。", "explanation": "ここは〈成立〉の意味。協定や契約が正式に結ばれることには成立を使い、存立は合わない。"}, {"text": "その問題は、話し合いで存立した。", "explanation": "ここは〈解決〉の意味。問題が片づくことには解決を使い、存立は合わない。"}, {"text": "長年の計画が存立した。", "explanation": "ここは〈実現〉の意味。計画が形になって現実となることには実現を使い、存立は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '14797358-abb1-41c2-b4e0-49bf54ce91a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39409, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "存立", "is_correct": true, "explanation": "工場がなりたち続けることを表す。「工場の存立は難しくなった」は、経営が続かなくなる状況に合う。"}, {"text": "煙突", "is_correct": false, "explanation": "工場の設備だが、「工場の煙突は難しくなった」は意味が通らず、売り上げの落ち込みの文脈に合わない。"}, {"text": "排気口", "is_correct": false, "explanation": "工場の設備ではあるが、難しくなるという述語とつながらず、経営の状態を述べる文に入らない。"}, {"text": "作業着", "is_correct": false, "explanation": "工場で使う衣服で、「作業着は難しくなった」は不自然で、売り上げと関係する文脈に合わない。"}], "explanations": {"存立": "工場がなりたち続けることを表す。「工場の存立は難しくなった」は、経営が続かなくなる状況に合う。", "煙突": "工場の設備だが、「工場の煙突は難しくなった」は意味が通らず、売り上げの落ち込みの文脈に合わない。", "排気口": "工場の設備ではあるが、難しくなるという述語とつながらず、経営の状態を述べる文に入らない。", "作業着": "工場で使う衣服で、「作業着は難しくなった」は不自然で、売り上げと関係する文脈に合わない。"}, "sentence_index": 6, "correct_answer": "存立"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "祖母は百歳まで存立した。", "explanation": "ここは〈生存〉の意味。人が生き続けることには生存を使い、存立は人の命には使わない。"}, {"text": "彼は二十歳で存立し、一人暮らしを始めた。", "explanation": "ここは〈独立〉の意味。親元から離れて自立する場合は独立と言い、存立は合わない。"}, {"text": "新しい体育館が存立した。", "explanation": "ここは〈完成〉の意味。建物や製品ができあがることには完成を使い、存立は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '14797358-abb1-41c2-b4e0-49bf54ce91a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39409, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "会社は利益を上げて、存立させていくことが必要だ。", "corrected_sentence": "会社は利益を上げて、存立していくことが必要だ。", "error_description": "「存立する」は自動詞なので、「存立させる」とは言わない。「存続させる」と混同した形で、正しくは「存立していく」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '14797358-abb1-41c2-b4e0-49bf54ce91a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39409, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "町の存立を、産業の発展が欠かせない。", "corrected_sentence": "町の存立には、産業の発展が欠かせない。", "error_description": "「欠かせない」は「には」を取る表現なので、存立に付けるのは「を」ではなく「には」。目的語の「を」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '14797358-abb1-41c2-b4e0-49bf54ce91a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39410, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「見る」の目的語として「化石を」が正しい。"}, {"text": "に", "is_correct": false, "explanation": "「見る」の目的語には「を」を使い、「に」は合わない。"}, {"text": "が", "is_correct": false, "explanation": "「化石が見た」では化石が見る主体になってしまい、意味が通らない。"}, {"text": "へ", "is_correct": false, "explanation": "「見る」は方向の「へ」を取らず、ここでは不自然。"}], "correct_answer": "を", "explanations": {"を": "「見る」の目的語として「化石を」が正しい。", "に": "「見る」の目的語には「を」を使い、「に」は合わない。", "が": "「化石が見た」では化石が見る主体になってしまい、意味が通らない。", "へ": "「見る」は方向の「へ」を取らず、ここでは不自然。"}, "error_tags": {"に": "対象", "が": "主語", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5fa85734-4702-4ee4-8b6d-fd6e1534aa8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39410, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「見る」の目的語として「化石を」が正しい。"}, {"text": "で", "is_correct": false, "explanation": "「化石で見る」は手段や場所を表さず、意味が通らない。"}, {"text": "の", "is_correct": false, "explanation": "「化石の見ると」は修飾の形にならず、文が成り立たない。"}, {"text": "より", "is_correct": false, "explanation": "「化石より見ると」は比較の文脈がなく、不自然。"}], "correct_answer": "を", "explanations": {"を": "「見る」の目的語として「化石を」が正しい。", "で": "「化石で見る」は手段や場所を表さず、意味が通らない。", "の": "「化石の見ると」は修飾の形にならず、文が成り立たない。", "より": "「化石より見ると」は比較の文脈がなく、不自然。"}, "error_tags": {"で": "手段・場所", "の": "所属・修飾", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5fa85734-4702-4ee4-8b6d-fd6e1534aa8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39410, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "ずっと昔の生き物や植物が石になったもの。", "primary_collocate": null, "pronunciation": "かせき", "ipa": "kaseki", "syllable_count": 3, "sentences": [{"text": "山で、貝の化石を拾いました。", "target_word": "化石", "complexity_tier": "T3", "furigana": "やまで、かいのかせきをひろいました。", "sentence_source": "generated"}, {"text": "博物館で大きな恐竜の化石を見た。", "target_word": "化石", "complexity_tier": "T3", "furigana": "はくぶつかんでおおきなきょうりゅうのかせきをみた。", "sentence_source": "generated"}, {"text": "この石には、魚の化石が入っている。", "target_word": "化石", "complexity_tier": "T3", "furigana": "このいしには、さかなのかせきがはいっている。", "sentence_source": "generated"}, {"text": "兄は化石を集めるのが趣味だ。", "target_word": "化石", "complexity_tier": "T3", "furigana": "あにはかせきをあつめるのがしゅみだ。", "sentence_source": "generated"}, {"text": "化石は、昔の生き物が石になったものだ。", "target_word": "化石", "complexity_tier": "T3", "furigana": "かせきは、むかしのいきものがいしになったものだ。", "sentence_source": "generated"}, {"text": "川の近くの崖で、木の葉の化石が見つかった。", "target_word": "化石", "complexity_tier": "T3", "furigana": "かわのちかくのがけで、きのはのかせきがみつかった。", "sentence_source": "generated"}, {"text": "先生が、教室に三葉虫の化石を持ってきた。", "target_word": "化石", "complexity_tier": "T3", "furigana": "せんせいが、きょうしつにさんようちゅうのかせきをもってきた。", "sentence_source": "generated"}, {"text": "化石を見ると、大昔の地球の様子が想像できる。", "target_word": "化石", "complexity_tier": "T3", "furigana": "かせきをみると、おおむかしのちきゅうのようすがそうぞうできる。", "sentence_source": "generated"}, {"text": "海のない県でも、化石が出ることがある。", "target_word": "化石", "complexity_tier": "T3", "furigana": "うみのないけんでも、かせきがでることがある。", "sentence_source": "generated"}, {"text": "夏休みに、家族で化石を掘る体験に参加した。", "target_word": "化石", "complexity_tier": "T3", "furigana": "なつやすみに、かぞくでかせきをほるたいけんにさんかした。", "sentence_source": "generated"}], "morphological_forms": [{"form": "化石", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "大昔の生き物や植物が石になったもの", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 6 above tier T3: contains vocabulary far above tier T3: 葉虫 (Zipf 1.77)']::text[], '2cadf245-b057-4a4f-80e4-458d2df7fe35') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39410, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "化石", "is_correct": true, "explanation": "「貝の化石」として、大昔の貝が石になったものを指すので正しい。"}, {"text": "財布", "is_correct": false, "explanation": "「貝の財布」は意味が通らず、拾うものとして合わない。"}, {"text": "写真", "is_correct": false, "explanation": "「貝の写真」を山で拾うという文脈は成り立たない。"}, {"text": "手紙", "is_correct": false, "explanation": "「貝の手紙」は意味をなさず、この文脈に入らない。"}], "explanations": {"化石": "「貝の化石」として、大昔の貝が石になったものを指すので正しい。", "財布": "「貝の財布」は意味が通らず、拾うものとして合わない。", "写真": "「貝の写真」を山で拾うという文脈は成り立たない。", "手紙": "「貝の手紙」は意味をなさず、この文脈に入らない。"}, "sentence_index": 0, "correct_answer": "化石"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この鉱山では、銅の化石がたくさん掘り出された。", "explanation": "ここは〈鉱石〉の意味。化石は生き物が石になったものを指すので、銅の鉱石には使わない。"}, {"text": "この石器は縄文時代の化石として、博物館に展示されている。", "explanation": "ここは〈遺物〉の意味。石器は人が作った道具で、生き物が石になったものではない。"}, {"text": "亡くなった祖父の化石を、お墓に納めた。", "explanation": "ここは〈遺骨〉の意味。亡くなった人の骨は化石とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5fa85734-4702-4ee4-8b6d-fd6e1534aa8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39410, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "化石", "is_correct": true, "explanation": "「三葉虫の化石」として、大昔の生き物が石になったものを指すので正しい。"}, {"text": "香水", "is_correct": false, "explanation": "「三葉虫の香水」は成り立たず、教室に持ってくるものとしても不自然。"}, {"text": "切符", "is_correct": false, "explanation": "「三葉虫の切符」は成り立たず、この文脈に入らない。"}, {"text": "座布団", "is_correct": false, "explanation": "「三葉虫の座布団」は意味が通らず、教室に持ってくるものとして不自然。"}], "explanations": {"化石": "「三葉虫の化石」として、大昔の生き物が石になったものを指すので正しい。", "香水": "「三葉虫の香水」は成り立たず、教室に持ってくるものとしても不自然。", "切符": "「三葉虫の切符」は成り立たず、この文脈に入らない。", "座布団": "「三葉虫の座布団」は意味が通らず、教室に持ってくるものとして不自然。"}, "sentence_index": 6, "correct_answer": "化石"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "事故で壊れた車の化石が、川から引き上げられた。", "explanation": "ここは〈残骸〉の意味。化石は生き物が石になったもので、壊れた車には使わない。"}, {"text": "ネックレスに、珍しいダイヤの化石を使った。", "explanation": "ここは〈宝石〉の意味。化石は生き物が石になったもので、宝石には使わない。"}, {"text": "先週採ったばかりのカエルを、化石の標本として箱に入れた。", "explanation": "ここは〈標本〉の意味。先週採ったカエルは石になっていないので、化石とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5fa85734-4702-4ee4-8b6d-fd6e1534aa8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39410, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "砂浜で、貝の化石が見つけた。", "corrected_sentence": "砂浜で、貝の化石が見つかった。", "error_description": "「化石」が主語なので自動詞「見つかる」の過去形「見つかった」が正しい。「見つけた」は人が主語の他動詞で不自然。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5fa85734-4702-4ee4-8b6d-fd6e1534aa8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39410, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "岩の中に化石を閉じ込められている。", "corrected_sentence": "岩の中に化石が閉じ込められている。", "error_description": "「閉じ込められる」は受身で、化石は主語なので「が」が正しい。「を」は目的語を示すので不適。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5fa85734-4702-4ee4-8b6d-fd6e1534aa8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39411, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「化石」が「見つかる」の主語。自動詞の主語を示す「が」が正しい。"}, {"text": "を", "is_correct": false, "explanation": "「見つかる」は目的語を取らない自動詞なので、「を」は不自然。"}, {"text": "に", "is_correct": false, "explanation": "「化石に見つかる」は意味が通らない。"}, {"text": "で", "is_correct": false, "explanation": "「化石で見つかる」は場所や手段を表さず、ここでは合わない。"}], "correct_answer": "が", "explanations": {"が": "「化石」が「見つかる」の主語。自動詞の主語を示す「が」が正しい。", "を": "「見つかる」は目的語を取らない自動詞なので、「を」は不自然。", "に": "「化石に見つかる」は意味が通らない。", "で": "「化石で見つかる」は場所や手段を表さず、ここでは合わない。"}, "error_tags": {"を": "目的語", "に": "対象", "で": "場所・手段"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5fa85734-4702-4ee4-8b6d-fd6e1534aa8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39411, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「化石」が「出る」の主語。自動詞の主語には「が」を使う。"}, {"text": "へ", "is_correct": false, "explanation": "「出る」に方向の「へ」は合わず、化石が移動する文脈ではない。"}, {"text": "と", "is_correct": false, "explanation": "「化石と出る」では並列の相手にならず、意味が通らない。"}, {"text": "より", "is_correct": false, "explanation": "比較の「より」は「出る」の主語にならず、ここでは不自然。"}], "correct_answer": "が", "explanations": {"が": "「化石」が「出る」の主語。自動詞の主語には「が」を使う。", "へ": "「出る」に方向の「へ」は合わず、化石が移動する文脈ではない。", "と": "「化石と出る」では並列の相手にならず、意味が通らない。", "より": "比較の「より」は「出る」の主語にならず、ここでは不自然。"}, "error_tags": {"へ": "方向", "と": "並列・共同", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5fa85734-4702-4ee4-8b6d-fd6e1534aa8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39411, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "地中に埋もれた生物の遺骸などが、長い年月をかけて石化したもの。", "primary_collocate": null, "pronunciation": "かせき", "ipa": "kaseki", "syllable_count": 3, "sentences": [{"text": "この地層からは、三億年前の大型植物の化石が大量に見つかっている。", "target_word": "化石", "complexity_tier": "T3", "furigana": "このちそうからは、さんおくねんまえのおおがたしょくぶつのかせきがたいりょうにみつかっている。", "sentence_source": "generated"}, {"text": "地層から恐竜の化石が見つかり、研究者たちは調査を始めた。", "target_word": "化石", "complexity_tier": "T3", "furigana": "ちそうからきょうりゅうのかせきがみつかり、けんきゅうしゃたちはちょうさをはじめた。", "sentence_source": "generated"}, {"text": "この化石は約三億年前の植物のものだと推定されている。", "target_word": "化石", "complexity_tier": "T3", "furigana": "このかせきはやくさんおくねんまえのしょくぶつのものだとすいていされている。", "sentence_source": "generated"}, {"text": "化石を詳しく調べると、当時の気候や環境を知ることができる。", "target_word": "化石", "complexity_tier": "T3", "furigana": "かせきをくわしくしらべると、とうじのきこうやかんきょうをしることができる。", "sentence_source": "generated"}, {"text": "博物館には、アンモナイトの化石が数多く展示されている。", "target_word": "化石", "complexity_tier": "T3", "furigana": "はくぶつかんには、アンモナイトのかせきがかずおおくてんじされている。", "sentence_source": "generated"}, {"text": "琥珀の中に閉じ込められた昆虫の化石は、保存状態が非常に良い。", "target_word": "化石", "complexity_tier": "T3", "furigana": "こはくのなかにとじこめられたこんちゅうのかせきは、ほぞんじょうたいがひじょうによい。", "sentence_source": "generated"}, {"text": "化石の年代は、含まれる放射性元素の量から測定される。", "target_word": "化石", "complexity_tier": "T3", "furigana": "かせきのねんだいは、ふくまれるほうしゃせいげんそのりょうからそくていされる。", "sentence_source": "generated"}, {"text": "海から遠い山の中で貝の化石が出るのは、かつて海底だった証拠だ。", "target_word": "化石", "complexity_tier": "T3", "furigana": "うみからとおいやまのなかでかいのかせきがでるのは、かつてかいていだったしょうこだ。", "sentence_source": "generated"}, {"text": "発掘された化石は、慎重に岩から取り外されて研究室へ運ばれた。", "target_word": "化石", "complexity_tier": "T3", "furigana": "はっくつされたかせきは、しんちょうにいわからとりはずされてけんきゅうしつへはこばれた。", "sentence_source": "generated"}, {"text": "古生物学者は、わずかな化石の破片から生き物の姿を復元する。", "target_word": "化石", "complexity_tier": "T3", "furigana": "こせいぶつがくしゃは、わずかなかせきのはへんからいきもののすがたをふくげんする。", "sentence_source": "generated"}], "morphological_forms": [{"form": "化石", "label": "基本形"}], "register": "formal", "sense_fingerprint": "地中の生物遺骸が長年かけて石になったもの", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2cadf245-b057-4a4f-80e4-458d2df7fe35') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39411, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "化石", "is_correct": true, "explanation": "「植物の化石」として、大昔の植物が石になったものを指すので正しい。"}, {"text": "手紙", "is_correct": false, "explanation": "「植物の手紙」は意味をなさず、地層から大量に見つかるものとして合わない。"}, {"text": "金属", "is_correct": false, "explanation": "「植物の金属」は成り立たず、地層から大量に見つかるものとして合わない。"}, {"text": "産業", "is_correct": false, "explanation": "「植物の産業」は意味をなさず、この文脈に入らない。"}], "explanations": {"化石": "「植物の化石」として、大昔の植物が石になったものを指すので正しい。", "手紙": "「植物の手紙」は意味をなさず、地層から大量に見つかるものとして合わない。", "金属": "「植物の金属」は成り立たず、地層から大量に見つかるものとして合わない。", "産業": "「植物の産業」は意味をなさず、この文脈に入らない。"}, "sentence_index": 0, "correct_answer": "化石"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "このブローチには、珍しい水晶の化石がはめ込まれている。", "explanation": "ここは〈宝石〉の意味。化石は生き物が石になったものを指すので、水晶のような宝石には使わない。"}, {"text": "この土器は縄文時代の化石として、博物館に展示されている。", "explanation": "ここは〈遺物〉の意味。土器は人が作った物で、生き物が石になったものではないので化石とは言わない。"}, {"text": "祖先の化石を寺に納めて、供養した。", "explanation": "ここは〈遺骨〉の意味。近い時代の人の骨は化石とは言わず、化石は大昔の生き物を指す。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5fa85734-4702-4ee4-8b6d-fd6e1534aa8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39411, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "化石", "is_correct": true, "explanation": "放射性元素から年代を測る対象として自然。「化石の年代」は文脈に合う。"}, {"text": "電池", "is_correct": false, "explanation": "電池は放射性元素による年代測定の対象ではないので、文脈に合わない。"}, {"text": "教科書", "is_correct": false, "explanation": "教科書は年代測定の対象にならず、放射性元素の文脈と合わない。"}, {"text": "砂糖", "is_correct": false, "explanation": "砂糖の年代を放射性元素で測るという文脈は成り立たない。"}], "explanations": {"化石": "放射性元素から年代を測る対象として自然。「化石の年代」は文脈に合う。", "電池": "電池は放射性元素による年代測定の対象ではないので、文脈に合わない。", "教科書": "教科書は年代測定の対象にならず、放射性元素の文脈と合わない。", "砂糖": "砂糖の年代を放射性元素で測るという文脈は成り立たない。"}, "sentence_index": 6, "correct_answer": "化石"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "事故で壊れた飛行機の化石が、海底から引き上げられた。", "explanation": "ここは〈残骸〉の意味。化石は生き物が石になったもので、壊れた機械の残骸には使わない。"}, {"text": "実験のために、今朝採ったカエルの化石を標本箱に入れた。", "explanation": "ここは〈標本〉の意味。今朝採ったカエルは石になっていないので、化石とは言わない。"}, {"text": "この山では、金の化石が多く採れる。", "explanation": "ここは〈鉱石〉の意味。化石は生き物の遺骸が石になったもので、金属の鉱石には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5fa85734-4702-4ee4-8b6d-fd6e1534aa8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39411, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "夏の終わりに、川辺で魚の化石を見つかった。", "corrected_sentence": "夏の終わりに、川辺で魚の化石が見つかった。", "error_description": "「化石」に付く助詞が誤り。「見つかる」の主語を示すには「が」が正しく、「を」は目的語を示すので不適。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5fa85734-4702-4ee4-8b6d-fd6e1534aa8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39411, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "昨日、川の砂利から貝の化石が見つけた。", "corrected_sentence": "昨日、川の砂利から貝の化石が見つかった。", "error_description": "「化石」を主語にするなら自動詞「見つかる」を使う。「見つけた」は人が主語の他動詞で、ここでは不自然。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5fa85734-4702-4ee4-8b6d-fd6e1534aa8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39412, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「契機に」の「に」。きっかけとして、という意味で契機に付く格助詞で、ここが正しい。"}, {"text": "が", "is_correct": false, "explanation": "「留学を契機が、彼は」では、契機が主語になり、留学をきっかけにするという文の流れが崩れる。"}, {"text": "で", "is_correct": false, "explanation": "「契機で」は手段や場所の意味になり、きっかけを示す用法として不自然。"}, {"text": "と", "is_correct": false, "explanation": "「契機と」は並列の相手を示すが、きっかけとして文を続けることができない。"}], "correct_answer": "に", "explanations": {"に": "「契機に」の「に」。きっかけとして、という意味で契機に付く格助詞で、ここが正しい。", "が": "「留学を契機が、彼は」では、契機が主語になり、留学をきっかけにするという文の流れが崩れる。", "で": "「契機で」は手段や場所の意味になり、きっかけを示す用法として不自然。", "と": "「契機と」は並列の相手を示すが、きっかけとして文を続けることができない。"}, "error_tags": {"が": "主語", "で": "場所・手段", "と": "並列"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '14797358-abb1-41c2-b4e0-49bf54ce91a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39412, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「契機になった」の「に」。きっかけとして契機に付く格助詞で、ここが正しい。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す「へ」では、契機が向かう先になり、「なった」と続けると意味が通らない。"}, {"text": "から", "is_correct": false, "explanation": "起点を示す「から」では、契機から何かが生じるという意味になり、きっかけの文として不自然。"}, {"text": "を", "is_correct": false, "explanation": "「契機を」は目的語になるが、「なった」と続けると意味が成り立たない。"}], "correct_answer": "に", "explanations": {"に": "「契機になった」の「に」。きっかけとして契機に付く格助詞で、ここが正しい。", "へ": "方向を示す「へ」では、契機が向かう先になり、「なった」と続けると意味が通らない。", "から": "起点を示す「から」では、契機から何かが生じるという意味になり、きっかけの文として不自然。", "を": "「契機を」は目的語になるが、「なった」と続けると意味が成り立たない。"}, "error_tags": {"へ": "方向", "から": "起点", "を": "目的語"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '14797358-abb1-41c2-b4e0-49bf54ce91a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39412, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "何かが始まるきっかけになること。", "primary_collocate": null, "pronunciation": "けいき", "ipa": "keːki", "syllable_count": 3, "sentences": [{"text": "病気になったことが、生活を見直す契機になった。", "target_word": "契機", "complexity_tier": "T3", "furigana": "病気[びょうき]になったことが、生活[せいかつ]を見直[みなお]す契機[けいき]になった。", "sentence_source": "generated"}, {"text": "留学を契機に、彼は海外で働きたいと考え始めた。", "target_word": "契機", "complexity_tier": "T3", "furigana": "留学[りゅうがく]を契機[けいき]に、彼[かれ]は海外[かいがい]で働[はたら]きたいと考[かんが]え始[はじ]めた。", "sentence_source": "generated"}, {"text": "この事件を契機として、法律が改正された。", "target_word": "契機", "complexity_tier": "T3", "furigana": "この事件[じけん]を契機[けいき]として、法律[ほうりつ]が改正[かいせい]された。", "sentence_source": "generated"}, {"text": "友人の一言が、転職を考える契機だった。", "target_word": "契機", "complexity_tier": "T3", "furigana": "友人[ゆうじん]の一言[ひとこと]が、転職[てんしょく]を考[かんが]える契機[けいき]だった。", "sentence_source": "generated"}, {"text": "引っ越しを契機に、古い物を思い切って捨てた。", "target_word": "契機", "complexity_tier": "T3", "furigana": "引[ひ]っ越[こ]しを契機[けいき]に、古[ふる]い物[もの]を思[おも]い切[き]って捨[す]てた。", "sentence_source": "generated"}, {"text": "震災は、防災を考え直す大きな契機となった。", "target_word": "契機", "complexity_tier": "T3", "furigana": "震災[しんさい]は、防災[ぼうさい]を考[かんが]え直[なお]す大[おお]きな契機[けいき]となった。", "sentence_source": "generated"}, {"text": "結婚を契機に、彼女は仕事のやり方を変えた。", "target_word": "契機", "complexity_tier": "T3", "furigana": "結婚[けっこん]を契機[けいき]に、彼女[かのじょ]は仕事[しごと]のやり方[かた]を変[か]えた。", "sentence_source": "generated"}, {"text": "先生との出会いが、音楽を始める契機になった。", "target_word": "契機", "complexity_tier": "T3", "furigana": "先生[せんせい]との出会[であ]いが、音楽[おんがく]を始[はじ]める契機[けいき]になった。", "sentence_source": "generated"}, {"text": "今回の失敗を契機に、チームの運営を見直そう。", "target_word": "契機", "complexity_tier": "T3", "furigana": "今回[こんかい]の失敗[しっぱい]を契機[けいき]に、チームの運営[うんえい]を見直[みなお]そう。", "sentence_source": "generated"}, {"text": "入院を契機にたばこをやめ、体調がよくなった。", "target_word": "契機", "complexity_tier": "T3", "furigana": "入院[にゅういん]を契機[けいき]にたばこをやめ、体調[たいちょう]がよくなった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "契機", "label": "基本形"}, {"form": "契機に", "label": "に格"}, {"form": "契機として", "label": "として形"}, {"form": "契機となる", "label": "となる形"}], "register": "formal", "sense_fingerprint": "変化や新しい行動が始まるきっかけ", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4930162-e49e-4526-a312-ee6d7f8dd798') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39412, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "契機", "is_correct": true, "explanation": "何かが始まるきっかけのこと。「生活を見直す契機になった」は、病気が見直しのきっかけになったという自然な文。"}, {"text": "食材", "is_correct": false, "explanation": "料理に使う材料で、「生活を見直す食材になった」は文の意味が通らない。"}, {"text": "冷蔵庫", "is_correct": false, "explanation": "家電の一つで、病気が生活を見直すきっかけになったという文脈に合わない。"}, {"text": "湿気", "is_correct": false, "explanation": "じめじめした空気のことで、病気が生活を見直すきっかけになるという文脈には合わない。"}], "explanations": {"契機": "何かが始まるきっかけのこと。「生活を見直す契機になった」は、病気が見直しのきっかけになったという自然な文。", "食材": "料理に使う材料で、「生活を見直す食材になった」は文の意味が通らない。", "冷蔵庫": "家電の一つで、病気が生活を見直すきっかけになったという文脈に合わない。", "湿気": "じめじめした空気のことで、病気が生活を見直すきっかけになるという文脈には合わない。"}, "sentence_index": 0, "correct_answer": "契機"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "会社は新しい取引先と契機を結び、事業を広げた。", "explanation": "ここは〈契約〉の意味。契約は結ぶものだが、契機は始まりのきっかけを指すので結ぶとは言わない。"}, {"text": "工事の契機を毎週報告している。", "explanation": "ここは〈進行〉の意味。工事の経過を報告する場面なので、進行を使い、契機は合わない。"}, {"text": "彼女は母親としての契機を果たしている。", "explanation": "ここは〈役割〉の意味。役割は果たすものなので、契機を果たすとは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '14797358-abb1-41c2-b4e0-49bf54ce91a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39412, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "契機", "is_correct": true, "explanation": "何かが始まるきっかけのこと。「結婚を契機に」は、結婚をきっかけに変わったという自然な表現。"}, {"text": "寄付", "is_correct": false, "explanation": "お金や物を贈ることで、「結婚を寄付に」では意味が通らず、仕事のやり方が変わる文脈にも合わない。"}, {"text": "節約", "is_correct": false, "explanation": "お金を使わないことで、「結婚を節約に」は不自然で、変化のきっかけを表す文に入らない。"}, {"text": "作法", "is_correct": false, "explanation": "礼儀や手順のことで、「結婚を作法に」は文として成り立たず、仕事のやり方の変化とも合わない。"}], "explanations": {"契機": "何かが始まるきっかけのこと。「結婚を契機に」は、結婚をきっかけに変わったという自然な表現。", "寄付": "お金や物を贈ることで、「結婚を寄付に」では意味が通らず、仕事のやり方が変わる文脈にも合わない。", "節約": "お金を使わないことで、「結婚を節約に」は不自然で、変化のきっかけを表す文に入らない。", "作法": "礼儀や手順のことで、「結婚を作法に」は文として成り立たず、仕事のやり方の変化とも合わない。"}, "sentence_index": 6, "correct_answer": "契機"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "社会では環境保護の契機が高まっている。", "explanation": "ここは〈機運〉の意味。機運は高まるものだが、契機は高まるとは言わない。契機は何かが始まるきっかけを指す。"}, {"text": "先生は手を挙げて、出発の契機を送った。", "explanation": "ここは〈合図〉の意味。合図は送るものなので、契機を送るとは言わない。契機は何かが始まる時点を指す。"}, {"text": "彼女は毎日、英語の勉強に契機を重ねた。", "explanation": "ここは〈努力〉の意味。努力は重ねるものなので、契機を重ねるとは言わず、契機は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '14797358-abb1-41c2-b4e0-49bf54ce91a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39412, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "病気を契機で、生活を見直す人が増えた。", "corrected_sentence": "病気を契機に、生活を見直す人が増えた。", "error_description": "「契機」をきっかけの意味で使うときは「契機に」と言う。「契機で」の「で」は誤りで、正しくは「に」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '14797358-abb1-41c2-b4e0-49bf54ce91a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39412, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "その事故が、安全基準を見直す契機となるった。", "corrected_sentence": "その事故が、安全基準を見直す契機となった。", "error_description": "「なる」の過去形は「なった」なので、「となるった」は誤り。誤りは「なる」に付いた活用形。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '14797358-abb1-41c2-b4e0-49bf54ce91a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
