INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39413, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "「契機は」の「は」。文の主題を示す係助詞で、ここが正しい。"}, {"text": "を", "is_correct": false, "explanation": "「契機を、同じ電車に乗り合わせた」では契機が目的語になり、主題を示す文の形が崩れる。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す「へ」では、契機が向かう先になり、主語として文が成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "「契機と」は並列の相手を示すが、主題として文を続けることができない。"}], "correct_answer": "は", "explanations": {"は": "「契機は」の「は」。文の主題を示す係助詞で、ここが正しい。", "を": "「契機を、同じ電車に乗り合わせた」では契機が目的語になり、主題を示す文の形が崩れる。", "へ": "方向を示す「へ」では、契機が向かう先になり、主語として文が成り立たない。", "と": "「契機と」は並列の相手を示すが、主題として文を続けることができない。"}, "error_tags": {"を": "目的語", "へ": "方向", "と": "並列"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '14797358-abb1-41c2-b4e0-49bf54ce91a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39413, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "ある事柄が起こる原因やきっかけとなる出来事や時点。", "primary_collocate": null, "pronunciation": "けいき", "ipa": "keːki", "syllable_count": 3, "sentences": [{"text": "戦争の終結が、社会が大きく変わる契機となった。", "target_word": "契機", "complexity_tier": "T3", "furigana": "戦争[せんそう]の終結[しゅうけつ]が、社会[しゃかい]が大[おお]きく変[か]わる契機[けいき]となった。", "sentence_source": "generated"}, {"text": "あの発表は、会社が成長する契機だったと言われている。", "target_word": "契機", "complexity_tier": "T3", "furigana": "あの発表[はっぴょう]は、会社[かいしゃ]が成長[せいちょう]する契機[けいき]だったと言[い]われている。", "sentence_source": "generated"}, {"text": "技術の進歩は、産業が発展する契機をもたらした。", "target_word": "契機", "complexity_tier": "T3", "furigana": "技術[ぎじゅつ]の進歩[しんぽ]は、産業[さんぎょう]が発展[はってん]する契機[けいき]をもたらした。", "sentence_source": "generated"}, {"text": "万博の開催を契機に、街の交通網が整備された。", "target_word": "契機", "complexity_tier": "T3", "furigana": "万博[ばんぱく]の開催[かいさい]を契機[けいき]に、街[まち]の交通網[こうつうもう]が整備[せいび]された。", "sentence_source": "generated"}, {"text": "彼の死を契機として、家族の関係が変わっていった。", "target_word": "契機", "complexity_tier": "T3", "furigana": "彼[かれ]の死[し]を契機[けいき]として、家族[かぞく]の関係[かんけい]が変[か]わっていった。", "sentence_source": "generated"}, {"text": "都市の再開発の契機は、古い駅舎の火災だった。", "target_word": "契機", "complexity_tier": "T3", "furigana": "都市[とし]の再開発[さいかいはつ]の契機[けいき]は、古[ふる]い駅舎[えきしゃ]の火災[かさい]だった。", "sentence_source": "generated"}, {"text": "この発明は、人々の暮らしを変える契機を与えた。", "target_word": "契機", "complexity_tier": "T3", "furigana": "この発明[はつめい]は、人々[ひとびと]の暮[く]らしを変[か]える契機[けいき]を与[あた]えた。", "sentence_source": "generated"}, {"text": "二人が親しくなった契機は、同じ電車に乗り合わせたことだ。", "target_word": "契機", "complexity_tier": "T3", "furigana": "二人[ふたり]が親[した]しくなった契機[けいき]は、同[おな]じ電車[でんしゃ]に乗[の]り合[あ]わせたことだ。", "sentence_source": "generated"}, {"text": "政権交代を契機に、国の政策は大きく転換した。", "target_word": "契機", "complexity_tier": "T3", "furigana": "政権交代[せいけんこうたい]を契機[けいき]に、国[くに]の政策[せいさく]は大[おお]きく転換[てんかん]した。", "sentence_source": "generated"}, {"text": "事故の発生を契機として、安全基準が厳しくなった。", "target_word": "契機", "complexity_tier": "T3", "furigana": "事故[じこ]の発生[はっせい]を契機[けいき]として、安全基準[あんぜんきじゅん]が厳[きび]しくなった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "契機", "label": "基本形"}, {"form": "契機に", "label": "に格"}, {"form": "契機として", "label": "として形"}, {"form": "契機となる", "label": "となる形"}], "register": "formal", "sense_fingerprint": "ある事態を引き起こす原因となった出来事や時点", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4930162-e49e-4526-a312-ee6d7f8dd798') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39413, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "契機", "is_correct": true, "explanation": "ある事柄が起こる原因やきっかけとなる時点のこと。「社会が大きく変わる契機となった」は、戦争の終結が変化の引き金になったという文。"}, {"text": "方言", "is_correct": false, "explanation": "地域の言葉で、「社会が大きく変わる方言となった」は意味が通らない。"}, {"text": "天気", "is_correct": false, "explanation": "その日の空模様で、社会の変化を引き起こす要因にはならず、文脈に合わない。"}, {"text": "干潟", "is_correct": false, "explanation": "潮が引いて現れる海辺の泥地で、社会が大きく変わる出来事を指す文とはつながらない。"}], "explanations": {"契機": "ある事柄が起こる原因やきっかけとなる時点のこと。「社会が大きく変わる契機となった」は、戦争の終結が変化の引き金になったという文。", "方言": "地域の言葉で、「社会が大きく変わる方言となった」は意味が通らない。", "天気": "その日の空模様で、社会の変化を引き起こす要因にはならず、文脈に合わない。", "干潟": "潮が引いて現れる海辺の泥地で、社会が大きく変わる出来事を指す文とはつながらない。"}, "sentence_index": 0, "correct_answer": "契機"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は来年の契機を立てて、毎日走ることにした。", "explanation": "ここは〈目標〉の意味。目標は立てるものなので、契機を立てるとは言わない。契機は事が始まるきっかけを指す。"}, {"text": "その会社は地域の契機を果たしている。", "explanation": "ここは〈役割〉の意味。役割は果たすものなので、契機を果たすとは言わず、契機は合わない。"}, {"text": "経済の契機が上向き、会社の業績も良くなった。", "explanation": "ここは同じ読みの〈景気〉の意味。景気は上向くものだが、契機は上向くとは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '14797358-abb1-41c2-b4e0-49bf54ce91a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39413, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "契機", "is_correct": true, "explanation": "何かが始まるきっかけのこと。「暮らしを変える契機を与えた」は、発明が暮らしの変化のきっかけをもたらしたという自然な文。"}, {"text": "挨拶", "is_correct": false, "explanation": "人と会ったときの言葉で、「暮らしを変える挨拶を与えた」は意味が通らない。"}, {"text": "天気", "is_correct": false, "explanation": "空模様のことで、発明が暮らしを変えるきっかけになるという文脈に合わない。"}, {"text": "寝息", "is_correct": false, "explanation": "眠っているときの呼吸のことで、「暮らしを変える寝息を与えた」は文として成り立たない。"}], "explanations": {"契機": "何かが始まるきっかけのこと。「暮らしを変える契機を与えた」は、発明が暮らしの変化のきっかけをもたらしたという自然な文。", "挨拶": "人と会ったときの言葉で、「暮らしを変える挨拶を与えた」は意味が通らない。", "天気": "空模様のことで、発明が暮らしを変えるきっかけになるという文脈に合わない。", "寝息": "眠っているときの呼吸のことで、「暮らしを変える寝息を与えた」は文として成り立たない。"}, "sentence_index": 6, "correct_answer": "契機"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "先生は笛で、練習開始の契機を送った。", "explanation": "ここは〈合図〉の意味。合図は送るものなので、契機を送るとは言わない。契機は何かが始まる時点を指す。"}, {"text": "彼は毎日の練習に、大きな契機を重ねた。", "explanation": "ここは〈努力〉の意味。努力は重ねるものなので、契機を重ねるとは言わず、契機は合わない。"}, {"text": "その映画は、観客に強い契機を受けた。", "explanation": "ここは〈印象〉の意味。観客が受けるのは印象なので、強い印象を受けると言い、契機は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '14797358-abb1-41c2-b4e0-49bf54ce91a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39413, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "市長の決断を契機の、街の計画が動き出した。", "corrected_sentence": "市長の決断を契機に、街の計画が動き出した。", "error_description": "「契機」をきっかけとして使うときは「契機に」と言う。「契機の」の「の」は誤りで、正しくは「に」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '14797358-abb1-41c2-b4e0-49bf54ce91a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39413, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "大雨が、防災を見直す契機となるった。", "corrected_sentence": "大雨が、防災を見直す契機となった。", "error_description": "「なる」の過去形は「なった」なので、「となるった」は誤り。誤りは「なる」に付いた活用形。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '14797358-abb1-41c2-b4e0-49bf54ce91a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39414, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "主語を示す格助詞。「風力が弱い」で、風の力が弱いという状態の主語になる。"}, {"text": "を", "is_correct": false, "explanation": "目的語を示す格助詞で、「風力を弱い」では形容詞「弱い」の主語にならず成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "手段や場所を示す格助詞で、「風力で弱い」では状態の主語にならず不自然。"}, {"text": "から", "is_correct": false, "explanation": "起点を示す格助詞で、「風力から弱い」は「弱い」の主語にならず不自然。"}], "correct_answer": "が", "explanations": {"が": "主語を示す格助詞。「風力が弱い」で、風の力が弱いという状態の主語になる。", "を": "目的語を示す格助詞で、「風力を弱い」では形容詞「弱い」の主語にならず成り立たない。", "で": "手段や場所を示す格助詞で、「風力で弱い」では状態の主語にならず不自然。", "から": "起点を示す格助詞で、「風力から弱い」は「弱い」の主語にならず不自然。"}, "error_tags": {"を": "目的語（主語を示さない）", "で": "手段・場所（主語を示さない）", "から": "起点（主語を示さない）"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'afc7ec28-a387-4bb1-bfd6-5477845bd053') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39414, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "主語を示す格助詞で、「風力が増す」の主語として風の強さが増える主体を示す。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表す助詞で、「風力へ増す」では増える主体を示せず不自然。"}, {"text": "と", "is_correct": false, "explanation": "共同や引用を表す助詞で、「風力と増す」では主語を示せず成り立たない。"}, {"text": "より", "is_correct": false, "explanation": "比較の助詞で、「風力より増す」は比較の文型になっておらず不自然。"}], "correct_answer": "が", "explanations": {"が": "主語を示す格助詞で、「風力が増す」の主語として風の強さが増える主体を示す。", "へ": "方向を表す助詞で、「風力へ増す」では増える主体を示せず不自然。", "と": "共同や引用を表す助詞で、「風力と増す」では主語を示せず成り立たない。", "より": "比較の助詞で、「風力より増す」は比較の文型になっておらず不自然。"}, "error_tags": {"へ": "方向（主語を示さない）", "と": "共同・引用（主語を示さない）", "より": "比較（主語を示さない）"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'afc7ec28-a387-4bb1-bfd6-5477845bd053') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39414, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "風の力のことです。", "primary_collocate": null, "pronunciation": "ふうりょく", "ipa": "ɸɯːɾʲokɯ", "syllable_count": 4, "sentences": [{"text": "台風の風力はとても強かった。", "target_word": "風力", "complexity_tier": "T3", "furigana": "台風(たいふう)の風力(ふうりょく)はとても強(つよ)かった。", "sentence_source": "generated"}, {"text": "今日は風力が弱くて、洗濯物がなかなか乾かない。", "target_word": "風力", "complexity_tier": "T3", "furigana": "今日(きょう)は風力(ふうりょく)が弱(よわ)くて、洗濯物(せんたくもの)がなかなか乾(かわ)かない。", "sentence_source": "generated"}, {"text": "風力が強くて、この小さな船は大きく揺れた。", "target_word": "風力", "complexity_tier": "T3", "furigana": "風力(ふうりょく)が強(つよ)くて、この小(ちい)さな船(ふね)は大(おお)きく揺(ゆ)れた。", "sentence_source": "generated"}, {"text": "風力が強すぎて、傘が壊れてしまった。", "target_word": "風力", "complexity_tier": "T3", "furigana": "風力(ふうりょく)が強(つよ)すぎて、傘(かさ)が壊(こわ)れてしまった。", "sentence_source": "generated"}, {"text": "天気予報では、明日の風力は三になるそうだ。", "target_word": "風力", "complexity_tier": "T3", "furigana": "天気予報(てんきよほう)では、明日(あした)の風力(ふうりょく)は三(さん)になるそうだ。", "sentence_source": "generated"}, {"text": "海辺は風力が強いので、帆船の練習に向いている。", "target_word": "風力", "complexity_tier": "T3", "furigana": "海辺(うみべ)は風力(ふうりょく)が強(つよ)いので、帆船(はんせん)の練習(れんしゅう)に向(む)いている。", "sentence_source": "generated"}, {"text": "山の上は風力が強く、立っているのも大変だった。", "target_word": "風力", "complexity_tier": "T3", "furigana": "山(やま)の上(うえ)は風力(ふうりょく)が強(つよ)く、立(た)っているのも大変(たいへん)だった。", "sentence_source": "generated"}, {"text": "風力が増すにつれて、波も高くなってきた。", "target_word": "風力", "complexity_tier": "T3", "furigana": "風力(ふうりょく)が増(ま)すにつれて、波(なみ)も高(たか)くなってきた。", "sentence_source": "generated"}, {"text": "昔の人は、木の揺れを見て風力の強さを知った。", "target_word": "風力", "complexity_tier": "T3", "furigana": "昔(むかし)の人(ひと)は、木(き)の揺(ゆ)れを見(み)て風力(ふうりょく)の強(つよ)さを知(し)った。", "sentence_source": "generated"}, {"text": "風力が弱い日は、凧がうまく上がらない。", "target_word": "風力", "complexity_tier": "T3", "furigana": "風力(ふうりょく)が弱(よわ)い日(ひ)は、凧(たこ)がうまく上(あ)がらない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "風力", "label": "dictionary form (noun)"}, {"form": "風力が", "label": "with subject particle"}, {"form": "風力を", "label": "with object particle"}], "register": "neutral", "sense_fingerprint": "風の強さ、風の力の大きさ", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a6c39368-b1a1-4be5-ad73-c3324aee30fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39414, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "風力", "is_correct": true, "explanation": "風の強さを表す名詞。台風の風について「とても強かった」と続き、意味が通る。"}, {"text": "風向", "is_correct": false, "explanation": "風の吹いてくる方向を表すので、強さを表す「強かった」とは結びつかない。"}, {"text": "湿度", "is_correct": false, "explanation": "空気の湿り具合を表す語で、高い・低いで示すもので、風の強さを述べる対象ではない。"}, {"text": "気温", "is_correct": false, "explanation": "空気の温度を表すので、台風の風について「強かった」と述べる文には合わない。"}], "explanations": {"風力": "風の強さを表す名詞。台風の風について「とても強かった」と続き、意味が通る。", "風向": "風の吹いてくる方向を表すので、強さを表す「強かった」とは結びつかない。", "湿度": "空気の湿り具合を表す語で、高い・低いで示すもので、風の強さを述べる対象ではない。", "気温": "空気の温度を表すので、台風の風について「強かった」と述べる文には合わない。"}, "sentence_index": 0, "correct_answer": "風力"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "台風の風力が毎秒三十メートルを超えた。", "explanation": "ここは〈風速〉の意味。毎秒何メートルという速さは風速で表し、風力は風の強さを段階の数字で示す。"}, {"text": "この地域に風力注意報が出ている。", "explanation": "ここは〈強風〉の意味。注意報の名称は「強風注意報」で、風力は注意報の名前にはならない。"}, {"text": "この町は風力で電気をまかなっている。", "explanation": "ここは〈発電に使うエネルギー〉の意味。風の強さの段階ではなく、風が持つエネルギーを指す。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'afc7ec28-a387-4bb1-bfd6-5477845bd053') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39414, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "風力", "is_correct": true, "explanation": "風の強さを表す名詞。山の上について「風力が強く」と続け、強風の状態を述べる。"}, {"text": "標高", "is_correct": false, "explanation": "海抜の高さを表す語で、「強く」と続く力の大きさの対象にはならない。"}, {"text": "雲量", "is_correct": false, "explanation": "空の雲の量を表す語で、風の強さを述べる文には合わない。"}, {"text": "体温", "is_correct": false, "explanation": "人の体の温度を表す語で、山の上の気象状況を述べる文には合わない。"}], "explanations": {"風力": "風の強さを表す名詞。山の上について「風力が強く」と続け、強風の状態を述べる。", "標高": "海抜の高さを表す語で、「強く」と続く力の大きさの対象にはならない。", "雲量": "空の雲の量を表す語で、風の強さを述べる文には合わない。", "体温": "人の体の温度を表す語で、山の上の気象状況を述べる文には合わない。"}, "sentence_index": 6, "correct_answer": "風力"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "昨日の風力は十ミリを超えた。", "explanation": "ここは〈降水量〉の意味。雨の量はミリで表すもので、風力は風の強さの段階を示すので単位が合わない。"}, {"text": "今日の風力は六時間だった。", "explanation": "ここは〈日照時間〉の意味。日が照った時間を示す語で、風力は時間を表さない。"}, {"text": "一晩で風力が十センチに達した。", "explanation": "ここは〈積雪〉の意味。雪の深さを表す語で、風の強さは長さの単位では測らない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'afc7ec28-a387-4bb1-bfd6-5477845bd053') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39414, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "夕方は風力を弱くなって、ようやく涼しくなった。", "corrected_sentence": "夕方は風力が弱くなって、ようやく涼しくなった。", "error_description": "「風力」が「弱くなる」の主語になるので、格助詞は「が」を使う。「を」を付けると「風力を弱くなる」となり誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'afc7ec28-a387-4bb1-bfd6-5477845bd053') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39414, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "夜になると風力から増して、船は揺れ続けた。", "corrected_sentence": "夜になると風力が増して、船は揺れ続けた。", "error_description": "「風力」が「増す」の主語になるので、格助詞は「が」を使う。「から」は起点を示すため「風力から増す」は不自然。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'afc7ec28-a387-4bb1-bfd6-5477845bd053') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39415, 3, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'afc7ec28-a387-4bb1-bfd6-5477845bd053') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39415, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "目的語を示す格助詞。「風力を電気に変える」で、変換される対象を示す。"}, {"text": "より", "is_correct": false, "explanation": "比較の助詞で、「風力より電気に変える」は比較の文型にならず不自然。"}, {"text": "の", "is_correct": false, "explanation": "連体修飾の助詞で、「風力の電気に変える」では動詞の対象を示せない。"}, {"text": "に", "is_correct": false, "explanation": "結果を示す助詞だが、「電気に」の後に続けると「風力に電気に変える」となり二重に「に」が重なって不自然。"}], "correct_answer": "を", "explanations": {"を": "目的語を示す格助詞。「風力を電気に変える」で、変換される対象を示す。", "より": "比較の助詞で、「風力より電気に変える」は比較の文型にならず不自然。", "の": "連体修飾の助詞で、「風力の電気に変える」では動詞の対象を示せない。", "に": "結果を示す助詞だが、「電気に」の後に続けると「風力に電気に変える」となり二重に「に」が重なって不自然。"}, "error_tags": {"より": "比較（対象を示さない）", "の": "連体修飾（対象を示さない）", "に": "結果（二重になり不自然）"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'afc7ec28-a387-4bb1-bfd6-5477845bd053') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39415, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "風が持つエネルギーや、風が物を動かす力のこと。", "primary_collocate": null, "pronunciation": "ふうりょく", "ipa": "ɸɯːɾʲokɯ", "syllable_count": 4, "sentences": [{"text": "風力は、風が持つエネルギーを電気に変えて利用される。", "target_word": "風力", "complexity_tier": "T3", "furigana": "風力(ふうりょく)は、風(かぜ)が持(も)つエネルギーを電気(でんき)に変(か)えて利用(りよう)される。", "sentence_source": "generated"}, {"text": "この村では風力で水をくみ上げている。", "target_word": "風力", "complexity_tier": "T3", "furigana": "この村(むら)では風力(ふうりょく)で水(みず)をくみ上(あ)げている。", "sentence_source": "generated"}, {"text": "風力を使った発電所が、海の近くに建てられた。", "target_word": "風力", "complexity_tier": "T3", "furigana": "風力(ふうりょく)を使(つか)った発電所(はつでんしょ)が、海(うみ)の近(ちか)くに建(た)てられた。", "sentence_source": "generated"}, {"text": "風力で回る大きな羽根が、丘の上に並んでいる。", "target_word": "風力", "complexity_tier": "T3", "furigana": "風力(ふうりょく)で回(まわ)る大(おお)きな羽根(はね)が、丘(おか)の上(うえ)に並(なら)んでいる。", "sentence_source": "generated"}, {"text": "石油が減るなか、風力に注目する国が増えている。", "target_word": "風力", "complexity_tier": "T3", "furigana": "石油(せきゆ)が減(へ)るなか、風力(ふうりょく)に注目(ちゅうもく)する国(くに)が増(ふ)えている。", "sentence_source": "generated"}, {"text": "風力は自然の力なので、使っても資源がなくならない。", "target_word": "風力", "complexity_tier": "T3", "furigana": "風力(ふうりょく)は自然(しぜん)の力(ちから)なので、使(つか)っても資源(しげん)がなくならない。", "sentence_source": "generated"}, {"text": "オランダの風車は、風力で粉をひくために作られた。", "target_word": "風力", "complexity_tier": "T3", "furigana": "オランダの風車(ふうしゃ)は、風力(ふうりょく)で粉(こな)をひくために作(つく)られた。", "sentence_source": "generated"}, {"text": "風力を電気に変える技術が、年々進んでいる。", "target_word": "風力", "complexity_tier": "T3", "furigana": "風力(ふうりょく)を電気(でんき)に変(か)える技術(ぎじゅつ)が、年々(ねんねん)進(すす)んでいる。", "sentence_source": "generated"}, {"text": "風力だけで動く車の模型を、子どもたちが作った。", "target_word": "風力", "complexity_tier": "T3", "furigana": "風力(ふうりょく)だけで動(うご)く車(くるま)の模型(もけい)を、子(こ)どもたちが作(つく)った。", "sentence_source": "generated"}, {"text": "風の強い北の地方は、風力を利用するのに適している。", "target_word": "風力", "complexity_tier": "T3", "furigana": "風(かぜ)の強(つよ)い北(きた)の地方(ちほう)は、風力(ふうりょく)を利用(りよう)するのに適(てき)している。", "sentence_source": "generated"}], "morphological_forms": [{"form": "風力", "label": "dictionary form (noun)"}, {"form": "風力で", "label": "with means particle"}, {"form": "風力を", "label": "with object particle"}], "register": "neutral", "sense_fingerprint": "発電や動力に使う風のエネルギー", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a6c39368-b1a1-4be5-ad73-c3324aee30fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39415, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "風力", "is_correct": true, "explanation": "風が持つエネルギーを指す語で、そのエネルギーを電気に変えて利用される主語になる。"}, {"text": "雷雨", "is_correct": false, "explanation": "雷を伴う激しい雨の現象で、エネルギーを電気に変えて利用される対象ではない。"}, {"text": "湿気", "is_correct": false, "explanation": "空気中の水分を表す語で、風のエネルギーを電気に変える文の主語にはならない。"}, {"text": "霧雨", "is_correct": false, "explanation": "細かく降る雨を表す語で、風のエネルギーを利用する主語としては成り立たない。"}], "explanations": {"風力": "風が持つエネルギーを指す語で、そのエネルギーを電気に変えて利用される主語になる。", "雷雨": "雷を伴う激しい雨の現象で、エネルギーを電気に変えて利用される対象ではない。", "湿気": "空気中の水分を表す語で、風のエネルギーを電気に変える文の主語にはならない。", "霧雨": "細かく降る雨を表す語で、風のエネルギーを利用する主語としては成り立たない。"}, "sentence_index": 0, "correct_answer": "風力"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "丘の上には風力が並んでいる。", "explanation": "ここは〈風車〉の意味。羽根が回る設備は風車と言い、風力は風の力を指すので設備を並べる語にはならない。"}, {"text": "今朝の風力は、ようやく三になった。", "explanation": "ここは〈風の強さの段階〉の意味。風が持つエネルギーではなく、天気予報の風の強さを示す数字。"}, {"text": "上空の風力が北へ流れている。", "explanation": "ここは〈気流〉の意味。空気の流れは気流と言い、風力は力の大きさを指すので流れる対象にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'afc7ec28-a387-4bb1-bfd6-5477845bd053') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39415, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "風力", "is_correct": true, "explanation": "風の力を表す名詞。「風力で粉をひく」と手段を示し、風車の動力源になる。"}, {"text": "夕立", "is_correct": false, "explanation": "夕方の激しい雨で、粉をひく動力にはならない。"}, {"text": "眠気", "is_correct": false, "explanation": "眠りたい感覚を表す語で、粉をひく手段として成り立たない。"}, {"text": "絵の具", "is_correct": false, "explanation": "色をつける材料で、粉をひく動力にはならない。"}], "explanations": {"風力": "風の力を表す名詞。「風力で粉をひく」と手段を示し、風車の動力源になる。", "夕立": "夕方の激しい雨で、粉をひく動力にはならない。", "眠気": "眠りたい感覚を表す語で、粉をひく手段として成り立たない。", "絵の具": "色をつける材料で、粉をひく動力にはならない。"}, "sentence_index": 6, "correct_answer": "風力"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "今日は風力が北から南に変わった。", "explanation": "ここは〈風向〉の意味。風の吹いてくる方向は風向で、風力は力の大きさを表すので方向は変わらない。"}, {"text": "今日の風力は六十パーセントだった。", "explanation": "ここは〈湿度〉の意味。空気の中の水分の割合は湿度で表し、風力は風の強さを指すので割合では表せない。"}, {"text": "今朝の風力は五度まで下がった。", "explanation": "ここは〈気温〉の意味。空気の温かさを表す語で、風の力の大きさは温度では表せない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'afc7ec28-a387-4bb1-bfd6-5477845bd053') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39415, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "丘の上の大きな羽根が、風力に回っている。", "corrected_sentence": "丘の上の大きな羽根が、風力で回っている。", "error_description": "風の力を使って回るときは手段の「で」を使う。「に」を使うと「風力に回る」となり不自然。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'afc7ec28-a387-4bb1-bfd6-5477845bd053') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39415, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この古い製粉所は、風力から動く羽根を使って粉をひいている。", "corrected_sentence": "この古い製粉所は、風力で動く羽根を使って粉をひいている。", "error_description": "風の力を手段として示すので「で」を使う。「から」は起点を示すため「風力から動く」は不自然。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'afc7ec28-a387-4bb1-bfd6-5477845bd053') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39416, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "で", "is_correct": false, "explanation": "『主軸で』は手段や場所を示すので、『主軸にして』の形に合わない。"}, {"text": "に", "is_correct": true, "explanation": "『〜を主軸にする』の形で結果や位置づけを示す『に』が正しい。"}, {"text": "を", "is_correct": false, "explanation": "『主軸を』は直接の目的語を示すが、後ろの『して』とつながらず不自然になる。"}, {"text": "へ", "is_correct": false, "explanation": "『主軸へ』は方向を示すので、ここでは意味が通らない。"}], "correct_answer": "に", "explanations": {"で": "『主軸で』は手段や場所を示すので、『主軸にして』の形に合わない。", "に": "『〜を主軸にする』の形で結果や位置づけを示す『に』が正しい。", "を": "『主軸を』は直接の目的語を示すが、後ろの『して』とつながらず不自然になる。", "へ": "『主軸へ』は方向を示すので、ここでは意味が通らない。"}, "error_tags": {"で": "手段・場所", "を": "対象", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7d645761-a470-43e1-a068-67a54f16899d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39416, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "と", "is_correct": false, "explanation": "『主軸と』は並列や相手を示し、『はっきりしない』の主語にはならない。"}, {"text": "から", "is_correct": false, "explanation": "『主軸から』は起点を示し、ここでは文が不自然になる。"}, {"text": "の", "is_correct": false, "explanation": "『主軸の』は修飾を示すので、『はっきりしない』の主語として文が成り立たない。"}, {"text": "が", "is_correct": true, "explanation": "『主軸が』は主語を示し、『はっきりしない』へ続く正しい形。"}], "correct_answer": "が", "explanations": {"と": "『主軸と』は並列や相手を示し、『はっきりしない』の主語にはならない。", "から": "『主軸から』は起点を示し、ここでは文が不自然になる。", "の": "『主軸の』は修飾を示すので、『はっきりしない』の主語として文が成り立たない。", "が": "『主軸が』は主語を示し、『はっきりしない』へ続く正しい形。"}, "error_tags": {"と": "並列・相手", "から": "起点", "の": "修飾"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7d645761-a470-43e1-a068-67a54f16899d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39416, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物事の中心になる大事なもの。", "primary_collocate": null, "pronunciation": "しゅじく", "ipa": "ɕɯdʑikɯ", "syllable_count": 3, "sentences": [{"text": "新しい事業では、環境にやさしい商品づくりが主軸になります。", "target_word": "主軸", "complexity_tier": "T3", "furigana": "新[あたら]しい事業[じぎょう]では、環境[かんきょう]にやさしい商品[しょうひん]づくりが主軸[しゅじく]になります。", "sentence_source": "generated"}, {"text": "この会社は海外販売を主軸にして、売り上げを伸ばしてきた。", "target_word": "主軸", "complexity_tier": "T3", "furigana": "この会社[かいしゃ]は海外[かいがい]販売[はんばい]を主軸[しゅじく]にして、売[う]り上[あ]げを伸[の]ばしてきた。", "sentence_source": "generated"}, {"text": "監督は守りを主軸にしたチームづくりを進めている。", "target_word": "主軸", "complexity_tier": "T3", "furigana": "監督[かんとく]は守[まも]りを主軸[しゅじく]にしたチームづくりを進[すす]めている。", "sentence_source": "generated"}, {"text": "今年の計画は、地域の人との交流を主軸に考えました。", "target_word": "主軸", "complexity_tier": "T3", "furigana": "今年[ことし]の計画[けいかく]は、地域[ちいき]の人[ひと]との交流[こうりゅう]を主軸[しゅじく]に考[かんが]えました。", "sentence_source": "generated"}, {"text": "店の主軸は人気のカレーで、ほかのメニューは少ない。", "target_word": "主軸", "complexity_tier": "T3", "furigana": "店[みせ]の主軸[しゅじく]は人気[にんき]のカレーで、ほかのメニューは少[すく]ない。", "sentence_source": "generated"}, {"text": "このドラマは親子の関係が主軸で、恋愛の話は少しだけ出てくる。", "target_word": "主軸", "complexity_tier": "T3", "furigana": "このドラマは親子[おやこ]の関係[かんけい]が主軸[しゅじく]で、恋愛[れんあい]の話[はなし]は少[すこ]しだけ出[で]てくる。", "sentence_source": "generated"}, {"text": "彼は研究の主軸を変えずに、新しい方法を試した。", "target_word": "主軸", "complexity_tier": "T3", "furigana": "彼[かれ]は研究[けんきゅう]の主軸[しゅじく]を変[か]えずに、新[あたら]しい方法[ほうほう]を試[ため]した。", "sentence_source": "generated"}, {"text": "話の主軸がはっきりしないと、聞く人は内容がわかりません。", "target_word": "主軸", "complexity_tier": "T3", "furigana": "話[はなし]の主軸[しゅじく]がはっきりしないと、聞[き]く人[ひと]は内容[ないよう]がわかりません。", "sentence_source": "generated"}, {"text": "農業を主軸とする町では、収穫の時期がいちばん忙しい。", "target_word": "主軸", "complexity_tier": "T3", "furigana": "農業[のうぎょう]を主軸[しゅじく]とする町[まち]では、収穫[しゅうかく]の時期[じき]がいちばん忙[いそが]しい。", "sentence_source": "generated"}, {"text": "授業はグループ活動を主軸にして、先生は少し助けるだけだ。", "target_word": "主軸", "complexity_tier": "T3", "furigana": "授業[じゅぎょう]はグループ活動[かつどう]を主軸[しゅじく]にして、先生[せんせい]は少[すこ]し助[たす]けるだけだ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "主軸", "label": "基本形"}], "register": "中立（やや硬い書き言葉寄り）", "sense_fingerprint": "計画・事業・活動などの中心となる大事なもの", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f839c227-2f16-4265-b473-70b89a9b588c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39416, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "残高", "is_correct": false, "explanation": "預金や残りの金額を表す語で、商品づくりが中心になるという文脈には入らない。"}, {"text": "主軸", "is_correct": true, "explanation": "事業の中心になる大事なものという意味で、ここに合う。"}, {"text": "利息", "is_correct": false, "explanation": "お金に付く利子を表す語で、商品づくりの説明としては意味が通らない。"}, {"text": "手数料", "is_correct": false, "explanation": "取引で支払う料金を表す語で、商品づくりが何かになるという文には合わない。"}], "explanations": {"残高": "預金や残りの金額を表す語で、商品づくりが中心になるという文脈には入らない。", "主軸": "事業の中心になる大事なものという意味で、ここに合う。", "利息": "お金に付く利子を表す語で、商品づくりの説明としては意味が通らない。", "手数料": "取引で支払う料金を表す語で、商品づくりが何かになるという文には合わない。"}, "sentence_index": 0, "correct_answer": "主軸"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼はこの映画で主軸を演じ、観客の注目を集めた。", "explanation": "ここは〈主役〉の意味。『役を演じる』の役は主役を指すが、主軸は物事の中心を指すので、俳優の役としては使わない。"}, {"text": "この家の主軸が古くなったので、建て替えることにした。", "explanation": "ここは建物を支える柱の意味。主軸は計画や活動の中心を指すので、家の柱には使わない。"}, {"text": "細胞の主軸には、遺伝の情報が書かれている。", "explanation": "ここは細胞の中心にある核の意味。主軸は計画や活動の中心を指すので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7d645761-a470-43e1-a068-67a54f16899d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39416, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "湿度", "is_correct": false, "explanation": "空気中の水分の割合を表す語で、研究の中心を変えるという文とはつながらない。"}, {"text": "主軸", "is_correct": true, "explanation": "研究の中心になる大事なものという意味で、ここに合う。"}, {"text": "体重", "is_correct": false, "explanation": "体の重さを表す語で、研究の何かを変えるという文には合わない。"}, {"text": "気温", "is_correct": false, "explanation": "空気の温度を表す語で、研究の一部として変えるという文には入らない。"}], "explanations": {"湿度": "空気中の水分の割合を表す語で、研究の中心を変えるという文とはつながらない。", "主軸": "研究の中心になる大事なものという意味で、ここに合う。", "体重": "体の重さを表す語で、研究の何かを変えるという文には合わない。", "気温": "空気の温度を表す語で、研究の一部として変えるという文には入らない。"}, "sentence_index": 6, "correct_answer": "主軸"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "人の体では、主軸が血液を全身に送り出している。", "explanation": "ここは臓器の心臓の意味。主軸は計画や活動、話などの中心を指すので、体の器官には使わない。"}, {"text": "この橋の主軸は、コンクリートでしっかり作られている。", "explanation": "ここは橋などを支える土台の意味。主軸は計画や活動の中心を指すので合わない。"}, {"text": "工作機械の主軸が折れて、作業を止めた。", "explanation": "ここは機械の回転軸の意味。主軸は計画や活動、話などの中心を指すので、機械の部品としては使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7d645761-a470-43e1-a068-67a54f16899d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39416, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この研究所では、環境の調査を主軸で据えている。", "corrected_sentence": "この研究所では、環境の調査を主軸に据えている。", "error_description": "「主軸に据える」の「に」が「で」になっている。『〜を主軸に据える』が正しく、『主軸で据える』は成り立たない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7d645761-a470-43e1-a068-67a54f16899d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39416, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "今年の事業は、若者の雇用を主軸をする予定だ。", "corrected_sentence": "今年の事業は、若者の雇用を主軸にする予定だ。", "error_description": "「主軸にする」の「に」が「を」になっている。『〜を主軸にする』が正しく、『主軸をする』は文として不自然になる。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7d645761-a470-43e1-a068-67a54f16899d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39417, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "が", "is_correct": false, "explanation": "『主軸が』は主語を示すが、後ろに『には』が続くので不自然になる。"}, {"text": "を", "is_correct": false, "explanation": "『主軸を』は目的語を示すが、ここでは『には』とつながらない。"}, {"text": "へ", "is_correct": false, "explanation": "『主軸へ』は方向を示すので、話題を示す文には合わない。"}, {"text": "に", "is_correct": true, "explanation": "『主軸には』で、考えの中心をめぐる話題を示す『に』が正しい。"}], "correct_answer": "に", "explanations": {"が": "『主軸が』は主語を示すが、後ろに『には』が続くので不自然になる。", "を": "『主軸を』は目的語を示すが、ここでは『には』とつながらない。", "へ": "『主軸へ』は方向を示すので、話題を示す文には合わない。", "に": "『主軸には』で、考えの中心をめぐる話題を示す『に』が正しい。"}, "error_tags": {"が": "主語", "を": "対象", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7d645761-a470-43e1-a068-67a54f16899d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39417, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "と", "options": [{"text": "で", "is_correct": false, "explanation": "『主軸で』は手段を示すので、『としている』とはつながらない。"}, {"text": "から", "is_correct": false, "explanation": "『主軸から』は起点を示し、ここでは文が不自然になる。"}, {"text": "の", "is_correct": false, "explanation": "『主軸の』は修飾を示すので、『している』に続く述語にならない。"}, {"text": "と", "is_correct": true, "explanation": "『主軸としている』で、位置づけを示す『と』が正しい。"}], "correct_answer": "と", "explanations": {"で": "『主軸で』は手段を示すので、『としている』とはつながらない。", "から": "『主軸から』は起点を示し、ここでは文が不自然になる。", "の": "『主軸の』は修飾を示すので、『している』に続く述語にならない。", "と": "『主軸としている』で、位置づけを示す『と』が正しい。"}, "error_tags": {"で": "手段", "から": "起点", "の": "修飾"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7d645761-a470-43e1-a068-67a54f16899d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39417, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物事の中心となる、重要な部分や考え方。", "primary_collocate": null, "pronunciation": "しゅじく", "ipa": "ɕɯdʑikɯ", "syllable_count": 3, "sentences": [{"text": "この論文の主軸は、子どもの睡眠と成績の関係にある。", "target_word": "主軸", "complexity_tier": "T3", "furigana": "この論文[ろんぶん]の主軸[しゅじく]は、子[こ]どもの睡眠[すいみん]と成績[せいせき]の関係[かんけい]にある。", "sentence_source": "generated"}, {"text": "彼の考えの主軸には、いつも人を大切にする気持ちがある。", "target_word": "主軸", "complexity_tier": "T3", "furigana": "彼[かれ]の考[かんが]えの主軸[しゅじく]には、いつも人[ひと]を大切[たいせつ]にする気持[きも]ちがある。", "sentence_source": "generated"}, {"text": "話し合いでは、先生の意見を主軸にして、案をまとめました。", "target_word": "主軸", "complexity_tier": "T3", "furigana": "話[はな]し合[あ]いでは、先生[せんせい]の意見[いけん]を主軸[しゅじく]にして、案[あん]をまとめました。", "sentence_source": "generated"}, {"text": "物語の主軸は兄弟の友情で、事件はその背景にすぎない。", "target_word": "主軸", "complexity_tier": "T3", "furigana": "物語[ものがたり]の主軸[しゅじく]は兄弟[きょうだい]の友情[ゆうじょう]で、事件[じけん]はその背景[はいけい]にすぎない。", "sentence_source": "generated"}, {"text": "会議の主軸になった意見は、費用を減らす案でした。", "target_word": "主軸", "complexity_tier": "T3", "furigana": "会議[かいぎ]の主軸[しゅじく]になった意見[いけん]は、費用[ひよう]を減[へ]らす案[あん]でした。", "sentence_source": "generated"}, {"text": "計画の主軸が決まったので、細かい部分は後で考えましょう。", "target_word": "主軸", "complexity_tier": "T3", "furigana": "計画[けいかく]の主軸[しゅじく]が決[き]まったので、細[こま]かい部分[ぶぶん]は後[あと]で考[かんが]えましょう。", "sentence_source": "generated"}, {"text": "小説の主軸をしっかり決めてから、書き始めるつもりだ。", "target_word": "主軸", "complexity_tier": "T3", "furigana": "小説[しょうせつ]の主軸[しゅじく]をしっかり決[き]めてから、書[か]き始[はじ]めるつもりだ。", "sentence_source": "generated"}, {"text": "この政党は、教育の改善を政策の主軸としている。", "target_word": "主軸", "complexity_tier": "T3", "furigana": "この政党[せいとう]は、教育[きょういく]の改善[かいぜん]を政策[せいさく]の主軸[しゅじく]としている。", "sentence_source": "generated"}, {"text": "発表の主軸がずれると、全体がわかりにくくなる。", "target_word": "主軸", "complexity_tier": "T3", "furigana": "発表[はっぴょう]の主軸[しゅじく]がずれると、全体[ぜんたい]がわかりにくくなる。", "sentence_source": "generated"}, {"text": "私の生活の主軸は仕事ではなく、家族と過ごす時間です。", "target_word": "主軸", "complexity_tier": "T3", "furigana": "私[わたし]の生活[せいかつ]の主軸[しゅじく]は仕事[しごと]ではなく、家族[かぞく]と過[す]ごす時間[じかん]です。", "sentence_source": "generated"}], "morphological_forms": [{"form": "主軸", "label": "基本形"}], "register": "中立（やや硬い書き言葉寄り）", "sense_fingerprint": "話・考え・作品などの中心となる重要な部分や考え方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f839c227-2f16-4265-b473-70b89a9b588c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39417, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "座席", "is_correct": false, "explanation": "乗り物や会場で座る場所を表す語で、論文の中心という意味には合わない。"}, {"text": "気温", "is_correct": false, "explanation": "空気の温度を表す語で、論文の中心を説明する文には入らない。"}, {"text": "主軸", "is_correct": true, "explanation": "論文の中心になる重要な部分という意味で、ここに合う。"}, {"text": "利息", "is_correct": false, "explanation": "お金に付く利子を表す語で、論文の内容としては意味が通らない。"}], "explanations": {"座席": "乗り物や会場で座る場所を表す語で、論文の中心という意味には合わない。", "気温": "空気の温度を表す語で、論文の中心を説明する文には入らない。", "主軸": "論文の中心になる重要な部分という意味で、ここに合う。", "利息": "お金に付く利子を表す語で、論文の内容としては意味が通らない。"}, "sentence_index": 0, "correct_answer": "主軸"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "工場の機械の主軸を交換するため、作業を一時止めた。", "explanation": "ここは機械の回転軸の意味。話や考えの中心を指す主軸とは別の意味なので合わない。"}, {"text": "この建物の主軸は古くなって、少しかたむいている。", "explanation": "ここは建物を支える柱の意味。話や考えの中心となる部分の意味では合わない。"}, {"text": "細胞の主軸は、遺伝の情報を守る大切な部分だ。", "explanation": "ここは細胞の核の意味。話や考えの中心を指す主軸とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7d645761-a470-43e1-a068-67a54f16899d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39417, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "残高", "is_correct": false, "explanation": "預金や残りの金額を表す語で、小説を決めるという文には合わない。"}, {"text": "主軸", "is_correct": true, "explanation": "小説の中心になる重要な部分という意味で、ここに合う。"}, {"text": "手数料", "is_correct": false, "explanation": "取引で支払う料金を表す語で、小説の内容を決めるという文には入らない。"}, {"text": "湿度", "is_correct": false, "explanation": "空気中の水分の割合を表す語で、小説の内容を決める文とはつながらない。"}], "explanations": {"残高": "預金や残りの金額を表す語で、小説を決めるという文には合わない。", "主軸": "小説の中心になる重要な部分という意味で、ここに合う。", "手数料": "取引で支払う料金を表す語で、小説の内容を決めるという文には入らない。", "湿度": "空気中の水分の割合を表す語で、小説の内容を決める文とはつながらない。"}, "sentence_index": 6, "correct_answer": "主軸"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "心臓の主軸が弱まると、全身に血液が回りにくくなる。", "explanation": "ここは臓器の心臓の意味。主軸は話や考えの中心を指すので、体の器官には使わない。"}, {"text": "このビルの主軸は地下にあり、地震の揺れを受け止める。", "explanation": "ここは建物を支える土台の意味。話や考えの中心となる部分の意味では合わない。"}, {"text": "鉛筆の主軸が折れてしまい、書けなくなった。", "explanation": "ここは〈芯〉の意味。鉛筆の中の黒い部分は芯と言い、主軸は物事の中心を指すので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7d645761-a470-43e1-a068-67a54f16899d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39417, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼は話の主軸が家族の思い出に置いた。", "corrected_sentence": "彼は話の主軸を家族の思い出に置いた。", "error_description": "「主軸を置く」の「を」が「が」になっている。『〜を〜に置く』の形が正しく、『主軸が』では置く対象がなく文が成り立たない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7d645761-a470-43e1-a068-67a54f16899d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39417, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "会議の主軸をなったのは、費用の削減だ。", "corrected_sentence": "会議の主軸となったのは、費用の削減だ。", "error_description": "「主軸となる」の「と」が「を」になっている。『〜となる』が正しく、『主軸をなった』は成り立たない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7d645761-a470-43e1-a068-67a54f16899d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
