INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39418, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "二十と一の数のことです。", "primary_collocate": null, "pronunciation": "にじゅういち", "ipa": "nidʑɯːitɕi", "syllable_count": 5, "sentences": [{"text": "11に10を足すと、答えは「21」になります。", "target_word": "21", "complexity_tier": "T3", "furigana": "11に10を足[た]すと、答[こた]えは「21[にじゅういち]」になります。", "sentence_source": "generated"}, {"text": "20の次の数は「21」です。", "target_word": "21", "complexity_tier": "T3", "furigana": "20の次[つぎ]の数[かず]は「21[にじゅういち]」です。", "sentence_source": "generated"}, {"text": "クラスの人数は「21」人で、全員がそろっている。", "target_word": "21", "complexity_tier": "T3", "furigana": "クラスの人数[にんずう]は「21[にじゅういち]」人[にん]で、全員[ぜんいん]がそろっている。", "sentence_source": "generated"}, {"text": "42を2で割ると、「21」になる。", "target_word": "21", "complexity_tier": "T3", "furigana": "42を2で割[わ]ると、「21[にじゅういち]」になる。", "sentence_source": "generated"}, {"text": "3に7をかけると「21」になります。", "target_word": "21", "complexity_tier": "T3", "furigana": "3に7をかけると「21[にじゅういち]」になります。", "sentence_source": "generated"}, {"text": "ブラックジャックは、カードの合計が「21」に近いほうが勝つゲームです。", "target_word": "21", "complexity_tier": "T3", "furigana": "ブラックジャックは、カードの合計[ごうけい]が「21[にじゅういち]」に近[ちか]いほうが勝[か]つゲームです。", "sentence_source": "generated"}, {"text": "箱の中の玉を数えると、全部で「21」個でした。", "target_word": "21", "complexity_tier": "T3", "furigana": "箱[はこ]の中[なか]の玉[たま]を数[かぞ]えると、全部[ぜんぶ]で「21[にじゅういち]」個[こ]でした。", "sentence_source": "generated"}, {"text": "くじの景品は全部で「21」個ありました。", "target_word": "21", "complexity_tier": "T3", "furigana": "くじの景品[けいひん]は全部[ぜんぶ]で「21[にじゅういち]」個[こ]ありました。", "sentence_source": "generated"}, {"text": "31から10を引くと、残りは「21」です。", "target_word": "21", "complexity_tier": "T3", "furigana": "31から10を引[ひ]くと、残[のこ]りは「21[にじゅういち]」です。", "sentence_source": "generated"}, {"text": "数字の並びは19、20と続いて、次が「21」です。", "target_word": "21", "complexity_tier": "T3", "furigana": "数字[すうじ]の並[なら]びは19、20と続[つづ]いて、次[つぎ]が「21[にじゅういち]」です。", "sentence_source": "generated"}], "morphological_forms": [{"form": "21", "label": "基本形"}], "register": "中立", "sense_fingerprint": "二十と一を合わせた数、にじゅういち", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f839c227-2f16-4265-b473-70b89a9b588c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39418, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "残高", "is_correct": false, "explanation": "預金や残りの金額を表す語で、足し算の答えを示す文には入らない。"}, {"text": "差", "is_correct": false, "explanation": "引き算の結果を表す語で、11と10を足した答えとしては入らない。"}, {"text": "21", "is_correct": true, "explanation": "11と10を足すと21になるので、答えとしてここに入る。"}, {"text": "積", "is_correct": false, "explanation": "掛け算の結果を表す語で、足し算の答えとしては入らない。"}], "explanations": {"残高": "預金や残りの金額を表す語で、足し算の答えを示す文には入らない。", "差": "引き算の結果を表す語で、11と10を足した答えとしては入らない。", "21": "11と10を足すと21になるので、答えとしてここに入る。", "積": "掛け算の結果を表す語で、足し算の答えとしては入らない。"}, "sentence_index": 0, "correct_answer": "21"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "参加者のうち、21番目に並んだのは私だった。", "explanation": "ここは順番の意味（二十一番目）。数量の二十一とは別の使い方なので合わない。"}, {"text": "明日の夜は21時に集まって、一緒に映画を見よう。", "explanation": "ここは時刻の意味（二十一時）。数としての二十一の定義とは合わない。"}, {"text": "この建物の部屋の番号は21号室で、三階にある。", "explanation": "ここは部屋番号としての意味。数量の二十一を表すのではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7d645761-a470-43e1-a068-67a54f16899d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39418, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "余り", "is_correct": false, "explanation": "割り算で残った数を表す語で、玉の個数を数えた文には入らない。"}, {"text": "平方根", "is_correct": false, "explanation": "同じ数を二回かけて元に戻す数を表す語で、番号としては入らない。"}, {"text": "倍数", "is_correct": false, "explanation": "ある数の何倍かになる数を表す語で、玉の個数としては入らない。"}, {"text": "21", "is_correct": true, "explanation": "玉を数えた個数として、ここに入る数字。"}], "explanations": {"余り": "割り算で残った数を表す語で、玉の個数を数えた文には入らない。", "平方根": "同じ数を二回かけて元に戻す数を表す語で、番号としては入らない。", "倍数": "ある数の何倍かになる数を表す語で、玉の個数としては入らない。", "21": "玉を数えた個数として、ここに入る数字。"}, "sentence_index": 6, "correct_answer": "21"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "その試合では、背番号21の選手が得点を決めた。", "explanation": "ここは背番号の意味。数量の二十一を表すのではないので合わない。"}, {"text": "21世紀に入ってから、この町の人口は増え続けている。", "explanation": "ここは世紀の番号の意味。数量の二十一とは違う使い方なので合わない。"}, {"text": "この住所は、駅前の21番地にある。", "explanation": "ここは番地の意味。数量の二十一を表すのではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7d645761-a470-43e1-a068-67a54f16899d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
