INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39419, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "20に1を足した数。二十一。", "primary_collocate": null, "pronunciation": "にじゅういち", "ipa": "nidʑɯːitɕi", "syllable_count": 5, "sentences": [{"text": "20に1を足した数は「21」だ。", "target_word": "21", "complexity_tier": "T3", "furigana": "20に1を足[た]した数[かず]は「21[にじゅういち]」だ。", "sentence_source": "generated"}, {"text": "店で買い物の金額を計算すると、合計は「21」円になった。", "target_word": "21", "complexity_tier": "T3", "furigana": "店[みせ]で買[か]い物[もの]の金額[きんがく]を計算[けいさん]すると、合計[ごうけい]は「21[にじゅういち]」円[えん]になった。", "sentence_source": "generated"}, {"text": "7の3倍は「21」なので、答えは簡単に出せる。", "target_word": "21", "complexity_tier": "T3", "furigana": "7の3倍[さんばい]は「21[にじゅういち]」なので、答[こた]えは簡単[かんたん]に出[だ]せる。", "sentence_source": "generated"}, {"text": "20より1多い数は「21」で、数えやすい。", "target_word": "21", "complexity_tier": "T3", "furigana": "20より1[いち]多[おお]い数[かず]は「21[にじゅういち]」で、数[かぞ]えやすい。", "sentence_source": "generated"}, {"text": "9と12を足すと「21」になるので、すぐに計算できた。", "target_word": "21", "complexity_tier": "T3", "furigana": "9と12を足[た]すと「21[にじゅういち]」になるので、すぐに計算[けいさん]できた。", "sentence_source": "generated"}, {"text": "100から79を引くと、「21」が残ります。", "target_word": "21", "complexity_tier": "T3", "furigana": "100から79を引[ひ]くと、「21[にじゅういち]」が残[のこ]ります。", "sentence_source": "generated"}, {"text": "地図の上に赤い数字が書いてあり、いちばん大きいのは「21」だった。", "target_word": "21", "complexity_tier": "T3", "furigana": "地図[ちず]の上[うえ]に赤[あか]い数字[すうじ]が書[か]いてあり、いちばん大[おお]きいのは「21[にじゅういち]」だった。", "sentence_source": "generated"}, {"text": "問題の答えは「21」だと思ったが、計算が違っていた。", "target_word": "21", "complexity_tier": "T3", "furigana": "問題[もんだい]の答[こた]えは「21[にじゅういち]」だと思[おも]ったが、計算[けいさん]が違[ちが]っていた。", "sentence_source": "generated"}, {"text": "「21」は奇数なので、2では割り切れません。", "target_word": "21", "complexity_tier": "T3", "furigana": "「21[にじゅういち]」は奇数[きすう]なので、2では割[わ]り切[き]れません。", "sentence_source": "generated"}, {"text": "18に3を足せば、「21」になる。", "target_word": "21", "complexity_tier": "T3", "furigana": "18に3を足[た]せば、「21[にじゅういち]」になる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "21", "label": "基本形"}], "register": "中立", "sense_fingerprint": "20に1を足した数、二十一", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f839c227-2f16-4265-b473-70b89a9b588c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
