INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39419, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "合計", "is_correct": false, "explanation": "足し算の結果を表す語で、地図の数字として一番大きいものという文には入らない。"}, {"text": "平方根", "is_correct": false, "explanation": "同じ数を二回かけて元に戻す数を表す語で、ここには入らない。"}, {"text": "倍数", "is_correct": false, "explanation": "ある数の何倍かになる数を表す語で、地図の数字としては意味が通らない。"}, {"text": "21", "is_correct": true, "explanation": "地図に書いてある数字の中で一番大きいものとして、21がここに入る。"}], "explanations": {"合計": "足し算の結果を表す語で、地図の数字として一番大きいものという文には入らない。", "平方根": "同じ数を二回かけて元に戻す数を表す語で、ここには入らない。", "倍数": "ある数の何倍かになる数を表す語で、地図の数字としては意味が通らない。", "21": "地図に書いてある数字の中で一番大きいものとして、21がここに入る。"}, "sentence_index": 6, "correct_answer": "21"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "そのチームでは、背番号21のエースが毎試合活躍している。", "explanation": "ここは背番号の意味。20に1を足した数としての使い方ではないので合わない。"}, {"text": "21世紀の最初の年に、この店は開店した。", "explanation": "ここは世紀の順番の意味。20に1を足した数としての意味とは違うので合わない。"}, {"text": "郵便は、住所の21番地に届けてください。", "explanation": "ここは番地の意味。20に1を足した数としての意味では合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7d645761-a470-43e1-a068-67a54f16899d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
