INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39420, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "出る", "is_correct": true, "explanation": "「入る」の対義語。中に入る⇔外に出る、として辞書で対になる。"}, {"text": "座る", "is_correct": false, "explanation": "「入る」の対義語ではない。座るは腰を下ろす動作。"}, {"text": "寝る", "is_correct": false, "explanation": "「入る」の対義語ではない。寝るは横になって眠る動作。"}, {"text": "歩く", "is_correct": false, "explanation": "「入る」の対義語ではない。歩くは足を動かして進む動作。"}], "correct_answer": "出る", "explanations": {"出る": "「入る」の対義語。中に入る⇔外に出る、として辞書で対になる。", "座る": "「入る」の対義語ではない。座るは腰を下ろす動作。", "寝る": "「入る」の対義語ではない。寝るは横になって眠る動作。", "歩く": "「入る」の対義語ではない。歩くは足を動かして進む動作。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7d645761-a470-43e1-a068-67a54f16899d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39420, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「プールに入りたい」の「に」。入るの移動先を示す。"}, {"text": "を", "is_correct": false, "explanation": "「プールを入りたい」は移動先に目的語の格を使うことになり、不自然。"}, {"text": "が", "is_correct": false, "explanation": "「プールが入りたい」は主語の格で、希望の文の対象を表せない。"}, {"text": "より", "is_correct": false, "explanation": "「プールより入りたい」は比較の意味になり、入る先を示せない。"}], "correct_answer": "に", "explanations": {"に": "「プールに入りたい」の「に」。入るの移動先を示す。", "を": "「プールを入りたい」は移動先に目的語の格を使うことになり、不自然。", "が": "「プールが入りたい」は主語の格で、希望の文の対象を表せない。", "より": "「プールより入りたい」は比較の意味になり、入る先を示せない。"}, "error_tags": {"を": "目的語の格（移動先には使わない）", "が": "主語の格（希望の文の主語にならない）", "より": "比較（入る先を示さない）"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "出る", "is_correct": true, "explanation": "「入る」の対義語。お風呂に入る⇔お風呂から出る、として対になる。"}, {"text": "置く", "is_correct": false, "explanation": "「入る」の対義語ではない。置くは物を場所に据える動作。"}, {"text": "読む", "is_correct": false, "explanation": "「入る」の対義語ではない。読むは文字を目で追う動作。"}, {"text": "待つ", "is_correct": false, "explanation": "「入る」の対義語ではない。待つは時が来るのを過ごす動作。"}], "correct_answer": "出る", "explanations": {"出る": "「入る」の対義語。お風呂に入る⇔お風呂から出る、として対になる。", "置く": "「入る」の対義語ではない。置くは物を場所に据える動作。", "読む": "「入る」の対義語ではない。読むは文字を目で追う動作。", "待つ": "「入る」の対義語ではない。待つは時が来るのを過ごす動作。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7d645761-a470-43e1-a068-67a54f16899d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39420, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "人が中にはいる。", "primary_collocate": null, "pronunciation": "はいる", "ipa": "haiɾɯ", "syllable_count": 3, "sentences": [{"text": "部屋に入る前に、ドアをノックしてください。", "target_word": "入る", "complexity_tier": "T3", "furigana": "部屋[へや]に入[はい]る前[まえ]に、ドアをノックしてください。", "sentence_source": "generated"}, {"text": "急な雨が降り出したので、私たちは雨宿りのために近くの店に入った。", "target_word": "入った", "complexity_tier": "T3", "furigana": "急[きゅう]な雨[あめ]が降[ふ]り出[だ]したので、私[わたし]たちは雨宿[あまやど]りのために近[ちか]くの店[みせ]に入[はい]った。", "sentence_source": "generated"}, {"text": "寒いから、早く家の中に入ろう。", "target_word": "入ろう", "complexity_tier": "T3", "furigana": "寒[さむ]いから、早[はや]く家[いえ]の中[なか]に入[はい]ろう。", "sentence_source": "generated"}, {"text": "弟はテントに入って、すぐに寝てしまった。", "target_word": "入って", "complexity_tier": "T3", "furigana": "弟[おとうと]はテントに入[はい]って、すぐに寝[ね]てしまった。", "sentence_source": "generated"}, {"text": "先生が教室に入ると、みんなが静かになった。", "target_word": "入ると", "complexity_tier": "T3", "furigana": "先生[せんせい]が教室[きょうしつ]に入[はい]ると、みんなが静[しず]かになった。", "sentence_source": "generated"}, {"text": "この先は関係者だけが入ることができます。", "target_word": "入る", "complexity_tier": "T3", "furigana": "この先[さき]は関係者[かんけいしゃ]だけが入[はい]ることができます。", "sentence_source": "generated"}, {"text": "靴をぬいでから、和室に入ってください。", "target_word": "入って", "complexity_tier": "T3", "furigana": "靴[くつ]をぬいでから、和室[わしつ]に入[はい]ってください。", "sentence_source": "generated"}, {"text": "暑いので、早くプールに入りたいです。", "target_word": "入りたい", "complexity_tier": "T3", "furigana": "暑[あつ]いので、早[はや]くプールに入[はい]りたいです。", "sentence_source": "generated"}, {"text": "夜おそくに駅の中へ入ると、人はほとんどいなかった。", "target_word": "入ると", "complexity_tier": "T3", "furigana": "夜[よる]おそくに駅[えき]の中[なか]へ入[はい]ると、人[ひと]はほとんどいなかった。", "sentence_source": "generated"}, {"text": "私は毎晩、十時にお風呂に入ります。", "target_word": "入ります", "complexity_tier": "T3", "furigana": "私[わたし]は毎晩[まいばん]、十時[じゅうじ]にお風呂[ふろ]に入[はい]ります。", "sentence_source": "generated"}], "morphological_forms": [{"form": "入る", "label": "辞書形"}, {"form": "入ります", "label": "丁寧形"}, {"form": "入った", "label": "過去形"}, {"form": "入って", "label": "て形"}, {"form": "入らない", "label": "否定形"}, {"form": "入れば", "label": "仮定形"}, {"form": "入ろう", "label": "意志形"}], "register": "中立", "sense_fingerprint": "人が場所や建物などの中に移動して入る", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 8 above tier T1: contains vocabulary far above tier T1: おそく (Zipf 2.34)']::text[], 'f839c227-2f16-4265-b473-70b89a9b588c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39420, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "入る", "is_correct": true, "explanation": "「部屋に入る前に」の入る。部屋の中へ移動する意味で、文脈に合う。"}, {"text": "食べる", "is_correct": false, "explanation": "「部屋に食べる前に」は場所への移動を表さず、文が成り立たない。"}, {"text": "歌う", "is_correct": false, "explanation": "「部屋に歌う前に」は場所に入る動作ではなく、文として不自然。"}, {"text": "眠る", "is_correct": false, "explanation": "「部屋に眠る前に」は場所への移動を表さず、意味が通らない。"}], "explanations": {"入る": "「部屋に入る前に」の入る。部屋の中へ移動する意味で、文脈に合う。", "食べる": "「部屋に食べる前に」は場所への移動を表さず、文が成り立たない。", "歌う": "「部屋に歌う前に」は場所に入る動作ではなく、文として不自然。", "眠る": "「部屋に眠る前に」は場所への移動を表さず、意味が通らない。"}, "sentence_index": 0, "correct_answer": "入る"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "寒いので、すぐに外に入った。", "explanation": "ここは〈出る〉の意味。外へ出ていく場合は〈出る〉を使う。〈入る〉は中へ行く意味なので合わない。"}, {"text": "寒い朝、ベランダの外に入って、そのまま戻らなかった。", "explanation": "ここは〈出る〉の意味。ベランダの外へ出ていく動きは〈出る〉で表すので、〈入る〉は合わない。"}, {"text": "玄関のドアを開けて、外に入った。", "explanation": "ここは〈出る〉の意味。屋外へ出る場合は〈出る〉を使い、〈入る〉は中へ行く意味なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7d645761-a470-43e1-a068-67a54f16899d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39420, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "入って", "is_correct": true, "explanation": "「和室に入ってください」の入って。和室の中へ移動する意味で文脈に合う。"}, {"text": "洗って", "is_correct": false, "explanation": "「和室に洗ってください」は場所への移動を表さず、文として成り立たない。"}, {"text": "読んで", "is_correct": false, "explanation": "「和室に読んでください」は場所を動作の対象にできず、不自然。"}, {"text": "笑って", "is_correct": false, "explanation": "「和室に笑ってください」は意味が通らない。"}], "explanations": {"入って": "「和室に入ってください」の入って。和室の中へ移動する意味で文脈に合う。", "洗って": "「和室に洗ってください」は場所への移動を表さず、文として成り立たない。", "読んで": "「和室に読んでください」は場所を動作の対象にできず、不自然。", "笑って": "「和室に笑ってください」は意味が通らない。"}, "sentence_index": 6, "correct_answer": "入って"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "車が壁に入って、大きな音がした。", "explanation": "ここは〈突っ込む〉の意味。壁に勢いよくぶつかる意味で、〈入る〉は静かに中へ入る意味なので合わない。"}, {"text": "猫が塀の上に入った。", "explanation": "ここは〈乗る〉の意味。ものの上に移る場合は〈乗る〉を使い、〈入る〉は中へ入る意味なので合わない。"}, {"text": "波が岸に入った。", "explanation": "ここは〈押し寄せる〉の意味。勢いよく迫る動きで、〈入る〉は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7d645761-a470-43e1-a068-67a54f16899d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39420, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "図書館を入るときは、静かにしてください。", "corrected_sentence": "図書館に入るときは、静かにしてください。", "error_description": "「入る」は移動先を「に」で示す。「を」は誤りで、正しくは「図書館に入る」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "入った", "is_correct": true, "explanation": "過去形で、店に入った出来事を述べるので文に合う。"}, {"text": "入る", "is_correct": false, "explanation": "辞書形は現在・未来を表すため、過去の出来事を述べる文と合わない。"}, {"text": "入らない", "is_correct": false, "explanation": "否定形なので「入らなかった」の意味になり、店に入った事実と矛盾する。"}, {"text": "入れば", "is_correct": false, "explanation": "仮定形で、実際に店に入った出来事を述べる文には合わない。"}], "correct_form": "入った", "base_form": "入る", "form_label": "過去形", "sentence_index": 1, "explanations": {"入った": "過去形で、店に入った出来事を述べるので文に合う。", "入る": "辞書形は現在・未来を表すため、過去の出来事を述べる文と合わない。", "入らない": "否定形なので「入らなかった」の意味になり、店に入った事実と矛盾する。", "入れば": "仮定形で、実際に店に入った出来事を述べる文には合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7d645761-a470-43e1-a068-67a54f16899d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39420, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "暑いので、早くお風呂が入りたいです。", "corrected_sentence": "暑いので、早くお風呂に入りたいです。", "error_description": "「入りたい」は移動先を「に」で示す。「が」は誤りで、正しくは「お風呂に入りたい」。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "入りたい", "is_correct": true, "explanation": "希望を表す形で、早く入りたいという文脈に合う。"}, {"text": "入る", "is_correct": false, "explanation": "辞書形は希望を表さず、「早く入る」は事実の述べ方になり文脈と合わない。"}, {"text": "入って", "is_correct": false, "explanation": "て形は単独で希望を表せず、「入ってたいです」のように続かない。"}, {"text": "入ろう", "is_correct": false, "explanation": "意志形は話し手の意志を表し、プールに入りたいという希望の文と合わない。"}], "correct_form": "入りたい", "base_form": "入る", "form_label": "希望形", "sentence_index": 7, "explanations": {"入りたい": "希望を表す形で、早く入りたいという文脈に合う。", "入る": "辞書形は希望を表さず、「早く入る」は事実の述べ方になり文脈と合わない。", "入って": "て形は単独で希望を表せず、「入ってたいです」のように続かない。", "入ろう": "意志形は話し手の意志を表し、プールに入りたいという希望の文と合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7d645761-a470-43e1-a068-67a54f16899d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39422, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "緩やか", "is_correct": true, "explanation": "変化がゆっくりなことを表し、「急激」の対義語。"}, {"text": "丁寧", "is_correct": false, "explanation": "注意深く行うようす。変化の速さの反対ではないので対義語ではない。"}, {"text": "派手", "is_correct": false, "explanation": "目立つようす。変化の速さとは関係がない。"}, {"text": "大切", "is_correct": false, "explanation": "価値が高いこと。変化の速さとは関係がない。"}], "correct_answer": "緩やか", "explanations": {"緩やか": "変化がゆっくりなことを表し、「急激」の対義語。", "丁寧": "注意深く行うようす。変化の速さの反対ではないので対義語ではない。", "派手": "目立つようす。変化の速さとは関係がない。", "大切": "価値が高いこと。変化の速さとは関係がない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75f8b2ea-b1b2-4b0b-bd9b-d6649c858d5a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39422, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "緩やか", "is_correct": true, "explanation": "変化がゆっくりなことを表し、「急激」の対義語。"}, {"text": "慎重", "is_correct": false, "explanation": "注意深く行うようす。変化の速さの反対ではないので対義語ではない。"}, {"text": "地味", "is_correct": false, "explanation": "目立たないようす。変化の速さとは関係がない。"}, {"text": "厳格", "is_correct": false, "explanation": "決まりを厳しく守るようす。変化の速さとは関係がない。"}], "correct_answer": "緩やか", "explanations": {"緩やか": "変化がゆっくりなことを表し、「急激」の対義語。", "慎重": "注意深く行うようす。変化の速さの反対ではないので対義語ではない。", "地味": "目立たないようす。変化の速さとは関係がない。", "厳格": "決まりを厳しく守るようす。変化の速さとは関係がない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75f8b2ea-b1b2-4b0b-bd9b-d6649c858d5a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39422, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "急激は、変化がとても速くて大きいことです。", "primary_collocate": null, "pronunciation": "きゅうげき", "ipa": "kʲɯːɡeki", "syllable_count": 4, "sentences": [{"text": "気温が急激に下がった。", "target_word": "急激", "complexity_tier": "T3", "furigana": "気温[きおん]が急激[きゅうげき]に下[さ]がった。", "sentence_source": "generated"}, {"text": "急激な変化に、体がついていけない。", "target_word": "急激", "complexity_tier": "T3", "furigana": "急激[きゅうげき]な変化[へんか]に、体[からだ]がついていけない。", "sentence_source": "generated"}, {"text": "人口が急激にふえている。", "target_word": "急激", "complexity_tier": "T3", "furigana": "人口[じんこう]が急激[きゅうげき]にふえている。", "sentence_source": "generated"}, {"text": "急激な値上がりで、みんなが困った。", "target_word": "急激", "complexity_tier": "T3", "furigana": "急激[きゅうげき]な値上[ねあ]がりで、みんなが困[こま]った。", "sentence_source": "generated"}, {"text": "川の水が急激に増えて、あぶなかった。", "target_word": "急激", "complexity_tier": "T3", "furigana": "川[かわ]の水[みず]が急激[きゅうげき]に増[ふ]えて、あぶなかった。", "sentence_source": "generated"}, {"text": "急激に体重が減ると、体によくないことがある。", "target_word": "急激", "complexity_tier": "T3", "furigana": "急激[きゅうげき]に体重[たいじゅう]が減[へ]ると、体[からだ]によくないことがある。", "sentence_source": "generated"}, {"text": "天気が急激に悪くなったので、山を下りた。", "target_word": "急激", "complexity_tier": "T3", "furigana": "天気[てんき]が急激[きゅうげき]に悪[わる]くなったので、山[やま]を下[お]りた。", "sentence_source": "generated"}, {"text": "急激な運動をさけて、ゆっくり歩こう。", "target_word": "急激", "complexity_tier": "T3", "furigana": "急激[きゅうげき]な運動[うんどう]をさけて、ゆっくり歩[ある]こう。", "sentence_source": "generated"}, {"text": "町は急激に大きくなった。", "target_word": "急激", "complexity_tier": "T3", "furigana": "町[まち]は急激[きゅうげき]に大[おお]きくなった。", "sentence_source": "generated"}, {"text": "急激な成長の裏には、たくさんの努力があった。", "target_word": "急激", "complexity_tier": "T3", "furigana": "急激[きゅうげき]な成長[せいちょう]の裏[うら]には、たくさんの努力[どりょく]があった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "急激だ", "label": "終止形"}, {"form": "急激な", "label": "連体形"}, {"form": "急激に", "label": "連用形"}, {"form": "急激で", "label": "連用形（で）"}, {"form": "急激なら", "label": "仮定形"}], "register": "neutral", "sense_fingerprint": "変化が速くて大きいようす", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 4 above tier T3: contains vocabulary far above tier T3: あぶなかっ (Zipf 1.38)']::text[], '55d77c36-1221-46e8-9ca1-e98c3b3fa4f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39422, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "急激", "is_correct": true, "explanation": "「急激に下がった」は変化の速さと大きさを表し、気温の下がり方に合う。"}, {"text": "複雑", "is_correct": false, "explanation": "「複雑」は仕組みが込み入っていることを表し、気温が下がるようすとは合わない。"}, {"text": "丈夫", "is_correct": false, "explanation": "「丈夫」は壊れにくいことを表し、下がるようすには使えない。"}, {"text": "便利", "is_correct": false, "explanation": "「便利」は使いやすさを表し、気温が下がる動きには合わない。"}], "explanations": {"急激": "「急激に下がった」は変化の速さと大きさを表し、気温の下がり方に合う。", "複雑": "「複雑」は仕組みが込み入っていることを表し、気温が下がるようすとは合わない。", "丈夫": "「丈夫」は壊れにくいことを表し、下がるようすには使えない。", "便利": "「便利」は使いやすさを表し、気温が下がる動きには合わない。"}, "sentence_index": 0, "correct_answer": "急激"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "急激な質問に、言葉を失った。", "explanation": "ここは〈唐突〉の意味。「唐突な質問」は不意に出た質問を指す。急激は変化の速さと大きさを表すので、質問には使えない。"}, {"text": "急激な電話がかかってきて、びっくりした。", "explanation": "ここは〈急な〉（予定になく、突然）の意味。「急な電話」と言う。急激は変化の速さと大きさを表すので、電話には使わない。"}, {"text": "この坂は急激で、自転車では上がれない。", "explanation": "ここは〈急〉（傾きが大きい）の意味。「急な坂」と言う。急激は変化に使い、坂の傾きには合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75f8b2ea-b1b2-4b0b-bd9b-d6649c858d5a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39422, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "急激", "is_correct": true, "explanation": "「天気が急激に悪くなった」は変化の速さを表し、天気の変わり方に合う。"}, {"text": "親切", "is_correct": false, "explanation": "「親切」は人への思いやりを表し、天気の変化には使えない。"}, {"text": "豪快", "is_correct": false, "explanation": "「豪快」は大胆で勢いがあるようすで、天気が悪くなる変化には合わない。"}, {"text": "純粋", "is_correct": false, "explanation": "「純粋」は混じりけがないことで、天気の変化には使えない。"}], "explanations": {"急激": "「天気が急激に悪くなった」は変化の速さを表し、天気の変わり方に合う。", "親切": "「親切」は人への思いやりを表し、天気の変化には使えない。", "豪快": "「豪快」は大胆で勢いがあるようすで、天気が悪くなる変化には合わない。", "純粋": "「純粋」は混じりけがないことで、天気の変化には使えない。"}, "sentence_index": 6, "correct_answer": "急激"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "その契約は急激に検討された。", "explanation": "ここは〈慎重〉の意味。「慎重に検討する」は注意深く考えること。急激は変化の速さを表すので、検討のしかたには合わない。"}, {"text": "彼女は急激に感謝した。", "explanation": "ここは〈心から〉の意味（感謝する）。急激は変化の速さを表すので、気持ちを表す動作には使わない。"}, {"text": "彼の服装は急激だ。", "explanation": "ここは〈地味〉の意味。「地味な服装」は目立たないことを表す。急激は変化の速さなので、服装の様子には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75f8b2ea-b1b2-4b0b-bd9b-d6649c858d5a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39422, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "夜になると、気温が急激な下がる。", "corrected_sentence": "夜になると、気温が急激に下がる。", "error_description": "「下がる」を修飾するには連用形「急激に」が必要。「急激な」は連体形で、名詞にしかかからない。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "急激な", "is_correct": true, "explanation": "「急激な変化」と名詞を修飾する連体形で、文中の形と同じ。"}, {"text": "急激だ", "is_correct": false, "explanation": "終止形。名詞の前に置けないので「変化に」とつながらない。"}, {"text": "急激に", "is_correct": false, "explanation": "連用形。動詞や形容詞を修飾する形で、名詞「変化」にはつながらない。"}, {"text": "急激で", "is_correct": false, "explanation": "中止形（で）。「急激で変化」とは続けられない。"}], "correct_form": "急激な", "base_form": "急激だ", "form_label": "連体形", "sentence_index": 1, "explanations": {"急激な": "「急激な変化」と名詞を修飾する連体形で、文中の形と同じ。", "急激だ": "終止形。名詞の前に置けないので「変化に」とつながらない。", "急激に": "連用形。動詞や形容詞を修飾する形で、名詞「変化」にはつながらない。", "急激で": "中止形（で）。「急激で変化」とは続けられない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75f8b2ea-b1b2-4b0b-bd9b-d6649c858d5a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39422, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "その会社の売り上げは急激が伸びた。", "corrected_sentence": "その会社の売り上げは急激に伸びた。", "error_description": "誤りは「急激が」の「が」。「伸びた」を修飾するには連用形「急激に」が必要。「急激が」は活用形として成り立たない。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "急激な", "is_correct": true, "explanation": "「急激な運動」と名詞を修飾する連体形で、文中の形と同じ。"}, {"text": "急激なら", "is_correct": false, "explanation": "仮定形。名詞の前に置けないので「運動」とつながらない。"}, {"text": "急激さ", "is_correct": false, "explanation": "名詞化した形。「運動」を修飾できない。"}, {"text": "急激に", "is_correct": false, "explanation": "連用形。動詞や形容詞を修飾する形で、名詞「運動」の前には置けない。"}], "correct_form": "急激な", "base_form": "急激だ", "form_label": "連体形", "sentence_index": 7, "explanations": {"急激な": "「急激な運動」と名詞を修飾する連体形で、文中の形と同じ。", "急激なら": "仮定形。名詞の前に置けないので「運動」とつながらない。", "急激さ": "名詞化した形。「運動」を修飾できない。", "急激に": "連用形。動詞や形容詞を修飾する形で、名詞「運動」の前には置けない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75f8b2ea-b1b2-4b0b-bd9b-d6649c858d5a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39424, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「細かい表情に着目」の形で、着目の対象を示す。"}, {"text": "を", "is_correct": false, "explanation": "「表情を着目」は対象を示せず、目的語の形として不自然。"}, {"text": "で", "is_correct": false, "explanation": "「表情で着目」は手段の意味になり、不自然。"}, {"text": "と", "is_correct": false, "explanation": "「表情と着目」は並列の形になり、着目の対象を示せない。"}], "correct_answer": "に", "explanations": {"に": "「細かい表情に着目」の形で、着目の対象を示す。", "を": "「表情を着目」は対象を示せず、目的語の形として不自然。", "で": "「表情で着目」は手段の意味になり、不自然。", "と": "「表情と着目」は並列の形になり、着目の対象を示せない。"}, "error_tags": {"を": "目的語", "で": "手段", "と": "並列"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3cf92071-1d16-456b-80e1-4ce44bb16a1a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39424, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「選手の足元に着目」の形で、着目の対象を示す。"}, {"text": "が", "is_correct": false, "explanation": "主語の「が」では「足元が着目して」となり、着目の対象を示せない。"}, {"text": "へ", "is_correct": false, "explanation": "方向の「へ」では「足元へ着目して」となり、不自然。"}, {"text": "より", "is_correct": false, "explanation": "比較の「より」では「足元より着目して」となり、対象を示せない。"}], "correct_answer": "に", "explanations": {"に": "「選手の足元に着目」の形で、着目の対象を示す。", "が": "主語の「が」では「足元が着目して」となり、着目の対象を示せない。", "へ": "方向の「へ」では「足元へ着目して」となり、不自然。", "より": "比較の「より」では「足元より着目して」となり、対象を示せない。"}, "error_tags": {"が": "主語", "へ": "方向", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3cf92071-1d16-456b-80e1-4ce44bb16a1a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39424, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "何かを特に注意してみること。", "primary_collocate": null, "pronunciation": "ちゃくもく", "ipa": "tɕakɯmokɯ", "syllable_count": 4, "sentences": [{"text": "刑事は、犯人の靴に着目して捜査を進めた。", "target_word": "着目して", "complexity_tier": "T3", "furigana": "刑事[けいじ]は、犯人[はんにん]の靴[くつ]に着目[ちゃくもく]して捜査[そうさ]を進[すす]めた。", "sentence_source": "generated"}, {"text": "先生は、生徒の細かい表情に着目している。", "target_word": "着目して", "complexity_tier": "T3", "furigana": "先生[せんせい]は、生徒[せいと]の細[こま]かい表情[ひょうじょう]に着目[ちゃくもく]している。", "sentence_source": "generated"}, {"text": "絵の右下の小さな署名に着目してみよう。", "target_word": "着目して", "complexity_tier": "T3", "furigana": "絵[え]の右下[みぎした]の小[ちい]さな署名[しょめい]に着目[ちゃくもく]してみよう。", "sentence_source": "generated"}, {"text": "私は彼の指の動きに着目して、手品の種を見破った。", "target_word": "着目して", "complexity_tier": "T3", "furigana": "私[わたし]は彼[かれ]の指[ゆび]の動[うご]きに着目[ちゃくもく]して、手品[てじな]の種[たね]を見破[みやぶ]った。", "sentence_source": "generated"}, {"text": "写真の背景に着目すると、撮影した場所が分かる。", "target_word": "着目する", "complexity_tier": "T3", "furigana": "写真[しゃしん]の背景[はいけい]に着目[ちゃくもく]すると、撮影[さつえい]した場所[ばしょ]が分[わ]かる。", "sentence_source": "generated"}, {"text": "医者は、患者の顔色の変化に着目した。", "target_word": "着目した", "complexity_tier": "T3", "furigana": "医者[いしゃ]は、患者[かんじゃ]の顔色[かおいろ]の変化[へんか]に着目[ちゃくもく]した。", "sentence_source": "generated"}, {"text": "地図の色の違いに着目すれば、高い場所と低い場所が分かる。", "target_word": "着目すれば", "complexity_tier": "T3", "furigana": "地図[ちず]の色[いろ]の違[ちが]いに着目[ちゃくもく]すれば、高[たか]い場所[ばしょ]と低[ひく]い場所[ばしょ]が分[わ]かる。", "sentence_source": "generated"}, {"text": "審判は、選手の足元に着目して反則を見つけた。", "target_word": "着目して", "complexity_tier": "T3", "furigana": "審判[しんぱん]は、選手[せんしゅ]の足元[あしもと]に着目[ちゃくもく]して反則[はんそく]を見[み]つけた。", "sentence_source": "generated"}, {"text": "彼は誰も見ない小さな文字に着目し、誤りを見つけた。", "target_word": "着目し", "complexity_tier": "T3", "furigana": "彼[かれ]は誰[だれ]も見[み]ない小[ちい]さな文字[もじ]に着目[ちゃくもく]し、誤[あやま]りを見[み]つけた。", "sentence_source": "generated"}, {"text": "鳥の羽の模様に着目すると、種類を区別しやすい。", "target_word": "着目する", "complexity_tier": "T3", "furigana": "鳥[とり]の羽[はね]の模様[もよう]に着目[ちゃくもく]すると、種類[しゅるい]を区別[くべつ]しやすい。", "sentence_source": "generated"}], "morphological_forms": [{"form": "着目", "label": "名詞形"}, {"form": "着目する", "label": "辞書形"}, {"form": "着目した", "label": "タ形"}, {"form": "着目して", "label": "テ形"}, {"form": "着目しない", "label": "ナイ形"}, {"form": "着目しよう", "label": "意向形"}], "register": "neutral", "sense_fingerprint": "ある一点を特に注意して見ること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80d5caf6-f21d-47d6-aabb-a8ee0a91932d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39424, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "着目して", "is_correct": true, "explanation": "テ形で「靴に注目し、そのうえで」と続き、「捜査を進めた」へつながる。"}, {"text": "着目", "is_correct": false, "explanation": "名詞形だけでは「靴に着目捜査」と続かず、文が成立しない。"}, {"text": "着目を", "is_correct": false, "explanation": "「を」は目的語を示すため、「着目を捜査を進めた」となって文が崩れる。"}, {"text": "着目しよう", "is_correct": false, "explanation": "意向形は「〜しよう」の誘いの形で、後ろの名詞「捜査」を修飾できない。"}], "explanations": {"着目して": "テ形で「靴に注目し、そのうえで」と続き、「捜査を進めた」へつながる。", "着目": "名詞形だけでは「靴に着目捜査」と続かず、文が成立しない。", "着目を": "「を」は目的語を示すため、「着目を捜査を進めた」となって文が崩れる。", "着目しよう": "意向形は「〜しよう」の誘いの形で、後ろの名詞「捜査」を修飾できない。"}, "sentence_index": 0, "correct_answer": "着目して"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "突然の爆音に、彼は思わず着目した。", "explanation": "ここは〈驚く〉の意味。驚いて体が反応する驚きとは違い、着目は意識して一点に注意を向けることなので、「思わず着目した」とは合わない。"}, {"text": "研究者は、池の魚の動きを見ずに、毎朝着目している。", "explanation": "ここは〈なんとなく眺める〉の意味。何となく眺めることとは違い、着目は特定の一点に意識して注意を向けることなので、「見ずに着目」は矛盾する。"}, {"text": "彼は、そわそわと視線を泳がせながら、議長の顔に着目していた。", "explanation": "ここは〈きょろきょろ見回す〉の意味。視線を一点に定める着目とは違い、落ち着きなく見回すことなので、一点に注意を集中する意味とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3cf92071-1d16-456b-80e1-4ce44bb16a1a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39424, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "着目すれば", "is_correct": true, "explanation": "バ形で「〜すれば」と条件を示し、「高い場所と低い場所が分かる」へ続く。"}, {"text": "着目する", "is_correct": false, "explanation": "辞書形のまま読点で切ると、条件を示す形にならず、文が続かない。"}, {"text": "着目した", "is_correct": false, "explanation": "タ形は条件を示す形にならず、「高い場所と低い場所が分かる」へつながらない。"}, {"text": "着目しない", "is_correct": false, "explanation": "否定の形では条件の意味が合わず、文の流れが崩れる。"}], "explanations": {"着目すれば": "バ形で「〜すれば」と条件を示し、「高い場所と低い場所が分かる」へ続く。", "着目する": "辞書形のまま読点で切ると、条件を示す形にならず、文が続かない。", "着目した": "タ形は条件を示す形にならず、「高い場所と低い場所が分かる」へつながらない。", "着目しない": "否定の形では条件の意味が合わず、文の流れが崩れる。"}, "sentence_index": 6, "correct_answer": "着目すれば"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "警備員は、出入口に無意識に着目していた。", "explanation": "ここは〈ぼんやり目に入る〉の意味。ぼんやり目に入ることとは違い、着目は意識して注意を向けることなので、「無意識に着目」は矛盾する。"}, {"text": "彼は、目を閉じたまま、部屋の隅に着目していた。", "explanation": "ここは〈何も見ない〉の意味。目を閉じて何も見ないこととは違い、着目は一点に注意を向けることなので、目を閉じた状態とは両立しない。"}, {"text": "彼は、落ちていた硬貨を見失ったまま、その模様に着目した。", "explanation": "ここは〈見失う〉の意味。見えなくなることとは違い、着目は一点を見続けて注意を向けることなので、見失ったまま着目するのは矛盾する。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3cf92071-1d16-456b-80e1-4ce44bb16a1a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39424, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "記者は、政治家の発言の矛盾を着目して、記事を書いた。", "corrected_sentence": "記者は、政治家の発言の矛盾に着目して、記事を書いた。", "error_description": "「着目する」は「〜に着目する」と助詞「に」をとる。「を」にすると誤りで、正しくは「矛盾に着目して」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3cf92071-1d16-456b-80e1-4ce44bb16a1a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39424, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "店長は、客の動きの変化に着目しに、売れ筋が分かると言った。", "corrected_sentence": "店長は、客の動きの変化に着目すると、売れ筋が分かると言った。", "error_description": "条件を表す「着目すると」を「着目しに」としたのは誤り。「しに」は目的を表す形で、ここでは後ろの文が成り立たない。正しくは「着目すると」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3cf92071-1d16-456b-80e1-4ce44bb16a1a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39425, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「若者の消費の変化に着目して」の形で、着目の対象を示す。"}, {"text": "を", "is_correct": false, "explanation": "「変化を着目して」は対象を示せず、不自然。"}, {"text": "で", "is_correct": false, "explanation": "「変化で着目して」は手段の意味になり、不自然。"}, {"text": "と", "is_correct": false, "explanation": "「変化と着目して」は並列の形になり、対象を示せない。"}], "correct_answer": "に", "explanations": {"に": "「若者の消費の変化に着目して」の形で、着目の対象を示す。", "を": "「変化を着目して」は対象を示せず、不自然。", "で": "「変化で着目して」は手段の意味になり、不自然。", "と": "「変化と着目して」は並列の形になり、対象を示せない。"}, "error_tags": {"を": "目的語", "で": "手段", "と": "並列"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3cf92071-1d16-456b-80e1-4ce44bb16a1a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39425, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「人口の減少に着目し」の形で、着目の対象を示す。"}, {"text": "が", "is_correct": false, "explanation": "主語の「が」では「減少が着目し」となり、着目の対象を示せない。"}, {"text": "へ", "is_correct": false, "explanation": "方向の「へ」では「減少へ着目し」となり、不自然。"}, {"text": "より", "is_correct": false, "explanation": "比較の「より」では「減少より着目し」となり、対象を示せない。"}], "correct_answer": "に", "explanations": {"に": "「人口の減少に着目し」の形で、着目の対象を示す。", "が": "主語の「が」では「減少が着目し」となり、着目の対象を示せない。", "へ": "方向の「へ」では「減少へ着目し」となり、不自然。", "より": "比較の「より」では「減少より着目し」となり、対象を示せない。"}, "error_tags": {"が": "主語", "へ": "方向", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3cf92071-1d16-456b-80e1-4ce44bb16a1a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39425, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "ある物事や現象に特に注意を集中して考えること。", "primary_collocate": null, "pronunciation": "ちゃくもく", "ipa": "tɕakɯmokɯ", "syllable_count": 4, "sentences": [{"text": "この研究は、言葉の変化という現象に着目している。", "target_word": "着目して", "complexity_tier": "T3", "furigana": "この研究[けんきゅう]は、言葉[ことば]の変化[へんか]という現象[げんしょう]に着目[ちゃくもく]している。", "sentence_source": "generated"}, {"text": "会社は、若者の消費の変化に着目して新商品を作った。", "target_word": "着目して", "complexity_tier": "T3", "furigana": "会社[かいしゃ]は、若者[わかもの]の消費[しょうひ]の変化[へんか]に着目[ちゃくもく]して新商品[しんしょうひん]を作[つく]った。", "sentence_source": "generated"}, {"text": "彼女は、他の人が見落とした点に着目した発想で賞を取った。", "target_word": "着目した", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は、他[ほか]の人[ひと]が見落[みお]とした点[てん]に着目[ちゃくもく]した発想[はっそう]で賞[しょう]を取[と]った。", "sentence_source": "generated"}, {"text": "歴史学者は、天候と農作物の関係に着目して、飢饉の原因を考えた。", "target_word": "着目して", "complexity_tier": "T3", "furigana": "歴史学者[れきしがくしゃ]は、天候[てんこう]と農作物[のうさくぶつ]の関係[かんけい]に着目[ちゃくもく]して、飢饉[ききん]の原因[げんいん]を考[かんが]えた。", "sentence_source": "generated"}, {"text": "環境問題に着目する学生が、年々増えている。", "target_word": "着目する", "complexity_tier": "T3", "furigana": "環境問題[かんきょうもんだい]に着目[ちゃくもく]する学生[がくせい]が、年々[ねんねん]増[ふ]えている。", "sentence_source": "generated"}, {"text": "新しい視点に着目することで、問題の解決策が見えてきた。", "target_word": "着目する", "complexity_tier": "T3", "furigana": "新[あたら]しい視点[してん]に着目[ちゃくもく]することで、問題[もんだい]の解決策[かいけつさく]が見[み]えてきた。", "sentence_source": "generated"}, {"text": "投資家は、小さな企業の成長力に着目している。", "target_word": "着目して", "complexity_tier": "T3", "furigana": "投資家[とうしか]は、小[ちい]さな企業[きぎょう]の成長力[せいちょうりょく]に着目[ちゃくもく]している。", "sentence_source": "generated"}, {"text": "彼は人口の減少に着目し、町の将来について論文を書いた。", "target_word": "着目し", "complexity_tier": "T3", "furigana": "彼[かれ]は人口[じんこう]の減少[げんしょう]に着目[ちゃくもく]し、町[まち]の将来[しょうらい]について論文[ろんぶん]を書[か]いた。", "sentence_source": "generated"}, {"text": "先生は、子どもの学び方の違いに着目して授業を考えた。", "target_word": "着目して", "complexity_tier": "T3", "furigana": "先生[せんせい]は、子[こ]どもの学[まな]び方[かた]の違[ちが]いに着目[ちゃくもく]して授業[じゅぎょう]を考[かんが]えた。", "sentence_source": "generated"}, {"text": "経済の動きに着目すれば、物の値段が変わる理由が分かる。", "target_word": "着目すれば", "complexity_tier": "T3", "furigana": "経済[けいざい]の動[うご]きに着目[ちゃくもく]すれば、物[もの]の値段[ねだん]が変[か]わる理由[りゆう]が分[わ]かる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "着目", "label": "名詞形"}, {"form": "着目する", "label": "辞書形"}, {"form": "着目した", "label": "タ形"}, {"form": "着目して", "label": "テ形"}, {"form": "着目しない", "label": "ナイ形"}, {"form": "着目すれば", "label": "バ形"}], "register": "neutral", "sense_fingerprint": "ある物事や現象に注意を向けて考察すること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80d5caf6-f21d-47d6-aabb-a8ee0a91932d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39425, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "着目して", "is_correct": true, "explanation": "テ形に「いる」を続けて進行・継続の意味になり、「現象に着目している」が成立する。"}, {"text": "着目する", "is_correct": false, "explanation": "辞書形は「いる」へ直接続かず、「現象に着目するいる」となって文が成立しない。"}, {"text": "着目した", "is_correct": false, "explanation": "タ形は「いる」の前に置けず、文が成立しない。"}, {"text": "着目しない", "is_correct": false, "explanation": "ナイ形に「いる」を続けると、形も意味も合わない。"}], "explanations": {"着目して": "テ形に「いる」を続けて進行・継続の意味になり、「現象に着目している」が成立する。", "着目する": "辞書形は「いる」へ直接続かず、「現象に着目するいる」となって文が成立しない。", "着目した": "タ形は「いる」の前に置けず、文が成立しない。", "着目しない": "ナイ形に「いる」を続けると、形も意味も合わない。"}, "sentence_index": 0, "correct_answer": "着目して"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "学者は、データを一度も見ないまま、その数字に着目していた。", "explanation": "ここは〈見ないで決めつける〉の意味。資料を実際に見て注意を向ける着目とは違い、見ないまま着目するのは矛盾する。"}, {"text": "先生は、子どもの学び方の違いに気づかないまま、授業で着目した。", "explanation": "ここは〈気づかない〉の意味。気づかずに通り過ぎることとは違い、着目は注意を向けて考えることなので、気づかないまま着目するのは矛盾する。"}, {"text": "学者は、目の前の論文に無意識に着目して、内容を読み飛ばした。", "explanation": "ここは〈ぼんやり目に入る〉の意味。ぼんやり目に入ることとは違い、着目は意識して注意を向けることなので、「無意識に着目」とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3cf92071-1d16-456b-80e1-4ce44bb16a1a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39425, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "着目して", "is_correct": true, "explanation": "テ形に「いる」を続けて進行の意味になり、「成長力に着目している」が成立する。"}, {"text": "着目し", "is_correct": false, "explanation": "連用中止形は「いる」に続けられず、文が成立しない。"}, {"text": "着目すれば", "is_correct": false, "explanation": "バ形は条件を示す形で、「いる」へは続かず、文の形が崩れる。"}, {"text": "着目しよう", "is_correct": false, "explanation": "意向形は「いる」へ続けられず、文が成立しない。"}], "explanations": {"着目して": "テ形に「いる」を続けて進行の意味になり、「成長力に着目している」が成立する。", "着目し": "連用中止形は「いる」に続けられず、文が成立しない。", "着目すれば": "バ形は条件を示す形で、「いる」へは続かず、文の形が崩れる。", "着目しよう": "意向形は「いる」へ続けられず、文が成立しない。"}, "sentence_index": 6, "correct_answer": "着目して"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "検査員は、小さな傷に着目して、見落とした。", "explanation": "ここは〈気づかずに逃す〉の意味。注意が届かず気づかないこととは違い、着目は注意を向けることなので、「着目して見落とした」は矛盾する。"}, {"text": "学者は、全体を概観するために、細かい一点に着目した。", "explanation": "ここは〈ざっと見渡す〉の意味。全体をおおまかに眺めるのとは違い、着目は一点を特に注意して見ることなので、全体を見る目的とは合わない。"}, {"text": "彼は、昼に熟睡しながら、窓の外の光景に着目していた。", "explanation": "ここは〈眠る〉の意味。眠っていることとは違い、着目は起きて意識的に注意を向けることなので、眠りながら着目するのは矛盾する。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3cf92071-1d16-456b-80e1-4ce44bb16a1a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39425, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "投資家は、景気の変化に着目で、株を買った。", "corrected_sentence": "投資家は、景気の変化に着目して、株を買った。", "error_description": "後ろの文へ続けるにはテ形の「着目して」にする必要がある。「着目で」は誤りで、正しくは「着目して」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3cf92071-1d16-456b-80e1-4ce44bb16a1a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39425, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "研究者は、新しい薬の副作用を着目して、論文を書いた。", "corrected_sentence": "研究者は、新しい薬の副作用に着目して、論文を書いた。", "error_description": "「着目する」は「〜に着目する」と助詞「に」をとる。「を」にすると誤りで、正しくは「副作用に着目して」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3cf92071-1d16-456b-80e1-4ce44bb16a1a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39426, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「帆布が」で主語を示し、布が破れたという文の意味が通る。"}, {"text": "を", "is_correct": false, "explanation": "「破れる」は自動詞で目的語を取らないため、「を」は合わない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表し、「帆布へ破れた」は文として成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "「と破れる」という形は文として成り立たない。"}], "correct_answer": "が", "explanations": {"が": "「帆布が」で主語を示し、布が破れたという文の意味が通る。", "を": "「破れる」は自動詞で目的語を取らないため、「を」は合わない。", "へ": "「へ」は方向を表し、「帆布へ破れた」は文として成り立たない。", "と": "「と破れる」という形は文として成り立たない。"}, "error_tags": {"を": "自動詞に目的語", "へ": "方向", "と": "不自然な格"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59842fc5-799f-4d98-a8d3-278d78c2adcf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39426, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "「この船の帆布は」で話題を示し、後ろで布の性質を説明する文になる。"}, {"text": "を", "is_correct": false, "explanation": "「帆布を、厚くて強い布だ」は目的語が文の中で成り立たず、不自然。"}, {"text": "に", "is_correct": false, "explanation": "「帆布に、厚くて強い布だ」は場所の意味になり、「厚くて強い布だ」と続かず文が成り立たない。"}, {"text": "より", "is_correct": false, "explanation": "「帆布より、厚くて強い布だ」は比較の文にならず、意味が通らない。"}], "correct_answer": "は", "explanations": {"は": "「この船の帆布は」で話題を示し、後ろで布の性質を説明する文になる。", "を": "「帆布を、厚くて強い布だ」は目的語が文の中で成り立たず、不自然。", "に": "「帆布に、厚くて強い布だ」は場所の意味になり、「厚くて強い布だ」と続かず文が成り立たない。", "より": "「帆布より、厚くて強い布だ」は比較の文にならず、意味が通らない。"}, "error_tags": {"を": "目的語", "に": "場所", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59842fc5-799f-4d98-a8d3-278d78c2adcf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39426, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "布でできた、船の帆を作るための、丈夫な材料です。", "primary_collocate": null, "pronunciation": "ほぬの", "ipa": "honɯnɔ", "syllable_count": 3, "sentences": [{"text": "昔の船は、丈夫な帆布で帆を作りました。", "target_word": "帆布", "complexity_tier": "T3", "furigana": "昔[むかし]の船[ふね]は、丈夫[じょうぶ]な帆布[ほぬの]で帆[ほ]を作[つく]りました。", "sentence_source": "generated"}, {"text": "帆布が破れたので、船は進めなくなった。", "target_word": "帆布", "complexity_tier": "T3", "furigana": "帆布[ほぬの]が破[やぶ]れたので、船[ふね]は進[すす]めなくなった。", "sentence_source": "generated"}, {"text": "漁師は新しい帆布を買って、船の帆を直した。", "target_word": "帆布", "complexity_tier": "T3", "furigana": "漁師[りょうし]は新[あたら]しい帆布[ほぬの]を買[か]って、船[ふね]の帆[ほ]を直[なお]した。", "sentence_source": "generated"}, {"text": "帆布は風を受けても破れにくいので、船乗りに好まれた。", "target_word": "帆布", "complexity_tier": "T3", "furigana": "帆布[ほぬの]は風[かぜ]を受[う]けても破[やぶ]れにくいので、船乗[ふなの]りに好[この]まれた。", "sentence_source": "generated"}, {"text": "港の店では、帆布を長く巻いて売っている。", "target_word": "帆布", "complexity_tier": "T3", "furigana": "港[みなと]の店[みせ]では、帆布[ほぬの]を長[なが]く巻[ま]いて売[う]っている。", "sentence_source": "generated"}, {"text": "雨にぬれた帆布は重くなるので、使ったあとはよく干します。", "target_word": "帆布", "complexity_tier": "T3", "furigana": "雨[あめ]にぬれた帆布[ほぬの]は重[おも]くなるので、使[つか]ったあとはよく干[ほ]します。", "sentence_source": "generated"}, {"text": "古い帆布を切って、船の小さな帆を作った。", "target_word": "帆布", "complexity_tier": "T3", "furigana": "古[ふる]い帆布[ほぬの]を切[き]って、船[ふね]の小[ちい]さな帆[ほ]を作[つく]った。", "sentence_source": "generated"}, {"text": "この船の帆布は、厚くて強い布だ。", "target_word": "帆布", "complexity_tier": "T3", "furigana": "この船[ふね]の帆布[ほぬの]は、厚[あつ]くて強[つよ]い布[ぬの]だ。", "sentence_source": "generated"}, {"text": "嵐の前に、船乗りたちは帆布をたたんでしまった。", "target_word": "帆布", "complexity_tier": "T3", "furigana": "嵐[あらし]の前[まえ]に、船乗[ふなの]りたちは帆布[ほぬの]をたたんでしまった。", "sentence_source": "generated"}, {"text": "帆布がなければ、帆船は風の力で進めない。", "target_word": "帆布", "complexity_tier": "T3", "furigana": "帆布[ほぬの]がなければ、帆船[はんせん]は風[かぜ]の力[ちから]で進[すす]めない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "帆布", "label": "基本形"}], "register": "標準（中立）", "sense_fingerprint": "船の帆を作る丈夫な布地", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01e5a7c6-6233-4cdf-b902-182071ea0773') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39426, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "帆布", "is_correct": true, "explanation": "〈帆布〉は船の帆を作る丈夫な布で、この文の空所に入る。"}, {"text": "錨", "is_correct": false, "explanation": "〈錨〉は船を止める重い金具で、布で帆を作るという文には合わない。"}, {"text": "櫂", "is_correct": false, "explanation": "〈櫂〉は船をこぐ道具で、帆の材料にはならない。"}, {"text": "羅針盤", "is_correct": false, "explanation": "〈羅針盤〉は方角を示す道具で、帆を作る材料ではない。"}], "explanations": {"帆布": "〈帆布〉は船の帆を作る丈夫な布で、この文の空所に入る。", "錨": "〈錨〉は船を止める重い金具で、布で帆を作るという文には合わない。", "櫂": "〈櫂〉は船をこぐ道具で、帆の材料にはならない。", "羅針盤": "〈羅針盤〉は方角を示す道具で、帆を作る材料ではない。"}, "sentence_index": 0, "correct_answer": "帆布"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この帆布は薄くて軽いので、夏の下着にちょうどいい。", "explanation": "ここは〈綿布〉の意味。帆布は厚く丈夫な布で、薄い下着の素材には使わない。"}, {"text": "寒い夜は、厚い帆布の布団で体を温めた。", "explanation": "ここは〈寝具〉の意味。帆布は船の帆やかばんに使う丈夫な布で、寝具の素材としては使わない。"}, {"text": "港の店で、古い帆布を裂いて雑巾にした。", "explanation": "ここは〈ぞうきん用の布〉の意味。船の帆を作る材料としての帆布とは別の用途。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59842fc5-799f-4d98-a8d3-278d78c2adcf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39426, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "帆布", "is_correct": true, "explanation": "〈帆布〉は帆を作る布で、古い布を切って帆を作るという文に合う。"}, {"text": "海図", "is_correct": false, "explanation": "〈海図〉は航路を書いた紙で、切って帆にする材料ではない。"}, {"text": "双眼鏡", "is_correct": false, "explanation": "〈双眼鏡〉は遠くを見る道具で、帆を作る材料にはならない。"}, {"text": "救命具", "is_correct": false, "explanation": "〈救命具〉は溺れた人を助ける道具で、帆の材料にはならない。"}], "explanations": {"帆布": "〈帆布〉は帆を作る布で、古い布を切って帆を作るという文に合う。", "海図": "〈海図〉は航路を書いた紙で、切って帆にする材料ではない。", "双眼鏡": "〈双眼鏡〉は遠くを見る道具で、帆を作る材料にはならない。", "救命具": "〈救命具〉は溺れた人を助ける道具で、帆の材料にはならない。"}, "sentence_index": 6, "correct_answer": "帆布"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "夜の海で、高い帆布が岸に打ち寄せ、白く砕けた。", "explanation": "ここは〈波〉の意味。岸に打ち寄せて砕けるのは波で、布地の帆布ではない。"}, {"text": "重い帆布を溶かして、船の部品を作った。", "explanation": "ここは〈鉄〉の意味。帆布は布で、溶かして金属の部品を作る材料にはならない。"}, {"text": "強い風で帆布が根元から折れてしまった。", "explanation": "ここは〈帆柱〉の意味。折れるのは柱で、布地には当てはまらない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59842fc5-799f-4d98-a8d3-278d78c2adcf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39426, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "嵐の日、船乗りは丈夫な帆布の広げて、帆を張った。", "corrected_sentence": "嵐の日、船乗りは丈夫な帆布を広げて、帆を張った。", "error_description": "「帆布の」となっているが、正しくは「帆布を」。動詞「広げる」の目的語には「を」が必要。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59842fc5-799f-4d98-a8d3-278d78c2adcf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39426, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "港の職人は、丈夫な帆布が縫い合わせて、新しい帆を作った。", "corrected_sentence": "港の職人は、丈夫な帆布を縫い合わせて、新しい帆を作った。", "error_description": "「帆布が」となっているが、正しくは「帆布を」。他動詞「縫い合わせる」の目的語には「を」が必要。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59842fc5-799f-4d98-a8d3-278d78c2adcf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39427, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "「厚い帆布で」は材料を表し、「トートバッグを作った」の材料として正しい。"}, {"text": "が", "is_correct": false, "explanation": "「帆布がトートバッグを作った」は布が作る主体になり、意味が通らない。"}, {"text": "を", "is_correct": false, "explanation": "「帆布をトートバッグを作った」は目的語が二つ重なり、非文になる。"}, {"text": "より", "is_correct": false, "explanation": "「帆布よりトートバッグを作った」は比較の文にならず、意味が通らない。"}], "correct_answer": "で", "explanations": {"で": "「厚い帆布で」は材料を表し、「トートバッグを作った」の材料として正しい。", "が": "「帆布がトートバッグを作った」は布が作る主体になり、意味が通らない。", "を": "「帆布をトートバッグを作った」は目的語が二つ重なり、非文になる。", "より": "「帆布よりトートバッグを作った」は比較の文にならず、意味が通らない。"}, "error_tags": {"が": "主語の誤り", "を": "目的語の重複", "より": "比較の誤用"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59842fc5-799f-4d98-a8d3-278d78c2adcf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39427, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「帆布を買って」の「を」は買う対象を示し、正しい。"}, {"text": "と", "is_correct": false, "explanation": "「帆布と一メートル買って」は並列の意味になり、買う対象の文として不自然。"}, {"text": "へ", "is_correct": false, "explanation": "「帆布へ一メートル買って」は方向を表すが、買う対象の文には合わない。"}, {"text": "から", "is_correct": false, "explanation": "「帆布から一メートル買って」は起点の意味になり、買う対象を示す文として不自然。"}], "correct_answer": "を", "explanations": {"を": "「帆布を買って」の「を」は買う対象を示し、正しい。", "と": "「帆布と一メートル買って」は並列の意味になり、買う対象の文として不自然。", "へ": "「帆布へ一メートル買って」は方向を表すが、買う対象の文には合わない。", "から": "「帆布から一メートル買って」は起点の意味になり、買う対象を示す文として不自然。"}, "error_tags": {"と": "並列", "へ": "方向", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59842fc5-799f-4d98-a8d3-278d78c2adcf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39427, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "麻や綿などで平らに織った、丈夫で厚い布。帆やテント、鞄などに使われる。", "primary_collocate": null, "pronunciation": "ほぬの", "ipa": "honɯnɔ", "syllable_count": 3, "sentences": [{"text": "帆布のかばんは丈夫なので、毎日使っても長持ちします。", "target_word": "帆布", "complexity_tier": "T3", "furigana": "帆布[ほぬの]のかばんは丈夫[じょうぶ]なので、毎日[まいにち]使[つか]っても長持[ながも]ちします。", "sentence_source": "generated"}, {"text": "彼女は厚い帆布でトートバッグを作った。", "target_word": "帆布", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は厚[あつ]い帆布[ほぬの]でトートバッグを作[つく]った。", "sentence_source": "generated"}, {"text": "山でキャンプをするとき、帆布のテントを使った。", "target_word": "帆布", "complexity_tier": "T3", "furigana": "山[やま]でキャンプをするとき、帆布[ほぬの]のテントを使[つか]った。", "sentence_source": "generated"}, {"text": "この帆布は、麻と綿を平らに織った布です。", "target_word": "帆布", "complexity_tier": "T3", "furigana": "この帆布[ほぬの]は、麻[あさ]と綿[わた]を平[たい]らに織[お]った布[ぬの]です。", "sentence_source": "generated"}, {"text": "帆布は厚いので、ミシンで縫うのが少し大変だ。", "target_word": "帆布", "complexity_tier": "T3", "furigana": "帆布[ほぬの]は厚[あつ]いので、ミシンで縫[ぬ]うのが少[すこ]し大変[たいへん]だ。", "sentence_source": "generated"}, {"text": "帆布の靴は軽くて、夏の散歩にちょうどいい。", "target_word": "帆布", "complexity_tier": "T3", "furigana": "帆布[ほぬの]の靴[くつ]は軽[かる]くて、夏[なつ]の散歩[さんぽ]にちょうどいい。", "sentence_source": "generated"}, {"text": "帆布のエプロンは汚れても、洗えばきれいになる。", "target_word": "帆布", "complexity_tier": "T3", "furigana": "帆布[ほぬの]のエプロンは汚[よご]れても、洗[あら]えばきれいになる。", "sentence_source": "generated"}, {"text": "店で帆布を一メートル買って、小さな袋を作りました。", "target_word": "帆布", "complexity_tier": "T3", "furigana": "店[みせ]で帆布[ほぬの]を一[いち]メートル買[か]って、小[ちい]さな袋[ふくろ]を作[つく]りました。", "sentence_source": "generated"}, {"text": "帆布は使うほど柔らかくなり、味が出てくる。", "target_word": "帆布", "complexity_tier": "T3", "furigana": "帆布[ほぬの]は使[つか]うほど柔[やわ]らかくなり、味[あじ]が出[で]てくる。", "sentence_source": "generated"}, {"text": "雨の日は、帆布のかばんに防水スプレーをかけます。", "target_word": "帆布", "complexity_tier": "T3", "furigana": "雨[あめ]の日[ひ]は、帆布[ほぬの]のかばんに防水[ぼうすい]スプレーをかけます。", "sentence_source": "generated"}], "morphological_forms": [{"form": "帆布", "label": "基本形"}], "register": "標準（中立）", "sense_fingerprint": "鞄やテントに使う丈夫で厚い織物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01e5a7c6-6233-4cdf-b902-182071ea0773') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39427, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "帆布", "is_correct": true, "explanation": "〈帆布〉は丈夫で厚い織物で、かばんの素材として文に合う。"}, {"text": "石鹸", "is_correct": false, "explanation": "〈石鹸〉は洗うための固形物で、かばんの素材にはならない。"}, {"text": "紙幣", "is_correct": false, "explanation": "〈紙幣〉はお金のことで、かばんの素材ではない。"}, {"text": "砂糖", "is_correct": false, "explanation": "〈砂糖〉は食べ物で、かばんの素材にはならない。"}], "explanations": {"帆布": "〈帆布〉は丈夫で厚い織物で、かばんの素材として文に合う。", "石鹸": "〈石鹸〉は洗うための固形物で、かばんの素材にはならない。", "紙幣": "〈紙幣〉はお金のことで、かばんの素材ではない。", "砂糖": "〈砂糖〉は食べ物で、かばんの素材にはならない。"}, "sentence_index": 0, "correct_answer": "帆布"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この帆布は、牛の皮をなめして作ったもので、柔らかい。", "explanation": "ここは〈革〉の意味。帆布は織った布で、皮をなめたものではない。"}, {"text": "この帆布は薄くて肌触りがよく、夏の寝間着に向いている。", "explanation": "ここは〈綿布〉の意味。帆布は厚く丈夫な布で、薄い寝間着の素材には使わない。"}, {"text": "この帆布は細い糸を結んで作った網で、魚を取るのに使う。", "explanation": "ここは〈漁具〉の意味。帆布は平らに織った布で、網目のある漁具の素材としては使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59842fc5-799f-4d98-a8d3-278d78c2adcf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39427, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "帆布", "is_correct": true, "explanation": "〈帆布〉の布でできたエプロンは、汚れても洗える素材として文に合う。"}, {"text": "陶器", "is_correct": false, "explanation": "〈陶器〉は焼いた土の器で、エプロンの素材にはならない。"}, {"text": "石油", "is_correct": false, "explanation": "〈石油〉は燃料で、エプロンの素材にはならない。"}, {"text": "ガラス", "is_correct": false, "explanation": "〈ガラス〉は割れやすい材料で、洗ってエプロンにする文とは合わない。"}], "explanations": {"帆布": "〈帆布〉の布でできたエプロンは、汚れても洗える素材として文に合う。", "陶器": "〈陶器〉は焼いた土の器で、エプロンの素材にはならない。", "石油": "〈石油〉は燃料で、エプロンの素材にはならない。", "ガラス": "〈ガラス〉は割れやすい材料で、洗ってエプロンにする文とは合わない。"}, "sentence_index": 6, "correct_answer": "帆布"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "雨の日は、帆布を編んで、マフラーを作った。", "explanation": "ここは〈毛糸〉の意味。帆布は厚く織った布で、編んで衣類を作る糸にはならない。"}, {"text": "帆布に手紙を書いて、ポストに入れた。", "explanation": "ここは〈紙〉の意味。帆布は厚い織物で、手紙を書く紙の代わりにはならない。"}, {"text": "けがをしたので、帆布の包帯を巻いた。", "explanation": "ここは〈ガーゼ〉の意味。帆布は丈夫な織物で、傷口に当てる医療用の布としては使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59842fc5-799f-4d98-a8d3-278d78c2adcf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39427, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "旅行用のトートバッグは、厚い帆布に作ると丈夫になる。", "corrected_sentence": "旅行用のトートバッグは、厚い帆布で作ると丈夫になる。", "error_description": "「帆布に」となっているが、正しくは「帆布で」。「作る」の材料は「で」で示す。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59842fc5-799f-4d98-a8d3-278d78c2adcf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39427, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "お気に入りの帆布の、毎日使っている。", "corrected_sentence": "お気に入りの帆布を、毎日使っている。", "error_description": "「帆布の」となっているが、正しくは「帆布を」。「使う」の目的語には「を」が必要。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59842fc5-799f-4d98-a8d3-278d78c2adcf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39428, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「空力を考えて」の「を」は「考える」の目的語を示し、正しい。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を示すので、「空力が考えて」では目的語の位置に合わない。"}, {"text": "に", "is_correct": false, "explanation": "「に」は相手や到着点を示すので、「空力に考えて」では目的語として成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "「の」は名詞どうしをつなぐので、「空力の考えて」は動詞の目的語にならない。"}], "correct_answer": "を", "explanations": {"を": "「空力を考えて」の「を」は「考える」の目的語を示し、正しい。", "が": "「が」は主語を示すので、「空力が考えて」では目的語の位置に合わない。", "に": "「に」は相手や到着点を示すので、「空力に考えて」では目的語として成り立たない。", "の": "「の」は名詞どうしをつなぐので、「空力の考えて」は動詞の目的語にならない。"}, "error_tags": {"が": "主語", "に": "場所・相手", "の": "所属・修飾"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c087fde-8a23-4107-9fdc-2f977c77c827') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39428, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「空力を調べた」の「を」は「調べる」の目的語を示し、正しい。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すので、「空力へ調べた」では目的語の位置に合わない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列や相手を示すので、「空力と調べた」では目的語として文が成り立たない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較を示すので、「空力より調べた」では目的語の位置に合わない。"}], "correct_answer": "を", "explanations": {"を": "「空力を調べた」の「を」は「調べる」の目的語を示し、正しい。", "へ": "「へ」は方向を示すので、「空力へ調べた」では目的語の位置に合わない。", "と": "「と」は並列や相手を示すので、「空力と調べた」では目的語として文が成り立たない。", "より": "「より」は比較を示すので、「空力より調べた」では目的語の位置に合わない。"}, "error_tags": {"へ": "方向を示す", "と": "並列・相手を示す", "より": "比較を示す"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c087fde-8a23-4107-9fdc-2f977c77c827') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39428, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "空気の中を動くときに、ものに働く力のこと。", "primary_collocate": null, "pronunciation": "くうりょく", "ipa": "kɯːɾʲokɯ", "syllable_count": 4, "sentences": [{"text": "速い車ほど、空力の影響を強く受ける。", "target_word": "空力", "complexity_tier": "T3", "furigana": "速[はや]い車[くるま]ほど、空力[くうりょく]の影響[えいきょう]を強[つよ]く受[う]ける。", "sentence_source": "generated"}, {"text": "空力を考えて、車の前の形を丸くした。", "target_word": "空力", "complexity_tier": "T3", "furigana": "空力[くうりょく]を考[かんが]えて、車[くるま]の前[まえ]の形[かたち]を丸[まる]くした。", "sentence_source": "generated"}, {"text": "空力が悪いと、同じ力で走っても速度が出ない。", "target_word": "空力", "complexity_tier": "T3", "furigana": "空力[くうりょく]が悪[わる]いと、同[おな]じ力[ちから]で走[はし]っても速度[そくど]が出[で]ない。", "sentence_source": "generated"}, {"text": "この車は空力がよく、高速でも安定して走る。", "target_word": "空力", "complexity_tier": "T3", "furigana": "この車[くるま]は空力[くうりょく]がよく、高速[こうそく]でも安定[あんてい]して走[はし]る。", "sentence_source": "generated"}, {"text": "紙飛行機は、羽の形で空力が変わる。", "target_word": "空力", "complexity_tier": "T3", "furigana": "紙飛行機[かみひこうき]は、羽[はね]の形[かたち]で空力[くうりょく]が変[か]わる。", "sentence_source": "generated"}, {"text": "新幹線の先頭が長いのは、空力を良くするためだ。", "target_word": "空力", "complexity_tier": "T3", "furigana": "新幹線[しんかんせん]の先頭[せんとう]が長[なが]いのは、空力[くうりょく]を良[よ]くするためだ。", "sentence_source": "generated"}, {"text": "空力の勉強をして、速い模型の車を作りたい。", "target_word": "空力", "complexity_tier": "T3", "furigana": "空力[くうりょく]の勉強[べんきょう]をして、速[はや]い模型[もけい]の車[くるま]を作[つく]りたい。", "sentence_source": "generated"}, {"text": "風洞実験で、車にかかる空力を調べた。", "target_word": "空力", "complexity_tier": "T3", "furigana": "風洞[ふうどう]実験[じっけん]で、車[くるま]にかかる空力[くうりょく]を調[しら]べた。", "sentence_source": "generated"}, {"text": "鳥は羽を広げて、空力をうまく使って飛ぶ。", "target_word": "空力", "complexity_tier": "T3", "furigana": "鳥[とり]は羽[はね]を広[ひろ]げて、空力[くうりょく]をうまく使[つか]って飛[と]ぶ。", "sentence_source": "generated"}, {"text": "速度が上がるほど、空力は大きくなる。", "target_word": "空力", "complexity_tier": "T3", "furigana": "速度[そくど]が上[あ]がるほど、空力[くうりょく]は大[おお]きくなる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "空力", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "空気中を動く物に働く力。車や自転車の速さや形との関係で使う。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e9d0569-35c2-4591-8d48-a8dee00aafec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39428, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "空力", "is_correct": true, "explanation": "空力は空気中を動く車に働く力で、速い車が強く受ける影響に合う。"}, {"text": "歌詞", "is_correct": false, "explanation": "歌詞は歌の言葉のことで、速い車が影響を受ける対象にはならない。"}, {"text": "方言", "is_correct": false, "explanation": "方言は地域独自のことばで、速い車の影響を受けるという文が成り立たない。"}, {"text": "絵画", "is_correct": false, "explanation": "絵画は描かれた作品のことで、速い車が影響を受ける対象としては意味が通らない。"}], "explanations": {"空力": "空力は空気中を動く車に働く力で、速い車が強く受ける影響に合う。", "歌詞": "歌詞は歌の言葉のことで、速い車が影響を受ける対象にはならない。", "方言": "方言は地域独自のことばで、速い車の影響を受けるという文が成り立たない。", "絵画": "絵画は描かれた作品のことで、速い車が影響を受ける対象としては意味が通らない。"}, "sentence_index": 0, "correct_answer": "空力"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この選手は高い空力が持ち味だ。", "explanation": "ここは〈能力〉の意味。空力は空気中で物体に働く力を指すので、人の能力には使わない。"}, {"text": "空力で電気を作る発電所が、海沿いにいくつもできた。", "explanation": "ここは〈風力〉の意味。空力は動く物体が空気から受ける力で、風のエネルギーで発電する話には合わない。"}, {"text": "この薬は空力が強いので、量を減らすよう医者に言われた。", "explanation": "ここは〈効力〉の意味。空力は空気中で物体に働く力で、薬の効き目には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c087fde-8a23-4107-9fdc-2f977c77c827') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39428, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "空力", "is_correct": true, "explanation": "空力の勉強は、空気中で車が受ける力を学ぶことなので、模型の車作りに合う。"}, {"text": "歌詞", "is_correct": false, "explanation": "歌詞の勉強は歌の言葉を学ぶことで、模型の車を作る話とは結びつかない。"}, {"text": "寝袋", "is_correct": false, "explanation": "寝袋は眠るための道具で、勉強の対象として文が成り立たない。"}, {"text": "大根", "is_correct": false, "explanation": "大根は野菜で、勉強の対象として意味が通らない。"}], "explanations": {"空力": "空力の勉強は、空気中で車が受ける力を学ぶことなので、模型の車作りに合う。", "歌詞": "歌詞の勉強は歌の言葉を学ぶことで、模型の車を作る話とは結びつかない。", "寝袋": "寝袋は眠るための道具で、勉強の対象として文が成り立たない。", "大根": "大根は野菜で、勉強の対象として意味が通らない。"}, "sentence_index": 6, "correct_answer": "空力"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "床と靴の空力で、足が滑りにくい。", "explanation": "ここは〈摩擦〉の意味。空力は空気中で物体が受ける力なので、床と靴の間に働く力には使わない。"}, {"text": "水中で手を前に動かすと、空力で手が押し返される。", "explanation": "ここは〈抗力〉の意味。空力は空気の中で動く物体に働く力で、水の中で押し返される場合には使わない。"}, {"text": "このパソコンは空力で熱を逃がす。", "explanation": "ここは〈空冷〉の意味。空力は物体が空気から受ける力で、空気で熱を冷ます仕組みには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c087fde-8a23-4107-9fdc-2f977c77c827') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39428, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "車の形を変えて、空力が良くした。", "corrected_sentence": "車の形を変えて、空力を良くした。", "error_description": "「良くする」の目的語は「空力を」。「空力が」は主語の形になり、ここでは誤り（正しくは「を」）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c087fde-8a23-4107-9fdc-2f977c77c827') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39428, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "空力を変化を、模型の車で確かめた。", "corrected_sentence": "空力の変化を、模型の車で確かめた。", "error_description": "「空力の変化」の「の」は「空力」と「変化」をつなぐ助詞。「を」にすると目的語の形になり不自然で、正しくは「の」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c087fde-8a23-4107-9fdc-2f977c77c827') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39430, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「北の極限には」は場所を示し、「ある」「広がる」の場所の文として正しい。"}, {"text": "を", "is_correct": false, "explanation": "「北の極限を」は場所ではなく対象を示し、文の意味が通らない。"}, {"text": "の", "is_correct": false, "explanation": "「北の極限の」は所属を示すが、場所を表す文脈には合わない。"}, {"text": "が", "is_correct": false, "explanation": "「北の極限がは」は主語の後に「は」が続き、非文になる。"}], "correct_answer": "に", "explanations": {"に": "「北の極限には」は場所を示し、「ある」「広がる」の場所の文として正しい。", "を": "「北の極限を」は場所ではなく対象を示し、文の意味が通らない。", "の": "「北の極限の」は所属を示すが、場所を表す文脈には合わない。", "が": "「北の極限がは」は主語の後に「は」が続き、非文になる。"}, "error_tags": {"を": "目的語", "の": "所属", "が": "主語"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59842fc5-799f-4d98-a8d3-278d78c2adcf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39430, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「岬の極限に着いた」の「に」は到着する場所を示し、正しい。"}, {"text": "が", "is_correct": false, "explanation": "「極限が着いた」は極限が着く主体になり、意味が通らない。"}, {"text": "と", "is_correct": false, "explanation": "「極限と着いた」は並列の意味になり、到着の文として成り立たない。"}, {"text": "より", "is_correct": false, "explanation": "「極限より着いた」は比較の意味になり、到着の文として不自然。"}], "correct_answer": "に", "explanations": {"に": "「岬の極限に着いた」の「に」は到着する場所を示し、正しい。", "が": "「極限が着いた」は極限が着く主体になり、意味が通らない。", "と": "「極限と着いた」は並列の意味になり、到着の文として成り立たない。", "より": "「極限より着いた」は比較の意味になり、到着の文として不自然。"}, "error_tags": {"が": "主語", "と": "並列", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59842fc5-799f-4d98-a8d3-278d78c2adcf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39430, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "これ以上はないという、いちばんはしっこのところ。", "primary_collocate": null, "pronunciation": "きょくげん", "ipa": "kʲokɯɡeɴ", "syllable_count": 4, "sentences": [{"text": "探検家は、世界の極限にある島へ向かった。", "target_word": "極限", "complexity_tier": "T3", "furigana": "探検家[たんけんか]は、世界[せかい]の極限[きょくげん]にある島[しま]へ向[む]かった。", "sentence_source": "generated"}, {"text": "北の極限には、一年中氷しかない土地が広がっている。", "target_word": "極限", "complexity_tier": "T3", "furigana": "北[きた]の極限[きょくげん]には、一年中[いちねんじゅう]氷[こおり]しかない土地[とち]が広[ひろ]がっている。", "sentence_source": "generated"}, {"text": "陸地の極限はここで、これより先は海だった。", "target_word": "極限", "complexity_tier": "T3", "furigana": "陸地[りくち]の極限[きょくげん]はここで、これより先[さき]は海[うみ]だった。", "sentence_source": "generated"}, {"text": "旅人は大地の極限に立って、遠い水平線を見た。", "target_word": "極限", "complexity_tier": "T3", "furigana": "旅人[たびびと]は大地[だいち]の極限[きょくげん]に立[た]って、遠[とお]い水平線[すいへいせん]を見[み]た。", "sentence_source": "generated"}, {"text": "望遠鏡でも、宇宙の極限は見えない。", "target_word": "極限", "complexity_tier": "T3", "furigana": "望遠鏡[ぼうえんきょう]でも、宇宙[うちゅう]の極限[きょくげん]は見[み]えない。", "sentence_source": "generated"}, {"text": "彼は国の極限の町で生まれ、海を見て育った。", "target_word": "極限", "complexity_tier": "T3", "furigana": "彼[かれ]は国[くに]の極限[きょくげん]の町[まち]で生[う]まれ、海[うみ]を見[み]て育[そだ]った。", "sentence_source": "generated"}, {"text": "森の極限まで歩くと、高い壁が現れた。", "target_word": "極限", "complexity_tier": "T3", "furigana": "森[もり]の極限[きょくげん]まで歩[ある]くと、高[たか]い壁[かべ]が現[あらわ]れた。", "sentence_source": "generated"}, {"text": "岬の極限に着いたとき、もう進む道はなかった。", "target_word": "極限", "complexity_tier": "T3", "furigana": "岬[みさき]の極限[きょくげん]に着[つ]いたとき、もう進[すす]む道[みち]はなかった。", "sentence_source": "generated"}, {"text": "村人は、谷の極限にある古い家に住んでいる。", "target_word": "極限", "complexity_tier": "T3", "furigana": "村人[むらびと]は、谷[たに]の極限[きょくげん]にある古[ふる]い家[いえ]に住[す]んでいる。", "sentence_source": "generated"}, {"text": "船は海の極限を目指したが、霧で引き返した。", "target_word": "極限", "complexity_tier": "T3", "furigana": "船[ふね]は海[うみ]の極限[きょくげん]を目指[めざ]したが、霧[きり]で引[ひ]き返[かえ]した。", "sentence_source": "generated"}], "morphological_forms": [{"form": "極限", "label": "基本形"}], "register": "標準（やや硬い）", "sense_fingerprint": "場所のいちばん端、これ以上先のない所", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01e5a7c6-6233-4cdf-b902-182071ea0773') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39430, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "極限", "is_correct": true, "explanation": "〈極限〉は場所のいちばん端を指し、「世界の極限にある島」として自然に入る。"}, {"text": "眠気", "is_correct": false, "explanation": "〈眠気〉は眠い感じのことで、場所を表す語ではないため「世界の眠気」は成り立たない。"}, {"text": "友情", "is_correct": false, "explanation": "〈友情〉は人の気持ちの語で、島の場所を示す語にはならない。"}, {"text": "色彩", "is_correct": false, "explanation": "〈色彩〉は色のことで、島の位置を示す語としては合わない。"}], "explanations": {"極限": "〈極限〉は場所のいちばん端を指し、「世界の極限にある島」として自然に入る。", "眠気": "〈眠気〉は眠い感じのことで、場所を表す語ではないため「世界の眠気」は成り立たない。", "友情": "〈友情〉は人の気持ちの語で、島の場所を示す語にはならない。", "色彩": "〈色彩〉は色のことで、島の位置を示す語としては合わない。"}, "sentence_index": 0, "correct_answer": "極限"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "重い荷物で腕の力が極限に達して、箱を落とした。", "explanation": "ここは〈極度〉の意味。力の程度が尽きる話で、場所の端を指す極限とは合わない。"}, {"text": "この関数の極限を求めると、値は0になる。", "explanation": "ここは〈極限値〉の意味。数学で値が近づく先を指す語で、場所の端を指す極限とは合わない。"}, {"text": "彼の怒りは極限に達し、部屋を飛び出した。", "explanation": "ここは〈怒りの最高潮〉の意味。感情の高まりを指す語で、場所の端を指す極限とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59842fc5-799f-4d98-a8d3-278d78c2adcf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39430, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "極限", "is_correct": true, "explanation": "〈極限〉は森のいちばん端を指し、「森の極限まで歩く」に合う。"}, {"text": "季節", "is_correct": false, "explanation": "〈季節〉は時の区切りで、場所を指す語ではないため「森の季節まで」は成り立たない。"}, {"text": "手紙", "is_correct": false, "explanation": "〈手紙〉は文書で、森の場所を表す語にはならない。"}, {"text": "音楽", "is_correct": false, "explanation": "〈音楽〉は音の芸術で、歩いていく場所を示す語にはならない。"}], "explanations": {"極限": "〈極限〉は森のいちばん端を指し、「森の極限まで歩く」に合う。", "季節": "〈季節〉は時の区切りで、場所を指す語ではないため「森の季節まで」は成り立たない。", "手紙": "〈手紙〉は文書で、森の場所を表す語にはならない。", "音楽": "〈音楽〉は音の芸術で、歩いていく場所を示す語にはならない。"}, "sentence_index": 6, "correct_answer": "極限"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "疲れが極限に達して、彼はその場に座り込んだ。", "explanation": "ここは〈限界〉の意味。体の疲れや程度の話で、場所の端を指す語ではない。"}, {"text": "船は海の極限をくぐり抜けたが、霧で引き返した。", "explanation": "ここは〈出口〉の意味。通り抜ける穴を指す語で、はしっこの極限とは違う。"}, {"text": "試合の極限で、彼は同点ゴールを決めた。", "explanation": "ここは〈終盤〉の意味。試合の後半の時間を指す語で、はしっこの極限とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59842fc5-799f-4d98-a8d3-278d78c2adcf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39430, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "旅人は、南の果てにある大地の極限に目指して歩いた。", "corrected_sentence": "旅人は、南の果てにある大地の極限を目指して歩いた。", "error_description": "「極限に」となっているが、正しくは「極限を」。動詞「目指す」の目的語には「を」が必要。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59842fc5-799f-4d98-a8d3-278d78c2adcf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39430, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "島の極限を小さな村があった。", "corrected_sentence": "島の極限に小さな村があった。", "error_description": "「極限を」となっているが、正しくは「極限に」。存在する場所を示すには「に」が必要。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59842fc5-799f-4d98-a8d3-278d78c2adcf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39431, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "まで", "options": [{"text": "まで", "is_correct": true, "explanation": "「極限まで我慢した」は我慢の限界まで耐えたという意味で、正しい。"}, {"text": "が", "is_correct": false, "explanation": "「極限が我慢した」は極限が耐える主体になり、意味が通らない。"}, {"text": "と", "is_correct": false, "explanation": "「極限と我慢した」は並列の意味になり、文として成り立たない。"}, {"text": "より", "is_correct": false, "explanation": "「極限より我慢した」は比較の意味になり、我慢の程度を示す文として不自然。"}], "correct_answer": "まで", "explanations": {"まで": "「極限まで我慢した」は我慢の限界まで耐えたという意味で、正しい。", "が": "「極限が我慢した」は極限が耐える主体になり、意味が通らない。", "と": "「極限と我慢した」は並列の意味になり、文として成り立たない。", "より": "「極限より我慢した」は比較の意味になり、我慢の程度を示す文として不自然。"}, "error_tags": {"が": "主語", "と": "並列", "より": "比較"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59842fc5-799f-4d98-a8d3-278d78c2adcf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39431, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「極限を目指して」の「を」は目指す対象を示し、正しい。"}, {"text": "に", "is_correct": false, "explanation": "「極限に目指して」は「目指す」の対象の格として不自然。"}, {"text": "から", "is_correct": false, "explanation": "「極限から目指して」は起点の意味になり、目指す対象を示す文として成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "「極限の目指して」は所属の意味になり、動詞とつながらず不自然。"}], "correct_answer": "を", "explanations": {"を": "「極限を目指して」の「を」は目指す対象を示し、正しい。", "に": "「極限に目指して」は「目指す」の対象の格として不自然。", "から": "「極限から目指して」は起点の意味になり、目指す対象を示す文として成り立たない。", "の": "「極限の目指して」は所属の意味になり、動詞とつながらず不自然。"}, "error_tags": {"に": "方向・対象", "から": "起点", "の": "所属"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59842fc5-799f-4d98-a8d3-278d78c2adcf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39431, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物事の状態や程度が、それ以上進めないという限界の点。", "primary_collocate": null, "pronunciation": "きょくげん", "ipa": "kʲokɯɡeɴ", "syllable_count": 4, "sentences": [{"text": "長い練習で、体力が極限に達した。", "target_word": "極限", "complexity_tier": "T3", "furigana": "長[なが]い練習[れんしゅう]で、体力[たいりょく]が極限[きょくげん]に達[たっ]した。", "sentence_source": "generated"}, {"text": "極限まで我慢したが、ついに泣き出してしまった。", "target_word": "極限", "complexity_tier": "T3", "furigana": "極限[きょくげん]まで我慢[がまん]したが、ついに泣[な]き出[だ]してしまった。", "sentence_source": "generated"}, {"text": "登山者たちは極限の寒さの中で夜を過ごした。", "target_word": "極限", "complexity_tier": "T3", "furigana": "登山者[とざんしゃ]たちは極限[きょくげん]の寒[さむ]さの中[なか]で夜[よる]を過[す]ごした。", "sentence_source": "generated"}, {"text": "彼の集中力は極限に近づき、手が止まった。", "target_word": "極限", "complexity_tier": "T3", "furigana": "彼[かれ]の集中力[しゅうちゅうりょく]は極限[きょくげん]に近[ちか]づき、手[て]が止[と]まった。", "sentence_source": "generated"}, {"text": "この技術は、極限まで小さくすることができる。", "target_word": "極限", "complexity_tier": "T3", "furigana": "この技術[ぎじゅつ]は、極限[きょくげん]まで小[ちい]さくすることができる。", "sentence_source": "generated"}, {"text": "極限の状態でも、冷静に判断できる人は少ない。", "target_word": "極限", "complexity_tier": "T3", "furigana": "極限[きょくげん]の状態[じょうたい]でも、冷静[れいせい]に判断[はんだん]できる人[ひと]は少[すく]ない。", "sentence_source": "generated"}, {"text": "疲れが極限だったので、帰ってすぐ眠った。", "target_word": "極限", "complexity_tier": "T3", "furigana": "疲[つか]れが極限[きょくげん]だったので、帰[かえ]ってすぐ眠[ねむ]った。", "sentence_source": "generated"}, {"text": "速さの極限を目指して、選手は毎日走り込んでいる。", "target_word": "極限", "complexity_tier": "T3", "furigana": "速[はや]さの極限[きょくげん]を目指[めざ]して、選手[せんしゅ]は毎日[まいにち]走[はし]り込[こ]んでいる。", "sentence_source": "generated"}, {"text": "緊張が極限に達して、声が出なくなった。", "target_word": "極限", "complexity_tier": "T3", "furigana": "緊張[きんちょう]が極限[きょくげん]に達[たっ]して、声[こえ]が出[で]なくなった。", "sentence_source": "generated"}, {"text": "食べ物がなく、村人は極限の生活を強いられた。", "target_word": "極限", "complexity_tier": "T3", "furigana": "食[た]べ物[もの]がなく、村人[むらびと]は極限[きょくげん]の生活[せいかつ]を強[し]いられた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "極限", "label": "基本形"}], "register": "標準（やや硬い）", "sense_fingerprint": "状態や程度がこれ以上進めない限界", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01e5a7c6-6233-4cdf-b902-182071ea0773') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39431, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "極限", "is_correct": true, "explanation": "〈極限〉は限界の点で、「体力が極限に達した」と自然に続く。"}, {"text": "寝床", "is_correct": false, "explanation": "〈寝床〉は寝る場所で、体力の程度を表す語ではないため「体力が寝床に達した」は成り立たない。"}, {"text": "花火", "is_correct": false, "explanation": "〈花火〉は夜空に上がる光で、体力の程度とは関係がない。"}, {"text": "機嫌", "is_correct": false, "explanation": "〈機嫌〉は気分の状態で、体力の限界を表す語にはならない。"}], "explanations": {"極限": "〈極限〉は限界の点で、「体力が極限に達した」と自然に続く。", "寝床": "〈寝床〉は寝る場所で、体力の程度を表す語ではないため「体力が寝床に達した」は成り立たない。", "花火": "〈花火〉は夜空に上がる光で、体力の程度とは関係がない。", "機嫌": "〈機嫌〉は気分の状態で、体力の限界を表す語にはならない。"}, "sentence_index": 0, "correct_answer": "極限"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "長い旅の極限に着いて、みんなで休んだ。", "explanation": "ここは〈終点〉の意味。旅の行き先を指す語で、程度の限界を表す極限とは合わない。"}, {"text": "長い旅の極限から出発した。", "explanation": "ここは〈出発点〉の意味。出発の場所を指す語で、程度の限界とは合わない。"}, {"text": "山の極限に登ったとき、雲の上に出た。", "explanation": "ここは〈頂点〉の意味。山の一番上を指す語で、程度の限界を表す極限とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59842fc5-799f-4d98-a8d3-278d78c2adcf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39431, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "極限", "is_correct": true, "explanation": "〈極限〉は限界の点で、「疲れが極限だったので」と限界に達した状態を示す。"}, {"text": "花束", "is_correct": false, "explanation": "〈花束〉は花をまとめたもので、疲れの程度を表す語ではない。"}, {"text": "湯呑", "is_correct": false, "explanation": "〈湯呑〉は茶を飲む器で、疲れの程度を表す語にはならない。"}, {"text": "電卓", "is_correct": false, "explanation": "〈電卓〉は計算機で、疲れの状態を表す語としては合わない。"}], "explanations": {"極限": "〈極限〉は限界の点で、「疲れが極限だったので」と限界に達した状態を示す。", "花束": "〈花束〉は花をまとめたもので、疲れの程度を表す語ではない。", "湯呑": "〈湯呑〉は茶を飲む器で、疲れの程度を表す語にはならない。", "電卓": "〈電卓〉は計算機で、疲れの状態を表す語としては合わない。"}, "sentence_index": 6, "correct_answer": "極限"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この地図の極限には、未知の国が描かれている。", "explanation": "ここは〈端〉の意味。地図や場所の端を指す語で、程度の限界とは違う。"}, {"text": "船は極限の彼方へ消えていき、もう見えなかった。", "explanation": "ここは〈地平線〉の意味。見える境目を指す語で、程度の限界を表す極限とは合わない。"}, {"text": "この数列の極限を求めると、答えは2になった。", "explanation": "ここは〈極限値〉の意味。数学で数列が近づく値を指す語で、程度の限界とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59842fc5-799f-4d98-a8d3-278d78c2adcf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39431, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "疲れが極限を近づいたので、少し休むことにした。", "corrected_sentence": "疲れが極限に近づいたので、少し休むことにした。", "error_description": "「極限を」となっているが、正しくは「極限に」。動詞「近づく」は「に」を取る。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59842fc5-799f-4d98-a8d3-278d78c2adcf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39431, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼は極限を疲れを感じながら、仕事を続けた。", "corrected_sentence": "彼は極限の疲れを感じながら、仕事を続けた。", "error_description": "「極限を」となっているが、正しくは「極限の」。「極限の疲れ」は限界に達した疲れを表す名詞句で、「の」が必要。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59842fc5-799f-4d98-a8d3-278d78c2adcf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39432, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "「ブレードは〜羽です」と、説明の主題を示す「は」。"}, {"text": "に", "is_correct": false, "explanation": "方向や相手を示す「に」は、説明の主題を作れないので合わない。"}, {"text": "を", "is_correct": false, "explanation": "動作の対象を示す「を」は、「です」で説明する文の主題には入らない。"}, {"text": "で", "is_correct": false, "explanation": "手段や場所を示す「で」は、主題の位置には入らないので合わない。"}], "correct_answer": "は", "explanations": {"は": "「ブレードは〜羽です」と、説明の主題を示す「は」。", "に": "方向や相手を示す「に」は、説明の主題を作れないので合わない。", "を": "動作の対象を示す「を」は、「です」で説明する文の主題には入らない。", "で": "手段や場所を示す「で」は、主題の位置には入らないので合わない。"}, "error_tags": {"に": "方向・相手", "を": "目的語", "で": "手段・場所"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ff88f66-a23a-43b4-812c-c0d92e99400c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39432, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「ブレードを止める」の目的語を示す「を」。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す「へ」は「止める」の対象にはならないので合わない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は相手や並列を示すため、「止める」の目的語にはならない。"}, {"text": "から", "is_correct": false, "explanation": "起点を示す「から」は、「止める」の対象を表す位置には入らない。"}], "correct_answer": "を", "explanations": {"を": "「ブレードを止める」の目的語を示す「を」。", "へ": "方向を示す「へ」は「止める」の対象にはならないので合わない。", "と": "「と」は相手や並列を示すため、「止める」の目的語にはならない。", "から": "起点を示す「から」は、「止める」の対象を表す位置には入らない。"}, "error_tags": {"へ": "方向", "と": "相手・並列", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ff88f66-a23a-43b4-812c-c0d92e99400c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39432, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "かぜのちからでまわる、はねのようなもの。", "primary_collocate": null, "pronunciation": "ぶれーど", "ipa": "bɯɾeːdo", "syllable_count": 4, "sentences": [{"text": "風車のブレードが、風を受けてゆっくり回っている。", "target_word": "ブレード", "complexity_tier": "T3", "furigana": "風車[ふうしゃ]のブレードが、風[かぜ]を受[う]けてゆっくり回[まわ]っている。", "sentence_source": "generated"}, {"text": "ブレードは、風の力で回る大きな羽です。", "target_word": "ブレード", "complexity_tier": "T3", "furigana": "ブレードは、風[かぜ]の力[ちから]で回[まわ]る大[おお]きな羽[はね]です。", "sentence_source": "generated"}, {"text": "強い風がふくと、ブレードの回る速さが上がる。", "target_word": "ブレード", "complexity_tier": "T3", "furigana": "強[つよ]い風[かぜ]がふくと、ブレードの回[まわ]る速[はや]さが上[あ]がる。", "sentence_source": "generated"}, {"text": "丘の上に、三枚のブレードをもつ風車が立っている。", "target_word": "ブレード", "complexity_tier": "T3", "furigana": "丘[おか]の上[うえ]に、三[さん]枚[まい]のブレードをもつ風車[ふうしゃ]が立[た]っている。", "sentence_source": "generated"}, {"text": "ブレードはとても長くて、見上げると首が痛くなる。", "target_word": "ブレード", "complexity_tier": "T3", "furigana": "ブレードはとても長[なが]くて、見上[みあ]げると首[くび]が痛[いた]くなる。", "sentence_source": "generated"}, {"text": "風がないと、ブレードは止まったまま動かない。", "target_word": "ブレード", "complexity_tier": "T3", "furigana": "風[かぜ]がないと、ブレードは止[と]まったまま動[うご]かない。", "sentence_source": "generated"}, {"text": "ブレードが回るのを、子どもたちはずっと見ていた。", "target_word": "ブレード", "complexity_tier": "T3", "furigana": "ブレードが回[まわ]るのを、子[こ]どもたちはずっと見[み]ていた。", "sentence_source": "generated"}, {"text": "台風の前に、ブレードを止めて風車を守る。", "target_word": "ブレード", "complexity_tier": "T3", "furigana": "台風[たいふう]の前[まえ]に、ブレードを止[と]めて風車[ふうしゃ]を守[まも]る。", "sentence_source": "generated"}, {"text": "ブレードの先は、ものすごい速さで動いている。", "target_word": "ブレード", "complexity_tier": "T3", "furigana": "ブレードの先[さき]は、ものすごい速[はや]さで動[うご]いている。", "sentence_source": "generated"}, {"text": "鳥がぶつからないように、ブレードに色をぬった。", "target_word": "ブレード", "complexity_tier": "T3", "furigana": "鳥[とり]がぶつからないように、ブレードに色[いろ]をぬった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "ブレード", "label": "基本形"}], "register": "一般・やさしい文", "sense_fingerprint": "風の力で回る風車の羽根（子ども向けの説明）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa11b1da-6a01-497b-ba17-85963d2f0c23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39432, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "基礎", "is_correct": false, "explanation": "風車を支える土台の部分で、風を受けて回る部分ではないので合わない。"}, {"text": "ブレード", "is_correct": true, "explanation": "風を受けて回る風車の羽根の部分で、ここに入る。"}, {"text": "タワー", "is_correct": false, "explanation": "風車を支える塔で、風を受けて回るものではないので合わない。"}, {"text": "ケーブル", "is_correct": false, "explanation": "電気を送る線で、風を受けて回る部分ではないので合わない。"}], "explanations": {"基礎": "風車を支える土台の部分で、風を受けて回る部分ではないので合わない。", "ブレード": "風を受けて回る風車の羽根の部分で、ここに入る。", "タワー": "風車を支える塔で、風を受けて回るものではないので合わない。", "ケーブル": "電気を送る線で、風を受けて回る部分ではないので合わない。"}, "sentence_index": 0, "correct_answer": "ブレード"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "鳥は、ブレードを大きく広げて飛び立った。", "explanation": "〈羽根〉（鳥の羽）と混同した文。ブレードは風車の部品なので、鳥の体には使わない。"}, {"text": "朝ごはんに、ブレードを焼いた。", "explanation": "食べ物を焼く文。風車の部品のブレードは焼く対象ではないので合わない。"}, {"text": "寒い日は、ブレードで丸くなる。", "explanation": "人が入って丸くなれる場所の文。ブレードは風車の部品で、人が入れるものではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ff88f66-a23a-43b4-812c-c0d92e99400c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39432, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "ガラス", "is_correct": false, "explanation": "光を通す材料で、子どもたちがずっと見ていた回転するものとは合わない。"}, {"text": "石炭", "is_correct": false, "explanation": "燃料になる鉱物で、回転する物として見ていたという文脈と合わない。"}, {"text": "ブレード", "is_correct": true, "explanation": "回転する風車の羽根を指す語で、子どもたちが見ていたものに当たる。"}, {"text": "レンガ", "is_correct": false, "explanation": "積み上げる建材で、回る物ではないので合わない。"}], "explanations": {"ガラス": "光を通す材料で、子どもたちがずっと見ていた回転するものとは合わない。", "石炭": "燃料になる鉱物で、回転する物として見ていたという文脈と合わない。", "ブレード": "回転する風車の羽根を指す語で、子どもたちが見ていたものに当たる。", "レンガ": "積み上げる建材で、回る物ではないので合わない。"}, "sentence_index": 6, "correct_answer": "ブレード"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "電気を家に送るのは、ブレードの仕事だ。", "explanation": "〈発電機〉と混同した文。ブレードは風で回る羽根の部分で、電気を送るのは発電機の役目なので合わない。"}, {"text": "今日の給食は、ブレードだった。", "explanation": "食べ物として出される文。ブレードは食べられる物ではないので、給食の献立にはならない。"}, {"text": "夜ふかしして、ブレードを消してねむった。", "explanation": "明かりを消す文。ブレードは光を出さない風車の部品なので、消す物としては合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ff88f66-a23a-43b4-812c-c0d92e99400c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39432, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "ブレードに強い風を受けて、大きく揺れた。", "corrected_sentence": "ブレードが強い風を受けて、大きく揺れた。", "error_description": "「受ける」の主語は「が」で示す。「に」は誤りで、正しくは「ブレードが」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ff88f66-a23a-43b4-812c-c0d92e99400c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39432, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "強い風の日は、ブレードを止めた点検する。", "corrected_sentence": "強い風の日は、ブレードを止めて点検する。", "error_description": "「止めて点検する」が正しい。「止めた」は完了の形で、後の「点検する」とつながらない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ff88f66-a23a-43b4-812c-c0d92e99400c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39433, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "「ブレードは、〜ものもある」と主題を示す「は」。"}, {"text": "を", "is_correct": false, "explanation": "目的語を示す「を」は、「ものもある」の主題の位置には入らない。"}, {"text": "に", "is_correct": false, "explanation": "場所や相手を示す「に」は、この文の主題を作れないので合わない。"}, {"text": "で", "is_correct": false, "explanation": "手段や場所を示す「で」は、主題の位置には入らないので合わない。"}], "correct_answer": "は", "explanations": {"は": "「ブレードは、〜ものもある」と主題を示す「は」。", "を": "目的語を示す「を」は、「ものもある」の主題の位置には入らない。", "に": "場所や相手を示す「に」は、この文の主題を作れないので合わない。", "で": "手段や場所を示す「で」は、主題の位置には入らないので合わない。"}, "error_tags": {"を": "目的語", "に": "方向・相手", "で": "手段・場所"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ff88f66-a23a-43b4-812c-c0d92e99400c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39433, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「ブレードの形」と続けて、形の所有・修飾を示す「の」。"}, {"text": "を", "is_correct": false, "explanation": "「ブレードを形を」と目的語が二つ重なり、文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す「へ」は「形」とつながらないので合わない。"}, {"text": "から", "is_correct": false, "explanation": "起点を示す「から」は、「形」を修飾する位置には入らない。"}], "correct_answer": "の", "explanations": {"の": "「ブレードの形」と続けて、形の所有・修飾を示す「の」。", "を": "「ブレードを形を」と目的語が二つ重なり、文が成り立たない。", "へ": "方向を示す「へ」は「形」とつながらないので合わない。", "から": "起点を示す「から」は、「形」を修飾する位置には入らない。"}, "error_tags": {"へ": "方向", "から": "起点", "を": "目的語の重なり"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ff88f66-a23a-43b4-812c-c0d92e99400c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39433, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "風力発電の風車の羽根の部分。風を受けて回転し、発電機を動かす。", "primary_collocate": null, "pronunciation": "ぶれーど", "ipa": "bɯɾeːdo", "syllable_count": 4, "sentences": [{"text": "風力発電では、ブレードが風を受けて回転し、発電機を動かす。", "target_word": "ブレード", "complexity_tier": "T3", "furigana": "風力[ふうりょく]発電[はつでん]では、ブレードが風[かぜ]を受[う]けて回転[かいてん]し、発電機[はつでんき]を動[うご]かす。", "sentence_source": "generated"}, {"text": "大型の風車のブレードは、長さが七十メートルを超えるものもある。", "target_word": "ブレード", "complexity_tier": "T3", "furigana": "大型[おおがた]の風車[ふうしゃ]のブレードは、長[なが]さが七十[ななじゅう]メートルを超[こ]えるものもある。", "sentence_source": "generated"}, {"text": "ブレードの角度を変えて、風の強さに合わせて回転を調整する。", "target_word": "ブレード", "complexity_tier": "T3", "furigana": "ブレードの角度[かくど]を変[か]えて、風[かぜ]の強[つよ]さに合[あ]わせて回転[かいてん]を調整[ちょうせい]する。", "sentence_source": "generated"}, {"text": "落雷でブレードが損傷し、発電が止まった。", "target_word": "ブレード", "complexity_tier": "T3", "furigana": "落雷[らくらい]でブレードが損傷[そんしょう]し、発電[はつでん]が止[と]まった。", "sentence_source": "generated"}, {"text": "軽くて丈夫な素材で、ブレードを作る。", "target_word": "ブレード", "complexity_tier": "T3", "furigana": "軽[かる]くて丈夫[じょうぶ]な素材[そざい]で、ブレードを作[つく]る。", "sentence_source": "generated"}, {"text": "点検員は、ロープでつり下がってブレードの傷を調べた。", "target_word": "ブレード", "complexity_tier": "T3", "furigana": "点検員[てんけんいん]は、ロープでつり下[さ]がってブレードの傷[きず]を調[しら]べた。", "sentence_source": "generated"}, {"text": "風を受けて回る古いブレードの処分が、新たな課題になっている。", "target_word": "ブレード", "complexity_tier": "T3", "furigana": "風[かぜ]を受[う]けて回[まわ]る古[ふる]いブレードの処分[しょぶん]が、新[あら]たな課題[かだい]になっている。", "sentence_source": "generated"}, {"text": "ブレードの形を工夫すると、少ない風でも効率よく発電できる。", "target_word": "ブレード", "complexity_tier": "T3", "furigana": "ブレードの形[かたち]を工夫[くふう]すると、少[すく]ない風[かぜ]でも効率[こうりつ]よく発電[はつでん]できる。", "sentence_source": "generated"}, {"text": "海上の風車は、陸上よりも大きなブレードを付けられる。", "target_word": "ブレード", "complexity_tier": "T3", "furigana": "海上[かいじょう]の風車[ふうしゃ]は、陸上[りくじょう]よりも大[おお]きなブレードを付[つ]けられる。", "sentence_source": "generated"}, {"text": "輸送の際、長いブレードは専用のトラックで運ぶ。", "target_word": "ブレード", "complexity_tier": "T3", "furigana": "輸送[ゆそう]の際[さい]、長[なが]いブレードは専用[せんよう]のトラックで運[はこ]ぶ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "ブレード", "label": "基本形"}], "register": "技術・説明文", "sense_fingerprint": "風力発電の風車で風を受けて回転し発電機を動かす羽根部分", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa11b1da-6a01-497b-ba17-85963d2f0c23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39433, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "送電線", "is_correct": false, "explanation": "電気を運ぶ線で、風を受けて回転し発電機を動かす部分ではないので合わない。"}, {"text": "ブレード", "is_correct": true, "explanation": "風を受けて回転し、発電機を動かす風力発電の部品なので、ここに入る。"}, {"text": "変電所", "is_correct": false, "explanation": "電圧を変える施設で、風を受けて回る部品ではないので合わない。"}, {"text": "蓄電池", "is_correct": false, "explanation": "電気をためる装置で、風を受けて回転する部分ではないので合わない。"}], "explanations": {"送電線": "電気を運ぶ線で、風を受けて回転し発電機を動かす部分ではないので合わない。", "ブレード": "風を受けて回転し、発電機を動かす風力発電の部品なので、ここに入る。", "変電所": "電圧を変える施設で、風を受けて回る部品ではないので合わない。", "蓄電池": "電気をためる装置で、風を受けて回転する部分ではないので合わない。"}, "sentence_index": 0, "correct_answer": "ブレード"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "鳥が、ブレードを抜いて巣を整えた。", "explanation": "〈羽根〉（鳥の羽）と混同した文。ブレードは風車の部品なので、鳥の体には使わない。"}, {"text": "朝、ブレードを干した。", "explanation": "干す物（布団など）の文。風車の部品のブレードは干さないので合わない。"}, {"text": "夏休みに、ブレードへ遊びに行った。", "explanation": "人が遊びに行く場所の文。ブレードは風車の部品で、行ける場所ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ff88f66-a23a-43b4-812c-c0d92e99400c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39433, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "配管", "is_correct": false, "explanation": "水や気体を通す管で、風力発電の羽根ではないので、この文の対象とは合わない。"}, {"text": "歯車", "is_correct": false, "explanation": "機械の動力を伝える部品で、風を受けて回る羽根の部分ではないので合わない。"}, {"text": "ブレード", "is_correct": true, "explanation": "古くなると処分が課題になる、風力発電の羽根を指す語なので、ここに入る。"}, {"text": "梁", "is_correct": false, "explanation": "建物を支える横木で、風力発電の羽根ではないので合わない。"}], "explanations": {"配管": "水や気体を通す管で、風力発電の羽根ではないので、この文の対象とは合わない。", "歯車": "機械の動力を伝える部品で、風を受けて回る羽根の部分ではないので合わない。", "ブレード": "古くなると処分が課題になる、風力発電の羽根を指す語なので、ここに入る。", "梁": "建物を支える横木で、風力発電の羽根ではないので合わない。"}, "sentence_index": 6, "correct_answer": "ブレード"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "車のブレードを踏んで、交差点で止まった。", "explanation": "〈ブレーキ〉（車を止める装置）と混同した文。ブレードは風車の羽根の部分で、車を止める装置ではないので合わない。"}, {"text": "ぼくの好きな食べ物は、ブレードだ。", "explanation": "食べ物の文。ブレードは食べられる物ではないので、好物にはならない。"}, {"text": "ブレードが、窓辺でひなたぼっこをしている。", "explanation": "ひなたぼっこをする生き物の文。ブレードは生き物ではないので、この文は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ff88f66-a23a-43b4-812c-c0d92e99400c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39433, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "ブレードを角度を変えると、回る速さも変わる。", "corrected_sentence": "ブレードの角度を変えると、回る速さも変わる。", "error_description": "「ブレードの角度」は「の」でつなぐのが正しい。「ブレードを角度を」と目的語が二つ重なるのが誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ff88f66-a23a-43b4-812c-c0d92e99400c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39433, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "ブレードを外れて、倉庫へ運ぶ。", "corrected_sentence": "ブレードを外して、倉庫へ運ぶ。", "error_description": "「外す」は他動詞で「を」の目的語を取る。「外れる」は自動詞なので、「ブレードを外れて」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ff88f66-a23a-43b4-812c-c0d92e99400c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39434, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「融合が、この建物の特長です」の「が」。融合を主語として示す。"}, {"text": "を", "is_correct": false, "explanation": "「融合を、この建物の特長です」は主語を示せず、文が成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「融合に、この建物の特長です」は主語にも主題にもならず不自然。"}, {"text": "の", "is_correct": false, "explanation": "「融合の、この建物の特長です」は名詞修飾になり、述語が成り立たない。"}], "correct_answer": "が", "explanations": {"が": "「融合が、この建物の特長です」の「が」。融合を主語として示す。", "を": "「融合を、この建物の特長です」は主語を示せず、文が成り立たない。", "に": "「融合に、この建物の特長です」は主語にも主題にもならず不自然。", "の": "「融合の、この建物の特長です」は名詞修飾になり、述語が成り立たない。"}, "error_tags": {"を": "目的語の格（ここでは主語が必要）", "に": "帰着点（主語や主題に当たらない）", "の": "連体修飾（述語が成り立たない）"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7d645761-a470-43e1-a068-67a54f16899d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39434, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7d645761-a470-43e1-a068-67a54f16899d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39434, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "二つ以上の物が一つになること。", "primary_collocate": null, "pronunciation": "ゆうごう", "ipa": "jɯːɡoː", "syllable_count": 4, "sentences": [{"text": "和食と洋食の融合から、新しい料理が生まれた。", "target_word": "融合", "complexity_tier": "T3", "furigana": "和食[わしょく]と洋食[ようしょく]の融合[ゆうごう]から、新[あたら]しい料理[りょうり]が生[う]まれた。", "sentence_source": "generated"}, {"text": "伝統と最新の技術の融合が、この建物の特長です。", "target_word": "融合", "complexity_tier": "T3", "furigana": "伝統[でんとう]と最新[さいしん]の技術[ぎじゅつ]の融合[ゆうごう]が、この建物[たてもの]の特長[とくちょう]です。", "sentence_source": "generated"}, {"text": "自然と建物が融合した庭は、散歩する人に人気がある。", "target_word": "融合", "complexity_tier": "T3", "furigana": "自然[しぜん]と建物[たてもの]が融合[ゆうごう]した庭[にわ]は、散歩[さんぽ]する人[ひと]に人気[にんき]がある。", "sentence_source": "generated"}, {"text": "絵と光の融合をねらった作品が、話題になっている。", "target_word": "融合", "complexity_tier": "T3", "furigana": "絵[え]と光[ひかり]の融合[ゆうごう]をねらった作品[さくひん]が、話題[わだい]になっている。", "sentence_source": "generated"}, {"text": "異なる文化の融合は、時間をかけてゆっくり進む。", "target_word": "融合", "complexity_tier": "T3", "furigana": "異[こと]なる文化[ぶんか]の融合[ゆうごう]は、時間[じかん]をかけてゆっくり進[すす]む。", "sentence_source": "generated"}, {"text": "古い町並みと新しい店が融合し、おもしろい通りになった。", "target_word": "融合", "complexity_tier": "T3", "furigana": "古[ふる]い町並[まちな]みと新[あたら]しい店[みせ]が融合[ゆうごう]し、おもしろい通[とお]りになった。", "sentence_source": "generated"}, {"text": "二つの考えを融合させて、より良い案を作りました。", "target_word": "融合", "complexity_tier": "T3", "furigana": "二[ふた]つの考[かんが]えを融合[ゆうごう]させて、より良[よ]い案[あん]を作[つく]りました。", "sentence_source": "generated"}, {"text": "この曲はジャズとクラシックの融合で、ほかにない音を出している。", "target_word": "融合", "complexity_tier": "T3", "furigana": "この曲[きょく]はジャズとクラシックの融合[ゆうごう]で、ほかにない音[おと]を出[だ]している。", "sentence_source": "generated"}, {"text": "科学と芸術の融合を目指す学生が、この研究室に集まっている。", "target_word": "融合", "complexity_tier": "T3", "furigana": "科学[かがく]と芸術[げいじゅつ]の融合[ゆうごう]を目指[めざ]す学生[がくせい]が、この研究室[けんきゅうしつ]に集[あつ]まっている。", "sentence_source": "generated"}, {"text": "日本とアジアの食文化が融合した料理は、味に深みがある。", "target_word": "融合", "complexity_tier": "T3", "furigana": "日本[にほん]とアジアの食文化[しょくぶんか]が融合[ゆうごう]した料理[りょうり]は、味[あじ]に深[ふか]みがある。", "sentence_source": "generated"}], "morphological_forms": [{"form": "融合", "label": "基本形"}, {"form": "融合する", "label": "する動詞の辞書形"}, {"form": "融合します", "label": "丁寧形"}, {"form": "融合した", "label": "過去形"}, {"form": "融合して", "label": "て形"}, {"form": "融合しない", "label": "否定形"}, {"form": "融合させる", "label": "使役形"}], "register": "中立（やや硬い書き言葉寄り）", "sense_fingerprint": "異なる二つ以上のものが溶け合って一つになること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f839c227-2f16-4265-b473-70b89a9b588c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39434, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "融合", "is_correct": true, "explanation": "「和食と洋食の融合から、新しい料理が生まれた」の融合。異なるものが一つになる意味で文脈に合う。"}, {"text": "分離", "is_correct": false, "explanation": "「和食と洋食の分離から」は意味が逆で、新しい料理が生まれる流れに合わない。"}, {"text": "除去", "is_correct": false, "explanation": "「和食と洋食の除去」は一方を取り除く意味で、料理が生まれる文脈に合わない。"}, {"text": "解散", "is_correct": false, "explanation": "「和食と洋食の解散」は集団を解く意味で、料理の誕生に続かない。"}], "explanations": {"融合": "「和食と洋食の融合から、新しい料理が生まれた」の融合。異なるものが一つになる意味で文脈に合う。", "分離": "「和食と洋食の分離から」は意味が逆で、新しい料理が生まれる流れに合わない。", "除去": "「和食と洋食の除去」は一方を取り除く意味で、料理が生まれる文脈に合わない。", "解散": "「和食と洋食の解散」は集団を解く意味で、料理の誕生に続かない。"}, "sentence_index": 0, "correct_answer": "融合"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "二台の車が交差点で融合した。", "explanation": "ここは〈衝突〉の意味。ぶつかり合う意味で、融合は溶け合って一つになる意味なので合わない。"}, {"text": "庭の草を融合して、ごみ袋に入れた。", "explanation": "融合の意味（溶け合って一つになる）ではなく、まとめて集める意味で使われており、融合は合わない。"}, {"text": "二種類の粉を融合して、生地を作る。", "explanation": "ここは「混ぜ合わせる」の意味で、粉は溶け合って一つにならないので、混合が正しい。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7d645761-a470-43e1-a068-67a54f16899d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39434, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "融合", "is_correct": true, "explanation": "「二つの考えを融合させて」の融合。異なる考えを一つにまとめる意味で文脈に合う。"}, {"text": "冷却", "is_correct": false, "explanation": "「二つの考えを冷却させて」は温度を下げる意味で、考えには使えず合わない。"}, {"text": "点火", "is_correct": false, "explanation": "「二つの考えを点火させて」は火をつける意味で、考えの文脈に合わない。"}, {"text": "接着", "is_correct": false, "explanation": "「二つの考えを接着させて」は接着剤で貼る意味で、考えの結びつきには使わない。"}], "explanations": {"融合": "「二つの考えを融合させて」の融合。異なる考えを一つにまとめる意味で文脈に合う。", "冷却": "「二つの考えを冷却させて」は温度を下げる意味で、考えには使えず合わない。", "点火": "「二つの考えを点火させて」は火をつける意味で、考えの文脈に合わない。", "接着": "「二つの考えを接着させて」は接着剤で貼る意味で、考えの結びつきには使わない。"}, "sentence_index": 6, "correct_answer": "融合"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "氷が融合して水になった。", "explanation": "ここは「固体が溶けて液体になる」の意味（融解）。融合は別々のもの同士が一つになる意味なので合わない。"}, {"text": "借金と貯金が融合して、ゼロになった。", "explanation": "ここは〈相殺〉の意味。打ち消し合う意味で、融合は溶け合って一つになる意味なので合わない。"}, {"text": "部品を融合して、机を作った。", "explanation": "ここは「部品をつなげて作る」の意味（組み立て）。融合は別々のものが溶け合う意味で、この文には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7d645761-a470-43e1-a068-67a54f16899d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39434, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "二つのチームの技術が融合て、新しい戦術が生まれた。", "corrected_sentence": "二つのチームの技術が融合して、新しい戦術が生まれた。", "error_description": "「融合する」のて形は「融合して」。「融合て」は活用の誤りで、正しくは「融合して」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7d645761-a470-43e1-a068-67a54f16899d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
