INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39438, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "『セル』が壊れるという主語を示すので『が』が正しい。"}, {"text": "を", "is_correct": false, "explanation": "『壊れる』は目的語を取らない自動詞なので、『を』は合わない。"}, {"text": "に", "is_correct": false, "explanation": "『セルに』は場所や受け手を示し、壊れる主体を示せない。"}, {"text": "へ", "is_correct": false, "explanation": "『セルへ』は向かう先を示すので、壊れる主体としては成り立たない。"}], "correct_answer": "が", "explanations": {"が": "『セル』が壊れるという主語を示すので『が』が正しい。", "を": "『壊れる』は目的語を取らない自動詞なので、『を』は合わない。", "に": "『セルに』は場所や受け手を示し、壊れる主体を示せない。", "へ": "『セルへ』は向かう先を示すので、壊れる主体としては成り立たない。"}, "error_tags": {"を": "目的語の誤り", "に": "場所・受け手の誤り", "へ": "方向の誤り"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ff88f66-a23a-43b4-812c-c0d92e99400c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
