INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39438, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "電池の中にある小さな部品で、電気をためたり、電気を作ったりするものです。", "primary_collocate": null, "pronunciation": "せる", "ipa": "seɾɯ", "syllable_count": 2, "sentences": [{"text": "この電池は、四つのセルをつないで作ってあります。", "target_word": "セル", "complexity_tier": "T3", "furigana": "この電池[でんち]は、四[よっ]つのセルをつないで作[つく]ってあります。", "sentence_source": "generated"}, {"text": "セルが一つ壊れたので、電池の力が弱くなりました。", "target_word": "セル", "complexity_tier": "T3", "furigana": "セルが一[ひと]つ壊[こわ]れたので、電池[でんち]の力[ちから]が弱[よわ]くなりました。", "sentence_source": "generated"}, {"text": "小さなセルに電気をためて、夜に使います。", "target_word": "セル", "complexity_tier": "T3", "furigana": "小[ちい]さなセルに電気[でんき]をためて、夜[よる]に使[つか]います。", "sentence_source": "generated"}, {"text": "工場では、電池のセルを一つずつ検査します。", "target_word": "セル", "complexity_tier": "T3", "furigana": "工場[こうじょう]では、電池[でんち]のセルを一[ひと]つずつ検査[けんさ]します。", "sentence_source": "generated"}, {"text": "セルの数が多いほど、電池はたくさん電気をためられる。", "target_word": "セル", "complexity_tier": "T3", "furigana": "セルの数[かず]が多[おお]いほど、電池[でんち]はたくさん電気[でんき]をためられる。", "sentence_source": "generated"}, {"text": "セルを一つ増やすと、電池の電圧が少し高くなります。", "target_word": "セル", "complexity_tier": "T3", "furigana": "セルを一[ひと]つ増[ふ]やすと、電池[でんち]の電圧[でんあつ]が少[すこ]し高[たか]くなります。", "sentence_source": "generated"}, {"text": "電気自動車の電池は、たくさんのセルを組み合わせてできている。", "target_word": "セル", "complexity_tier": "T3", "furigana": "電気[でんき]自動車[じどうしゃ]の電池[でんち]は、たくさんのセルを組[く]み合[あ]わせてできている。", "sentence_source": "generated"}, {"text": "セルを新しいものに替えたら、電池がまた使えるようになった。", "target_word": "セル", "complexity_tier": "T3", "furigana": "セルを新[あたら]しいものに替[か]えたら、電池[でんち]がまた使[つか]えるようになった。", "sentence_source": "generated"}, {"text": "一つのセルだけでは電気が弱いので、いくつもつなぎます。", "target_word": "セル", "complexity_tier": "T3", "furigana": "一[ひと]つのセルだけでは電気[でんき]が弱[よわ]いので、いくつもつなぎます。", "sentence_source": "generated"}, {"text": "温度が高すぎると、電池のセルがいたむことがあります。", "target_word": "セル", "complexity_tier": "T3", "furigana": "温度[おんど]が高[たか]すぎると、電池[でんち]のセルがいたむことがあります。", "sentence_source": "generated"}], "morphological_forms": [{"form": "セル", "label": "基本形"}], "register": "技術・説明文", "sense_fingerprint": "電池を構成する小さな単位部品（電池のセル）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 9 above tier T3: contains vocabulary far above tier T3: いたむ (Zipf 1.49)']::text[], 'fa11b1da-6a01-497b-ba17-85963d2f0c23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39438, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "セル", "is_correct": true, "explanation": "電池を組み立てる部品の単位で、四つつないで電池を作る文に合う。"}, {"text": "電圧", "is_correct": false, "explanation": "電圧は電気を押し出す力の大きさを表し、物として四つつないで電池を作るものではない。"}, {"text": "電流", "is_correct": false, "explanation": "電流は流れる電気の量で、つないで組み立てる部品にはならない。"}, {"text": "電解液", "is_correct": false, "explanation": "電解液は電池の中の液体で、四つ並べてつないで作る単位ではない。"}], "explanations": {"セル": "電池を組み立てる部品の単位で、四つつないで電池を作る文に合う。", "電圧": "電圧は電気を押し出す力の大きさを表し、物として四つつないで電池を作るものではない。", "電流": "電流は流れる電気の量で、つないで組み立てる部品にはならない。", "電解液": "電解液は電池の中の液体で、四つ並べてつないで作る単位ではない。"}, "sentence_index": 0, "correct_answer": "セル"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "豆電球のセルが光るので、電気が通っているとわかる。", "explanation": "豆電球に関係する文だが、電池のセルは光を出す部品ではないので合わない。"}, {"text": "この電源のセルは、コンセントにつないで使います。", "explanation": "電源につなぐ文だが、電池のセルはコンセントにつないで使うものではないので合わない。"}, {"text": "懐中電灯のセルを押すと、明かりがつく。", "explanation": "押して明かりをつける文だが、電池のセルはスイッチではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ff88f66-a23a-43b4-812c-c0d92e99400c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39438, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "セル", "is_correct": true, "explanation": "電池を構成する単位部品で、たくさん組み合わせて電池を作る文に合う。"}, {"text": "電荷", "is_correct": false, "explanation": "電荷は電気を帯びた量で、組み合わせて一つの電池を作るものではない。"}, {"text": "電力量", "is_correct": false, "explanation": "電力量は使った電気の総量で、物として組み合わせる対象にはならない。"}, {"text": "抵抗値", "is_correct": false, "explanation": "抵抗値は電流の流れにくさを示す数値で、組み合わせて電池を作るものではない。"}], "explanations": {"セル": "電池を構成する単位部品で、たくさん組み合わせて電池を作る文に合う。", "電荷": "電荷は電気を帯びた量で、組み合わせて一つの電池を作るものではない。", "電力量": "電力量は使った電気の総量で、物として組み合わせる対象にはならない。", "抵抗値": "抵抗値は電流の流れにくさを示す数値で、組み合わせて電池を作るものではない。"}, "sentence_index": 6, "correct_answer": "セル"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "温度が高すぎると、電子レンジのセルがいたむことがあります。", "explanation": "電子レンジに関係する文だが、電池のセルはこの使い方をしないので合わない。"}, {"text": "寒いと、ストーブのセルが弱ることがあります。", "explanation": "ストーブに関係する文だが、電池のセルは暖房の部品ではないので合わない。"}, {"text": "温度が高すぎると、ねじのセルがいたむことがあります。", "explanation": "ねじに関係する文だが、電池のセルはねじの部品ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ff88f66-a23a-43b4-812c-c0d92e99400c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39438, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "電池のセルを二つ壊れると、電気が足りなくなります。", "corrected_sentence": "電池のセルが二つ壊れると、電気が足りなくなります。", "error_description": "『壊れる』は自動詞なので、主語のセルには『が』を使う。『を』は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ff88f66-a23a-43b4-812c-c0d92e99400c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39438, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "電池のセルは、一つずつつなげらるので、好きな数の電池が作れます。", "corrected_sentence": "電池のセルは、一つずつつなげられるので、好きな数の電池が作れます。", "error_description": "『つなげる』の可能形は『つなげられる』。『つなげらる』は誤った活用。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ff88f66-a23a-43b4-812c-c0d92e99400c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39439, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "『このセル』を話題として示すので『は』が正しい。"}, {"text": "で", "is_correct": false, "explanation": "手段や場所を示す「で」は、光を受ける位置にも主題にもならず不自然。"}, {"text": "に", "is_correct": false, "explanation": "『このセルに』は受け手の場所を示し、文の主題としては不自然。"}, {"text": "へ", "is_correct": false, "explanation": "『このセルへ』は方向を示すので、主題として文が成立しない。"}], "correct_answer": "は", "explanations": {"は": "『このセル』を話題として示すので『は』が正しい。", "で": "手段や場所を示す「で」は、光を受ける位置にも主題にもならず不自然。", "に": "『このセルに』は受け手の場所を示し、文の主題としては不自然。", "へ": "『このセルへ』は方向を示すので、主題として文が成立しない。"}, "error_tags": {"を": "目的語の誤り", "へ": "方向の誤り", "で": "手段・場所の誤り"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ff88f66-a23a-43b4-812c-c0d92e99400c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39439, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "『セルに届く』の届き先を示すので『に』が正しい。"}, {"text": "で", "is_correct": false, "explanation": "『セルで届く』は手段や場所を示し、届き先の関係を表さない。"}, {"text": "と", "is_correct": false, "explanation": "『セルと届く』は並列を示すが、届き先としては成り立たない。"}, {"text": "より", "is_correct": false, "explanation": "『セルより届く』は比較を示すが、届き先を示せず不自然。"}], "correct_answer": "に", "explanations": {"に": "『セルに届く』の届き先を示すので『に』が正しい。", "で": "『セルで届く』は手段や場所を示し、届き先の関係を表さない。", "と": "『セルと届く』は並列を示すが、届き先としては成り立たない。", "より": "『セルより届く』は比較を示すが、届き先を示せず不自然。"}, "error_tags": {"で": "手段・場所の誤り", "と": "並列の誤り", "より": "比較の誤り"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ff88f66-a23a-43b4-812c-c0d92e99400c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39439, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "太陽光を電気に変える装置の最小単位。複数つなげてパネルにします。", "primary_collocate": null, "pronunciation": "せる", "ipa": "seɾɯ", "syllable_count": 2, "sentences": [{"text": "太陽光パネルは、たくさんのセルをつなげて作ります。", "target_word": "セル", "complexity_tier": "T3", "furigana": "太陽光[たいようこう]パネルは、たくさんのセルをつなげて作[つく]ります。", "sentence_source": "generated"}, {"text": "このセルは光を受けると、すぐに電気を生み出す。", "target_word": "セル", "complexity_tier": "T3", "furigana": "このセルは光[ひかり]を受[う]けると、すぐに電気[でんき]を生[う]み出[だ]す。", "sentence_source": "generated"}, {"text": "セルを百枚並べると、大きなパネルになります。", "target_word": "セル", "complexity_tier": "T3", "furigana": "セルを百[ひゃく]枚[まい]並[なら]べると、大[おお]きなパネルになります。", "sentence_source": "generated"}, {"text": "屋根のパネルは、セルが一枚割れると発電量が下がります。", "target_word": "セル", "complexity_tier": "T3", "furigana": "屋根[やね]のパネルは、セルが一[いち]枚[まい]割[わ]れると発電量[はつでんりょう]が下[さ]がります。", "sentence_source": "generated"}, {"text": "新しいセルは、前より多くの光を電気に変えられる。", "target_word": "セル", "complexity_tier": "T3", "furigana": "新[あたら]しいセルは、前[まえ]より多[おお]くの光[ひかり]を電気[でんき]に変[か]えられる。", "sentence_source": "generated"}, {"text": "太陽電池のセルは、薄い板のように見える。", "target_word": "セル", "complexity_tier": "T3", "furigana": "太陽[たいよう]電池[でんち]のセルは、薄[うす]い板[いた]のように見[み]える。", "sentence_source": "generated"}, {"text": "研究者は、安くて効率のよいセルを作る方法を探している。", "target_word": "セル", "complexity_tier": "T3", "furigana": "研究者[けんきゅうしゃ]は、安[やす]くて効率[こうりつ]のよいセル[せる]を作[つく]る方法[ほうほう]を探[さが]している。", "sentence_source": "generated"}, {"text": "曇りの日は、セルに届く光が少なく、発電も減ります。", "target_word": "セル", "complexity_tier": "T3", "furigana": "曇[くも]りの日[ひ]は、セルに届[とど]く光[ひかり]が少[すく]なく、発電[はつでん]も減[へ]ります。", "sentence_source": "generated"}, {"text": "パネルの表面を掃除して、セルがよごれないようにする。", "target_word": "セル", "complexity_tier": "T3", "furigana": "パネルの表面[ひょうめん]を掃除[そうじ]して、セルがよごれないようにする。", "sentence_source": "generated"}, {"text": "電卓の小さなセルでも、明るい場所なら電気を作れる。", "target_word": "セル", "complexity_tier": "T3", "furigana": "電卓[でんたく]の小[ちい]さなセルでも、明[あか]るい場所[ばしょ]なら電気[でんき]を作[つく]れる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "セル", "label": "基本形"}], "register": "技術・説明文", "sense_fingerprint": "太陽電池の最小単位（ソーラーセル）で、つなげてパネルにする", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa11b1da-6a01-497b-ba17-85963d2f0c23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39439, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "セル", "is_correct": true, "explanation": "太陽光パネルを構成する最小単位で、たくさんつなげてパネルを作る文に合う。"}, {"text": "発電量", "is_correct": false, "explanation": "発電量は発電した電気の量で、つなげて組み立てるものではない。"}, {"text": "日射量", "is_correct": false, "explanation": "日射量は地面に届く日光の量で、つなげてパネルを作る対象にはならない。"}, {"text": "照度", "is_correct": false, "explanation": "照度は明るさの単位で、パネルをつなぐ部品ではない。"}], "explanations": {"セル": "太陽光パネルを構成する最小単位で、たくさんつなげてパネルを作る文に合う。", "発電量": "発電量は発電した電気の量で、つなげて組み立てるものではない。", "日射量": "日射量は地面に届く日光の量で、つなげてパネルを作る対象にはならない。", "照度": "照度は明るさの単位で、パネルをつなぐ部品ではない。"}, "sentence_index": 0, "correct_answer": "セル"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "このセルは室温を測って、画面に表示する。", "explanation": "室温を測る文だが、太陽光パネルのセルは温度を測る部品ではないので合わない。"}, {"text": "このセルは雨の日に、ヒーターのように部屋を暖める。", "explanation": "熱で部屋を暖める文だが、セルは光を電気に変える部品で、暖房にはならないので合わない。"}, {"text": "漏電すると、このセルが自動で落ちて電気を止める。", "explanation": "漏電で電気を止める文だが、セルは電気を止める働きを持たないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ff88f66-a23a-43b4-812c-c0d92e99400c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39439, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "セル", "is_correct": true, "explanation": "効率のよいものとして作る対象で、太陽光発電の単位部品として合う。"}, {"text": "湿度", "is_correct": false, "explanation": "湿度は空気中の水分の割合で、効率のよいものとして作る対象にはならない。"}, {"text": "積雪量", "is_correct": false, "explanation": "積雪量は積もった雪の量で、作る方法の対象にはならない。"}, {"text": "気温", "is_correct": false, "explanation": "気温は空気の温度で、作る方法の対象にはならない。"}], "explanations": {"セル": "効率のよいものとして作る対象で、太陽光発電の単位部品として合う。", "湿度": "湿度は空気中の水分の割合で、効率のよいものとして作る対象にはならない。", "積雪量": "積雪量は積もった雪の量で、作る方法の対象にはならない。", "気温": "気温は空気の温度で、作る方法の対象にはならない。"}, "sentence_index": 6, "correct_answer": "セル"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "このセルを回すと、ラジオから音楽が流れる。", "explanation": "音楽を流す文だが、セルは音を出したり選局したりしないので合わない。"}, {"text": "強風の日は、風力発電のセルが折れることがある。", "explanation": "風力発電に関係する文だが、太陽光パネルのセルは風車の羽根ではないので合わない。"}, {"text": "このセルを窓にはめると、虫が入りにくくなる。", "explanation": "虫を防ぐ文だが、セルは光を電気に変える装置の単位で、虫を防ぐものではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ff88f66-a23a-43b4-812c-c0d92e99400c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39439, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "太陽光パネルのセルが光を受けらると、電気が生まれます。", "corrected_sentence": "太陽光パネルのセルが光を受けると、電気が生まれます。", "error_description": "『受ける』の条件形は『受けると』。『受けらる』は活用として成り立たない誤った形。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ff88f66-a23a-43b4-812c-c0d92e99400c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39439, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "屋根のパネルは、セルを百本並べて作ります。", "corrected_sentence": "屋根のパネルは、セルを百枚並べて作ります。", "error_description": "平たい板状のセルを数える助数詞は『枚』。『本』は細長いものに使うので誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ff88f66-a23a-43b4-812c-c0d92e99400c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
