INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39442, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "六つのこと。数を数えるときの「六」です。", "primary_collocate": null, "pronunciation": "ろく", "ipa": "ɾokɯ", "syllable_count": 2, "sentences": [{"text": "私の家族は 6 人で、みんな一緒に住んでいる。", "target_word": "6", "complexity_tier": "T3", "furigana": "私[わたし]の家族[かぞく]は 6[ろく] 人[にん]で、みんな一緒[いっしょ]に住[す]んでいる。", "sentence_source": "generated"}, {"text": "図書館で本を 6 冊借りて、一週間で読んだ。", "target_word": "6", "complexity_tier": "T3", "furigana": "図書館[としょかん]で本[ほん]を 6[ろく] 冊[さつ]借[か]りて、一週間[いっしゅうかん]で読[よ]んだ。", "sentence_source": "generated"}, {"text": "6 枚のチケットを買ったので、友達みんなで行ける。", "target_word": "6", "complexity_tier": "T3", "furigana": "6[ろく] 枚[まい]のチケットを買[か]ったので、友達[ともだち]みんなで行[い]ける。", "sentence_source": "generated"}, {"text": "私は 6 年間、同じ学校に通っている。", "target_word": "6", "complexity_tier": "T3", "furigana": "私[わたし]は 6[ろく] 年間[ねんかん]、同[おな]じ学校[がっこう]に通[かよ]っている。", "sentence_source": "generated"}, {"text": "先月、6 万円のかばんを買ってしまった。", "target_word": "6", "complexity_tier": "T3", "furigana": "先月[せんげつ]、6[ろく] 万円[まんえん]のかばんを買[か]ってしまった。", "sentence_source": "generated"}, {"text": "列に並んでいるのは 6 人で、みんな私の友達だ。", "target_word": "6", "complexity_tier": "T4", "furigana": "列[れつ]に並[なら]んでいるのは 6[ろく] 人[にん]で、みんな私[わたし]の友達[ともだち]だ。", "sentence_source": "generated"}, {"text": "妹は 6 歳になって、来月から小学生だ。", "target_word": "6", "complexity_tier": "T3", "furigana": "妹[いもうと]は 6[ろく] 歳[さい]になって、来月[らいげつ]から小学生[しょうがくせい]だ。", "sentence_source": "generated"}, {"text": "この町の人口は、十年前の 6 倍になった。", "target_word": "6", "complexity_tier": "T4", "furigana": "この町[まち]の人口[じんこう]は、十年前[じゅうねんまえ]の 6[ろく] 倍[ばい]になった。", "sentence_source": "generated"}, {"text": "昨日の夜、友達を 6 人呼んでパーティーをした。", "target_word": "6", "complexity_tier": "T3", "furigana": "昨日[きのう]の夜[よる]、友達[ともだち]を 6[ろく] 人[にん]呼[よ]んでパーティーをした。", "sentence_source": "generated"}, {"text": "庭に 6 匹の猫がいた。", "target_word": "6", "complexity_tier": "T3", "furigana": "庭[にわ]に 6[ろく] 匹[ひき]の猫[ねこ]がいた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "6", "label": "基本形"}], "register": "中立（普通体）", "sense_fingerprint": "ものや人を数えるときの数量としての六（ろく）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd469edc2-a0d2-4ebb-a930-1a26158348ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39442, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "6", "is_correct": true, "explanation": "正解。「家族は6人」と人数を表す数。"}, {"text": "人", "is_correct": false, "explanation": "数を表す位置に助数詞「人」は入らない。"}, {"text": "冊", "is_correct": false, "explanation": "本などを数える助数詞。家族の人数には使わない。"}, {"text": "枚", "is_correct": false, "explanation": "紙や薄い物を数える助数詞。人数には使えない。"}], "explanations": {"6": "正解。「家族は6人」と人数を表す数。", "人": "数を表す位置に助数詞「人」は入らない。", "冊": "本などを数える助数詞。家族の人数には使わない。", "枚": "紙や薄い物を数える助数詞。人数には使えない。"}, "sentence_index": 0, "correct_answer": "6"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "私の家族は 6 歳で、みんな一緒に住んでいる。", "explanation": "ここは「歳（年齢）」の意味。家族の人数は「人」で数えるので、歳は合わない。"}, {"text": "図書館で本を 6 台借りて、一週間で読んだ。", "explanation": "ここは「台（機械）」の数え方。本は冊で数えるので、台は合わない。"}, {"text": "友達を 6 点呼んで、パーティーをした。", "explanation": "ここは「点（点数）」の数え方。人は人で数えるので、点は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bee30dfd-656a-4a65-8a5b-04fa7a74fa9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39442, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "6", "is_correct": true, "explanation": "正解。「妹は6歳」と年齢を表す数。"}, {"text": "本", "is_correct": false, "explanation": "細長い物を数える助数詞。年齢には使わない。"}, {"text": "台", "is_correct": false, "explanation": "機械や車を数える助数詞。年齢には使わない。"}, {"text": "匹", "is_correct": false, "explanation": "動物を数える助数詞。人の年齢には使わない。"}], "explanations": {"6": "正解。「妹は6歳」と年齢を表す数。", "本": "細長い物を数える助数詞。年齢には使わない。", "台": "機械や車を数える助数詞。年齢には使わない。", "匹": "動物を数える助数詞。人の年齢には使わない。"}, "sentence_index": 6, "correct_answer": "6"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "私は 6 枚の時計を持っている。", "explanation": "ここは「枚（薄いものを数える）」の数え方。時計は個や台で数えるので、枚は合わない。"}, {"text": "山の上で 6 本の鳥を見た。", "explanation": "ここは「本（細長いものを数える）」の数え方。鳥は羽で数えるので、本は合わない。"}, {"text": "家の前に 6 軒の車が止まっていた。", "explanation": "ここは「軒（家を数える）」の数え方。車は台で数えるので、軒は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bee30dfd-656a-4a65-8a5b-04fa7a74fa9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39442, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "テーブルの上にりんごが 6 人ある。", "corrected_sentence": "テーブルの上にりんごが 6 個ある。", "error_description": "りんごは「個」で数える。「6 人」は人を数える助数詞で、りんごには使わない。正しくは「6 個」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bee30dfd-656a-4a65-8a5b-04fa7a74fa9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39442, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "先週、部屋の窓を 6 人拭いた。", "corrected_sentence": "先週、部屋の窓を 6 枚拭いた。", "error_description": "「窓」は枚で数える。「6 人」は人を数える助数詞なので誤り。正しくは「6 枚」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bee30dfd-656a-4a65-8a5b-04fa7a74fa9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
