INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39443, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "数字の6。数が五より一つ多いこと。", "primary_collocate": null, "pronunciation": "ろく", "ipa": "ɾokɯ", "syllable_count": 2, "sentences": [{"text": "5に1を足すと 6 になる。", "target_word": "6", "complexity_tier": "T2", "furigana": "5[ご]に1[いち]を足[た]すと 6[ろく] になる。", "sentence_source": "generated"}, {"text": "サイコロを振ったら、6 の目が出た。", "target_word": "6", "complexity_tier": "T2", "furigana": "サイコロを振[ふ]ったら、6[ろく] の目[め]が出[で]た。", "sentence_source": "generated"}, {"text": "数字の 6 は、5の次に来る数だ。", "target_word": "6", "complexity_tier": "T3", "furigana": "数字[すうじ]の 6[ろく] は、5の次[つぎ]に来[く]る数[かず]だ。", "sentence_source": "generated"}, {"text": "12を2で割ると 6 になる。", "target_word": "6", "complexity_tier": "T3", "furigana": "12[じゅうに]を2[に]で割[わ]ると 6[ろく] になる。", "sentence_source": "generated"}, {"text": "10から4を引くと 6 が残る。", "target_word": "6", "complexity_tier": "T3", "furigana": "10[じゅう]から4[よん]を引[ひ]くと 6[ろく] が残[のこ]る。", "sentence_source": "generated"}, {"text": "電話番号の最後の数字は 6 だ。", "target_word": "6", "complexity_tier": "T3", "furigana": "電話番号[でんわばんごう]の最後[さいご]の数字[すうじ]は 6[ろく] だ。", "sentence_source": "generated"}, {"text": "1、2、3、4、5、6 と順番に数えた。", "target_word": "6", "complexity_tier": "T2", "furigana": "1[いち]、2[に]、3[さん]、4[よん]、5[ご]、6[ろく] と順番[じゅんばん]に数[かぞ]えた。", "sentence_source": "generated"}, {"text": "小さなテストで、10点満点中 6 点を取って合格した。", "target_word": "6", "complexity_tier": "T3", "furigana": "小[ちい]さなテストで、10点[てん]満点[まんてん]中 6[ろく] 点[てん]を取[と]って合格[ごうかく]した。", "sentence_source": "generated"}, {"text": "3の2倍は 6 だ。", "target_word": "6", "complexity_tier": "T2", "furigana": "3[さん]の2[に]倍[ばい]は 6[ろく] だ。", "sentence_source": "generated"}, {"text": "5より1大きい数は 6 だ。", "target_word": "6", "complexity_tier": "T2", "furigana": "5[ご]より1[いち]大[おお]きい数[かず]は 6[ろく] だ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "6", "label": "基本形"}], "register": "中立（普通体）", "sense_fingerprint": "5の次にくる数、数字そのものとしての6（計算・数字・順番）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd469edc2-a0d2-4ebb-a930-1a26158348ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39443, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "6", "is_correct": true, "explanation": "5に1を足すと6になるので、空欄には6が入る。"}, {"text": "4", "is_correct": false, "explanation": "5+1は4ではないので、「5に1を足すと4になる」は計算が合わない。"}, {"text": "9", "is_correct": false, "explanation": "5+1は9ではないので、「5に1を足すと9になる」は計算が合わない。"}, {"text": "8", "is_correct": false, "explanation": "5+1は8ではないので、「5に1を足すと8になる」は計算が合わない。"}], "explanations": {"6": "5に1を足すと6になるので、空欄には6が入る。", "4": "5+1は4ではないので、「5に1を足すと4になる」は計算が合わない。", "9": "5+1は9ではないので、「5に1を足すと9になる」は計算が合わない。", "8": "5+1は8ではないので、「5に1を足すと8になる」は計算が合わない。"}, "sentence_index": 0, "correct_answer": "6"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "6は五より一つ少ない数だ。", "explanation": "「6」は五より一つ多い数。五より一つ少ないのは4で、ここでは大小を取り違えている。"}, {"text": "6は4の次に来る数だ。", "explanation": "4の次に来るのは5。6は5の次の数なので、ここでは5の位置と混同している。"}, {"text": "6は1を足すと偶数になる数だ。", "explanation": "6は偶数なので、1を足すと奇数になる。ここでは奇数の性質と取り違えている。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bee30dfd-656a-4a65-8a5b-04fa7a74fa9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39443, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "6", "is_correct": true, "explanation": "1から順に数えると5の次は6なので、空欄には6が入る。"}, {"text": "7", "is_correct": false, "explanation": "順番に数えると5の次は6で、7はその次の数なので、ここには入らない。"}, {"text": "10", "is_correct": false, "explanation": "順番に数えると5の次は6で、10は5より五つ多い数なので、ここには入らない。"}, {"text": "12", "is_correct": false, "explanation": "12は順番に数えたときに5の次に来る数ではないので、ここには入らない。"}], "explanations": {"6": "1から順に数えると5の次は6なので、空欄には6が入る。", "7": "順番に数えると5の次は6で、7はその次の数なので、ここには入らない。", "10": "順番に数えると5の次は6で、10は5より五つ多い数なので、ここには入らない。", "12": "12は順番に数えたときに5の次に来る数ではないので、ここには入らない。"}, "sentence_index": 6, "correct_answer": "6"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "6は3の次の数だ。", "explanation": "3の次は4で、6は5の次の数。ここでは4と取り違えている。"}, {"text": "6は9より二つ少ない数だ。", "explanation": "9より二つ少ないのは7で、6は9より三つ少ない数。ここでは7と取り違えている。"}, {"text": "6は八より一つ少ない数だ。", "explanation": "八より一つ少ないのは7で、6は八より二つ少ない数。ここでは7と取り違えている。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bee30dfd-656a-4a65-8a5b-04fa7a74fa9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39443, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "サイコロを振ったら、6を目が出なかった。", "corrected_sentence": "サイコロを振ったら、6の目が出なかった。", "error_description": "数字の6と「目」をつなぐ助詞は「の」。「6を目」は誤りで、正しくは「6の目」。誤りは目標語の直後の助詞だけ。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bee30dfd-656a-4a65-8a5b-04fa7a74fa9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39443, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "昨日サイコロを振ったら、6人の目が出た。", "corrected_sentence": "昨日サイコロを振ったら、6の目が出た。", "error_description": "「6人」は人を数える助数詞で、サイコロの目には使えない。正しくは「6の目」。誤りは目標語に続く助数詞だけ。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bee30dfd-656a-4a65-8a5b-04fa7a74fa9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39444, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "『百パーセント』を話題として示すので『は』が正しい。"}, {"text": "を", "is_correct": false, "explanation": "『百パーセントを』は目的語を示すが、ここは説明の話題で目的語ではない。"}, {"text": "に", "is_correct": false, "explanation": "『百パーセントに』は結果や位置を示すが、『全部ということです』の話題にはならない。"}, {"text": "へ", "is_correct": false, "explanation": "『百パーセントへ』は方向を示すので、ここでは文が成り立たない。"}], "correct_answer": "は", "explanations": {"は": "『百パーセント』を話題として示すので『は』が正しい。", "を": "『百パーセントを』は目的語を示すが、ここは説明の話題で目的語ではない。", "に": "『百パーセントに』は結果や位置を示すが、『全部ということです』の話題にはならない。", "へ": "『百パーセントへ』は方向を示すので、ここでは文が成り立たない。"}, "error_tags": {"を": "目的語の誤り", "に": "結果・位置の誤り", "へ": "方向の誤り"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ff88f66-a23a-43b4-812c-c0d92e99400c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39444, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "『四十パーセント』が『来ます』の主語を示すので『が』が正しい。"}, {"text": "と", "is_correct": false, "explanation": "『四十パーセントと』は並列を示すが、ここでは主語の位置に入らない。"}, {"text": "で", "is_correct": false, "explanation": "『四十パーセントで』は手段や基準を示すが、来る主体を示せない。"}, {"text": "より", "is_correct": false, "explanation": "『四十パーセントより』は比較を示すが、主語にはならない。"}], "correct_answer": "が", "explanations": {"が": "『四十パーセント』が『来ます』の主語を示すので『が』が正しい。", "と": "『四十パーセントと』は並列を示すが、ここでは主語の位置に入らない。", "で": "『四十パーセントで』は手段や基準を示すが、来る主体を示せない。", "より": "『四十パーセントより』は比較を示すが、主語にはならない。"}, "error_tags": {"と": "並列の誤り", "で": "手段・基準の誤り", "より": "比較の誤り"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ff88f66-a23a-43b4-812c-c0d92e99400c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39444, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "パーセントは、全体を百に分けたときの、いくつ分かを表すことばです。", "primary_collocate": null, "pronunciation": "ぱーせんと", "ipa": "paːseɴto", "syllable_count": 5, "sentences": [{"text": "クラスの三十パーセントが、犬を飼っています。", "target_word": "パーセント", "complexity_tier": "T3", "furigana": "クラスの三十[さんじゅっ]パーセントが、犬[いぬ]を飼[か]っています。", "sentence_source": "generated"}, {"text": "百パーセントは、全部ということです。", "target_word": "パーセント", "complexity_tier": "T3", "furigana": "百[ひゃく]パーセントは、全部[ぜんぶ]ということです。", "sentence_source": "generated"}, {"text": "ジュースを半分飲んだので、残りは五十パーセントです。", "target_word": "パーセント", "complexity_tier": "T3", "furigana": "ジュースを半分[はんぶん]飲[の]んだので、残[のこ]りは五十[ごじゅっ]パーセントです。", "sentence_source": "generated"}, {"text": "テストで八十パーセント正解して、先生にほめられた。", "target_word": "パーセント", "complexity_tier": "T3", "furigana": "テストで八十[はちじゅっ]パーセント正解[せいかい]して、先生[せんせい]にほめられた。", "sentence_source": "generated"}, {"text": "雨が降る可能性が九十パーセントだから、かさを持って行こう。", "target_word": "パーセント", "complexity_tier": "T3", "furigana": "雨[あめ]が降[ふ]る可能性[かのうせい]が九十[きゅうじゅっ]パーセントだから、かさを持[も]って行[い]こう。", "sentence_source": "generated"}, {"text": "全体を百に分けた、その一つが一パーセントです。", "target_word": "パーセント", "complexity_tier": "T3", "furigana": "全体[ぜんたい]を百[ひゃく]に分[わ]けた、その一[ひと]つが一[いっ]パーセントです。", "sentence_source": "generated"}, {"text": "電池が二十パーセントしかないので、早く充電しよう。", "target_word": "パーセント", "complexity_tier": "T3", "furigana": "電池[でんち]が二十[にじゅっ]パーセントしかないので、早[はや]く充電[じゅうでん]しよう。", "sentence_source": "generated"}, {"text": "学校の生徒のうち、四十パーセントが電車で来ます。", "target_word": "パーセント", "complexity_tier": "T3", "furigana": "学校[がっこう]の生徒[せいと]のうち、四十[よんじゅっ]パーセントが電車[でんしゃ]で来[き]ます。", "sentence_source": "generated"}, {"text": "コップに水を七十パーセントまで入れた。", "target_word": "パーセント", "complexity_tier": "T3", "furigana": "コップに水[みず]を七十[ななじゅっ]パーセントまで入[い]れた。", "sentence_source": "generated"}, {"text": "今日の宿題は、もう六十パーセント終わりました。", "target_word": "パーセント", "complexity_tier": "T3", "furigana": "今日[きょう]の宿題[しゅくだい]は、もう六十[ろくじゅっ]パーセント終[お]わりました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "パーセント", "label": "基本形"}], "register": "一般・やさしい説明", "sense_fingerprint": "全体を百に分けたうちのいくつ分かを表すことば（日常の割合）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa11b1da-6a01-497b-ba17-85963d2f0c23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39444, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "パーセント", "is_correct": true, "explanation": "全体を百に分けたうちのいくつ分かを表し、三十パーセントの犬を飼う人の割合を示せる。"}, {"text": "グラム", "is_correct": false, "explanation": "グラムは重さの単位で、クラスの人の割合を表す文には入らない。"}, {"text": "リットル", "is_correct": false, "explanation": "リットルは体積の単位で、クラスの人や犬を飼う割合の表現には合わない。"}, {"text": "メートル", "is_correct": false, "explanation": "メートルは長さの単位で、人数の割合を表す語としては成り立たない。"}], "explanations": {"パーセント": "全体を百に分けたうちのいくつ分かを表し、三十パーセントの犬を飼う人の割合を示せる。", "グラム": "グラムは重さの単位で、クラスの人の割合を表す文には入らない。", "リットル": "リットルは体積の単位で、クラスの人や犬を飼う割合の表現には合わない。", "メートル": "メートルは長さの単位で、人数の割合を表す語としては成り立たない。"}, "sentence_index": 0, "correct_answer": "パーセント"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "教室のパーセントは、三十人だった。", "explanation": "ここは〈人数〉の意味。パーセントは割合の単位で、人を数える語ではないので合わない。"}, {"text": "あの店のパーセントは、駅から近くて便利だ。", "explanation": "ここは〈店の評判・特徴〉の意味。パーセントは割合の単位で、店の立地や性質を表す語ではないので合わない。"}, {"text": "紙のパーセントは、もう五枚しかない。", "explanation": "ここは〈紙の枚数〉の意味。パーセントは割合の単位で、枚数を数える語ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ff88f66-a23a-43b4-812c-c0d92e99400c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39444, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "パーセント", "is_correct": true, "explanation": "割合を表す単位で、『二十パーセントしかない』と残りの量を示せる。"}, {"text": "ヘクタール", "is_correct": false, "explanation": "ヘクタールは面積の単位で、電池の残量には使わない。"}, {"text": "デシベル", "is_correct": false, "explanation": "デシベルは音の大きさの単位で、電池の残りを表す語ではない。"}, {"text": "カロリー", "is_correct": false, "explanation": "カロリーは熱量の単位で、電池の残量を表す語としては合わない。"}], "explanations": {"パーセント": "割合を表す単位で、『二十パーセントしかない』と残りの量を示せる。", "ヘクタール": "ヘクタールは面積の単位で、電池の残量には使わない。", "デシベル": "デシベルは音の大きさの単位で、電池の残りを表す語ではない。", "カロリー": "カロリーは熱量の単位で、電池の残量を表す語としては合わない。"}, "sentence_index": 6, "correct_answer": "パーセント"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "弟は、もう六十パーセント寝ました。", "explanation": "ここは〈睡眠の分量〉の意味。パーセントは割合の単位で、寝た量を表す語ではないので、この文は合わない。"}, {"text": "この電車は、六十パーセントの駅を通った。", "explanation": "パーセントは割合の単位で、駅の数を数える語ではないので合わない。"}, {"text": "今日の宿題は、もう六十パーセントの宿題です。", "explanation": "ここは〈宿題の種類・分量〉の意味。パーセントは割合の単位で、宿題の種類を名乗る語ではないので、この文は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ff88f66-a23a-43b4-812c-c0d92e99400c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39444, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "クラスの女子の八十パーセントを、毎日宿題をします。", "corrected_sentence": "クラスの女子の八十パーセントが、毎日宿題をします。", "error_description": "『宿題をします』の主語にあたる『八十パーセント』には『が』を使う。『を』は目的語の印なので誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ff88f66-a23a-43b4-812c-c0d92e99400c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39444, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "正答率は、五十パーセントを満たなかった。", "corrected_sentence": "正答率は、五十パーセントに満たなかった。", "error_description": "『満たない』は『〜に満たない』と『に』を取る。『を』は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ff88f66-a23a-43b4-812c-c0d92e99400c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39445, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "『超える』は目的語を取るので、『六十パーセント』に『を』が付くのが正しい。"}, {"text": "に", "is_correct": false, "explanation": "『六十パーセントに超えた』は、超える対象を示す形としては不自然。"}, {"text": "で", "is_correct": false, "explanation": "『六十パーセントで超えた』は手段や基準を示し、超える対象にはならない。"}, {"text": "と", "is_correct": false, "explanation": "『六十パーセントと超えた』は並列を示すが、超える対象としては成り立たない。"}], "correct_answer": "を", "explanations": {"を": "『超える』は目的語を取るので、『六十パーセント』に『を』が付くのが正しい。", "に": "『六十パーセントに超えた』は、超える対象を示す形としては不自然。", "で": "『六十パーセントで超えた』は手段や基準を示し、超える対象にはならない。", "と": "『六十パーセントと超えた』は並列を示すが、超える対象としては成り立たない。"}, "error_tags": {"に": "方向・基準の誤り", "で": "手段の誤り", "と": "並列の誤り"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ff88f66-a23a-43b4-812c-c0d92e99400c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
