INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39445, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "全体を100としたときの割合を示す単位。百分率。", "primary_collocate": null, "pronunciation": "ぱーせんと", "ipa": "paːseɴto", "syllable_count": 5, "sentences": [{"text": "今年の売り上げは、前の年より五パーセント増えた。", "target_word": "パーセント", "complexity_tier": "T3", "furigana": "今年[ことし]の売[う]り上[あ]げは、前[まえ]の年[とし]より五[ご]パーセント増[ふ]えた。", "sentence_source": "generated"}, {"text": "世論調査では、賛成が六十パーセントを超えた。", "target_word": "パーセント", "complexity_tier": "T3", "furigana": "世論[よろん]調査[ちょうさ]では、賛成[さんせい]が六十[ろくじゅっ]パーセントを超[こ]えた。", "sentence_source": "generated"}, {"text": "会員は、定価の二十パーセントを割り引きます。", "target_word": "パーセント", "complexity_tier": "T3", "furigana": "会員[かいいん]は、定価[ていか]の二十[にじゅっ]パーセントを割[わ]り引[び]きます。", "sentence_source": "generated"}, {"text": "失業率は三パーセントまで下がった。", "target_word": "パーセント", "complexity_tier": "T3", "furigana": "失業率[しつぎょうりつ]は三[さん]パーセントまで下[さ]がった。", "sentence_source": "generated"}, {"text": "水分は、体重の約六十パーセントを占めている。", "target_word": "パーセント", "complexity_tier": "T3", "furigana": "水分[すいぶん]は、体重[たいじゅう]の約[やく]六十[ろくじゅっ]パーセントを占[し]めている。", "sentence_source": "generated"}, {"text": "年利二パーセントの預金に、お金を預けた。", "target_word": "パーセント", "complexity_tier": "T3", "furigana": "年利[ねんり]二[に]パーセントの預金[よきん]に、お金[かね]を預[あず]けた。", "sentence_source": "generated"}, {"text": "全体を百としたとき、四十五パーセントは半分に届かない。", "target_word": "パーセント", "complexity_tier": "T3", "furigana": "全体[ぜんたい]を百[ひゃく]としたとき、四十五[よんじゅうご]パーセントは半分[はんぶん]に届[とど]かない。", "sentence_source": "generated"}, {"text": "参加者の九十五パーセント以上が、満足したと答えた。", "target_word": "パーセント", "complexity_tier": "T3", "furigana": "参加者[さんかしゃ]の九十五[きゅうじゅうご]パーセント以上[いじょう]が、満足[まんぞく]したと答[こた]えた。", "sentence_source": "generated"}, {"text": "アンケートの回答率は、七十パーセントでした。", "target_word": "パーセント", "complexity_tier": "T3", "furigana": "アンケートの回答率[かいとうりつ]は、七十[ななじゅっ]パーセントでした。", "sentence_source": "generated"}, {"text": "試験の合格率は、昨年の三十パーセントから四十パーセントに上がった。", "target_word": "パーセント", "complexity_tier": "T3", "furigana": "試験[しけん]の合格率[ごうかくりつ]は、昨年[さくねん]の三十[さんじゅっ]パーセントから四十[よんじゅっ]パーセントに上[あ]がった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "パーセント", "label": "基本形"}], "register": "報道・統計の文体", "sense_fingerprint": "全体を100としたときの割合を示す単位（百分率、統計・経済の用法）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa11b1da-6a01-497b-ba17-85963d2f0c23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39445, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "パーセント", "is_correct": true, "explanation": "増えた量を割合で示す単位で、前の年より五パーセント増えたという文に合う。"}, {"text": "デシベル", "is_correct": false, "explanation": "デシベルは音の大きさの単位で、売り上げの増加を表す語ではない。"}, {"text": "ヘルツ", "is_correct": false, "explanation": "ヘルツは周波数の単位で、売り上げの増減には使わない。"}, {"text": "カラット", "is_correct": false, "explanation": "カラットは宝石の重さの単位で、売り上げの増加を表す語としては合わない。"}], "explanations": {"パーセント": "増えた量を割合で示す単位で、前の年より五パーセント増えたという文に合う。", "デシベル": "デシベルは音の大きさの単位で、売り上げの増加を表す語ではない。", "ヘルツ": "ヘルツは周波数の単位で、売り上げの増減には使わない。", "カラット": "カラットは宝石の重さの単位で、売り上げの増加を表す語としては合わない。"}, "sentence_index": 0, "correct_answer": "パーセント"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "失業者の人数は三パーセントまで下がった。", "explanation": "ここは人数の意味。パーセントは割合の単位で、人の数そのものは表せないので合わない。"}, {"text": "この箱の色は三パーセントだ。", "explanation": "ここは〈色〉の意味。パーセントは割合の単位で、色の種類を表す語ではないので合わない。"}, {"text": "三パーセントの電車が、十時に駅に着いた。", "explanation": "割合の単位で、電車の台数や時刻を表す語ではないので、この文は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ff88f66-a23a-43b4-812c-c0d92e99400c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39445, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "パーセント", "is_correct": true, "explanation": "全体を百としたときの割合を表す単位で、四十五パーセントは半分に届かないという文に合う。"}, {"text": "ルクス", "is_correct": false, "explanation": "ルクスは明るさの単位で、全体の割合を示す文には合わない。"}, {"text": "ニュートン", "is_correct": false, "explanation": "ニュートンは力の単位で、全体を百としたときの割合には使わない。"}, {"text": "オーム", "is_correct": false, "explanation": "オームは電気抵抗の単位で、全体の割合を表す語としては成り立たない。"}], "explanations": {"パーセント": "全体を百としたときの割合を表す単位で、四十五パーセントは半分に届かないという文に合う。", "ルクス": "ルクスは明るさの単位で、全体の割合を示す文には合わない。", "ニュートン": "ニュートンは力の単位で、全体を百としたときの割合には使わない。", "オーム": "オームは電気抵抗の単位で、全体の割合を表す語としては成り立たない。"}, "sentence_index": 6, "correct_answer": "パーセント"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "試験の会場は、昨年の三十パーセントから四十パーセントに上がった。", "explanation": "ここは〈会場の広さ・規模〉の意味。パーセントは割合の単位で、会場の規模を表す語ではないので合わない。"}, {"text": "試験の合格者は、昨年の三十パーセントから四十パーセントに上がった。", "explanation": "ここは合格者の人数の意味。人の数はパーセントでは表せないので、この文は合わない。"}, {"text": "三十パーセントの店が、四十パーセントの駅へ移った。", "explanation": "ここは〈店や駅を数える・移る〉の意味。パーセントは割合の単位で、店や駅を数えたり移したりする語ではないので、この文は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ff88f66-a23a-43b4-812c-c0d92e99400c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39445, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "来年の売り上げは、今年より十パーセントを増える見込みです。", "corrected_sentence": "来年の売り上げは、今年より十パーセント増える見込みです。", "error_description": "『増える』は自動詞で目的語を取らないので、『十パーセント』の後に『を』は不要。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ff88f66-a23a-43b4-812c-c0d92e99400c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39445, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "不良品の割合は、三パーセントを下がった。", "corrected_sentence": "不良品の割合は、三パーセント下がった。", "error_description": "『下がる』は自動詞で目的語の『を』を取らない。『三パーセント』には『を』を付けず、そのまま続ける。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ff88f66-a23a-43b4-812c-c0d92e99400c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
