INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39446, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "あるものの大きさや量がどれくらいかを、だいたいで表すことば。", "primary_collocate": null, "pronunciation": "ていど", "ipa": "teːdo", "syllable_count": 3, "sentences": [{"text": "駅から家までは、歩いて十分程度です。", "target_word": "程度", "complexity_tier": "T3", "furigana": "駅[えき]から家[いえ]までは、歩[ある]いて十分[じゅっぷん]程度[ていど]です。", "sentence_source": "generated"}, {"text": "この箱には、りんごが二十個程度入ります。", "target_word": "程度", "complexity_tier": "T3", "furigana": "この箱[はこ]には、りんごが二十個[にじゅっこ]程度[ていど]入[はい]ります。", "sentence_source": "generated"}, {"text": "会議には、五十人程度が集まる予定です。", "target_word": "程度", "complexity_tier": "T3", "furigana": "会議[かいぎ]には、五十人[ごじゅうにん]程度[ていど]が集[あつ]まる予定[よてい]です。", "sentence_source": "generated"}, {"text": "塩を小さじ一杯程度、加えてください。", "target_word": "程度", "complexity_tier": "T3", "furigana": "塩[しお]を小[こ]さじ一杯[いっぱい]程度[ていど]、加[くわ]えてください。", "sentence_source": "generated"}, {"text": "作業が終わるまで、あと一時間程度かかります。", "target_word": "程度", "complexity_tier": "T3", "furigana": "作業[さぎょう]が終[お]わるまで、あと一時間[いちじかん]程度[ていど]かかります。", "sentence_source": "generated"}, {"text": "この荷物は五キロ程度なので、一人でも運べます。", "target_word": "程度", "complexity_tier": "T3", "furigana": "この荷物[にもつ]は五[ご]キロ程度[ていど]なので、一人[ひとり]でも運[はこ]べます。", "sentence_source": "generated"}, {"text": "去年の夏は、気温が三十度程度の日が多かったです。", "target_word": "程度", "complexity_tier": "T4", "furigana": "去年[きょねん]の夏[なつ]は、気温[きおん]が三十度[さんじゅうど]程度[ていど]の日[ひ]が多[おお]かったです。", "sentence_source": "generated"}, {"text": "来たのは二十人程度で、予想より少なかったです。", "target_word": "程度", "complexity_tier": "T3", "furigana": "来[き]たのは二十人[にじゅうにん]程度[ていど]で、予想[よそう]より少[すく]なかったです。", "sentence_source": "generated"}, {"text": "この部屋は六畳程度の広さで、一人で住むにはちょうどいいです。", "target_word": "程度", "complexity_tier": "T4", "furigana": "この部屋[へや]は六畳[ろくじょう]程度[ていど]の広[ひろ]さで、一人[ひとり]で住[す]むにはちょうどいいです。", "sentence_source": "generated"}, {"text": "参加費は千円程度なので、気軽に申し込めます。", "target_word": "程度", "complexity_tier": "T3", "furigana": "参加費[さんかひ]は千円[せんえん]程度[ていど]なので、気軽[きがる]に申[もう]し込[こ]めます。", "sentence_source": "generated"}], "morphological_forms": [{"form": "程度", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "数や量・大きさのおおよその見当を表す（数字＋程度）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 9 above tier T1: contains vocabulary far above tier T1: 申し込め (Zipf 2.47)']::text[], '01e5a7c6-6233-4cdf-b902-182071ea0773') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39446, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "程度", "is_correct": true, "explanation": "「およそ十分くらい」の意味で、歩く時間のおおよその見当に合う。"}, {"text": "途中", "is_correct": false, "explanation": "「歩いている途中」の意味で、「歩いて十分」という所要時間の見当には続かない。"}, {"text": "最中", "is_correct": false, "explanation": "「〜の真っ最中」の形で使い、時間の長さを表す語には続かない。"}, {"text": "要点", "is_correct": false, "explanation": "「要点」は話の大事な部分を指し、時間の見当には合わない。"}], "explanations": {"程度": "「およそ十分くらい」の意味で、歩く時間のおおよその見当に合う。", "途中": "「歩いている途中」の意味で、「歩いて十分」という所要時間の見当には続かない。", "最中": "「〜の真っ最中」の形で使い、時間の長さを表す語には続かない。", "要点": "「要点」は話の大事な部分を指し、時間の見当には合わない。"}, "sentence_index": 0, "correct_answer": "程度"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "会場の程度は、駅の向かい側です。", "explanation": "ここは〈場所〉の意味。程度はだいたいの分量を表す語で、場所を示すことはできない。"}, {"text": "この薬の程度は、正確に五ミリグラムです。", "explanation": "ここは〈量〉の意味。程度はだいたいの見当を表すので、「正確に五ミリグラム」という精密な分量とは合わない。"}, {"text": "参加者の程度は、ちょうど二十人でした。", "explanation": "ここは〈数〉の意味。「ちょうど二十人」という確定した人数には、だいたいを表す程度は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59842fc5-799f-4d98-a8d3-278d78c2adcf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39446, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "程度", "is_correct": true, "explanation": "「三十度くらい」の意味で、気温のおおよその範囲を表すので空所に合う。"}, {"text": "分野", "is_correct": false, "explanation": "「分野」は領域の意味で、気温の数値には続かない。"}, {"text": "形式", "is_correct": false, "explanation": "「形式」は決まった型の意味で、気温の範囲は表せない。"}, {"text": "基調", "is_correct": false, "explanation": "「基調」は全体の調子の意味で、気温の数値には続かない。"}], "explanations": {"程度": "「三十度くらい」の意味で、気温のおおよその範囲を表すので空所に合う。", "分野": "「分野」は領域の意味で、気温の数値には続かない。", "形式": "「形式」は決まった型の意味で、気温の範囲は表せない。", "基調": "「基調」は全体の調子の意味で、気温の数値には続かない。"}, "sentence_index": 6, "correct_answer": "程度"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "会議の程度は、来週の月曜日の午後三時です。", "explanation": "ここは〈日時〉の意味。程度はだいたいの見当を表すので、はっきり決まった日時には合わない。"}, {"text": "テストの程度は、三番です。", "explanation": "ここは〈順位〉の意味。程度は度合いを表す語で、競争で何番目かという順位は示せない。"}, {"text": "このシャツの程度は、三種類あります。", "explanation": "ここは〈種類〉の意味。程度は数や量のおおよその見当を表すので、商品の種類の数を示す語ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59842fc5-799f-4d98-a8d3-278d78c2adcf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39446, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この箱は重さが三キロ程度だので、子どもでも持てます。", "corrected_sentence": "この箱は重さが三キロ程度なので、子どもでも持てます。", "error_description": "誤：程度だので　正：程度なので。「程度」に続けて理由を示すときは「なので」を使う。「だので」は「だ」と「ので」が合わず不自然。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59842fc5-799f-4d98-a8d3-278d78c2adcf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39446, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この店のケーキは、一つ千円程度を買えます。", "corrected_sentence": "この店のケーキは、一つ千円程度で買えます。", "error_description": "誤：程度を買えます　正：程度で買えます。「千円程度で」は「その金額で」という手段を示す「で」が必要。「を」は目的語を示し、「買える」の手段にはならない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59842fc5-799f-4d98-a8d3-278d78c2adcf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39447, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「程度に合わせる」の「に」。合わせる相手を示す。"}, {"text": "を", "is_correct": false, "explanation": "「程度を合わせる」とは言わず、「合わせる」の相手には「に」を使う。"}, {"text": "が", "is_correct": false, "explanation": "主語を示す「が」は、ここでは「合わせる」の相手を表せない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す「へ」は「合わせる」の相手には使わない。"}], "correct_answer": "に", "explanations": {"に": "「程度に合わせる」の「に」。合わせる相手を示す。", "を": "「程度を合わせる」とは言わず、「合わせる」の相手には「に」を使う。", "が": "主語を示す「が」は、ここでは「合わせる」の相手を表せない。", "へ": "方向を示す「へ」は「合わせる」の相手には使わない。"}, "error_tags": {"を": "対象の取り違え", "が": "主語の取り違え", "へ": "方向の誤り"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59842fc5-799f-4d98-a8d3-278d78c2adcf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
