INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39447, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物事の状態や数量が、おおよそその範囲にあることを示す名詞。", "primary_collocate": null, "pronunciation": "ていど", "ipa": "teːdo", "syllable_count": 3, "sentences": [{"text": "病気の程度が軽いので、入院はしなくて大丈夫です。", "target_word": "程度", "complexity_tier": "T3", "furigana": "病気[びょうき]の程度[ていど]が軽[かる]いので、入院[にゅういん]はしなくて大丈夫[だいじょうぶ]です。", "sentence_source": "generated"}, {"text": "痛みの程度に合わせて、薬の量を変えます。", "target_word": "程度", "complexity_tier": "T3", "furigana": "痛[いた]みの程度[ていど]に合[あ]わせて、薬[くすり]の量[りょう]を変[か]えます。", "sentence_source": "generated"}, {"text": "日本語の上手さは、人によって程度が違います。", "target_word": "程度", "complexity_tier": "T3", "furigana": "日本語[にほんご]の上手[じょうず]さは、人[ひと]によって程度[ていど]が違[ちが]います。", "sentence_source": "generated"}, {"text": "どの程度の雨なら、試合を中止しますか。", "target_word": "程度", "complexity_tier": "T3", "furigana": "どの程度[ていど]の雨[あめ]なら、試合[しあい]を中止[ちゅうし]しますか。", "sentence_source": "generated"}, {"text": "彼の失敗は、笑って済ませられる程度のものでした。", "target_word": "程度", "complexity_tier": "T4", "furigana": "彼[かれ]の失敗[しっぱい]は、笑[わら]って済[す]ませられる程度[ていど]のものでした。", "sentence_source": "generated"}, {"text": "冗談にも程度があります。", "target_word": "程度", "complexity_tier": "T3", "furigana": "冗談[じょうだん]にも程度[ていど]があります。", "sentence_source": "generated"}, {"text": "被害の程度を調べるため、専門家が現地に入りました。", "target_word": "程度", "complexity_tier": "T4", "furigana": "被害[ひがい]の程度[ていど]を調[しら]べるため、専門家[せんもんか]が現地[げんち]に入[はい]りました。", "sentence_source": "generated"}, {"text": "二人の実力は、ほとんど同じ程度です。", "target_word": "程度", "complexity_tier": "T3", "furigana": "二人[ふたり]の実力[じつりょく]は、ほとんど同[おな]じ程度[ていど]です。", "sentence_source": "generated"}, {"text": "辞書を引けば分かる程度の漢字なら、問題ありません。", "target_word": "程度", "complexity_tier": "T4", "furigana": "辞書[じしょ]を引[ひ]けば分[わ]かる程度[ていど]の漢字[かんじ]なら、問題[もんだい]ありません。", "sentence_source": "generated"}, {"text": "大雪の程度は、地域によって大きく異なります。", "target_word": "程度", "complexity_tier": "T4", "furigana": "大雪[おおゆき]の程度[ていど]は、地域[ちいき]によって大[おお]きく異[こと]なります。", "sentence_source": "generated"}], "morphological_forms": [{"form": "程度", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "物事の状態・度合いがどの範囲にあるか（病気の程度、どの程度）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01e5a7c6-6233-4cdf-b902-182071ea0773') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39447, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "程度", "is_correct": true, "explanation": "「病気の重さ・度合い」を表し、「軽い」と合う。"}, {"text": "原因", "is_correct": false, "explanation": "「病気の原因」はなぜ起きたかを表し、「軽い」とは結びつかない。"}, {"text": "種類", "is_correct": false, "explanation": "「病気の種類」は分類を表し、重さの評価には使わない。"}, {"text": "日数", "is_correct": false, "explanation": "「病気の日数」は期間の長さを表し、「軽い」とは合わない。"}], "explanations": {"程度": "「病気の重さ・度合い」を表し、「軽い」と合う。", "原因": "「病気の原因」はなぜ起きたかを表し、「軽い」とは結びつかない。", "種類": "「病気の種類」は分類を表し、重さの評価には使わない。", "日数": "「病気の日数」は期間の長さを表し、「軽い」とは合わない。"}, "sentence_index": 0, "correct_answer": "程度"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼の程度は、今年で二十歳です。", "explanation": "ここは〈年齢〉の意味。程度は状態の度合いを表すので、確定した年齢には使わない。"}, {"text": "事故の程度は、先月の十日でした。", "explanation": "ここは〈発生日〉の意味。程度は状態の度合いで、日付を示すことはできない。"}, {"text": "作業の程度は、あと一時間です。", "explanation": "ここは〈時間〉の意味。程度は状態の度合いで、残りの時間の長さを表す語ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59842fc5-799f-4d98-a8d3-278d78c2adcf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39447, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "程度", "is_correct": true, "explanation": "「被害の重さ・度合い」を表し、調べる対象として合う。"}, {"text": "天候", "is_correct": false, "explanation": "「天候」は空模様のことで、被害の大きさを調べる対象ではない。"}, {"text": "料金", "is_correct": false, "explanation": "「料金」は支払う金額で、被害の調査とは結びつかない。"}, {"text": "注文", "is_correct": false, "explanation": "「注文」は品物を頼む行為で、被害の説明には合わない。"}], "explanations": {"程度": "「被害の重さ・度合い」を表し、調べる対象として合う。", "天候": "「天候」は空模様のことで、被害の大きさを調べる対象ではない。", "料金": "「料金」は支払う金額で、被害の調査とは結びつかない。", "注文": "「注文」は品物を頼む行為で、被害の説明には合わない。"}, "sentence_index": 6, "correct_answer": "程度"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この商品の程度は、千円です。", "explanation": "ここは〈価格〉の意味。程度は状態の度合いで、確定した金額は示せない。"}, {"text": "選手の程度は、三位でした。", "explanation": "ここは〈順位〉の意味。程度は度合いを表すので、順番を示す語ではない。"}, {"text": "学校から駅までの程度は、五キロです。", "explanation": "ここは〈距離〉の意味。程度は状態のおおよその度合いで、正確な距離には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59842fc5-799f-4d98-a8d3-278d78c2adcf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39447, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "熱の程度を高いので、今日は休みましょう。", "corrected_sentence": "熱の程度が高いので、今日は休みましょう。", "error_description": "誤：程度を高い　正：程度が高い。「高い」は状態を表す形容詞で、その主語は「が」で示す。「を」は目的語で、形容詞には続かない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59842fc5-799f-4d98-a8d3-278d78c2adcf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39447, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "揺れの程度なは、震度で表します。", "corrected_sentence": "揺れの程度は、震度で表します。", "error_description": "誤：程度なは　正：程度は。「程度」は名詞なので、直後に「な」を付けず、そのまま「は」で続ける。「な」は形容動詞の語尾で、名詞の「程度」には付かない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59842fc5-799f-4d98-a8d3-278d78c2adcf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39448, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「現在の時刻」の「の」。現在が時刻を修飾する名詞句を作る。"}, {"text": "が", "is_correct": false, "explanation": "「現在が」は主語を示すが、「時刻は」の述語と噛み合わない。"}, {"text": "を", "is_correct": false, "explanation": "目的語を示す「を」は、「時刻」の前に置くと不自然。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す「へ」は、時刻の説明には続かない。"}], "correct_answer": "の", "explanations": {"の": "「現在の時刻」の「の」。現在が時刻を修飾する名詞句を作る。", "が": "「現在が」は主語を示すが、「時刻は」の述語と噛み合わない。", "を": "目的語を示す「を」は、「時刻」の前に置くと不自然。", "へ": "方向を示す「へ」は、時刻の説明には続かない。"}, "error_tags": {"が": "主語の誤り", "を": "目的語の誤り", "へ": "方向の誤り"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59842fc5-799f-4d98-a8d3-278d78c2adcf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39448, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59842fc5-799f-4d98-a8d3-278d78c2adcf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39448, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "今のこと。今の時間。", "primary_collocate": null, "pronunciation": "げんざい", "ipa": "ɡendzai", "syllable_count": 4, "sentences": [{"text": "現在、社長は会議中です。", "target_word": "現在", "complexity_tier": "T3", "furigana": "現在[げんざい]、社長[しゃちょう]は会議中[かいぎちゅう]です。", "sentence_source": "generated"}, {"text": "現在の時刻は、午後三時です。", "target_word": "現在", "complexity_tier": "T3", "furigana": "現在[げんざい]の時刻[じこく]は、午後[ごご]三時[さんじ]です。", "sentence_source": "generated"}, {"text": "現在、この店ではセールをしています。", "target_word": "現在", "complexity_tier": "T3", "furigana": "現在[げんざい]、この店[みせ]ではセールをしています。", "sentence_source": "generated"}, {"text": "現在の日本の人口は、約一億二千万人です。", "target_word": "現在", "complexity_tier": "T4", "furigana": "現在[げんざい]の日本[にほん]の人口[じんこう]は、約[やく]一億二千万人[いちおくにせんまんにん]です。", "sentence_source": "generated"}, {"text": "彼は現在、大阪に住んでいます。", "target_word": "現在", "complexity_tier": "T3", "furigana": "彼[かれ]は現在[げんざい]、大阪[おおさか]に住[す]んでいます。", "sentence_source": "generated"}, {"text": "現在の状況では、旅行に行くのは難しいです。", "target_word": "現在", "complexity_tier": "T3", "furigana": "現在[げんざい]の状況[じょうきょう]では、旅行[りょこう]に行[い]くのは難[むずか]しいです。", "sentence_source": "generated"}, {"text": "過去も大切ですが、現在を大切に生きたいです。", "target_word": "現在", "complexity_tier": "T4", "furigana": "過去[かこ]も大切[たいせつ]ですが、現在[げんざい]を大切[たいせつ]に生[い]きたいです。", "sentence_source": "generated"}, {"text": "現在、その商品は売り切れです。", "target_word": "現在", "complexity_tier": "T3", "furigana": "現在[げんざい]、その商品[しょうひん]は売[う]り切[き]れです。", "sentence_source": "generated"}, {"text": "現在、工事のため道が通れません。", "target_word": "現在", "complexity_tier": "T3", "furigana": "現在[げんざい]、工事[こうじ]のため道[みち]が通[とお]れません。", "sentence_source": "generated"}, {"text": "過去と現在を比べると、町はずいぶん変わりました。", "target_word": "現在", "complexity_tier": "T4", "furigana": "過去[かこ]と現在[げんざい]を比[くら]べると、町[まち]はずいぶん変[か]わりました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "現在", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "今この時点（過去・未来に対する今）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01e5a7c6-6233-4cdf-b902-182071ea0773') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39448, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "現在", "is_correct": true, "explanation": "「今この時点」の意味で、社長の状況を示すのに合う。"}, {"text": "時刻", "is_correct": false, "explanation": "「時刻」は時の数字そのものを指し、「今」の意味では使えない。"}, {"text": "正式", "is_correct": false, "explanation": "「正式」は手続き上の正しさの意味で、「今」を表さない。"}, {"text": "本体", "is_correct": false, "explanation": "「本体」は物の主要な部分を指し、時点を表さない。"}], "explanations": {"現在": "「今この時点」の意味で、社長の状況を示すのに合う。", "時刻": "「時刻」は時の数字そのものを指し、「今」の意味では使えない。", "正式": "「正式」は手続き上の正しさの意味で、「今」を表さない。", "本体": "「本体」は物の主要な部分を指し、時点を表さない。"}, "sentence_index": 0, "correct_answer": "現在"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "迷子になったので、現在を警察に伝えました。", "explanation": "ここは〈現在地〉の意味。現在は今という時点を表す語で、自分が今いる場所は指せない。"}, {"text": "買い物は、現在で払いました。", "explanation": "ここは〈現金〉の意味。現在は今という時点を表す語で、支払いに使うお金の種類は指せない。"}, {"text": "現在、社長は学生でした。", "explanation": "ここは〈当時〉の意味。「学生でした」は過去の話なので、今を表す現在とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59842fc5-799f-4d98-a8d3-278d78c2adcf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39448, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "現在", "is_correct": true, "explanation": "「今」の意味で、過去との対比として「今を大切に」に合う。"}, {"text": "理論", "is_correct": false, "explanation": "「理論」は筋道立てた考えで、「大切に生きる」対象にはならない。"}, {"text": "天気", "is_correct": false, "explanation": "「天気」は空模様のことで、生き方の対象として不自然。"}, {"text": "機械", "is_correct": false, "explanation": "「機械」は道具の意味で、生き方の対象にはならない。"}], "explanations": {"現在": "「今」の意味で、過去との対比として「今を大切に」に合う。", "理論": "「理論」は筋道立てた考えで、「大切に生きる」対象にはならない。", "天気": "「天気」は空模様のことで、生き方の対象として不自然。", "機械": "「機械」は道具の意味で、生き方の対象にはならない。"}, "sentence_index": 6, "correct_answer": "現在"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "現在、私はこの町に住んでいました。", "explanation": "ここは〈過去の居住〉の意味。「住んでいました」と過去の暮らしを述べるので、今を表す現在とは合わない。"}, {"text": "現在、この店はまだ開いていませんでした。", "explanation": "ここは〈過去のある時点〉の意味。「まだ開いていませんでした」と過去の状況を述べるので、今を表す現在とは合わない。"}, {"text": "現在、この町は小さな漁村でした。", "explanation": "ここは〈過去の状態〉の意味。「小さな漁村でした」と過去の姿を述べるので、今を表す現在とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59842fc5-799f-4d98-a8d3-278d78c2adcf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39448, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "現在を会場に五百人がいます。", "corrected_sentence": "現在は会場に五百人がいます。", "error_description": "誤：現在を　正：現在は。「現在」は今という時の範囲を話題として示すので「は」で続ける。「を」は目的語で、「いる」とは合わない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59842fc5-799f-4d98-a8d3-278d78c2adcf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39448, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "現在な人数は、三十人です。", "corrected_sentence": "現在の人数は、三十人です。", "error_description": "誤：現在な　正：現在の。「現在」は名詞なので、名詞を続けるときは「の」を使う。「な」は形容動詞の語尾で、名詞の「現在」には付かない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59842fc5-799f-4d98-a8d3-278d78c2adcf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39450, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "分離", "is_correct": true, "explanation": "くっついたものを離すことで、接合の反対の関係にある。"}, {"text": "収穫", "is_correct": false, "explanation": "「収穫」は作物を取り入れることで、接合と反対の関係ではない。"}, {"text": "増加", "is_correct": false, "explanation": "「増加」は数や量が増えることで、接合の反対語ではない。"}, {"text": "散歩", "is_correct": false, "explanation": "「散歩」は気晴らしに歩くことで、接合の対義語ではない。"}], "correct_answer": "分離", "explanations": {"分離": "くっついたものを離すことで、接合の反対の関係にある。", "収穫": "「収穫」は作物を取り入れることで、接合と反対の関係ではない。", "増加": "「増加」は数や量が増えることで、接合の反対語ではない。", "散歩": "「散歩」は気晴らしに歩くことで、接合の対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59842fc5-799f-4d98-a8d3-278d78c2adcf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
